(window.AQIDA_TEXTS = window.AQIDA_TEXTS || {})["474"] = {"atoms": {"474.1": {"x": [[5, "المقدمة [للمحقق]\rكثيرا ما نخطئ في الحكم على الرجال، وما هم عليه من معتقد وأفكار، إذ نبادر بالحكم عليهم دون مراعاة لتبدل أحوالهم ومعتقداتهم، أوتطورها عبر الحقب الزمنية التي عاشها هؤلاء الرجال.\rومما يزيد هذه الأحكام خطأ وتعسفا، الانتقائية المفرطة التي تتحكم بنا عند ما نتناول شخصية فكرية أوسياسية بالدراسة والتحليل، خاصة إذا كان لنا موقف وجداني أوعقدي مناهض لها، فنلجأ بقصد أودون قصد، إلى إيقاف الزمن العقدي لهؤلاء الأشخاص، عند لحظة تاريخية أثر عنهم فيها قول أوكتاب أوانحياز إلى مذهب، أوموقف ما في إطار زمني محدد.\rوكما يقول المفسرون إنه لا يجوز تناول الآيات القرآنية عضينا (1) عند تفسيرها، وإنما يجب جمع كامل الآيات التي وردت في السياق نفسه لتشكل كلا موحدا، فكذلك الأمر ينبغي أن يسود في دراسة الشخصيات الإسلامية التاريخية، فالتحول أوالصيرورة يحكمان كل ما يحيط بنا من فكر ومادة، فما خطب هؤلاء الذين يأبون إلا أن يقفوا في تصنيف الرجال عند مسامير زمنية يعلقون عليها عباءات كريهة من التشدد والمغالاة والتعصب. أ لم يكن الأشعري معتزليا إلى أن بلغ الأربعين سنة ثم انحاز إلى أهل السنة أ لم يكن القاضي عبد الجبار الهمذاني في بداية تمذهبه أشعريا ثم انقلب معتزليا أ لم يكن الغزالي متفلسفا ثم انقلب على الفلسفة وأهلها وسار على منهاج السالكين أ لم يكن إبراهيم بن أدهم في مطلع شبابه صيادا عابثا ثم أصبح من كبار المتصوفة\rوإمام الحرمين عبد الملك الجويني، كان من هؤلاء الرجال الذين تناوله\r____________________________\r(1) عضينا: أجزاء متفرقة."], [6, "بعض المؤرخين والباحثين قديما وحديثا بالمديح والثناء، ولم يروا فيه من خلال كتبه المتقدمة إلا أشعريا متحمسا، وسخفوا، وبتحامل شديد، الذين أشاروا إلى التطور العقدي عند هذا الإمام في أواخر حياته. أما الآخرون فقد تحاملوا على إمام الحرمين في مناصرته للأشاعرة، ونالوا منه، ونسبوا إليه افتراءات لا تليق بمكانته، ثم هللوا وحمدلوا لهذا الإمام عند ما تناول بعض المسائل العقدية من وجهة نظر أهل السلف، فعدوه سلفيا خالصا، بناء على المواقف الجزئية التي وردت في العقيدة النظامية وانحاز فيها إلى فهم أهل السلف لها.\rإن الدراسة الموضوعية لفكر إمام الحرمين، لن تتحصل لأي باحث إذا لم يأخذ بعين الاعتبار الخصائص النفسية والفكرية له، وبالأخص طبيعة التمرد الفكري التي لازمته طوال حياته، فالجويني منذ صغره كان متمردا على كل ما لا يقبله عقله، فكان يخضع كل ما يسمع أويقرأ لمنهج عقلي متشدد، مما دفعه إلى رفض كل ما يتعارض مع الآليات العقلية التي كونها في نفسه لاكتساب المعرفة أوإنتاجها، فهوعند ما كان في أوج أشعريته، عارض كبار الأئمة، كالإمام مالك، إذ غمز من قناته في المصالح المرسلة، وخالف الأشاعرة جميعا بما فيهم الأشعري نفسه، وأخذ بنظرية الأحوال البهشمية (1) مما أثار حفيظة المالكية والأشاعرة على حد سواء.\rالعقيدة النظامية، هوآخر مؤلف عقدي وصل إلينا لإمام الحرمين، وقد وجد فيه خصوم الأشاعرة انحيازا من الجويني إلى مذهب أهل السلف، أما الأشاعرة المتأخرون عنه فلم يسلموا له ببعض مواقفه في هذه العقيدة، وضمنوا كتبهم ردودا عليه في هذه المواقف، وانتصروا لشيخهم الأشعري، لذا فإن هذه العقيدة قد لاقت قبولا واهتماما بالغين عند الأشاعرة وخصومهم على حد سواء، فاستلوا الجزء الخاص بالعقيدة من الكتاب الأصل، الرسالة النظامية في الأركان الإسلامية، وأفردوه بالنسخ والنشر قديما وحديثا.\rإن الدراسة المتأنية للعقيدة النظامية تزودنا بمستلزمات حقيقية للحكم\r_______________________________\r1) نسبة إلى أبي هاشم الجبائي."], [7, "الصحيح على ما آل إليه الجويني من معتقد في أواخر حياته. ولا نجانب الحقيقة إن قلنا: إن الجويني قد ختم معتقده الكلامي بموقف وسطي ما بين الأشاعرة وأهل السلف، فلم يكن سلفيا أوأشعريا خالصا في جل المسائل الكلامية التي بحثها في هذه العقيدة، وإنما كان في منزلة بين المنزلتين.\rنشرت العقيدة النظامية أولا من قبل محمد زاهد الكوثري، ثم ترجمها إلى الألمانية المستشرق هلموت كلوبفر، لكن هذه النشرة اعتمدت على نسخة خطية أندلسية لهذه العقيدة، وهي كثيرة السقط والخطأ باعتراف الكوثري نفسه، لذا قمت بإعادة تحقيق هذا الكتاب ونشره اعتمادا على نسخة خطية تركية له، كتبت من بعد وفاة الجويني نفسه بست وعشرين سنة تقريبا، وقارنتها بالنسخة الأندلسية المطبوعة، إيمانا مني بأهمية هذا المصنف.\rوآمل فيما قمت به من دراسة وتحقيق، أن أكون قد أخرجت الكتاب بما يليق بمنزلة إمام الحرمين الجويني الرفيعة.\rد. محمد الزبيدي بيروت في كانون الأول 2003 م"]], "pg": [5, 8]}, "474.2": {"x": [[9, "الفصل الأول: الحالة السياسية والاجتماعية والاقتصادية في عصر الجويني:\rعاصر إمام الحرمين الجويني خليفتين عباسيين هما القائم بأمر الله (- 467 ه‍) والمقتدي بأمر الله (- 487 ه‍)، وكانت الخلافة العباسية آنذاك مؤسسة معنوية فقط، إذ فقد الخليفة العباسي في هذا العصر سلطته الإجرائية الملزمة سواء في بغداد أوخارجها 1، ولم يبق له منها سوى الصفة الاعتبارية، فكان اسمه يتردد في الخطب المنبرية أيام الجمع والأعياد 2، ويسك على العملة المتداولة في الدويلات والإمارات التي أسسها أصحاب الشوكة والسلاطين من بويهيين وسلاجقة وغزنويين وغيرهم، حرصا منهم على إضفاء الشرعية على إماراتهم ودويلاتهم، وكان الخليفة مقابل ذلك يعطى أولئك السلاطين تفويضا شرعيا يزيد من سلطاتهم معنويا على أقل تقدير 3.\rوفي المشرق الإسلامي حيث قضى الجويني معظم حياته، تنازع السلطة ثلاث دويلات هي: الدولة البويهية (334 ه‍/ 945 م- 447 ه‍/ 1055 م) والدولة الغزنوية (351 ه‍/ 962 م- 582 ه‍/ 1186 م) ودولة السلاجقة (429 ه‍/ 1037 م- 522 ه‍/ 1128 م)، وقد ساد هذا العصر حالات من التفكك والاضطراب والصراع على المصالح ومناطق النفوذ، مما مكن سلاطين هذه الدول أن يستقلوا بإماراتهم، ويقرروا شكل العلاقة التي تربطهم بالخلافة العباسية في\r________________\r1) ابن الجوزي، المنتظم ج 7 ص 161، وانظر: بروكلمان، تاريخ الشعوب الإسلامية ص 246.\r2) سعد الغامدي، أوضاع الدول الإسلامية ص 62، 63.\r3) المصدر نفسه ص 63."], [10, "10 بغداد وفق مصالحهم الذاتية، أما حدود هذه الدويلات فكانت تتسع وتضيق تبعا لطموحات سلاطينها وإمكاناتهم العسكرية 1\rومما زاد من حالة التمزق والتشرذم في هذا العصر، الصراعات الحادة التي كانت تحصل بين الخلافة العباسية في بغداد، وحماتها من الغزنويين والسلاجقة من جهة، والخلافة الفاطمية في مصر، وأعوانها من سلاطين بني بويه، وأنصارهم من الشيعة في بغداد وحلب وفارس من جهة أخرى 2.\r\r***\rبدأ نجم الدولة البويهية بالظهور في أوائل القرن الرابع الهجري، عند ما استطاع الأخوة علي بن بويه، والحسن بن بويه، وأحمد بن بويه، من بسط سيطرتهم على معظم الحواضر الإسلامية في المشرق الإسلامي 3، ومن ثم اتجهوا إلى بغداد، وهناك استقبلهم الخليفة العباسي المستكفي بالله بحفاوة بالغة، ومنحهم الألقاب الدالة على تشريع حكمهم، كما أمر أن تسك هذه الألقاب على العملة المتداولة في إماراتهم الثلاث 4.\rوفي عهد بني بويه كانت السلطة الفعلية للسلاطين الذين تعاقبوا على دولتهم، ولم يبق للخليفة إلا إصدار المراسيم الاعتبارية وبتأثير منهم أيضا 5.\rتشيع البويهيون وفق المذهب الإثني عشري (الإمامي)، لذا جهدوا كثيرا في نشره في مناطق نفوذهم بعامة وفي بغداد بخاصة، من أجل محاصرة الخليفة العباسي ومنعه من الاستقواء عليهم، وقد أدى ذلك إلى نشوب الفتن بين أهل السنة المدعمين بسلطة الخليفة المعنوية، والشيعة الإمامية في حي الكرخ ببغداد وحلب ونيسابور وأبيورد، المستقوين بسلاطين بني بويه.\rوقد حاول البويهيون من حين لآخر التقارب مع الخلافة الفاطمية في\r_________________\r1) سيف الدين الآمدي، الإمامة، مقدمة المحقق ص 33.\r2) المصدر نفسه ص 33.\r3) ابن الطقطقي، الفخري في الآداب السلطانية ص 287.\r4) المصدر نفسه ص 287.\r5) ابن الأثير، الكامل في التاريخ ج 8 ص 452، وبروكلمان، تاريخ الشعوب الإسلامية ص 246."], [11, "11 مصر، قاصدين من ذلك، إضعاف الخليفة العباسي، ومنعه من تأليب الرأي العام السني ضدهم، وكف يد الخليفة من مؤازرة أمراء السلاجقة السنيين، المنافسين الجدد لبني بويه في المناطق نفسها الخاضعة لحكمهم 1.\rلكن هذا التقارب لم يصل إلى درجة التحالف، ذلك أنهم قد وعوا أن مثل هذا التحالف قد يؤدي إلى تحشيد القوى السنية الفاعلة ضدهم، أوربما قد خشوا أن ذلك قد يدفع عساكرهم إلى الانضمام للجيش الفاطمي وبالتالي إلى زوال سلطتهم 2.\rولم يدم الحفاظ على هذه السياسة المتوازنة طويلا، إذ جاهر أبوالحارث البساسيري (451 ه‍/ 1058 م) أحد قادة بني بويه بالدعوة والخطبة للخليفة الفاطمي على منابر بغداد نفسها، وأمده هذا الخليفة بالجند والأموال والدعاة الحذقين في المذهب الإسماعيلي 3. ثم صعد البساسيري من تحديه للخليفة العباسي، إذ هاجم عسكر الخليفة وألحق به الهزيمة، وقبض على الخليفة القائم بأمر الله وسجنه 4. وكان ذلك إيذانا بنهاية دولة بني بويه، فقد تمكن الخليفة من الاستنجاد بالسلطان السلجوقي طغرلبك (- 455 ه‍/ 1063 م)، فسارع هذا السلطان إلى التوجه نحوبغداد، وقتل البساسيري وأنهى تمرده، وأعاد الخليفة إلى قصره معززا مكرما 5.\r***\rفي أثناء سيطرة البويهيين على المشرق الإسلامي، تمكن السلطان سبكتكين الغزنوي (387 ه‍/ 1097 م) الذي كان أحد قادة العساكر السامانية- من الاستيلاء على بعض بلاد الهند والأفغان، وسيطر على مدينة غزنة وجعلها حاضرة لإمارته، ومنطلقا لغزواته وفتوحاته 6. ثم اتجه سبكتكين بمساعدة ابنه\r_____________________\r1) حسن حسن، تاريخ الإسلام السياسي ج 3 ص 62.\r2) المصدر نفسه ج 2 ص 248.\r3) المصدر نفسه ج 2 ص 248.\r4) الذهبي، تاريخ الإسلام، حوادث (441 - 460) ص 29، وابن الجوزي، المنتظم ج 8 ص 194.\r5) السيوطي، تاريخ الخلفاء ص 418.\r6) بروكلمان، تاريخ الشعوب الإسلامية ص 268."], [12, "محمود إلى خراسان، وتمكن من إخراج البويهيين من مدينة نيسابور وضمها لإمارته عام 384 ه‍/ 994 م 1.\rوبعد وفاة سبكتكين، واصل ابنه السلطان محمود الغزنوي (421 ه‍/ 1030 م) غزواته في بلاد الهند والبنجاب وخوارزم وجورجيا، وأخضع هذه الولايات، وضمها إلى دولته، ثم ضم بلاد الري وطرد البويهيين منها عام 417 ه‍/ 1026 م 2، ولاحق المعتزلة التي كانت تتخذ من هذه البلاد ملاذا وموطنا 3.\rبعد هذا الاتساع للدولة الغزنوية، حرص السلطان محمود على إضفاء صفة الشرعية على تحركاته العسكرية وفتوحاته، فأقام الخطبة للخليفة العباسي في الجمع والأعياد، مما دفع الخليفة بالمقابل إلى منحه لقب يمين الدولة، دلالة على شرعية هذا السلطان واعترافا بدولته الناشئة 4.\rلكن اندفاعة الغزنويين القوية والمتسارعة لم تدم طويلا، فقد انحسرت بعد وفاة السلطان محمود، إذ سرعان ما دب النزاع والتقاتل بين أولاده، مما شجع سلاطين السلاجقة على مهاجمة مناطق نفوذهم، وأوقعوا بهم الهزيمة في أكثر من موقع في خراسان، واستطاعوا السيطرة على عاصمتها نيسابور عام 432 ه‍/ 1040 م 5.\rوقد دفع ذلك الغزنويين إلى الانكفاء، والاكتفاء بما أسسوه من إمارات في بلاد الهند والبنغال والأفغان 6.\r***\rدخل السلاجقة بقوة معترك الحياة السياسية في المشرق الإسلامي عام 429 ه‍/ 1037 م، عند ما تولى أمرهم السلطان طغرلبك بن ميكائيل بن سلجوق\r______________\r1) ابن الأثير، الكامل في التاريخ ج 9 ص 103.\r2) بروكلمان، تاريخ الشعوب الإسلامية ص 268.\r3) ابن الأثير، الكامل في التاريخ ج 9 ص 271.\r4) المصدر نفسه ج 9 ص 244.\r5) ابن الجوزي، المنتظم ج 8 ص 107.\r6) المصدر نفسه ج 8 ص 107."], [13, "(- 455 ه‍)، فقد تمكن هذا السلطان بعد العديد من الغزوات والحروب الدامية، من بسط نفوذه على خوارزم وطبرستان 1 وكامل خراسان بما فيها نيسابور 2، ثم توجه إلى عراق العجم (بلاد الجبال) واستطاع إخراج البويهيين منها وضمها إلى سلطنته.\rوكان طغرلبك في أثناء تحركاته العسكرية ضد الغزنويين والبويهيين، يبعث بالسفراء والمبعوثين، محملين بالهدايا إلى الخليفة العباسي، وبالمقابل كان الخليفة يمنحه ألقابا تسوغ الفتوحات والانتصارات التي حققها 3.\rوعند ما تمكن طغرلبك من انتزاع ديار بكر وأصبهان وأذربيجان من بني بويه والغزنويين، استدعاه الخليفة القائم بأمر الله إلى بغداد، ولقبه بملك المشرق والمغرب، وأمر أن يسك اسمه على النقود قبل اسم السلطان البويهي آنذاك، كما أمر أن يذكر اسمه في الخطبة على منابر مساجد بغداد 4.\rوقد استغل طغرلبك استنجاد الخليفة به لقمع تمرد البساسيري المتحالف مع الخليفة الفاطمي، فتوجه إلى بغداد، وقبض على الملك الرحيم آخر ملوك بني بويه 5، وقتل البساسيري وأعاد والخليفة إلى قصره، وبذلك انفرد السلاجقة بالتحكم في الحياة السياسية، وأصبحت تقريراتهم السياسية أوامر ملزمة للخليفة ورعيته على حد سواء 6.\rومن بعد وفاة السلطان طغرلبك، تولى زمام الأمر في الدولة السلجوقية ابن أخيه السلطان ألب أرسلان (465 ه‍/ 1072 م)، الذي اهتم اهتماما خاصا ببلاد الشام والحجاز، حيث كانت المدن الشامية والحجازية تخضع للخلافة الفاطمية في مصر، وكانت حلب خاصة معقلا للشيعة الإمامية، وفي فترة\r_______________\r1) صدر الدين الحسيني، أخبار الدولة السلجوقية ص 2.\r2) بروكلمان، تاريخ الشعوب الإسلامية ص 272.\r3) صدر الدين الحسيني، أخبار الدولة السلجوقية ص 17، 18.\r4) المصدر نفسه ص 18، والكامل في التاريخ ج 9 ص 634.\r5) صدر الدين الحسيني، أخبار الدولة السلجوقية ص 8، وابن الأثير، الكامل في التاريخ ج 9 ص 634.\r6) الخضري، الدولة العباسية ص 417."], [14, "14 وجيزة استطاع ألب أرسلان من إخضاع مكة والمدينة ودمشق وحلب، وأصبحت الخطبة تقام فيها للخليفة العباسي والسلطان السلجوقي 1. ثم استوزر ألب أرسلان نظام الملك (408 - 486 ه‍/ 1018 - 1092 م) الذي اشتهر بحكمته وحسن سياسته، فكانت الدولة وتحركات السلطان تحكمها تقريرات هذا الوزير 2.\rوإجمالا فإنه رغم أن السلاجقة قد نصبوا أنفسهم حماة الخلافة العباسية بخاصة وأهل السنة بعامة، لكنهم لم يعيدوا للخليفة سلطاته التي انتزعها منه أصحاب الشوكة والسلاطين في القرن الماضي، ويمكن القول: إن عماد العلاقة الوطيدة التي ربطت السلاجقة بالخليفة العباسي، هوحاجة كل منهما للآخر، فالخليفة العباسي قد رأى بأم عينه من خلال حادثة البساسيري مدى ضعفه، وتأثير ذلك في زوال خلافة بني العباس إن لم يكن لها سند قوي يحميها من غائلة الطامعين في تقاسم إرث هذه الخلافة، فوجد في السلاطين السلاجقة خير حام وأهون الضررين. أما السلاجقة فكانوا مدركين تماما أنهم مهما أوتوا من قوة وشوكة، ومن اتفاق مع السواد الأعظم في المذهب، فلن يستطيعوا المحافظة على شرعية دولتهم إلا بتقديم خدمات سياسية وعسكرية للخليفة العباسي، فقد جرت العادة في ذلك العصر أنه كلما ورث سلطان أوأمير حكم دولة أوإمارة ما، فلا مناص من قرار يصدره الخليفة يؤكد شرعية هذا التوارث.\r***\rوقد تأثر الإمام عبد الملك الجويني بالحالة السياسية في عصره تأثرا مباشرا، فالجويني قد قضى معظم حياته في نيسابور وبغداد وبلاد الحجاز، وشهد في هذه البلاد الفتن والمحن التي كانت تحصل من حين لآخر بتحريض ظاهر من القوى السياسية الحاكمة بين أهل السنة في نيسابور، والشيعة الإمامية في كل من طوس وأبيورد 3.\r_______________\r1) ابن الأثير، الكامل في التاريخ ج 10 ص 61، 63.\r2) ابن خلكان، وفيات الأعيان ج 2 ص 128.\r3) ابن الأثير، الكامل في التاريخ 9 ص 434، 435."], [15, "إلا أن أهم انعكاس للحالة السياسية على إمام الحرمين، تمثل في المحنة الكبرى التي لحقت بأشاعرة نيسابور بافتعال حقيقي لها من عميد الملك أبي نصر الكندري (415 - 457 ه‍/ 1024 - 1604 م)، الذي كان بمثابة الوزير الأول للسلطان السلجوقي طغرلبك. فقد حرض هذا الوزير وأوغر صدر السلطان على ملاحقة الأشاعرة والتنكيل بهم، ومن ثم لعن شيخهم أبي الحسن الأشعري من على منابر مساجد نيسابور 1. وقد سوغت هذه الملاحقة من قبل السلطة السلجوقية الحاكمة بالحرص على تنقية العقيدة السنية في الصفات الإلهية من التقريرات الأشعرية المنافية لها 2. لكن حقيقة الأمر أن هذه التسويغات لم تكن إلا بمثابة تمويهات لدوافع سياسية أخفاها عميد الملك الكندري.\rوقد دفعت هذه المحنة بالجويني وأقطاب الأشاعرة في نيسابور كالبيهقي (- 456 ه‍/ 1063 م) والقشيري (- 465 ه‍/ 1072 م) والرئيس الفراتي إلى الهرب منها، واتجهوا إلى الحجاز 3، حيث كانت السلطة هناك للخلافة الفاطمية.\rلكن هذا الضيم الذي لحق بإمام الحرمين وأصحابه من الأشاعرة لم يدم طويلا، فبعد وفاة طغرلبك، وتسلم ألب أرسلان، السلطة، عزل هذا السلطان عميد الملك الكندري وقتله 4، ثم استوزر نظام الملك (غياث الدولة) الذي كان يتمذهب للشافعي في الفروع وللأشعري في الأصول 5. فسارع نظام الملك إلى إعادة الاعتبار لأشاعرة نيسابور بخاصة، وأشاعرة الحواضر الإسلامية الأخرى بعامة، فرجع الجويني وأقرانه إلى نيسابور معززين مكرمين، وربطت الجويني بهذا الوزير علاقات حميمة أثمرت عدة مؤلفات أهداها الجويني له وعنونها باسمه 6.\r***\r_______________\r1) الذهبي، تاريخ الإسلام، حوادث (441 - 460) ص 13، والشيرازي، المعونة في الجدل، مقدمة المحقق ص 17.\r2) ابن كثير، البداية والنهاية ج 12 ص 64.\r3) السبكي، طبقات الشافعية الكبرى ج 4 ص 271.\r4) ابن خلكان، وفيات الأعيان ج 5 ص 142.\r5) السبكي، طبقات الشافعية ج 4 ص 312.\r6) مثل غياث الأمم في التياث الظلم، والنظامية في الأركان الإسلامية."], [16, "ساهمت الحالة السياسية المضطربة التي عمت الديار الإسلامية في هذا العصر وعلى نحوفاعل في تردي الحالتين الاقتصادية والاجتماعية في مختلف أرجاء العالم الإسلامي آنذاك، ففي بغداد والموصل ونيسابور استفحل أمر العيارين، واشتد خطرهم، حيث لم يردعهم رادع، وكأن أصحاب الشوكة قد غضوا الطرف عنهم لإلهاء الناس بهمومهم الحياتية، وبذلك تصرف أنظارهم عما يدور حولهم من أحداث سياسية وعسكرية.\rوأخذ العيارون في هذه المدن وغيرها، يغيرون في وضح النهار على البيوت والمحال التجارية، ويسرقون ما تقع عليه أيديهم، ويفرضون عليهم الخوات 1، وإذا ما خابت مساعيهم، تحولوا إلى إيقاع الأذى والإهانات بهؤلاء الناس، لعلهم يدلونهم على المكان الذي يخفون فيه مدخراتهم وصرائرهم 2، وكانت الشرطة لا تجرؤ على توفير الحماية لهؤلاء المساكين خوفا من أن تمتد يد القتل إليهم 3.\rوقد وزع العيارون شوارع المدن التي كانوا يعيثون بها فسادا بينهم، مما حدا بكثير من الأهالي والتجار إلى سد مداخل زواريبهم بأعمدة حديدية 4.\rلكن ذلك لم يجد نفعا، وبقي الناس تحت رحمة العيارين، أما الخليفة فقد كان أعجز من رعيته في دفع شرهم، إذ طالما تعرضت دار الخلافة إلى السرقة والنهب 5.\rولم يقتصر أذى العيارين على السرقة والنهب وفرض الخوات، وإنما تعدى ذلك بإعلان مظاهر الفسق والفجور وشرب الخمر، وإقامة حفلات الرقص ليلا ونهارا حتى في شهر رمضان المبارك.\rوقد أطنب المؤرخون في ذكر هذه المظاهر، ومن الأمثلة التي يروونها، قصة ذلك الشيخ المسكين الذي مر في طريقه إلى المسجد بمجلس للغناء والرقص أقامه العيارون في شهر\r_______________\r1) ابن الجوزي، المنتظم ج 7 ص 153، وابن الأثير، الكامل في التاريخ ج 9 ص 353.\r2) ابن الجوزي، المنتظم ج 8 ص 22، وابن الأثير، الكامل في التاريخ ج 9 ص 353.\r3) ابن الجوزي، المنتظم ج 7 ص 287، وابن الأثير، الكامل في التاريخ ج 9 ص 432.\r4) ابن الأثير، الكامل في التاريخ ج 9 ص 353.\r5) ابن الجوزي، المنتظم ج 8 ص 82،192."], [17, "رمضان، فأرغموه على مجالستهم ومعاقرة الخمر، ومواقعة الراقصة التي كانت برفقتهم 1.\rكذلك، فشت في الحواضر الإسلامية بما فيها نيسابور ظاهرة البغاء، وأصبح لها قوانين خاصة 2، فكان للبغايا أحياء ومنازل وأعلام خاصة، وتقدم لهن الحماية من عساكر السلطان مقابل ضرائب كن يدفعنها لخزينة السلطنة، وكان السلطان البويهي عضد الدولة يسوغ عمل البغايا بحماية نساء الرعية من رجالات وعزاب عسكره 3.\rولم تكن مجالس الشرب والرقص والغناء في هذا العصر حكرا على العيارين، وإنما سادت مجالس الأغنياء والعديد من العلماء والأدباء والشعراء 4. كما انتشرت في هذا العصر بيوت النخاسين التي أصبحت مراكز لبيع الجواري والغلمان والخصيان، وكان البعض منها بمثابة نواد ليلية تقام فيها حفلات الرقص والغناء والمجون 5.\rوفي ظل انشغال السلاطين عن أمور الرعية، كثر قطاع الطرق والقتلة والخارجون على القانون، وأصبح كثير من الطرق التي تربط الحواضر الإسلامية تحت رحمة هؤلاء وغير آمنة، مما دفع كثير من الناس إلى الإحجام عن أداء فريضة الحج، كما سبب لجوء بعض قطاع الطرق إلى احتجاز بعض قوافل الحجاج كرهائن لتصفية حسابات بينهم وبين السلطات الحاكمة 6 توقف البعثات الرسمية التي كانت ترافق الحجاج من سائر البلدان إلى مكة المكرمة 7.\rأما الأعياد في هذا العصر فكانت مناسبات ينتظرها الأثرياء لإظهار\r_______________\r1) ابن الأثير، الكامل في التاريخ ج 9 ص 307.\r2) آدم متز، الحضارة الإسلامية ج 2 ص 175.\r3) المصدر نفسه ج 2 ص 174 (نقلا عن البيروني، كتاب الهند ص 279).\r4) أحمد أمين، ظهر الإسلام ج 2 ص 22.\r5) المصدر نفسه ج 2 ص 22.\r6) ابن الأثير، الكامل في التاريخ ج 9 ص 105.\r7) المصدر نفسه ج 9 ص 356،363،370،427."], [18, "الغنى والجاه وسعة العيش، وكانت الشوارع في أيام العيد تزين بالأعلام والأقمشة ذات الألوان الزاهية، وتضرب الطبول بها 1.\rوإضافة إلى عيدي الفطر والأضحى، كان الشيعة يحتفلون بعيد الغدير الذي أوصى فيه الرسول صلى الله عليه وسلم-حسب اعتقادهم-بالإمامة لعلي بن أبي طالب كرم الله وجهه، وبيوم عاشوراء، لكن الاحتفالات بهذين العيدين كانت تؤدي في أغلب الأحيان إلى فتن واحتكاكات غير سارة بين الشيعة وأهل السنة 2.\rوكان المجتمع في ذلك العصر ينقسم إلى ثلاث طبقات، أعلاها طبقة الخاصة، وتتكون من كبار أعوان الخليفة والسلطان، والأشراف، والوزراء، والقضاة، وأكابر العلماء والأدباء، وكبار ملاك الأراضي والأغنياء، وقادة العسكر 3. بينما كانت الطبقة الوسطى تتكون من التجار متوسطي الدخل، وملاك الأراضي الصغار، والجند 4. أما أدنى هذه الطبقات وأكبرها فهي طبقة العامة، وكانت تتكون من الحرفيين، وصغار الفلاحين، والعمال، والعبيد، والغلمان، والجواري، ونحوهم 4.\rوكانت الفروق بين هذه الطبقات كبيرة جدا، إذ كانت الأموال تتدفق على الطبقة الخاصة من مصادر أغلبها خفية، فامتلأت بيوت رجالاتها بالجواري والغلمان والخصيان والعبيد 5. كذلك كثر البذخ في هذه الطبقة، وكانت تلجأ في كثير من الأحيان لإشباع جشعها، إلى فرض الغرامات الباهظة على التجار، فإن رفضوا ذلك سلطوا عليهم الجند والعيارين 6. كذلك لم تكن العلاقات بين أفراد هذه الطبقة وطيدة، بل على العكس من ذلك، فقد غلب عليها التحاسد والتباغض، وإيقاع بعضهم ببعض، وكانوا كثيرا ما يدبرون المكائد لمصادرة أموال وأملاك المتوفين منهم، والمعارضين لسياسات صاحب الشوكة 7.\r_______________\r1) ابن الأثير، الكامل في التاريخ ج 9 ص 155 - 156.\r2) أحمد أمين، ظهر الإسلام ج 2 ص 12.\r3) المصدر نفسه ج 2 ص 12.\r4) المصدر نفسه ج 2 ص 12.\r5) آدم متز، الحضارة الإسلامية في القرن الرابع الهجري ج 1 ص 158.\r6) أحمد أمين، ظهر الإسلام ج 2 ص 13.\r7) ابن الأثير، الكامل في التاريخ 9 ص 110."], [19, "أما الطبقة الوسطى فكانت دائما تقع ضحية أطماع رجالات الطبقة الخاصة إذا ما أتى عليهم الزمان 1. وفي الوقت نفسه كانت فريسة سهلة لأعمال السلب والنهب التي كانت تقوم بها طبقة العامة، وعلى الأخص أيام القحط والمجاعة 2.\rوإضافة إلى هذه الطبقات، كان يوجد في الديار الإسلامية مجتمع أهل الكتاب من يهود ونصارى، وكان هؤلاء يتمتعون بالحرية الكاملة لإقامة شعائرهم الدينية، بفعل سياسة التسامح التي كان ينتهجها حكام ذلك العصر بخاصة، والمسلمون بعامة تجاههم 3. ولا نجد في المصادر التاريخية التي أرخت لتلك الفترة أي إشارة لمحنة وقعت بأهل الكتاب، سوى تلك المحنة التي لحقت بيهود ونصارى مصر أيام الخليفة الفاطمي الحاكم بأمر الله 4 (- 411 ه‍). ونجد في هذه المصادر إشارات واضحة إلى مشاركة الخليفة العباسي للنصارى واليهود في أعيادهم واحتفالاتهم، وكان يزور أديرتهم في بعض المناسبات، فيغدق عليهم بالهبات والعطايا، وكذلك كان يفعل السواد من المسلمين، إذ كانوا يشاركونهم في أعيادهم وأفراحهم وأتراحهم 5.\r\r***\rكان للأحداث والاضطرابات السياسية في ذلك العصر الأثر الأكبر في تردي أحوال الناس الاقتصادية، ومما كان يعمق تردي هذه الأحوال، الصراع الدائم بين طبقات المجتمع السالفة الذكر، والفتن الدينية التي كان يستعر أوارها بين المذاهب الإسلامية المختلفة. فعند ما كانت تقع الاضطرابات على اختلاف أسبابها في بلد ما، سرعان ما ترتفع أسعار المواد الغذائية والسلع الاستهلاكية، مما ينعكس سلبا على قدرة العامة في تأمين ما يقوتها، ويؤدي\r_______________\r1) أحمد أمين، ظهر الإسلام ج 2 ص 13، 14.\r2) زهير كبي، الإجماع ص 101.\r3) حسن حسن، تاريخ الإسلام السياسي ج 4 ص 627.\r4) ابن كثير، البداية والنهاية ج 12 ص 77.\r5) حسن حسن، تاريخ الإسلام السياسي ج 4 ص 627، وأحمد أمين، ظهر الإسلام ج 2 ص 22، 23."], [20, "بالتالي إلى تفشي أعمال السرقة والنهب، وفي بعض الحالات كانت هذه الأعمال تتخطى ذلك لتطال بيوت الحكام ودار الخلافة نفسها 1.\r\rوقد نقل المؤرخون تفاصيل دقيقة عن سنوات القحط والمجاعة التي عمت الديار الإسلامية في ذلك العصر، كالمجاعة الشديدة التي عمت نيسابور وكامل خراسان، فاشتد الغلاء، واختفت السلع الغذائية من الأسواق، مما دفع الناس إلى قتل بعضهم بعضا «فكان الإنسان يصيح: الخبز الخبر فيموت» 2.\r\rوفي سنة 439 ه‍/ 1047 م اشتد الغلاء في البلاد كافة، مما اضطر الناس إلى أكل الميتة والكلاب والبغال 3. ومما كان يزيد الحالة الاقتصادية سوءا، كثرة الحرائق التي كانت تحدث في أغلب الأحيان بفعل النزاعات والفتن المذهبية، كالحريق الذي أصاب نيسابور في أثناء مهاجمة شيعة طوس وأبيورد لها 4، والحريقين الهائلين اللذين أصابا بغداد سنة 417 ه‍/ 1026 م وسنة 467 ه‍/ 1045 م 5.\r\rومما ساعد أيضا على تفاقم الحالة الاقتصادية، العوامل الطبيعية التي عمت أرجاء العالم الإسلامي، إذ كثرت الزلازل والبراكين والهزات الأرضية، كما كثرت الأوبئة والأمراض الفتاكة، فكثر الموت بين الناس حتى عجزوا أحيانا عن دفن موتاهم 6.\r\rأما مصادر الدولة المالية، فكانت تعتمد إجمالا على الزكاة، والخراج، والجزية، وما يفرض من ضرائب على الأرض الزراعية، والمحال التجارية، وأصحاب الحرف 7، وكان الحكام والأمراء عند ما تضيق بهم الأحوال يلجأون إلى مصادرة الأموال، وزيادة الضرائب، مما دفع بالكثير من الأغنياء\r_______________\r1) ابن كثير، البداية والنهاية ج 12 ص 77.\r2) ابن الأثير، الكامل في التاريخ ج 9 ص 225.\r3) ابن الجوزي، المنتظم ج 7 ص 301.\r4) ابن الأثير، الكامل في التاريخ ج 9 ص 434.\r5) المصدر نفسه ج 9 ص 349، ج 10 ص 97.\r6) المصدر نفسه ج 9 ص 438، وابن الجوزي، المنتظم ج 7 ص 276.\r7) آدم متز، الحضارة الإسلامية في القرن الرابع الهجري ج 2 ص 174."], [21, "إلى إخفاء ثرواتهم في أماكن سرية في الصحاري، أوفي مزارعهم وبيوتهم 1.\rوقد دفعت هذه السياسات الاقتصادية التعسفية بعض أصحاب الأراضي الزراعية وكبار التجار إلى نظام الالتجاء الذي كان سائدا في ذلك العصر 2.\rفكان هؤلاء يعمدون، هربا من الضرائب أوخوفا من مصادرة أموالهم، إلى كتابة أراضيهم أومحالهم التجارية بأسماء بعض أصحاب الشوكة، أومن يطمئنون إليه من الأمراء وذوي النفوذ، فتخفف عنهم الضريبة بذلك إلى النصف أوالربع، لكن جشع هؤلاء الحماة أوالمتنفذين، كان يؤدي في أغلب الأوقات إلى ادعاء ملكية ما كتب بأسمائهم، وبذلك تقع الخسارة الفادحة على أصحابها الحقيقيين.\r_______________\r1) أحمد أمين، ظهر الإسلام ج 2 ص 8.\r2) المصدر نفسه ج 2 ص 14."], [22, "الفصل الثاني: الحالة الدينية في عصر الجويني:\r"]], "pg": [9, 22]}, "474.3": {"x": [[22, "شهد عصر إمام الحرمين حالة دينية متأزمة، بفعل الصراعات السياسية الدائمة بين أصحاب الشوكة وسلاطين الدويلات التي كانت تتحكم برقاب العباد آنذاك، إذ لجأ بعض هؤلاء السلاطين انتصارا للمذهب الذي كانوا عليه، إلى اضطهاد المذاهب الأخرى وملاحقتهم وحسر نشاطهم، ويظهر ذلك جليا باضطهاد عميد الملك أبي نصر الكندري لأشاعرة نيسابور 1، وبملاحقة السلطان محمود الغزنوي للمعتزلة والرافضة في الري بخاصة وبلاد خراسان بعامة 2، وبما أظهره البويهيون من حرص على دعم المذاهب الشيعية من إسماعيلية واثني عشرية في مناطق نفوذهم، واستقوائهم على الخليفة العباسي من خلال العلاقات الوثيقة التي أقاموها مع الخلافة الفاطمية في مصر 3.\rوقد أدت الحالة الدينية المتأزمة هذه، إلى شيوع الفتن المذهبية، بحيث أصبحت هذه الفتن سيارة في مختلف أرجاء العالم الإسلامي، وكثيرا ما كانت تؤدي إلى إراقة الدماء بين القوى الدينية المتناحرة. وكان يغذي هذا الصراع، الخلاف المذهبي بين أهل السنة من جهة، والمعتزلة والشيعة بفرعيها الإسماعيلي والاثني عشري من جهة أخرى، إضافة إلى الخلافات الحادة التي كانت تحصل بين المذاهب السنية نفسها، وعلى الأخص ما بين متكلمة الأشاعرة وأتباع المذهب الحنبلي في بغداد.\r_______________\r1) ابن كثير، البداية والنهاية ج 12 ص 65.\r2) ابن الأثير، الكامل في التاريخ ج 9 ص 372.\r3) الذهبي، تاريخ الإسلام، حوادث (441 - 460) ص 29."], [23, "ومن المفارقات في هذا العصر، ذلك التحالف غير المعلن الذي حصل بين المعتزلة والشيعة الاثني عشرية، بتشجيع ومباركة من سلاطين بني بويه المتشيعين، ويمكن أن يفسر هذا التحالف حاجة كل من هذه الأطراف إلى بعضها البعض، فالمعتزلة في ظل ملاحقة المؤسسة السنية الرسمية، والمتمثلة بالخلافة العباسية، كانوا بأمس الحاجة إلى من يحميهم ويوفر لهم المناخ المناسب لتوسيع دائرة نشاطهم، فوجدوا في بني بويه وما يمثلون من شوكة، الجهة الأنسب لتحقيق هذا الهدف 1.\rأما شيعة ذلك العصر، وإن كانوا يرون في المعتزلة خصما عنيدا لمقولاتهم السياسية 2، إلا أن كثيرا من المسائل الاعتقادية عندهم كالعدل والتوحيد واللطف، قد تشكلت بتأثير قوي من المعتزلة 3. لذا غضت الشيعة النظر عن نقاط الاختلاف مع المعتزلة، ورأت فيهم سندا قويا في مواجهاتهم الكلامية مع الفرق السنية.\rأما البويهيون، فكانوا يجدون في الشيعة والحركة الاعتزالية عصا غليظة يلوحون بها في وجه الخليفة العباسي إذا ما حاول تأليب الرأي العام السني ضدهم.\rاستفادت المعتزلة من هذا التعاون، فنشط رجالاتها في نشر الاعتزال والدفاع عنه أمام الخصوم، واتخذوا من مدينة الري مركزا لأنشطتهم، والدعوة إلى مذهبهم 4.\rولم يكن الخليفة العباسي أمام ما يمثله هذا التحالف من قوة، قادرا على مواجهة المعتزلة، واكتفى بالدور الذي تؤديه الفرق الكلامية السنية كالأشاعرة والماتريدية وجمهور الحنابلة في الرد على مقولات المعتزلة الاعتقادية.\r_______________\r1) انظر: ياقوت الحموي، معجم الأدباء ج 6 ص 190.\r2) قارن: الشريف المرتضى، الشافي في الإمامة ص 70، 167، والقاضي عبد الجبار، المغني في التوحيد والعدل ج 20 ق 1 ص 57، 100.\r3) زهدي جار الله، المعتزلة ص 215،216.\r4) المصدر نفسه، المعتزلة ص 218."], [24, "وقد خرج الخليفة العباسي القادر بالله من عجزه هذا، بفعل ضغط الرأي العام السني عليه، وعلى نحوأخص من الفقهاء والمحدثين الحنابلة، فتوعد المعتزلة بالعقاب الشديد إن استمروا في الدعوة إلى مذهبهم 1. لكن أركان الاعتزال لم يلتفتوا إلى هذا الوعيد، واستخفوا به لمعرفتهم بحالة الضعف التي آل إليها هذا الخليفة، ولا طمئنانهم إلى القوة التي يمثلها حماتهم من بني بويه 2.\rغير أن الخليفة قد خطا خطوة أخرى تصعيدية في وجه المعتزلة، إذ أصدر وبتحريض قوي من الفقهاء والمتكلمين السنة كتابا سمي بالاعتقاد القادري 3، نسبة إلى القادر بالله، أكد فيه أصول أهل السنة الاعتقادية، وحدد فيه أيضا القضايا التي خالفت بها المعتزلة والشيعة هذه الأصول، كقضية خلق القرآن، والصفات الإلهية، والترضي عن الصحابة 4، وأعلن في هذا الكتاب «أن من يدعي أن القرآن مخلوق على حال من الأحوال، فهوكافر حلال الدم بعد الاستتابة منه» 5.\rوقد ساند الفقهاء السنة الخليفة العباسي في خطوته هذه، فمهروا الاعتقاد القادري بتوقيعاتهم، وأجمعوا على أن ما ورد فيه هومعتقد أهل السنة، وأن من خالفه فقد كفر وفسق، ثم أخذوا يقرؤونه من على المنابر في بغداد، وسائر الحواضر الإسلامية 6.\rلكن الضربة القاسية التي قسمت ظهر المعتزلة في ذلك الوقت، كانت على يد السلطان محمود الغزنوي، إذ سارع هذا السلطان عند ما انتزع مدينة الري من البهويهيين عام 420 ه‍/ 1029 م، إلى البطش بهم، ونفاهم إلى خراسان، وأمر بحرق كتبهم ومكتباتهم 7، فأحرقت مكتبة الصاحب بن عباد،\r_______________\r1) ابن الجوزي، المنتظم ج 7 ص 287، وآدم متز، الحضارة الإسلامية ج 1 ص 381.\r2) زهدي جار الله، المعتزلة ص 221، 222.\r3) ابن الجوزي، المنتظم ج 8 ص 109.\r4) ابن الجوزي، المنتظم ج 8 ص 109.\r5) المصدر نفسه ج 8 ص 110.\r6) المصدر نفسه ج 8 ص 110.\r7) ابن الأثير، الكامل في التاريخ ج 9 ص 372."], [25, "25 وكانت من أضخم المكتبات الخاصة في تلك النواحي، إذ كان فهرسها يقع في عشرة مجلدات 1، وبذلك خسرت المكتبة الإسلامية آلافا من الكتب المختلفة.\r***\rاشتد الخلاف السني الشيعي في هذا العصر، وأصبح جسد الأمة الإسلامية ينزف يوميا، بفعل الفتن الأليمة التي كانت تحدث بين الطرفين، ويؤجج نارها ذوالمصالح السياسية والدينية من أمراء وسلاطين وفقهاء.\rوكان يغذي هذا الصراع أيضا، ما كان يظهره الشيعة في احتفالاتهم بالمناسبات الدينية، حيث كان يكثر فيها لعن معاوية بن أبي سفيان 2. وكان هذا اللعن يطال أحيانا الخلفاء الثلاثة الأول بطريقة خفية 3.\rكذلك لعبت الكتابات الاستفزازية التي كانت تغطي المساجد وجدران المحال والبيوت الشيعية 4، دورا أساسيا في استمرار التوتر والاحتقان السني الشيعي، وكان كل ذلك يتم برضى وتحريض من السلطان البويهي 5.\rأما في الجانب السني، فقد أدى التشدد الذي كانت تبديه بعض الأطراف السنية تجاه المقولات الشيعية، وعدم الاعتراف بهم ككيان مذهبي له تمايزاته في الأصول والفروع، إلى جعل الفتن بين الطرفين بمثابة أحداث مألوفة تتكرر عبر السنين والأيام.\rففي عام 425 ه‍/ 1033 م حدث في نيسابور-حيث نشأ إمام الحرمين- فتنة عظيمة بين أهلها من السنة، وبين أهالي طوس وأبيورد من الشيعة 6، إذ استغل أهالي هاتين البلدتين خروج والي هذه المدينة منها، وقاموا بالتوجه نحوها وأحدثوا فيها أعمال الشغب والنهب، فقام والي كرمان بنجدة أهل\r_______________\r1) ياقوت الحموي، معجم الأدباء ج 2 ص 315.\r2) ابن الأثير، الكامل في التاريخ ج 8 ص 542.\r3) المصدر نفسه ج 8 ص 542.\r4) ابن الجوزي، المنتظم ج 8 ص 149.\r5) ابن الأثير، الكامل في التاريخ ج 8 ص 542.\r6) ابن الجوزي، المنتظم ج 7 ص 283."], [26, "نيسابور وقاتل معهم، واشتدت الحرب بين الطرفين، فانهزم الشيعة، وأسر الكثير منهم، وصلب بعضهم في الطرقات وعلى الأشجار ويقال: إنه قد أعدم خلق كثير منهم، ثم أخذ والي كرمان بعضهم كرهائن، وأودعهم السجون، وهدد أهالي طوس وأبيورد بقتلهم إن كرروا مهاجمتهم نيسابور 1.\rأما في بغداد، فكان الاحتكاك اليومي المباشر بين شيعة حي الكرخ، وسنة باب البصرة، وباب نهر القلايين، يولد أحداثا مأساوية، وكثيرا ما كانت الدماء تسيل بين الطرفين نتيجة هذا الاحتكاك.\rومن هذه الفتن ما حدث في بغداد عام 420 ه‍/ 1029 م، إذ قال أحد مشايخ الشيعة في خطبة له يوم جمعة، بعد أن صلى على النبي صلى الله عليه وسلم «وعلى أخيه أمير المؤمنين علي بن أبي طالب، مكلم الجمجمة، ومحيي الأموات البشري، الإلهي، مكلم فتية أهل الكهف، إلى غير ذلك من الغلووالابتداع» 2، فاستبدل بهذا الخطيب خطيب آخر من السنة، ولما نزل من على المنبر، هاجمه المصلون، فأحرقوه، «وأعروه وأعروا ولده وحرمه» 3، فما كان من الخليفة إلا أن استدعى أعيان الشيعة وأمرهم بتهدئة الأمور، واتفق معهم على تعيين خطيب آخر أكثر اعتدالا يحرسه كبار العسكر 4.\rوفي عام 443 ه‍/ 1051 م قام شيعة حي الكرخ بالكتابة على أبراج قد بنوها «محمد وعلي خير البشر». فادعى أهل السنة أن أصل الكتابة كانت «محمد وعلي خير البشر، فمن رضي فقد شكر، ومن أبى فقد كفر» 5. إلا أن الشيعة قد أنكرت هذه الزيادة، وأيدهم في ذلك بعض مؤرخي أهل السنة 6.\rوقد أدت الكتابات الاستفزازية هذه إلى حدوث صدام دموي بين الطرفين، ذهب ضحيته خلق كثير 7، ونبش جهال أهل السنة المشهدين\r_______________\r1) ابن الأثير، الكامل في التاريخ ج 9 ص 435.\r2) المصدر نفسه ج 9 ص 393.\r3) ابن الجوزي، المنتظم ج 8 ص 43.\r4) المصدر نفسه ج 8 ص 43.\r5) المصدر نفسه ج 8 ص 149.\r6) انظر: المصدر نفسه ج 8 ص 149، وابن الأثير، الكامل في التاريخ ج 9 ص 576.\r7) ابن الجوزي، المنتظم ج 8 ص 150."], [27, "الخاصين بالإمامين الخامس والسابع عند الشيعة، محمد الجواد وموسى بن جعفر 1. أما جهال الشيعة فقد نبشوا مقابل ذلك قبور أعيان السنة، ثم هموا بقبر الإمام أحمد بن حنبل، إلا أنهم منعوا من ذلك 2.\rوبظهور دولة السلاجقة في المشرق الإسلامي، انحسر النشاط الشيعي هناك، ولا تشير المصادر إلى وقوع فتن ذات بال في نيسابور وغيرها من المناطق. وقد استفاد سنة بغداد من دخول السلاجقة مدينتهم، واستقووا بهم على الشيعة، وأصبحت كلمتهم نافذة حتى في الأحياء الشيعية نفسها، حيث أجبر الشيعة عام 448 ه‍/ 1056 م على الأذان في مساجدهم بالصيغة السنية 3، كما أزيلت الكتابات الاستفزازية في مساجدهم وشوارعهم، وأخذ المتشددون من السنة يطوفون ممرات حي الكرخ هاتفين بمآثر الصحابة جميعا 4. ثم أمر رئيس العسكر السلجوقي بقتل أحد أعيان الشيعة أبي عبد الله الجلاب، فقتل وصلب على باب دكانه 5، ثم هاجمت الجموع السنية دار شيخ الطائفة أبي جعفر الطوسي، لكنه لاذ بالفرار بعد ما أحرقت كتبه وداره 6.\rأما الشيعة، فقد انتهزوا حركة التمرد التي قام بها أبوالحارث البساسيري، فسهلوا لعسكره المرور في طرقاتهم 7، ثم هاجموا الأحياء السنية، ونهبوا المحال والبيوت، وأجبروا أهل السنة على الأذان بالصيغة الشيعية في مساجدهم 8.\rلكن الأمر لم يدم طويلا، فبعد مقتل البساسيري وعودة الخليفة والسلاجقة إلى بغداد، ضيق الخناق على الشيعة، وحظر عليهم ما كانوا يظهرونه في عاشوراء، ويوم الغدير من النوح والضرب والشتم 9.\rوقد جرى رغم هذه الصدامات، عدة محاولات للتقارب والصلح بين\r_______________\r1) ابن الأثير، الكامل في التاريخ ج 9 ص 577.\r2) ابن كثير، البداية والنهاية ج 12 ص 62.\r3) ابن الجوزي، المنتظم ج 8 ص 172.\r4) المصدر نفسه ج 8 ص 172.\r5) المصدر نفسه ج 8 ص 172.\r6) المصدر نفسه ج 8 ص 172.\r7) ابن كثير، البداية والنهاية ج 12 ص 77.\r8) المصدر نفسه ج 12 ص 77،78.\r9) ابن الجوزي، المنتظم ج 8 ص 240."], [28, "الطرفين، كان أهمها تلك المحاولة الرائدة التي حدثت عام 442 ه‍، واجتمع فيها العامة من السنة والشيعة على كلمة واحدة، وسار شيعة حي الكرخ إلى الحي السني في نهر القلايين فصلوا فيه، وخرج الجميع إلى زيارة المشاهد والصلاة بها، ثم أخذ شيعة حي الكرخ يترحمون على الصحابة في مساجدهم 1. لكن هذه الموادعة لم تدم طويلا، إذ سارع المتضررون من وحدة الكلمة إلى إفسادها والقضاء عليها في مهدها.\r***\rشهد هذا العصر أيضا صراعا دينيا حادا بين أهل السنة المستظلين بالخلافة العباسية وحماتها من السلاجقة، والشيعة الإسماعيلية، المتمثلة رسميا بالخلافة الفاطمية في مصر، وأتباعها في بلاد الشام، والحجاز.\rولم يأل الفاطميون جهدا في نشر المذهب الإسماعيلي في هذه المناطق، معتمدين في ذلك على إرسال الدعاة الحذقين إليها من حين لآخر 2، ومما زاد الطين بلة، الانشقاق الكبير الذي حدث بين صفوف الإسماعيلية في مصر، وأدى إلى ظهور المذهب الدرزي، واللافت للنظر في هذا المقام، ذلك التحالف الذي نشأ بين الشيعة الإسماعيلية، وأهل السنة في مصر، بقصد مقاومة الحركة الدرزية الناشئة 3، مما اضطر بعض أقطابها إلى الهرب نحوبلاد الشام والدعوة لمقولاتهم الغالية هناك 4.\rكذلك لعب الخليفة العباسي دورا أساسيا في مقاومة الانتشار الفاطمي، إذ تمكن من جمع أعيان وفقهاء السنة والشيعة في بغداد، وعقدوا مجلسين صدر عنهما القدح في نسب الفاطميين، وأنهم لا يمتون بصلة إلى آل البيت، وما ادعوه باطل وزور، وأنهم خارجون عن الإسلام، ويرجع نسبهم إلى\r_______________\r1) ابن الجوزي، المنتظم ج 8 ص 145، وابن الأثير، الكامل في التاريخ ج 1 ص 561.\r2) حسن حسن، تاريخ الإسلام السياسي ج 3 ص 150، 151.\r3) ابن تغري بردي، النجوم الزاهرة ج 4 ص 183، وحسن حسن، تاريخ الإسلام السياسي ج 4 ص 261.\r4) بروكلمان، تاريخ الشعوب الإسلامية ص 255."], [29, "ميمون القداح من اليهود 1.\rإلا أن الخطوة الأهم في مقاومة الامتداد الشيعي بمذاهبه المختلفة في مناطق الخلافة العباسية، تمثلت في بناء نظام الملك للمدارس النظامية، إذ وعى هذا الوزير أن الجهود العسكرية وحدها لن تفلح في الحد من التمدد الشيعي، إن لم يواكبها حركة فكرية تعمل على نشر العقيدة السنية، وتحصينها في مواجهة خصومها، فعمل على بناء النظاميات في كل من بلخ ونيسابور والموصل وبغداد ليتخرج منها العلماء والدعاة، واستطاعت هذه المدارس أن تؤدي دورا فاعلا في انحسار الامتداد الشيعي والاعتزالي على حد سواء.\r***\rلم يقتصر الصراع الديني في هذا العصر على المحاور الثلاثة السابقة، وإنما كانت له مشاهده المؤلمة بين المذاهب السنية نفسها، وعلى الأخص ما بين الحنابلة من جهة، والأشاعرة والشافعية من جهة أخرى.\rفالنشاط الفقهي في هذا العصر بقي أسيرا للقواعد الفقهية التي أرساها الأئمة الأربعة وأتباعهم في العصور السابقة، لذا فشت روح التقليد بين المذاهب 2، وتعمق التعصب للمذهب المتبع، وكثر النيل من المذاهب الأخرى، مما أدى إلى وقوع الأحداث الأليمة بين أتباع المذاهب الفقهية المختلفة، وكان أكثرها إيلاما تلك المصادمات العنيفة التي كانت تحدث من حين لآخر بين الشافعية والحنابلة. ففي عام 447 ه‍/ 1055 م قام الحنابلة في بغداد عامتهم وخاصتهم بمهاجمة الشافعية في الجامع المخصص لهم، وأنكروا عليهم الجهر بالبسملة، والترجيع في الأذان، والقنوت في صلاة الفجر، وبقي الشافعية فترة لا يستطيعون حضور الجمعة ولا الجماعات 3\r_______________\r1) ابن الجوزي، المنتظم ج 7 ص 255، ج 8 ص 154، 155، وابن الأثير، الكامل في التاريخ ج 9 ص 236 وج 9 ص 591.\r2) محمد الخضري، تاريخ التشريع الإسلامي ص 323.\r3) ابن الأثير، الكامل في التاريخ ج 9 ص 614، وابن كثير، البداية والنهاية ج 12 ص 16."], [30, "ولم يكن الشافعية أكثر تسامحا من الحنابلة، إذ عمد بعض أقطابهم في مجالسهم العلمية إلى النيل من الحنابلة وتسفيه آرائهم كأبي حامد الإسفراييني والخطيب البغدادي الذي كان «يقدح في الحنابلة ما أمكنه وله دسائس عجيبة في ذمهم» 1.\rومن مظاهر التوتر التي سادت العلاقات بين المذاهب الفقهية، كثرة عقد مجالس المناظرات بين أعيان المذاهب، بتحريض واضح من الأمراء والوزراء، بقصد إعلاء شأن بعض المذاهب، والحط من منزلة المذاهب الأخرى، مما دفع الخلص من علماء هذا العصر، إلى التأليف في قواعد المناظرة وآدابها للتخفيف من الغلواء التي كانت تسود المناظرات في هذه المجالس 2.\r***\rإن المخاشنات التي طبعت العلاقات بين بعض ممثلي المذاهب الفقهية في هذا العصر، ليست بذي بال إذا ما قورنت بالصدامات العنيفة التي وقعت بين المذاهب الكلامية السنية، وعلى الأخص في نيسابور وبغداد.\rففي نيسابور وما جاورها علا شأن الأشعرية، وأخذت تتقدم غيرها من المذاهب بعد ما كانت السيادة في عقود سابقة للمذهب الماتريدي 3. ويمكن أن يفسر هذا التقدم بكثرة أعلام الأشاعرة البارزين في تلك الديار؛ كالباقلاني وابن فورك وأبي إسحاق الإسفراييني وأبي منصور البغدادي والبيهقي وأبي القاسم القشيري وإمام الحرمين، فهؤلاء الأعلام قاموا بجهود كبيرة في تخريج التلامذة على مذهب أبي الحسن الأشعري، وقاموا بالدفاع عنه، ونشره وتحصينه أمام الخصوم من المذاهب الأخرى.\rلكن هذا التقدم قد مني بانتكاسة كبيرة بعد المحنة التي حلت بأشاعرة نيسابور، عند ما استطاع عميد الملك الكندري أن يوغر صدر السلطان طغرلبك\r_______________\r1) ابن كثير، البداية والنهاية ج 12 ص 102.\r2) محمد الخضري، تاريخ التشريع الإسلامي ص 323 - 325.\r3) قارن: النسفي، التمهيد في أصول الدين، مقدمة المحقق ص 19."], [31, "للنيل من الأشاعرة، فبادر إلى إصدار قرار بلعنهم إلى جانب الرافضة في مجالس الوعظ ومن على منابر نيسابور، متهما الأشعري «بالقول في الصفات بخلاف ما يقوله أهل السنة والجماعة» 1. وعند ما وضح وفد أشعري للسلطان موقف الأشاعرة من الصفات الإلهية، وبين له حجم الأذى الذي لحق بهم، أجابهم قائلا «نحن إنما لعنا من يقول ذلك» 2.\rثم أمر الكندري بمنع الأشاعرة من الوعظ والخطابة والتدريس، وسلط عليهم الأوباش فآذوهم، وجروا القشيري والرئيس الفراتي في أسواق نيسابور، ثم أدخلا السجن 3. وتمكن إمام الحرمين من مغادرة نيسابور خفية، واتجه إلى أصبهان حيث العسكر، ومنها غادر إلى بغداد، ومن ثم إلى الحجاز 4. أما البيهقي فقد غادر نيسابور إلى بيهق، ومنها اتجه إلى بغداد وبلاد الحجاز 5.\rلكن أبا سهل بن الموفق لم يرض بما حصل للرئيس الفراتي وأبي القاسم القشيري، وكان خارج نيسابور، فعاد إليها، وجمع بعض أنصاره وهاجم المكان الذي احتجز به القشيري والفراتي، وأخرجهما من هناك بالقوة، لكن عسكر السلطان قبضوا عليه وأودعوه ومن معه السجن، ولم يخرج منه إلا في عهد السلطان ألب أرسلان ووزيره نظام الملك 6. أما أبوالقاسم القشيري، فقد فر إلى بغداد، وهناك اجتمع بإمام الحرمين والبيهقي، وصحبهما إلى الحج 7.\rوقد وجه البيهقي في أثناء إقامته ببيهق رسالة مطولة إلى عميد الملك الكندري، بين فيها الظلم الكبير الذي وقع بالأشاعرة، ثم وضح موافقة المعتقد الأشعري لما جاء في القرآن والسنة، وما سار عليه الصحابة والتابعون 8.\r_______________\r1) الذهبي، تاريخ الإسلام، حوادث (441 - 460) ص 13.\r2) ابن كثير، البداية والنهاية ج 12 ص 65.\r3) السبكي، طبقات الشافعية ج 3 ص 392 وج 4 ص 210.\r4) المصدر نفسه ج 4 ص 210.\r5) المصدر نفسه ج 3 ص 394.\r6) المصدر نفسه ج 3 ص 393.\r7) المصدر نفسه ج 3 ص 394.\r8) ابن عساكر، تبيين كذب المفتري ص 100."], [32, "أما الأشاعرة المبعدون إلى بلاد الحجاز، فقد عقدوا مؤتمرا بمكة المكرمة في موسم الحج، للتظلم مما فعله الكندري بهم، والبحث في سبل الخروج من هذه المحنة، وشاركهم في هذا المؤتمر عدد كبير من الفقهاء الأحناف، بحيث بلغ عدد المؤتمرين أربعمائة من الفقهاء والأصوليين 1.\rواتفق المؤتمر على استفتاء علماء الأمصار فيما جرى، فلما وصل ذلك إلى بغداد قام أبوإسحاق الشيرازي بإصدار فتوى قال فيها: «إن الأشعرية أعيان السنة ونصار الشريعة، انتصبوا للرد على المبتدعة من القدرية والرافضة وغيرهم، فمن طعن فيهم فقد طعن على أهل السنة، وإذا رفع أمر من يفعل ذلك إلى الناظر في أمر المسلمين، وجب عليه تأديبه بما يرتدع به كل أحد» 2. ثم أصدر شيخ الأحناف في بغداد أبوعبد الله الدامغاني فتوى مماثلة 3.\rوقد أثار اتفاق المؤتمرين على هذا الاستفتاء حفيظة السبكي في طبقاته، وعلى الأخص لوجود إمام الحرمين بينهم، إذ يقول: «إذ في وجود مثل إمام الحرمين على ظهر الأرض غنية عن استفتاء غيره من الفقهاء، وإنه ليقبح بأهل إقليم فيهم إمام الحرمين، بل بأهل عصر أن تقع لهم نازلة فلا يصغون إلى فتياه، ويكتبون إلى النواحي يستفتون» 4.\rلكن التساؤل المهم في هذا المقام، هولما ذا أقدم الكندري على التنكيل بالأشاعرة في نيسابور وللإجابة عن ذلك، بحث المؤرخون قديما في هوية الكندري المذهبية، فعزاه مؤرخ الأشاعرة الكبير ابن عساكر إلى مذهب الاعتزال والرفض 5، وأضاف السبكي إلى ذلك فألصق فيه مذهب المجسمة 6، لكن ما ذكره كل من ابن عساكر والسبكي الأشعريين لا يستقيم إذا ما نظرنا إلى هوية السلطان السلجوقي طغرلبك.\r_______________\r1) السبكي، طبقات الشافعية ج 3 ص 394.\r2) ابن عساكر، تبيين كذب المفتري ص 332.\r3) المصدر نفسه ص 332.\r4) السبكي، طبقات الشافعية ج 3 ص 394.\r5) ابن عساكر، تبيين كذب المفتري ص 108.\r6) السبكي، طبقات الشافعية ج 3 ص 390."], [33, "فقد كان هذا السلطان سنيا على مذهب أبي حنيفة، فكيف يستوزر، أويغض النظر عمن هوفي مصاف خصوم أهل السنة، مع حاجته الشديدة إلى رضاهم عنه، وهذا دفع بالسمعاني والذهبي إلى التقليل من شأن هذه الاتهامات، وأشادا بمناقب الكندري ومآثره 1.\rوقد استفاد بعض الباحثين المحدثين من هذه الإشادة، وعزوا كراهية الكندرية للأشاعرة، لأنهم أصبحوا منافسين حقيقيين للأحناف في تلك البلاد، وهذا مما يعرقل جهود السلطان طغرلبك، وعميد الملك الكندري الحنفيين في جعل المذهب الحنفي المذهب الرسمي للدولة 2.\rلكن النص الذي أورده السبكي عن ابن الموفق يدفعنا إلى القول: إن العامل السياسي هوالذي دفع الكندري إلى ملاحقة الأشاعرة بعامة، وابن الموفق بخاصة، إذ يقول: «إن رئيس البلد (نيسابور) الأستاذ أبا سهل ابن الموفق. . . كان ممدحا جوادا ذا أموال جزيلة، وصدقات دارة، وهبات هائلة، ربما وهب الألف دينار لسائل، وكان مرموقا بالوزارة، وداره مجتمع العلماء، ملتقى الأئمة من الفريقين، الحنفية والشافعية، في داره يتناظرون، وعلى سماطه يتلقمون، وكان عارفا بأصول الدين على مذهب الأشعري، قائما في ذلك، مناضلا في الذب عنه، فعظم ذلك على الكندري لما في نفسه من المذهب، ومن بغض ابن الموفق بخصوصه، وخشيته منه أن يثب على الوزارة، فحسن للسلطان لعن المبتدعة على المنابر» 3.\rفهذا النص يشير صراحة إلى تخوف الكندري من أن يثب ابن الموفق على الوزارة، ويستوزره السلطان السلجوقي، لما له من مكانة عالية وجاه عريض، وقد عرضت الوزارة على ابن الموفق في عهد السلطان ألب أرسلان إلا إنه اغتيل قبل تسلمها.\r_______________\r1) السمعاني، الأنساب ج 5 ص 102، والذهبي، تاريخ الإسلام، حوادث (441 - 460) ص 423.\r2) الماوردي، قوانين الوزارة، مقدمة المحقق رضوان السيد ص 54، والبيهقي، الأسماء والصفات، مقدمة المحقق حلمي فودة ص 57\r3) السبكي، طبقات الشافعية ج 3 ص 390."], [34, "هذا في نيسابور، أما في بغداد فلم يكن حال الأشاعرة بأفضل مما كان عليه أخوتهم في نيسابور، فقد استغل الحنابلة نفوذهم القوي لدى العامة والخليفة العباسي للنيل من الأشاعرة، وتحريض العامة ضدهم، ولعنهم من على منابر بغداد 1.\rوعند ما وصل أبونصر القشيري بغداد مبعوثا من نظام الملك ليلقي بعض الدروس في نظاميتها، ثارت ثائرة الحنابلة، والتف حولهم العامة، وهاجموا النظامية، وقتلوا جماعة» 2.\rفحاول الخليفة العباسي وبضغط من نظام الملك إصلاح ذات البين بين الطرفين، إلا أن الشريف أبا جعفر مقدم الحنابلة رفض الصلح، ونال من وفد الأشاعرة الذي حضر مجلس الصلح، وعلى رأسهم الشيخ أبي إسحاق الشيرازي 3، فبقيت النفوس متوترة، ولم تهدأ إلا بعد مغادرة القشيري بغداد بطلب من الحنابلة 4.\rوعند ما قويت شوكة الأشاعرة بعد تسلم نظام الملك الوزارة، نظم الحنابلة أكثر من مسيرة، احتجاجا على النفوذ المتعاظم للأشاعرة في بغداد 5.\rوقد قابل الأشاعرة مخالفيهم من الفرق الكلامية الأخرى بالاضطهاد والقدح والذم، ونظموا الكثير من الهجمات الجدلية ضد الحنابلة والأحناف 6. ومن الأحداث الأليمة التي وقعت بين الأشاعرة والحنابلة، تلك الفتنة التي افتعلها أحد طلاب المدرسة النظامية-ويعرف بالطالب الإسكندراني-عند ما قام بالنيل من الحنابلة وكفرهم في سوق الثلاثاء، فقام\r_______________\r1) الماوردي، قوانين الوزارة، مقدمة المحقق ص 61.\r2) ابن الأثير، الكامل في التاريخ ج 10 ص 10.\r3) ابن الجوزي، المنتظم ج 8 ص 306.\r4) ابن كثير، البداية والنهاية ج 12 ص 187.\r5) الماوردي، قوانين الوزارة، مقدمة المحقق ص 62.\r6) المصدر نفسه ص 60، وانظر أيضا للمحقق نفسه: الأسد والغواص، المقدمة ص 19، 20."], [35, "العامة في السوق بمطاردته حتى سوق النظامية، وهناك وقعت أعمال الفوضى والنهب، وامتدت إلى دار مؤيد الدولة ابن نظام الملك، الذي سارع إلى الاستنجاد بالشرطة، وقتل من جراء ذلك بضعة عشر رجلا 1.\rوقد أثار هذا العمل غضب نظام الملك، فطلب من الخليفة العباسي حبس الشريف أبي جعفر، وعزل الوزير أبي نصر بن جهير، اللذين ساهما في دعم الحنابلة وتحريض العامة ضد الأشاعرة، ثم وعد أبا إسحاق الشيرازي «بالانتقام من الذين أثاروا الفتنة» 2.\rوفي عام 475 ه‍/ 1082 م قدم النظامية واعظ أشعري يدعى البكري، فوعظ بها، ونال من الحنابلة، وكفرهم، وكان يقول على المنبر: وم?ا كفر سليم?ان ول?كن الشي?اطين كفروا 3. ما كفر أحمد بن حنبل، وإنما أصحابه، فعاد الشغب بين الطرفين، ولم ينته إلا بخروج البكري من بغداد بعد أن أغدق عليه الخليفة بالمال، ولقبه بعلم السنة 4.\r_______________\r1) ابن الجوزي، المنتظم ج 8 ص 318.\r2) ابن الجوزي، المنتظم ج 8 ص 318، وابن الأثير، الكامل في التاريخ ج 10 ص 107، وابن كثير، البداية والنهاية ج 2 ص 117.\r3) سورة البقرة، الآية 102.\r4) ابن الجوزي، المنتظم ج 8 ص 4، وابن الأثير، الكامل في التاريخ ج 10 ص 124."], [36, "الفصل الثالث: الحالة الثقافية في عصر الجويني\r"]], "pg": [22, 36]}, "474.4": {"x": [[36, "تقاطع في عصر الجويني مجموعة من العوامل السياسية والدينية، ساهمت في إثراء الحركة الثقافية بمادة البحث أولا، وفي توجيهها نحومسارات محددة ثانيا، ومن هذه العوامل: الصراع السياسي بين أهل السنة الممثلين سياسيا بالخلافة العباسية وحماتها من غزنويين وسلاجقة، وبين المذاهب الشيعية الممثلة سياسيا بالخلافة الفاطمية في مصر وحلفائها البويهيين. والعامل الثاني: انتعاش حركة الاعتزال في ظل الحماية التي قدمها البويهيون لرجالاتها. أما العامل الثالث: فيتمثل بالخلافات الحادة بين المذاهب الفقهية والكلامية السنية.\rومما ميز الحركة الثقافية النشطة في ذلك العصر، سعي الفرق والمذاهب الإسلامية، إلى تدعيم مواقفها الأصولية أوالفروعية، من خلال الكتابة في المسائل الفقهية والكلامية على نحويسوغ استقلاليتها من جهة، ويحافظ على استمراريتها من جهة أخرى.\rلكن هذه الكتابات في الأصول أوالفروع، بقيت أسيرة للقواعد والمعايير التي رسخت من قبل أئمة الفرق والمذاهب في العصور السابقة، بحيث لم يبق لعلماء هذا العصر سوى رتق الثغرات التي قد تظهر في خطابهم الديني أمام الخصوم، مع تشديد في هذا الخطاب على منهج إلغائي للآخر، أما الإذعان للحق بنقد الذات، ورؤية الآخر بعين منصفة فهذا يصعب أويحال رصده في الحركة الثقافية لهذا العصر، ذلك أن الاعتراف بخطأ في بعض مسائل المذهب أوضعفها أمام الخصوم، هواعتراف بخطأ تاريخي يصعب تحمله.\r***\r_______________"], [37, "أول ما يميز الحركة العلمية في هذا العصر، هوظهور المدارس (الأكاديمية)، إلى جانب الجوامع التي كانت تضم بين زواياها العلم والعبادة، وقد بنيت أولى هذه المدارس في نيسابور للمتكلم الأشعري أبي إسحاق الإسفراييني 1 (418 ه‍). ثم تلا ذلك بناء مدرسة أخرى لعلم الأشاعرة الكبير أبي بكر ابن فورك 2 (406 ه‍/ 1015 م). كذلك بنى أبوبكر البستي مدرسة أخرى على باب داره في نيسابور أوقفها لأهل العلم 3.\rوقد ادعى المقريزي (845 ه‍/ 1441 م) أن أول مدرسة بنيت في الإسلام هي المدرسة البيهقية، التي بناها أهالي نيسابور تقديرا وتكريما للإمام البيهقي 4 (456 ه‍/ 1063 م). بينما نسب السبكي (771 ه‍/ 1369 م) إلى شيخه الذهبي (748 ه‍/ 1347 م) القول: بأن أولى المدارس في الإسلام هي المدرسة النظامية، التي بناها الوزير نظام الملك في بغداد ثم في نيسابور 5. لكننا إذا رجعنا إلى مؤلفات الذهبي نفسه، نجده يذكر في ترجمة أبي إسحاق الإسفراييني، أنه قد بني لهذا الشيخ مدرسة في نيسابور 6، لذا يمكن رفع هذا التعارض في أقوال الذهبي بالقول: إنه عنى فيما نقله السبكي عنه، بأن المدارس النظامية هي أولى المدارس الرسمية التي بنيت في الإسلام، ولم يقصد بقوله هذا المدارس الخاصة 7.\r***\rبقي علم الكلام في هذا العصر يسير في الاتجاه المحافظ، سواء من ناحية الموضوعات التي عالجها، أومن جهة المنهج الذي عولجت به هذه الموضوعات، مع ملاحظة تطور داخلي في الطريقة أوالمنهج بدأت ملامحه\r_______________\r1) آدم متز، الحضارة الإسلامية ج 1 ص 336.\r2) الصريفيني، المنتخب من السياق ص 93.\r3) السبكي، طبقات الشافعية ج 4 ص 80.\r4) المقريزي، الخطط والآثار ج 2 ص 363.\r5) السبكي، طبقات الشافعية ج 4 ص 314.\r6) الذهبي، تاريخ الإسلام، حوادث (401 - 420) ص 437.\r7) انظر ذلك أيضا في: السبكي، طبقات الشافعية ج 4 ص 314."], [38, "38 تظهر في مصنفات علم الكلام السني مع إمام الحرمين الجويني، الذي طوع المنطق الأرسطي لخدمة المسائل الأصولية التي عالجها 1، ثم أصبح هذا المنهج هوالسائد في كتابات المتكلمين السنة من بعده، وخلاصته هوالتفريق بين المنطق كأداة للاستدلال وعصمة الذهن من الخطأ، وبين استخدامه لمعالجة القضايا الكلامية والفلسفية.\r***\rظهر الأشاعرة كفرقة مستقلة كما هومعروف بعد ما أعلن أبوالحسن الأشعري (- 324 ه‍) براءته من مذهب الاعتزال، وانحيازه إلى أهل السنة والجماعة 2. ومن بعد وفاة الأشعري، تولى زمام هذا المذهب شيخان بارزان من تلامذته هما: أبوالحسن الباهلي (370 ه‍/ 980 م)، وأبوعبد الله بن مجاهد البصري (370 ه‍/ 980 م)، وقد درس على هذين الشيخين ثلاثة أشاعرة كبارهم: أبوالطيب الباقلاني (403 ه‍/ 1012 م)، وأبوبكر بن فورك (406 ه‍/ 1015 م)، وأبوإسحاق الإسفراييني (418 ه‍/ 1027 م)، وبفعل هؤلاء الأقطاب الثلاثة ترسخ هذا المذهب وانتشر في الأمصار 3.\rوفي عصر الجويني سار الأشاعرة على خطى أئمة المذهب السابقين لهم، وقد استفاد الجويني بخاصة، ومتكلموالأشاعرة بعامة، من التطوير الذي ابتدعه الباقلاني في الطريقة أوالمنهاج لمعالجة المسائل الكلامية 4. إذ إننا نجد الجويني قد جعل العقيدة «كلها بجميع مسائلها تدخل في نطاق العقل والمنطق، وبذلك دخلت القضايا المنطقية والبراهين الفلسفية في أمور الدين» 5.\rأما في موضوعات علم الكلام، فلا نجد عند أشاعرة هذا العصر جديدا لافتا للنظر يضاف إلى المسائل التي قررها الأشعري والباقلاني، سوى بعض\r_______________\r1) ابن خلدون، المقدمة ص 465، وانظر أيضا: سعيد العلوي، الخطاب الأشعري ص 8.\r2) ابن عساكر، تبيين كذب المفتري ص 34.\r3) ابن خلدون، المقدمة ص 495، وأحمد أمين، ظهر الإسلام ج 4 ص 73.\r4) ابن خلدون، المقدمة ص 465.\r5) جلال موسى، نشأة الأشعرية وتطورها ص 321."], [39, "الإضافات أوالمخالفات التي ضمنها إمام الحرمين كتبه الكلامية، كتبنيه لنظرية الأحوال البهشمية في معالجة صفات الذات 1، ومعارضته لشيخه الأشعري والإمام الباقلاني وسائر من تقدمه من الأشاعرة في مسألة خلق أفعال العباد 2، وانحيازه إلى مذهب أهل السلف في آخر كتبه العقدية التي وصلتنا، فيما يتعلق بمسألة صفات الأفعال، بحيث تحاشى التأويل والتزم تفويض أمرها إلى الله تعالى 3.\rوقد ظهر في هذا العصر إلى جانب الجويني العديد من الأشاعرة الكبار ومنهم: عبد القاهر البغدادي، وأبوسعيد المتولي، وأبوالمظفر الإسفراييني، والكياهراسي، وأبوالقاسم الإسفراييني.\rوقد ترك هؤلاء الأئمة مصنفات جليلة في علم الكلام، كالفرق بين الفرق، وأصول الدين للبغدادي، والغنية للمتولي، وأصول الدين للكياهراسي، والتبصير في الدين للإسفراييني.\r***\rشهدت حركة الاعتزال في هذا العصر نشاطا ملحوظا، إذ وجدت المعتزلة في بني بويه سندا قويا، يؤمن لها الحماية من ملاحقة الخصوم، لكن هذا النشاط لم يعمر طويلا بفعل الضربة الموجعة التي وجهها السلطان محمود الغزنوي لمذهب الاعتزال ورجالاته في مدينة الري 4.\rوأفضل من يمثل المعتزلة في هذا العصر القاضي عبد الجبار الهمذاني (- 415 ه‍)، الذي كان في مطلع حياته شافعي الفروع وأشعري الأصول، ثم انقلب على الأشعرية وانحاز إلى مذهب المعتزلة، وأصبح من ألمع رجالاتها المتأخرين، وأقوى المدافعين عن مقولاتها الكلامية. وترك القاضي عبد الجبار مطولات كلامية، دافع فيها بحماس شديد عن صحة المعتقد الاعتزالي كما تمثله المدرسة البصرية في الاعتزال، مثل المجموع في المحيط بالتكليف،\r_______________\r1) الجويني، الإرشاد ص 80.\r2) الجويني، العقيدة النظامية ص 184.\r3) المصدر نفسه ص 166.\r4) ابن الأثير، الكامل في التاريخ ج 9 ص 372."], [40, "والمغني في التوحيد والعدل، وشرح الأصول الخمسة 1.\rوتكمن أهمية مصنفات القاضي عبد الجبار، في جمعه وعرضه الدقيق لآراء شيوخ الاعتزال في المدرستين البصرية والاعتزالية، بعد أن كانت هذه الآراء لا يوقف عليها إلا من خلال كتب خصومهم الكثر 2.\rوقد ظهر من بعد القاضي عبد الجبار نفر من أعيان المعتزلة أبرزهم: أبورشيد النيسابوري، الذي صنف ديوان الأصول، والمسائل في الخلاف بين البصريين والبغداديين 3، وأبوالقاسم التنوخي (- 447 ه‍) الذي صنف كتاب الطوالات 4، وأبويوسف القزويني الذي ترك أضخم تفسير للقرآن الكريم 5.\r***\rاستفادت الشيعة في هذا العصر من طريقة المعتزلة في الحجاج الكلامي، بعد ما كانت تلجأ إلى المرويات الحديثية للرد على المقولات السنية في العصور السابقة 6.\rومما ساعد على ذلك، التقاطع الذي حصل في كثير من المسائل الكلامية بين الشيعة والمعتزلة، بحيث دفع ذلك الشيعة للاستفادة من التقريرات والاستدلالات والردود التي اعتمدتها المعتزلة في مقارعة خصومهم من الفرق الأخرى.\rكذلك استفادت الشيعة من طريقة المعتزلة في وضع المصنفات، فاعتمدوا طريقتهم في كتبهم الكلامية. ومن أقطاب الشيعة في هذا العصر:\rالشريف المرتضى (- 436 ه‍/ 1044 م)، الذي كان من فحول علم الكلام، وصنف فيه المؤلفات النفيسة، وأصبحت هذه المؤلفات فيما بعد مصادر لا غنى عنها لأعلام الشيعة المتأخرين عنه.\r_______________\r1) أحمد صبحي، في علم الكلام ج 1 ص 332، 333.\r2) القاضي عبد الجبار، شرح الأصول الخمسة، مقدمة الحقق الأهواني ص 11.\r3) ابن المرتضى، طبقات المعتزلة ص 116.\r4) البغدادي، تاريخ بغداد ج 12 ص 115، والسمعاني، الأنساب ج 1 ص 485.\r5) السيوطي، طبقات المفسرين ص 56.\r6) ويظهر ذلك جليا في مؤلفات الكليني الرازي (- 329 ه‍)، والشيخ الصدوق (- 381 ه‍)."], [41, "ويعد كتاب الشافي في الإمامة 1 أهم أعمال الشريف المرتضى في الفكر السياسي الشيعي، والكتاب بمثابة نقض لما أورده القاضي عبد الجبار المعتزلي في الجزأين الأخيرين من كتابه المغني في التوحيد والعدل، اللذين خصصهما لمسألة الإمامة 2.\rومن أعيان الشيعة في هذا العصر الذين اشتغلوا بعلم الكلام إلى جانب العلوم الأخرى: شيخ الطائفة، أبوجعفر الطوسي (460 ه‍/ 1067 م) الذي كان تلميذا للشريف المرتضي، ولخص كتابه الشافي في الإمامة 3.\r***\rاقتصر نشاط فقهاء هذا العصر من مختلف المذاهب على شرح مسائل أئمتهم، أوجمع أقوالهم، أوالمناظرة لها أمام مخالفيهم من المذاهب الأخرى 4.\rوكل هذا كان بسبب سد باب الاجتهاد خارج نطاق المذهب المتبع، حتى إن المحاولة التي قام بها أبومحمد الجويني للتفلت من المذاهب الفقهية التي كانت سائدة في عصره قد باءت بالفشل ولم تر النور 5.\rوجد المذهب الحنفي في هذا العصر رعاية وتشجيعا خاصا من قبل الدولة السلجوقية، إذ كان سلاطينها على مذهب أبي حنيفة، وكانوا يخصون مشايخ هذا المذهب بالمناصب الإدارية والفقهية، كالإفتاء والقضاء وغيرها 6.\rوهذا شجع الدارسين للفقه على التمذهب به طمعا بهذه المناصب، وقد ساعد ذلك على انتشار المذهب الحنفي وسيادته في القرن الخامس الهجري في\r_______________\r1) طبع الكتاب لأول مرة على الحجر بإيران سنة 1301 ه‍في مجلد ضخم، ثم حققه عبد الزهراء الحسيني في أربعة أجزاء، وصدر عن مؤسسة الصادق بطهران سنة 1410 ه‍.\r2) الشريف المرتضى، الشافي في الإمامة ج 1 ص 33.\r3) المصدر نفسه، مقدمة المحقق ج 1 ص 18.\r4) محمد الخضري، تاريخ التشريع الإسلامي ص 325.\r5) السبكي، طبقات الشافعية ج 5 ص 77.\r6) فاروق النبهان، المدخل للتشريع الإسلامي ص 249."], [42, "العراق وبلاد ما وراء النهر. وعند ما ضم السلاجقة بلاد الشام إلى دولتهم، انتشر هذا المذهب فيها، وأصبح المذهب الرسمي والشعبي فيها 1. ومن أئمة الأحناف في هذا العصر: أبوعبد الله الدامغاني وأبوعبد الله الصيمري، وأبوبكر خواهر زادة، وأبوزيد الدبوسي.\r***\rبدأ المذهب المالكي مع مؤسسه الإمام مالك بن أنس (- 179 ه‍/ 795 م) في المدينة المنورة، لذا فقد عم بلاد الحجاز 2. أما في القرن الخامس الهجري، فقد تراجع هذا المذهب مع قوة انتشار المذهب الحنبلي، إلا أن أعيان المالكية استطاعوا نشره في مصر، وأصبحت له السيادة فيها، دون منافس حقيقي له من المذاهب الفقهية الأخرى، إلا بعد خضوع مصر لسلطة الأيوبيين في القرن السادس الهجري 3 حيث انتشر فيها المذهب الشافعي وساد.\rكذلك اهتمت الدويلات التي قامت في الشمال الإفريقي بهذا المذهب، وهيأت له كل أسباب الشيوع والسيادة، حتى أصبح المذهب الرسمي والشعبي في هذه الدول، وعلى الأخص في عهد سلطان إفريقية وما والاها من المغرب، المعز بن باديس (454 ه‍/ 1062 م)، إذ حمل هذا السلطان أهل مملكته على الاشتغال بمذهب مالك، وعمل على توظيف أعيانه في المناصب الرسمية 4.\rوساد المذهب المالكي أيضا بلاد الأندلس، بعد أن كان السيادة فيها قبل هذا العصر لمذهب الإمام الأوزاعي (- 157 ه‍/ 773 م)، وكان ذلك بفعل سياسة السلاطين والأمراء هناك، إذ كانوا لا يولون المناصب الرسمية والدينية\r_______________\r1) ابن خلدون، المقدمة ص 448، ومحمد أبوزهرة، تاريخ المذاهب الإسلامية ص 387.\r2) محمد أبوزهرة، تاريخ المذاهب الإسلامية ص 432.\r3) المصدر نفسه ص 432.\r4) المصدر نفسه ص 432، 433."], [43, "إلا لمن كان مالكيا 1. ومن فقهاء المالكية في هذا العصر: أبوالوليد الباجي (474 ه‍/ 1081 م)، وأبوالقاسم اللبيدي (440 ه‍/ 1048 م)، وعبد الوهاب البغدادي (422 ه‍/ 1030 م).\r***\rانتشر المذهب الشافعي في عصور ما قبل الجويني في العراق ومصر وفلسطين، وذلك لتنقل الإمام الشافعي في هذه البلدان 2، وتخرج كثير من الأصحاب عليه. أما في بلاد ماوراء النهر، فكانت السيادة فيها كما أسلفنا للأحناف، مع منافسة متواضعة من الشافعية، بفعل جهود بعض أئمة الشافعية هناك: كالقفال الكبير أبي بكر الشاشي (365 ه‍/ 975 م) وأبي حامد المروزي (362 ه‍/ 972 م) وأبي بكر الصبغي (432 ه‍/ 1040 م)، بيد أن جهود هؤلاء الأئمة في نشر المذهب الشافعي بقيت محدودة ولم تحقق آمالهم المنشودة.\rإلا أن الأمر قد اختلف في عصر إمام الحرمين، إذ كثر أتباع الشافعية وأعيانهم في تلك البلاد، مما شكل حالة تنافسية حقيقية مع الأحناف للسيادة في تلك البلاد، الأمر الذي دفع بالسلاطين السلاجقة الأحناف إلى تقديم الدعم الرسمي لإخوانهم في المذهب الحنفي 3، وملاحقة أعيان الشافعية واضطهادهم أيام عميد الملك الكندري 4.\rوكان للنظاميات التي بناها الوزير نظام الملك في الحواضر الإسلامية الأثر الكبير في انتشار المذهب الشافعي، إذ خرجت هذه المدارس الكثير من العلماء في هذا المذهب، وأصبحوا بمثابة دعاة له في مختلف البلدان، مما جعل هذا المذهب يتقدم المذاهب السنية الأخرى.\rففي نيسابور-حيث أمضى الإمام الجويني أغلب حياته-بنى نظام الملك فيها مدرسة عرفت بنظامية نيسابور، وقام إمام الحرمين بإدارتها والتدريس بها، وبقي على هذا الحال، ولم يتركها إلا في الفترة التي أبعد فيها إلى بلاد الحجاز 5.\r_______________\r1) المصدر نفسه ص 433.\r2) المصدر نفسه ص 481.\r3) أحمد أمين، ظهر الإسلام ج 4 ص 70.\r4) البداية والنهاية ج 12 ص 65.\r5) السبكي، طبقات الشافعية ج 5 ص 176."], [44, "44 أما في بغداد، فقد ساند نظام الملك الشافعية وأعانهم في مواجهة الحنابلة، بأن بنى لهم مدرسة كبيرة عرفت بنظامية بغداد، وقد أدت هذه المدرسة دورا مهما في تخريج الفقهاء والأصوليين على مذهب الشافعي، فأصبح الشافعية في بغداد وبلاد الشام منافسين حقيقيين للحنابلة والأحناف، ومن أئمة الشافعية في هذا العصر: أبوالحسن الماوردي (- 450 ه‍/ 1058 م)، وابن الصباغ (- 477 ه‍/ 1088 م)، وأبوبكر البيهقي (- 456 ه‍/ 1063 م)، وأبوالقاسم الفوراني (- 461 ه‍/ 1068 م).\r***\rبقي نشاط فقهاء الحنابلة في هذا العصر محصورا في بغداد، ولم تجد العلاقة الوطيدة التي كانت تربطهم بالخليفة العباسي في نشر مذهبهم في البلدان المجاورة.\rوقد وصف خصوم الحنابلة أئمة المذهب الحنبلي بالتشدد، والوقوف بحزم أمام المخالفين لهم من المذاهب الأخرى بعامة، والشافعية بخاصة 1.\rلذا فإن جهود حنابلة هذا العصر قد تركزت للنيل من الشافعية والمعتزلة والشيعة والمتصوفة في بغداد، مما شغل الجميع عما يدور حولهم من أحداث عظيمة تهدد مصير الأمة، وتعمل في الوقت نفسه على إسقاط الخلافة السنية الجامعة لوحدتها رغم ما اعتراها من ضعف واستكانة.\rومن أمثلة هذا التشدد المسيرة الحاشدة التي نظمها القاضي أبويعلى الفراء 2 (- 458 ه‍/ 1065 م) -مقدم الحنابلة آنذاك-وتوجه بها إلى أحد مساجد الشافعية في بغداد، فنهوا المصلين وإمامهم عن الجهر بالبسملة، والترجيع بالأذان، والقنوت في الفجر، فبادرهم إمام الجامع، وأخرج مصحفا وقال لجموع الحنابلة فيما يخص البسملة: «أزيلوها من المصحف حتى لا أتلوها» 3.\r_______________\r1) محمد أبوزهرة، تاريخ المذاهب الإسلامية ص 543، وآدم متز، تاريخ الحضارة الإسلامية ج 1 ص 394.\r2) البغدادي، تاريخ بغداد ج 2 ص 256.\r3) ابن الأثير، الكامل في التاريخ ج 9 ص 614."], [45, "كما نجح الحنابلة بعد حشد مناصريهم من العامة، ومن كان على مذهبهم، بمنع الشافعية من حضور الجمعة والجماعات، بحجة أنهم كانوا على مذهب الأشعري في الأصول 1. وكان كل ذلك يتم بمساعدة قوية من الشيخ الأجل أبي منصور بن يوسف 2، الذي كان رئيسا في بغداد، فكان بالنسبة للحنابلة مقابل الوزير نظام الملك للشافعية.\rوبالإجمال يمكن القول إن السواد الأعظم من عامة بغداد، كان يتمذهب بالمذهب الحنبلي، ومن أعيان الحنابلة في هذا العصر: القاضي أبويعلى الفراء، والشريف أبوجعفر عبد الخالق بن عيسى الهاشمي (470 ه‍/ 1077 م)، وأبومحمد التميمي (- 488 ه‍/ 1095 م).\r***\rبدأ المذهب الظاهري في الظهور في بلاد المشرق الإسلامي، وقد أسسه داود بن علي الأصبهاني (270 ه‍/ 883 م)، وقد سمي هذا المذهب بالظاهري، لأن دعاته تمسكوا بشدة بظاهر النصوص دون صرف دلالاتها الظاهرة بتأويل أوغيره 3.\rومن اللافت للنظر أن السلطان البويهي عضد الدولة قد ساعد في انتشار هذا المذهب في بلاد المشرق الإسلامي، ويقال: إن هذا السلطان قد كان على المذهب 4، لذا فقد ولى الكثير من أعلامه القضاء والأعمال الإدارية في تلك البلاد.\rأما في القرن الخامس الهجري، فقد ظهر المجدد لهذا المذهب ابن حزم الظاهري (456 ه‍/ 1063 م)، الذي تمكن من استنباط أصوله وضمنها كتابه الشهير: الإحكام في أصول الأحكام 5. وبعد أن أصل ابن حزم هذا\r_______________\r1) ابن كثير، البداية والنهاية ج 12 ص 66.\r2) البغدادي، تاريخ بغداد ج 2 ص 256، والشيرازي، المعونة في الجدل، مقدمة المحقق عبد المجيد تركي ص 32، 33.\r3) آدم متز، الحضارة الإسلامية ج 1 ص 390.\r4) الشيرازي، المعونة في الجدل، مقدمة المحقق ص 24.\r5) محمد أبوزهرة، تاريخ المذاهب الإسلامية ص 594."], [46, "المذهب، دون ما فيه من أحكام وفقه لعلماء الأمصار في موسوعته الفقهية الكبرى المسماة بالمحلى 1.\rوعلى الرغم من الجهود الكبيرة التي قام بها ابن حزم لنشر هذا المذهب في بلاد الأندلس، فإنه لم يحصد النتائج التي تتناسب مع هذه الجهود، إذ بقيت السيادة في الأندلس للمذهب المالكي، وعلل ابن حزم ذلك بأن العالم لا يستجاب له في بلده 2.\r***\rينسب المذهب الجعفري إلى الإمام السادس عند الشيعة الاثني عشرية جعفر الصادق (148 ه‍/ 765 م)، ويعتمد هذا المذهب على الأقوال المستخرجة للأئمة المعصومين، التي تعد بمثابة نصوص ليس للباطل إليها سبيل.\rوقد رفضت الإمامية اعتبار الإجماع بالمفهوم السني مصدرا من مصادر التشريع، وهواتفاق أهل الحل والعقد على أمر من الأمور 3 له مستند شرعي، لكنها بينت أن الإجماع المعتبر في التشريع هوالكاشف عن رأي المعصوم، وفي ذلك يقول الشريف المرتضى أحد أعلام الشيعة في هذا العصر: «فأما الإجماع فليس بباطل عندنا، لأن الدليل قد دلنا على أن في جملة المجمعين معصوما، حجة لله تعالى، فليس يجوز أن ينعقد الإجماع على باطل من هذا الوجه، لا كما يدعيه المخالفون» 4. أما القياس، فقد رفضته الشيعة الإمامية، لأن عمدته الرأي، ومسائل الشريعة لا تتحصل بالرأي وإنما بقول المعصوم 5.\rوفي عصر إمام الحرمين انتشر المذهب الجعفري في كثير من البلدان، كفارس وبغداد وحلب وبلاد الشام، بفعل المساندة القوية التي قدمها بنوبويه لأعيان هذا المذهب، وتوفير الحماية لهم أمام خصومهم. ومن أعلام المذهب\r_______________\r1) محمد أبوزهرة، تاريخ المذاهب الإسلامية ص 594.\r2) المصدر نفسه ص 594.\r3) دوايت دونلدسن، عقيدة الشيعة ص 317، 318.\r4) الشريف المرتضى، الشافي في الإمامة ج 1 ص 78.\r5) المصدر نفسه ص 169، 276، ومحمد الخضري، تاريخ التشريع الإسلامي ص 263."], [47, "الجعفري في هذا العصر: الشيخ المفيد، الشهير بابن المعلم (413 ه‍/ 1022 م)، والشريف المرتضى، وأبوجعفر الطوسي.\r***\rلجأ علماء الحديث في هذا العصر إلى بيان المنهجية التي اتبعها أئمة الحديث في العصور السابقة، وأفردوا لما توصلوا إليه من قواعد ومعايير كتبا مستقلة، شكلت بمجموعها لما عرف لاحقا بمصطلح الحديث 1. إلا أن صورة علم المصطلح كاملة لم تظهر إلا مع الحاكم أبي عبد الله النيسابوري، الذي جعل أصول الحديث علما مستقلا، ووضع أصوله التي بقيت في جملتها إلى أيامنا، بحيث إن القرون التالية لم تضف إلى ما فعله الحاكم في هذا العلم إلا أشياء ثانوية 2. لكن الحاكم لم يرتب كتابه هذا، لذا عند ما نظر فيه أبونعيم الأصبهاني (430 ه‍/ 1038 م)، زاد فيه على الحاكم أشياء فاتته وسماه مستخرجا 3.\rولم يكتمل علم مصطلح الحديث إلا مع الخطيب البغدادي (- 463 ه‍/ 1070 م)، ومعه لم يبق فيه للمتأخرين إلا زيادة شرح أوتفريع المجمل منه.\rوقد صنف الخطيب البغدادي كتابين من أهم الكتب في هذا الفن، أولهما:\rكتاب الكفاية في الرواية، حدد فيه «البحث في قوانين الرواية، وأبان فيه عن أصولها وقواعدها الكلية، ومذاهب العلماء فيما اختلفت أراؤهم فيه» 4.\rوثانيهما: كتاب «الجامع لآداب الشيخ والسامع»، وضح فيه آداب وشروط رواية الحديث، ويؤكد أبوبكر ابن نقطة الحنبلي (629 ه‍/ 1231 م) أهمية ما كتبه الخطيب البغدادي في مصطلح الحديث بقوله: «ولا شبهة عند كل لبيب أن المتأخرين من أصحاب الحديث عيال على أبي بكر الخطيب» 5.\rوعلى الرغم من اهتمام المحدثين في عصر الجويني بهذا الفن\r_______________\r1) السباعي، السنة ومكانتها في التشريع الإسلامي ص 107.\r2) آدم متز، الحضارة الإسلامية ج 1 ص 360.\r3) العتر، منهج النقد في علوم الحديث ص 62.\r4) المصدر نفسه ص 63.\r5) ابن نقطة، التقييد ص 154."], [48, "المستحدث، فإنه لم يفتهم الاشتغال بما سار عليه المحدثون السابقون لهم في العصور الماضية، من جمع الحديث وترتيبه على أبواب الفقه، أوعلى أساس رجالات السند، كما فعل البيهقي في موسوعته الحديثية التي سماها السنن الكبرى 1، ولم يفت أيضا علماء هذا العصر، الاقتداء بسيرة المحدثين السابقين من جهة الرحلة في طلب الحديث وسماعه وجمعه، فكانوا يتفاخرون بكثرة الارتحال، وكثرة التلقي عن الشيوخ 2.\r***\rرجع علماء القرآن والتفسير في عصر إمام الحرمين إلى سيرة علماء القرن الثالث الهجري، وحذوا حذوهم في التأليف بكل علم من علوم القرآن على حده، إذ لا نجد في هذا العصر أي مؤلف جامع لهذه العلوم، في حين كثرت المؤلفات التي تعالج هذه العلوم منفردة، مع التركيز على علم القراءات وعلم التفسير 3.\rومن أهم المؤلفات التي ظهرت في علوم القرآن: أسباب النزول للواحدي النيسابوري (468 ه‍/ 1075 م)، والتيسير في القراءات السبع لأبي عمروالداني 4 (444 ه‍/1052 م)، وإعراب القرآن لأبي الحسن الحوفي 5 (430 ه‍/ 1038 م)، وفضائل القرآن لأبي العباس المستغفري 6 (432 ه‍/ 1040 م).\rكذلك اهتم علماء هذا العصر اهتماما خاصا بعلم التفسير، وصنفوا فيه المؤلفات الطوال، كتفسير الكشف والبيان عن تفسير القرآن لأبي إسحاق الثعلبي 7 (427 ه‍/ 1037 م)، الذي فسر فيه القرآن بما أثر عن الرسول صلى الله عليه وسلم والصحابة والتابعين، دون أن يغفل فيه المسائل اللغوية والنحوية،\r_______________\r1) البيهقي، إثبات القدر، مقدمة المحقق محمد الزبيدي ص 36.\r2) صبحي الصالح، علوم الحديث ومصطلحه ص 53.\r3) ابن خلدون، المقدمة ص 437.\r4) ابن الجزري، غاية النهاية في طبقات القراء ج 1 ص 505.\r5) السيوطي، بغية الوعاة ج 2 ص 140.\r6) السمعاني، الأنساب ج 5 ص 286.\r7) ابن الجزري، غاية النهاية ج 1 ص 100."], [49, "والاختلافات العقدية بين الفرق، لكن الثعلبي لم يسلم من الإسرائيليات في تفسيره، مما عرضه لكثير من الانتقادات 1. وقد شبهه ابن تيمية (- 728 ه‍/ 1327 م) ب‍ «حاطب ليل ينقل ما وجد في كتب التفسير من صحيح وضعيف وموضوع» 2.\rومن التفاسير التي ألفت في هذا العصر أيضا: التفسير الذي صنفه الواحدي النيسابوري تلميذ الثعلبي، لكنه كان كثير النقل عن أستاذه، مما عرضه للانتقادات نفسها التي تعرض لها الثعلبي في تفسيره 3. ومن هذه التفاسير أيضا: تفسير القرآن لأبي الوليد الباجي، والتفسير الكبير لأبي محمد الجويني 4، وكتاب النكت والعيون في تفسير القرآن لأبي الحسن الماوردي 5، والتفسير الكبير لأبي الحسن بن أبي الطيب النيسابوري 6.\r***\rشهد عصر الجويني فلاسفة كبارا، استفادوا كثيرا من النتاج الفكري الفلسفي لمن سبقهم من فلاسفة القرنين الثالث والرابع الهجريين، ومن أبرز فلاسفة هذا العصر: الشيخ الرئيس ابن سينا (- 428 ه‍/ 1036 م)، الذي قال فيه دي بور: «كان ابن سينا ولا يزال يعد عند أهل المشرق أمير الفلاسفة، وقد ظلت الفلسفة الأرسطية المصطبغة بالمذهب الأفلاطوني الجديد معروفة عند الشرقيين على الصورة التي عرضها فيها ابن سينا» 7.\rومن فلاسفة هذا العصر أيضا: ابن مسكويه (420 ه‍ / 1029 م) الذي اهتم بفلسفة الأخلاق، وحاول من خلال أبحاثه فيها التوفيق بين المفهوم الأفلاطوني للفضيلة، والمفهوم الأرسطي لها 8. وقد عرض ابن مسكويه\r_______________\r1) محمد الذهبي، التفسير والمفسرون ج 1 ص 233.\r2) ابن تيمية، مقدمة في أصول التفسير ص 19، والكتاني، الرسالة المستطرفة ص 59.\r3) ابن تيمية، مجموع الفتاوى ج 2 ص 193، والكتاني، الرسالة المستطرفة ص 193.\r4) السيوطي، طبقات المفسرين ص 46.\r5) ابن خلكان، وفيات الأعيان ج 3 ص 282.\r6) السيوطي، طبقات المفسرين ص 65.\r7) دي بور، تاريخ الفلسفة في الإسلام ص 272.\r8) ماجد فخري، تاريخ الفلسفة الإسلامية ص 262، 263 (نقلا عن دي بور ص 239)."], [50, "لفلسفته الأخلاقية في كتابيه: تهذيب الأخلاق، والحكمة الخالدة 1.\rومن الشعراء الذين مسوا الفلسفة بأشعارهم في هذا العصر: أبوالعلاء المعري (- 449 ه‍/ 1057 م)، الذي وصفه دي بور قائلا: «وكان نباتيا مما يليق بفلاسفة التشاؤم» 2، ويمكن اختصار النفحة الفلسفية في شعر أبي العلاء بقوله:\rتعب كلها الحياة فما أع‍جب إلا من راغب في ازدياد 3\rوقوله:\rأيا سارحا في الجو: دنياك معدن يفوز بشر قابع في غيرها وكرا\rفإن أنت لم تملك وشيك فراقها فعف ولا تنكح عوانا ولا بكرا\rوألقاك فيها والداك فلا تضع بها ولدا يلقى الشدائد والنكرا 4\r***\rمع نهاية القرن الرابع الهجري، استقرت الكتابات التاريخية لدى المؤرخين المسلمين، سواء من ناحية الموضوع أوالمنهج 5. وفي القرن الخامس الهجري، التزم المؤرخون بتلك المناهج، فكانت الأحداث التاريخية تدون عبر السنين.\rبيد أنه قد برز عند مؤرخي هذا القرن نزعة تخصصية، تمثلت بكتابة التاريخ المتعلق بسير الأمراء والسلاطين في تلك الفترة، كسيرة السلطان محمود الغزنوي لأبي النصر العتبي 6 (- 427 ه‍/ 1035 م)، الذي عده بروكلمان أول كتاب من هذا النوع 7. وتبرز النزعة التخصصية أيضا في التأريخ\r_______________\r1) هنري كوربان، تاريخ الفلسفة الإسلامية ص 266.\r2) دي بور، تاريخ الفلسفة في الإسلام ص 134.\r3) أبوالعلاء المعري، اللزوميات ج 2 ص 187.\r4) المصدر نفسه ج 2 ص 178.\r5) شاكر مصطفى، التاريخ والمؤرخون ج 1 ص 100.\r6) الصفدي، الوافي بالوفيات ج 3 ص 159، وطاش كبرى زادة، مفتاح السعادة ج 1 ص 217.\r7) بروكلمان، تاريخ الأدب العربي ج 6 ص 201."], [51, "لأحداث عصر معين، كالتاريخ الذي وضعه هلال الصابي (- 498 ه‍/ 1104 م)، وأرخ فيه لأحداث عصره فقط، ويقع في أربعين مجلدا 1.\rوقد نزع مؤرخوهذا العصر إلى ربط التاريخ بالجغرافيا في مؤلفاتهم التاريخية، كتاريخ أصبهان لأبي نعيم الأصبهاني، وتاريخ بغداد للخطيب البغدادي، وأخبار الشام لأبي القاسم السميساطي 2 (- 453 ه‍/ 1061 م).\rلكن ما يعيب المؤلفات التاريخية في هذه الفترة، أنها قد أولت الاهتمام بالأحداث التاريخية ذات الطابع السياسي والعسكري 3، بحيث أتخمت بالصراعات المسلحة بين الدويلات والإمارات في ذلك العصر، بينما لا نجد مصنفا واحدا خصص لوصف الحالة الاقتصادية أوالاجتماعية أوالدينية في تلك الدويلات.\rكذلك اهتم علماء هذا العصر بالجغرافيا، فأفردوا لها المصنفات، ومن أهمها: معجم البلدان لابن زنجويه السمان 4 (- 445 ه‍/ 1062 م)، والمختار في ذكر الخطط والآثار للقضاعي 5 (454 ه‍/ 1062 م). وقد استفاد المقريزي (- 845 ه‍/ 1441 م) من هذا الكتاب واعتمد عليه كثيرا في كتابه الخطط والآثار 6.\rوبلغت حركة التأليف في كتب التراجم والطبقات منزلة عظيمة في عصر الجويني، ومن أهم هذه المؤلفات: حلية الأولياء في طبقات الأصفياء لأبي نعيم الأصبهاني، وطبقات الصوفية لأبي عبد الرحمن السلمي (412 ه‍/ 1021 م)، ويتيمة الدهر في محاسن أهل العصر للثعالبي، وكتاب شجرة\r_______________\r1) ابن خلكان، وفيات الأعيان ج 6 ص 101، وياقوت الحموي، معجم الأدباء ج 19 ص 294.\r2) ياقوت الحموي، معجم البلدان ج 3 ص 258، وابن منظور، مختصر تاريخ دمشق ج 18 ص 169.\r3) أحمد أمين، ظهر الإسلام ج 2 ص 209.\r4) الذهبي، سير أعلام النبلاء ج 18 ص 528.\r5) ابن قاضي شهبة، طبقات الشافعية ج 1 ص 233.\r6) مصطفى شاكر، التاريخ والمؤرخون ج 1 ص 181."], [52, "الذهب في أخبار أهل الأدب لأبي الحسن المجاشعي (- 479 ه‍/ 1086 م)، وطبقات الشافعية للعبادي، وطبقات الفقهاء لأبي إسحاق الشيرازي.\r***\rنحا متصوفة هذا العصر منحى غلب عليه إصلاح ما علق بالتصوف من بدع وشعوذات ومخارق من بعض أدعيائه 1. وقد دفع ذلك أبا القاسم القشيري إلى جمع أقوال من مثل التصوف المعتدل، كإبراهيم بن أدهم (162 ه‍/ 778 م)، وبشر الحافي (226 ه‍/ 840 م)، والإمام الجنيد (297 ه‍/ 909 م)، وغيرهم، قاصدا من ذلك إعلاء شأن التصوف الخالي من الغلووالابتداع، وفي ذلك يقول: «اعلموا رحمكم الله أن شيوخ هذه الطائفة بنوا قواعد أمرهم على أصول صحيحة في التوحيد، صانوا بها عقائدهم عن البدع، ودانوا بما وجدوا عليه السلف وأهل السنة من توحيد، ليس فيه تمثيل ولا تعطيل» 2.\rثم ينتقد القشيري التصوف الفلسفي في عصره بقوله: «وادعوأنهم قد تحرروا عن رق الأغلال، وتمقتوا بحقائق الوصال، وأنهم قائمون بالحق، تجري عليهم أحكامه وهم محو، ليس لله عليهم فيما يؤثرونه أويذرونه عتب ولا لوم، وأنهم كوشفوا بأسرار الأحدية، وبقوا بعد فنائهم عنهم بأنوار الصمدية» 3.\rويتشدد القشيري في نقد المتصوفة الذين لا يلتزمون في تصوفهم معايير الكتاب والسنة فيقول: «وكل تصوف لا يقارنه التنظف والتعفف فهومخرقة وتكلف، وكل باطن يخالفه ظاهر باطل لا باطن، وكل توحيد يصحبه الكتاب والسنة فهوتلحيد لا توحيد، وكل معرفة لا يقارنها ورع واستقامة فهي مخرقة لا معرفة» 4.\rوقد أيد القشيري في حركته الإصلاحية لتصوف عصره، صوفي آخر\r_______________\r1) القشيري، الرسالة القشيرية ص 2، والهجويري، كشف المحجوب ص 196.\r2) القشيري، الرسالة القشيرية ص 2.\r3) المصدر نفسه ص 3.\r4) المصدر نفسه ص 2."], [53, "معاصر له هوأبوالحسن الهجويري (- 465 ه‍ / 1072 م)، الذي هاله ما لحق بالتصوف من أدران وخزعبلات، مما دفعه إلى القول: «إن هذا العلم قد اندرس في الحقيقة في زماننا هذا» 1. ثم يصور الهجويري حال المتصوفة في هذا العصر بقوله: «وقد أوجدنا الله عز وجل في زمان أسمى أهله الهوى شريعة، وطلب الجاه والرياسة والتكبر عزا وعلما، ورياء الخلق خشية، وإخفاء الحقيقة في القلوب حلما، والنفاق زهدا، والتمني إرادة، وهذيان الطبع معرفة، وحركات القلب وحديث النفس محبة، والإلحاد فقرا، والجحود صفوة، والزندقة فناء، وترك شريعة محمد صلى الله عليه وسلم طريقة، حتى احتجب أرباب المعاني بينهم على حين صارت الغلبة لهم» 2.\rوإذا كان القشيري في رسالته في التصوف، والهجويري في كشف المحجوب، قد صورا حالة التصوف في هذا العصر، فإن ما جاء في كتابيهما من شرح لمبادئ التصوف المعتدل، الذي يجمع ما بين الحقيقة والشريعة، يعد محاولة جادة منهما لإصلاح ما لحق بالتصوف من بدع وآفات. وقد أتت حركة الإصلاح هذه أكلها عند ما تزعمها أبوحامد الغزالي، إذا استطاع أن يعيد للتصوف الصفاء والنقاء. ومن أقطاب الصوفية في هذا العصر: أبوالقاسم القشيري، وأبوالحسن الهجويري، وأبونعيم الأصبهاني، وأبوعلي الفارمذي (- 477 ه‍/ 1084 م)، وأبوالحسن البوشنجي (- 467 ه‍)، وأبوالحسن الخرقاني (- 425 ه‍)، وأبوالفضل الختلي (- 431 ه‍/ 1039 م)، وأبوحامد الغزالي (- 505 ه‍/ 1111 م).\r_______________\r1) الهجويري، كشف المحجوب ص 197.\r2) المصدر نفسه ص 199."], [54, "الفصل الرابع\rحياة إمام الحرمين الجويني "]], "pg": [36, 54]}, "474.5": {"x": [[54, "1\r(419 - 487/ 1028 - 1085)\r*اسمه ونسبته:\rهوعبد الملك بن عبد الله بن يوسف بن عبد الله بن يوسف بن محمد بن حيويه، السنبسي، الطائي، الجويني، النيسابوري.\rوقد ذكرت بعض كتب التراجم والطبقات نسب الجويني مختصرا،\r_______________\r1) انظر في ترجمة الجويني: الصريفيني، المنتخب من السياق لتاريخ نيسابور ص 330، وابن عساكر، تبيين كذب المفتري ص 278، والسمعاني، الأنساب ج 2 ص 129، وياقوت الحموي، معجم البلدان ج 2 ص 192، وابن الجوزي، المنتظم ج 9 ص 18، والعبادي، طبقات فقهاء الشافعية ص 112، والباخرزي، دمية القصر ج 2 ص 246، وابن خلكان، وفيات الأعيان ج 3 ص 167، وابن الأثير، الكامل في التاريخ ج 10 ص 145، والذهبي، تاريخ الإسلام، حوادث (471 - 480) ص 229، سير أعلام النبلاء ج 18 ص 468، العبر في خير من غبر ج 3 ص 291، وابن هداية الله الحسيني، طبقات الشافعية ص 174، والسبكي، طبقات الشافعية الكبرى ج 5 ص 165، والأسنوي، طبقات الشافعية ج 1 ص 197، وابن كثير، البداية والنهاية ج 12 ص 128، وابن الوردي، التاريخ ج 1 ص 383، وابن النجار، ذيل تاريخ بغداد ص 85، واليافعي، مرآة الجنان ج 3 ص 123، وابن تغري بردي، النجوم الزاهرة ج 5 ص 121، وابن قنفذ، الوفيات ص 257، وابن قاضي شهبة، طبقات الشافعية ج 1 ص 255، وطاش كبرى زادة، مفتاح السعادة ج 1 ص 26، ج 2 ص 97، 298، وابن العماد، شذرات الذهب ج 3 ص 358، والخوانساري، روضات الجنات ص 463، والبغدادي، هدية العارفين ج 1 ص 626، ومحمد الحسني المكي، العقد الثمين ج 5 ص 507، وعماد الدين بن أبي الفداء، المختصر في أخبار البشر ج 2 ص 196، ودائرة المعارف الإسلامية ج 7 ص 179، وفوقية حسين، الجويني، إمام الحرمين، ومحمد الزحيلي، الإمام الجويني."], [55, "فوقفت عند الجد الأول يوسف 1، وهذا الاختصار لا ضير فيه، أما ما ذكره السبكي في طبقاته وطاش كبرى زاده في مفتاحه للسعادة من أن الجد الثاني للجويني هومحمد بدلا من عبد الله 2، فهوبمثابة خرق لما أجمع عليه أصحاب التراجم الآخرون 3، ومما يعزر هذا أن التفرد من السبكي وطاش كبرى زادة لا يعتد به، ما ذكره المترجمون لوالد الجويني الشيخ أبي محمد الجويني بما فيهم السبكي نفسه، من أن هذا الجد هوعبد الله 4.\rوينسب إمام الحرمين إلى بلدة جوين 5، فيقال له: الجويني، لكن العادة جرت أن ينسب العلماء والأعلام إلى الضيع أوالمدن أوالبلدان التي ولدوا بها، أوحلوا أوتوفوا بها، وإمام الحرمين لم يثبت له شيء من ذلك بالنسبة إلى جوين، لذا فإنه على الأرجح قد ورث هذه النسبة من والده أبي محمد الجويني، الذي ولد بجوين ونشأ فيها 6.\rوينسب إمام الحرمين وإن بدرجة أقل، إلى مدينة نيسابور 7 مسقط رأسه، وفي هذه المدينة نشأ وترعرع، وقضى بها معظم حياته متلقيا للعلم ومدرسا له، ومن نيسابور كان ينطلق إلى البلدان الأخرى ومن ثم يعود إليها.\r_______________\r1) ابن عساكر، تبيين كذب المفتري ص 278، والسمعاني، الأنساب ج 2 ص 129، والأسنوي، طبقات الشافعية ج 1 ص 197، والصريفيني، المنتخب من السياق ص 330.\r2) السبكي، طبقات الشافعية ج 5 ص 165، وطاش كبرى زادة، مصباح السعادة ج 2 ص 298.\r3) المصدر نفسه ج 5 ص 73.\r4) انظر السبكي، طبقات الشافعية ج 5 ص 73.\r5) جوين: اسم كورة على طريق القوافل من بسطام إلى نيسابور، تسميها أهل خراسان كويان، فعربت فقيل جوين، وحدودها تتصل ببيهق، وتشتمل جوين على العديد من القرى، وتبعد عن نيسابور عشرة فراسخ. قارن عنها: ياقوت الحموي، معجم البلدان ج 2 ص 192، والسمعاني، الأنساب ج 2 ص 128.\r6) ياقوت الحموي، معجم البلدان ج 2 ص 193.\r7) السبكي، طبقات الشافعية ج 5 ص 165، وابن عساكر، تبيين كذب المفتري ص 278."], [56, "وينسب الجويني أيضا إلى أصله العربي فيقال له: السنبسي الطائي 1، وسنبس قبيلة عربية معروفة من طي، لكن هذه النسبة لم تشتهر وتكاد لا تذكر إلا في معرض ذكر نسب إمام الحرمين كاملا.\r*كنيته ولقبه:\rاشتهر الجويني بكنية أبي المعالي 2، وهذه الكنية لم يتكن بها الجويني لولد سماه بهذا الاسم، فلم يكن له من الأولاد الذكور إلا ولد وحيد اسمه أبوالقاسم المظفر، وربما اكتسب الجويني هذه الكنية لنبوغه المبكر، وللمكانة الرفيعة التي تبوأها بين أقرانه رغم حداثة سنه 3.\rولقب الجويني بثلاثة ألقاب: الأول-وهوأقل اشتهارا، ناردا ما كان يشار إليه به-وهوضياء الدين 4. أما اللقب الذي لازمه واشتهر به فهوإمام الحرمين.\rوقد أكثر أصحاب التراجم والفقهاء والمتكلمين في معرض حديثهم عن الجويني وآرائه من ذكره بهذا اللقب شهرة واختصارا 5. وقد حاز الجويني هذا اللقب إثر هروبه من نيسابور بعد الاضطهاد الذي تعرض له الأشاعرة على يد عميد الملك الكندري، فلجأ إلى الحجاز، وأخذ يتنقل ما بين المسجد الحرام في مكة المكرمة، والمسجد النبوي في المدينة المنورة 6.\rواللقب الثالث للجويني هوفخر الإسلام 7، لكن هذا اللقب نادرا ما\r_______________\r1) ابن الجوزي، المنتظم ج 9 ص 8، وابن الأثير، الكامل في التاريخ ج 9 ص 535.\r2) الذهبي، تاريخ الإسلام، حوادث (471 - 480) ص 230، وابن خلكان، وفيات الأعيان ج 3 ص 167.\r3) فوقية حسين، الجويني ص 12، ومحمد الزحيلي (نقلا عن فوقية حسين)، الإمام الجويني ص 45.\r4) الباخرزي، دمية القصر ج 2 ص 196، والذهبي، العبر ج 3 ص 291، وابن خلكان، وفيات الأعيان ج 3 ص 167، وابن قاضي شهبة، طبقات الشافعية ج 1 ص 255.\r5) ابن خلكان، وفيات الأعيان ج 3 ص 167، والسمعاني، الأنساب ج 2 ص 129.\r6) ابن كثير، البداية والنهاية ج 12 ص 128، وابن العماد الحنبلي، شذرات الذهبي ج 3 ص 359.\r7) الصريفيني، المنتخب من السياق ص 331، وابن عساكر، تبيين كذب المفتري ص 278."], [57, "يذكر في سيرة إمام الحرمين، وكأنه من الألقاب الفخرية التي تدل على مكانة ورفعة صاحبها.\r*ولادته وتاريخها:\rلم يأت أحد من الذين استفاضوا في عرض سيرة إمام الحرمين على ذكر البلدة التي ولد بها، ويستبعد أن يكون الجويني قد ولد في جوين، لأن والده قد ترك هذه البلدة وتوجه أولا إلى نيسابور ثم غادرها إلى مرو، وعاد إلى نيسابور وقعد للتدريس والفتوى عام 407 ه‍/ 1016 م، ولما كان الجويني قد ولد عام 419 ه‍/ 1028 م، فإن إمام الحرمين يكون، على الأرجح، قد ولد في نيسابور مكان إقامة والده 1.\rاختلفت الأخبار الواردة في كتب التراجم حول تاريخ ولادة الجويني، فهناك فريق-وهوالأكثر قربا من عصره الجويني-قد حدد أن هذا الإمام قد ولد في الثامن عشر من المحرم عام أربعمائة وتسعة عشر، وأجمع هذا الفريق على أن الجويني قد عاش تسعة وخمسين عاما، وأنه توفي سنة 478 ه‍2.\rأما الفريق الثاني فقد ذهب إلى أن الجويني قد ولد سنة أربعمائة وسبع عشرة، وفي الوقت نفسه قرر هؤلاء أنه توفي سنة 478 ه‍، وكان عمره آنذاك تسعة وخمسين عاما 3.\rفإذا أخذنا بعين الاعتبار، أن الفريقين قد أجمعا على أن الجويني قد توفي عام 478 ه‍عن عمر وقدره تسعة وخمسين عاما، يتبين لنا عدم صحة ما ذهب إليه الفريق الثاني، ونقرر في الوقت نفسه أن ولادة الجويني كانت عام 419 ه‍4.\r_______________\r1) انظر أيضا: فوقية حسين، الجويني ص 21.\r2) الصريفيني، المنتخب من السياق ص 331، والسبكي، طبقات الشافعية ج 5 ص 168 - 181، وطاش كبرى زادة، مصباح السعادة ج 2 ص 299.\r3) ابن كثير، البداية والنهاية ج 12 ص 128.\r4) انظر أيضا: فوقية حسين، الجويني ص 22، ومحمد الزحيلي، الإمام الجويني ص 44 - 45."], [58, "*أسرته:\rنشأ الجويني في أسرة ضيقة، لم يعرف منها إلا والده وأمه، وأحد أعمامه. أما نسله، فقد ذكرت المصادر أنه لم يكن كثير الولد، وأنه أنجب ولدا ذكرا هوالمظفر 1 أبوالقاسم، وابنة تزوجها هبة الله بن سهل البسطامي 2 (533 ه‍/ 1138 م).\r*والده: أبومحمد الجويني (438 ه‍/ 1046 م):\rهوعبد الله بن يوسف بن عبد الله بن يوسف بن محمد السنبسي، الطائي، الجويني، نسب إلى جوين مسقط رأسه 3. وينسب أيضا إلى القبيلة العربية سنبس، وهي من طي، مما يدل على الأصل العربي لهذا الإمام ولابنه إمام الحرمين.\rنشأ أبومحمد الجويني في بلدته جوين، وفيها تلقى علومه الأولى، فقرأ الأدب على والده الأديب يوسف بن عبد الله 4، وأخذ الفقه عن أبي يعقوب الأبيوردي 5 (- 400 ه‍ / 1009 م) ثم غادر جوين وتوجه إلى نيسابور، وفيها لازم أبا الطيب الصعلوكي 6، ودرس عليه الفقه وتبحر فيه. بعد ذلك رحل أبومحمد الجويني إلى بلدة مرو، قاصدا القفال الصغير المروزي 7، حيث كان حاملا لواء طريقة أهل خراسان في المذهب الشافعي، وقائما بأعبائها، فلازمه حتى تخرج به مذهبا وخلافا، وأتقن طريقته في المذهب. ثم عاد إلى نيسابور عام 407 ه‍8 ولم يغادرها إلى حين وفاته، وفي نيسابور عقد له مجلس الفتوى والتدريس والمناظرة 9.\r_______________\r1) السبكي، طبقات الشافعية ج 5 ص 330.\r2) الذهبي، تاريخ الإسلام، حوادث (521 - 530) ص 340.\r3) السمعاني، الأنساب ج 2 ص 129.\r4) ابن خلكان، وفيات الأعيان ج 3 ص 47.\r5) الأسنوي، طبقات الشافعية ج 1 ص 165.\r6) ابن كثير، البداية والنهاية ج 12 ص 55.\r7) الأسنوي، طبقات الشافعية ج 1 ص 166.\r8) المصدر نفسه ج 1 ص 166.\r9) ابن كثير، البداية والنهاية ج 1 ص 55."], [59, "وكانت جلساته تتوزع على الفقه والأدب والتفسير والحديث، فتخرج به جماعة كثيرون منهم ابنه عبد الملك الجويني 1.\rصنف أبومحمد الجويني تصانيف عدة، منها: الفروق، والسلسلة، والتبصرة، والتذكرة، ومختصر المختصر، وشرح الرسالة، وشرح عيون المسائل، والتفسير الكبير، وكتاب المحيط 2.\rولا نبالغ إن قلنا: إن أهم مؤلف له هوكتاب المحيط، إذ تمرد فيه على تقييدات المذاهب الفقهية الأربعة، وعزم على عدم التقيد بمذهب منها، وقد مضى الجويني قدما في إنجاز هذا المؤلف، إلا أن الحافظ أبا بكر البيهقي (- 458 ه‍/ 1065 م) قد حال دون إكمال هذه المحاولة الرائدة، فقد سارع البيهقي عند ما وقعت بيده ثلاثة أجزاء من المحيط إلى تحرير رسالة لأبي محمد الجويني بين له فيها الأوهام والأخطاء الحديثية في المحيط، فلما وصلت هذه الرسالة إلى الجويني أمسك عن إكمال المحيط وشكر البيهقي على حسن صنيعه 3.\rوكان للشيخ أبي محمد الجويني الأثر البارز في صقل شخصية ابنه عبد الملك، ويتمثل هذا الأثر في المسارات الفكرية الآتية:\r\r*اختياره لمذهب الشافعي في الفروع، ودفاعه عنه في كتبه الفقهية والأصولية، والمناظرة له أمام أقطاب المذاهب الفقهية الأخرى.\r\r*إعلاؤه لشأن العقل، والركون إليه في النظر إلى الوحي، قرآنا كان أم سنة، مما دفع به إلى الإكثار من استخدام الأقيسة والقواعد المنطقية في تقريراته الفقهية والأصولية، هذا من جهة، وإلى انتقاد آراء سابقيه من الأئمة حتى ولوكانوا من الشافعية أوالأشاعرة من جهة أخرى، وهذا جلي وواضح في كتبه الأصولية، وعلى الأخص في: البرهان في أصول الفقه، والإرشاد إلى قواطع الأدلة، والعقيدة النظامية.\r_______________\r1) ابن خلكان، وفيات الأعيان ج 3 ص 47.\r2) السبكي، طبقات الشافعية ج 5 ص 76.\r3) المصدر نفسه ج 5 ص 77، وانظر نص الرسالة ص 77."], [60, "*عفة نفسه وزهده وتصوفه، واتقاؤه الشبهات أسوة بوالده الذي كان يؤدي زكاته مرتين في العام الواحد خوفا من النسيان 1، وعدم اتكائه على الحائط المشترك بين بيته وبين الجيران 2.\r*والدته:\rكانت والدة إمام الحرمين الجويني جارية اشتراها والده من كسبه الحلال 3، إذ حرص على أن يكون ثمنها من الأجر الذي كان يتقاضاه من نسخ الكتب الخالي من أي شبهة، وكانت هذه الجارية موصوفة بالصلاح والتقوى. كذلك حرص والد إمام الحرمين على أن لا يطعمها إلا مما يتأكد أنه حلال خالص، ثم حملت هذه الجارية بالجويني الابن، فزاد الشيخ أبومحمد من رعايتها، وكان يوصيها بالابتعاد عن كل ما فيه شبهة، سواء فيما يتعلق بها أوبولدها 4.\rويروى أنها انشغلت ذات يوم عن وليدها بإعداد الطعام لوالده، فبكى إمام الحرمين، فسلمته إلى جارية أخرى للجيران كانت تزورهم، فأرضعته مصة أومصتين، فلما رآها والده، أنكر عليها ذلك، وقال لها: «هذه الجارية ليست ملكا لنا، أوليس لها أن تتصرف في لبنها، ولم يأذن لها أصحابها بذلك». ثم أخذ الشيخ ابنه وقلبه رأسا على عقب، وأخذ يدلك بطنه ويضع يده في فيه حتى استفرغ ما في جوفه من حليب جارية الجيران 5.\rوكان إمام الحرمين يذكر هذه الحادثة في مجالسه العلمية، فإذا توقف في مناظرة، أوخانته فكرة ما، يقول: «هذا من بقايا تلك المصة» 6.\r_______________\r1) السبكي، طبقات الشافعية ج 5 ص 74.\r2) المصدر نفسه ج 5 ص 74.\r3) ابن خلكان، وفيات الأعيان ج 3 ص 169.\r4) ابن العماد الحنبلي، شذرات الذهب ج 3 ص 260.\r5) انظر تفاصيل هذه الرواية في: ابن خلكان، وفيات الأعيان ج 3 ص 169، والسبكي، طبقات الشافعية ج 5 ص 168، وابن كثير، البداية والنهاية ج 12 ص 128، وابن العماد، شذرات الذهب ج 3 ص 260، وطاش كبرى زادة، مصباح السعادة ج 2 ص 298.\r6) ابن كثير، البداية والنهاية ج 12 ص 128."], [61, "*ابنه أبوالقاسم (493 ه‍/ 1099 م):\rهوالمظفر بن عبد الملك بن عبد الله بن يوسف، أبوالقاسم الجويني، ولد بالري، وحمل صغيرا إلى نيسابور، نشأ في حجر والده، وسمع منه، وتربى على الفضل والعلم والأدب 1. سمع صحيح البخاري من أبي سهل الحفصي (465 ه‍/ 1072 م)، وسمع أيضا من طاهر الشحامي 2 (479 ه‍/ 1086 م). وإجمالا فإن أخبار هذا الابن قليلة، والظاهر أنه لم يبلغ من الشهرة ما يدفع المؤرخين إلى الاعتناء بأخباره. وقد قتل المظفر مسموما 3، لكن تفاصيل هذه الحادثة أيضا لم ينشغل بها أصحاب التراجم.\rوبوفاة المظفر، انقطع نسل إمام الحرمين من جهة الذكور، مما دفع السبكي إلى القول: «وفي أن آثار جده واجتهاده في دين الله، يدوم إلى يوم الساعة، وإن انقطع نسله من جهة الذكور ظاهرا، فنشر علمه يقوم مقام كل نسب ويغنيه عن كل نشب مكتسب» 4\r*ابنته:\rلم تذكر المصادر اسم ابنة إمام الحرمين، وإنما جاء ذكرها في معرض ترجمة زوجها أبي محمد البسطامي 5 (533 ه‍/ 1138 م). وهوهبة الله بن سهل بن عمر بن القاضي محمد أبي عمر البسطامي، المعروف بالسيدي، نسبة إلى السيد أبي الحسين محمد بن علي الهمذاني المعروف بالوضيء 6. كان عالما خيرا دينا، كثير العبادة والتهجد، لكنه كان عسر الخلق، يكره الرواية، وما كان أحد يقرأ عليه إلا بالشفاعة والجهد الجهيد 7. توفي في نيسابور.\r_______________\r1) السبكي، طبقات الشافعية ج 5 ص 330.\r2) المصدر نفسه ج 5 ص 330.\r3) الأسنوي، طبقات الشافعية ج 1 ص 198.\r4) السبكي، طبقات الشافعية ج 5 ص 182.\r5) الذهبي، تاريخ الإسلام، حوادث (521 - 530) ص 340.\r6) السمعاني، الأنساب ج 3 ص 356.\r7) الذهبي، تاريخ الإسلام، حوادث (521 - 530) ص 340."], [62, "*عمه أبوالحسين الجويني (463 ه‍/ 1070 م):\rعلي بن يوسف بن عبد الله بن يوسف الجويني، أبوالحسين، المعروف بشيخ الحجاز 1. كان صوفيا، اشتغل بالحديث والتصوف، وألف كتابا في الصوفية سماه كتاب السلوة 2. رحل في طلب العلم، وسمع الكثير من العلماء والمحدثين ومنهم: أبوعبد الرحمن السلمي، وأبومحمد الجويني، وأبونعيم الإسفراييني. روى عنه زاهر ووجيه الشحاميان، ومحمد بن الفضل الفراوي 3. وكان قد عقد له مجلس الإملاء في خراسان 4.\rفي هذه الأسرة، نشأ إمام الحرمين، إلا أن الأثر الأكبر لها في شخصية الجويني مرده إلى والده أبي محمد الجويني، الذي حرص على تربية ابنه تربية صالحة، وأحفظه القرآن في صغره، ويسر له علوم الفقه والأدب واللغة.\r*رحلته في طلب العلم:\rسبق القول: إن الجويني لم يولد في جوين، وإنما ولد على الأرجح في نيسابور، لذا يمكن القول أيضا: إن بداية تحصيله العلمي قد بدأ في هذه المدينة، إذ تتلمذ على والده، وأخذ عنه علوم الأدب والفقه والتفسير والخلاف والأصول 5.\rوبقي الجويني على هذا الحال إلى أن توفي والده، فأقعد مكانه للتدريس وهولم يتجاوز العشرين من عمره 6، مستفيدا مما حصله عن والده من علوم، ومتبعا للمنهجية العلمية الدقيقة التي اكتسبها منه، حيث عرف إمام الحرمين منذ بداية تلقيه العلم بميله إلى النقد، وظهر هذا الميل في مجالس والده، فكان يرفض كل رأي لا يقبله عقله، ولوكان هذا الرأي لكبار الأئمة أولوالده 7.\r_______________\r1) السمعاني، الأنساب ج 3 ص 129.\r2) المصدر نفسه ج 3 ص 129.\r3) السبكي، طبقات الشافعية ج 5 ص 298.\r4) الذهبي، تاريخ الإسلام، حوادث (461 - 470) ص 124.\r5) ابن كثير، البداية والنهاية ج 12 ص 128، وابن قاضي شهبة، طبقات الشافعية ج 1 ص 255.\r6) السبكي، طبقات الشافعية ج 5 ص 169.\r7) المصدر نفسه ج 5 ص 180، وابن عساكر، تبيين كذب المفتري ص 284."], [63, "وكان والده لا ينزعج من ذلك، بل على العكس من ذلك تماما، إذ كان يعزز هذا المنحى عنده ويثني عليه 1.\rوتتلمذ الجويني في هذه الفترة على أبي القاسم الإسفراييني المعروف بالإسكاف، الذي كان يلقى الدروس في الأصلين بالمدرسة البيهقية وفق أصول الفقه الشافعي، وأصول الدين الأشعري، فعلق عليه في هذين الأصلين أجزاء معدودة 2.\rولم تكن ثقافة الجويني في الأصول مبنية فقط على ما حصله من الإسكاف، وإنما ارتكزت هذه الثقافة في المقام الأول على القراءات الذاتية له، إذ قام الجويني بقراءة مجلدات عديدة لسابقيه في هذين العلمين، فقد روى عنه أنه قال: «كنت علقت عليه [على الإسكاف] في الأصول أجزاء معدودة، وطالعت في نفسي مائة مجلدة» 3. ويقول في موضع آخر: «ما تكلمت في علم الكلام كلمة حتى حفظت من كلام القاضي أبي بكر [الباقلاني] وحده اثنتي عشرة ألف ورقة» 4.\rولم يكتف الجويني بالتحصيل عن والده وأبي القاسم الإسفراييني، إذ كان يواظب أيضا على مجلس الأستاذ أبي عبد الله الخبازي، ويقرأ عليه القرآن وعلومه 5.\rولم يغفل الجويني في هذه الفترة دراسة الحديث النبوي وسماعه، فقد سمع الحديث أولا من والده، ثم سمعه من أبي حسان المزكي، وأبي سعد البصروي، ومنصور بن رامش، وفضل الله الميهني، وأبي سعد بن عليك 6.\r*رحلته إلى بغداد والحجاز:\rبقي الجويني في نيسابور متلقيا للعلم ومدرسا له في آن واحد، إلى أن\r_______________\r1) السبكي، طبقات الشافعية ج 5 ص 169.\r2) المصدر نفسه ج 5 ص 169، 175.\r3) المصدر نفسه ج 5 ص 175.\r4) المصدر نفسه ج 5 ص 185.\r5) ابن عساكر، تبيين كذب المفتري ص 280.\r6) الذهبي، تاريخ الإسلام، حوادث (471 - 480) ص 231."], [64, "حلت المحنة الكبيرة بالأشاعرة في نيسابور عام 445 ه‍/ 1053 م كما سبق ذكره 1. وقد علم الجويني أن أمرا قد صدر باعتقاله إلى جانب عدد من أقطاب الأشاعرة، فخرج من نيسابور خفية وتوجه إلى كرمان أولا 2، ومنها توجه إلى بغداد، ومن ثم إلى الحجاز 3.\rلكن الأخبار عن رحلته إلى كرمان تكاد تكون معدومة، حيث اكتفت المصادر بأنه التحق بالعسكر هووطائفة من مشايخ الأشاعرة. ويبدوأن الجويني لم يطل المكوث في كرمان، إذ دخل بغداد وقت دخول الغز الأتراك لها عام (447 ه‍/ 1055 م) 4، فتكون المدة التي قضاها منذ خروجه من نيسابور إلى كرمان ومن ثم إلى بغداد عامين كاملين.\rوفي بغداد سمع إمام الحرمين من أكابر علمائها وأخذ عنهم العلم. لكن المصادر لم تذكر أسماء هؤلاء العلماء أوالشيوخ، ولم تحدد المدة التي قضاها في هذه المدينة، وكل ما ذكر عنه في بغداد أنه سمع من أبي محمد الجوهري 5 (454 ه‍/ 1062 م). ويمكن القول: إن المقام في بغداد لم يطب للجويني، إذ قامت الحنابلة في السنة نفسها التي دخل فيها بغداد بالتصدي للشافعية والأشاعرة، وأنكروا عليهم الجهر بالبسملة والترجيع في الأذان والقنوت، ولم يقوالشافعية على حضور الجمعة أوالجماعات 6. لذا آثر الجويني ترك بغداد والتوجه نحوبلاد الحجاز.\rوأخذ الجويني في الحجاز يتنقل ما بين الحرم المكي والحرم المديني لذا لقب بإمام الحرمين كما ذكرنا سابقا 7. لكن الذي يدعوإلى التوقف، أن\r_______________\r1) انظر ص 30 - 34.\r2) السبكي، طبقات الشافعية ج 2 ص 210.\r3) ابن العماد الحنبلي، شذرات الذهب ج 3 ص 359.\r4) ابن الأثير، الكامل في التاريخ ج 9 ص 227.\r5) ابن خلكان، وفيات الأعيان ج 3 ص 168، والذهبي، تاريخ الإسلام، حوادث (471 - 480) ص 230.\r6) ابن الأثير، الكامل في التاريخ ج 9 ص 614.\r7) انظر ص 56."], [65, "بعض المصادر حددت المدة التي قضاها إمام الحرمين بالحجاز بأربع سنين 1. لكن من المقطوع به أن الجويني لم يرجع إلى نيسابور إلا بعد وفاة طغرلبك (455 ه‍/ 1063 م) ومقتل عميد الملك الكندري عام (456 ه‍/ 1064 م)، إذ شارك إمام الحرمين في المؤتمر الذي عقد في مكة في أثناء موسم الحج، وضم إلى جانب الجويني أربعمائة شيخ وعالم وقاض من الأحناف والشافعية، وأعلن أبوالقاسم القشيري في هذا المؤتمر مقتل الكندري وتقطيعه إربا إربا 2. لذا يمكن القول: إن الجويني قد بقي في الحجاز حتى سنة 456 ه‍/ 1063 م، وبذلك يكون أمضى عشرة أعوام بعيدا عن نيسابور، وإذا ما أخذنا بعين الاعتبار أنه وصل بغداد سنة 447 ه‍/ 1055 م وغادرها في هذه السنة، يكون الجويني قد أمضى في بلاد الحجاز تسع سنين، منها أربع سنين مجاورا للحرم المكي كما أجمعت المصادر، أما السنين الخمسة الباقية فيحتمل أنه قضاها متنقلا ما بين مكة والمدينة.\r*رجوع إمام الحرمين إلى نيسابور:\rبعد وفاة السلطان السلجوقي طغرلبك، تولى أمر السلاجقة من بعده ابن أخيه السلطان ألب أرسلان، فسارع هذا السلطان إلى عزل عميد الملك الكندري وقتله عام 456 ه‍/ 1063 م 3.\rثم استوزر هذا السلطان نظام الملك الذي كان شافعيا في الفروع وأشعريا في الأصول، فبادر نظام الملك إلى رد الاعتبار للأشاعرة، وطلب من المبعدين منهم الرجوع إلى ديارهم، ثم بنى لهم وللشافعية النظاميات 4.\rوعند ما رجع الجويني إلى نيسابور طلب منه نظام الملك تولي التدريس بنظامية\r_______________\r1) ابن عساكر، تبيين كذب المفتري ص 280، والذهبي، تاريخ الإسلام، حوادث (471 - 480) ص 230، وابن كثير، البداية والنهاية ج 12 ص 128، وابن خلكان، وفيات الأعيان ج 3 ص 168.\r2) السبكي، طبقات الشافعية ج 3 ص 392.\r3) ابن الأثير، الكامل في التاريخ ج 10 ص 31.\r4) انظر ص 43."], [66, "نيسابور 1، فقبل ذلك وأقام فيها مجالس الوعظ والمناظرة والخطابة 2 إلى أن وافته المنية.\rأما المدة التي قضاها الجويني بالتدريس في النظامية، فلا يمكن الركون إلى ما ذكره السبكي وغيره من أصحاب التراجم، إذ حددوا هذه المدة بثلاثين عاما 3، ذلك أن الجويني قد توفي عام 478 ه‍، وبناء نظامية نيسابور قد تم عام 457 ه‍/ 1064 م، فيكون الجويني قد درس بالنظامية ما يقارب العشرين عاما فقط، وليس كما ذكره السبكي وغيره.\rوفي هذه الفترة توطدت العلاقة بين الجويني ونظام الملك 4، ويظهر ذلك جليا في كلمات المديح والثناء التي صدر بها إمام الحرمين بعض كتبه وحملت اسم نظام الملك، كالعقيدة النظامية، وغياث الأمم في التياث الظلم، والمعروف أن نظام الملك قد عرف أيضا بغياث الدولة.\rوفي نيسابور، قلد الجويني زعامة الأشاعرة ورئاسة الشافعية على حد سواء 5. ولم تقتصر زعامته على أصحابه من الأشاعرة والشافعية، وإنما امتدت لتشمل كامل نيسابور، إذ تروي المصادر أنه عند ما زار الشيخ أبوإسحاق الشيرازي نيسابور، لقي من أهلها حفاوة بالغة وعلى رأسهم شيخ البلد إمام الحرمين 6.\rوقبل أن نختم عرضنا لرحلات الجويني في الأقطار طلبا للعلم، من الضرورة بمكان أن نقف عند ما ذكره السبكي في هذا المجال. فقد أورد أن الجويني قد غادر إلى أصبهان بعد ما دبت الفرقة بين الأصحاب، ولكنه لم يوضح طبيعة هذه الفرقة ولا وقتها. ولا تسعفنا المصادر الأخرى لبيان حقيقة\r_______________\r1) ابن خلكان، وفيات الأعيان ج 3 ص 168.\r2) ابن كثير، البداية والنهاية ج 12 ص 128.\r3) السبكي، طبقات الشافعية ج 5 ص 171، وكذا قال ابن خلكان، وفيات الأعيان ج 3 ص 168.\r4) ابن عساكر، تبيين كذب المفتري ص 281.\r5) ابن خلكان، وفيات الأعيان ج 3 ص 168.\r6) السبكي، طبقات الشافعية ج 4 ص 222."], [67, "هذا الخلاف الذي حصل بين أشاعرة نيسابور، لكن الرحلة ثابتة، والخلاف قد حصل. ويمكن أن يكون ما ورد في ترجمة أبي القاسم الدبوسي (482 ه‍/ 1089 م) توضيحا لهذا الخلاف، فقد ذكر فيها أن الدبوسي هذا قد تكلم «مع أبي المعالي الجويني بنيسابور في مسألة، فآذاه أصحاب أبي المعالي، حتى خرجوا إلى المخاشنة، فاحتمل الدبوسي وما قابلهم بشيء، وخرج إلى أصبهان، فاتفق خروج أبي المعالي إليها في أثره في مهم يرفعه إلى نظام الملك، فجرى بينهما مسألة بحضرة الوزير نظام الملك، فظهر كلام الدبوسي عليه، فقال له: أين كلابك الضارية» 1. والمعروف أن أبا القاسم الدبوسي من الشافعية الأشاعرة، لذا يمكن تفسير الفرقة التي حصلت بين الأصحاب التي أشار إليها السبكي، بالتوتر الذي حدث بين أبي المعالي الجويني وتلامذته من جهة، والشيخ أبي القاسم الدبوسي من جهة أخرى.\r*ثقافة الجويني:\rلم تقتصر ثقافة إمام الحرمين عما أخذه من العلماء والمشايخ الذين تتلمذ عليهم، وإنما أدرك بذكائه الحاد، وذهنه الوقاد، أهمية التعلم والقراءات الذاتية في حياة العالم، وخير شاهد على ذلك، قوله عند ما درس الأصلين على أبي القاسم الإسفراييني: «كنت علقت عليه في الأصول أجزاء معدودة وطالعت في نفسي مائة مجلدة» 2. ويقول في موضع آخر: «ما تكلمت في علم الكلام كلمة حتى حفظت من كلام القاضي أبي بكر [الباقلاني] وحده اثني عشر ألف ورقة» 3.\rكذلك يبين مزاحه مع تلميذه الغزالي (505 ه‍/ 1111 م) هذا المنهج عند الجويني، فيحكى أنه قال يوما للغزالي: يا فقيه، فرأى امتعاض الغزالي من هذا النعت، وكأنه رأى فيه تحقيرأ لمنزلته العلمية، فبادره الجويني قائلا:\r«افتح هذا البيت، ففتح مكانا وجده مملوءا بالكتب، فقال له: ما قيل لي يا\r_______________\r1) السبكي، طبقات الشافعية ج 5 ص 297، ولم أجد هذه الرواية في الأنساب للسمعاني.\r2) السبكي، طبقات الشافعية ج 5 ص 175.\r3) المصدر نفسه ج 5 ص 185."], [68, "فقيه حتى أتيت على هذه الكتب» 1.\rولا يخفى أن ثقافة الجويني لم تقتصر على العلوم الدينية، وإنما اتسعت لتشمل أغلب العلوم السائدة في عصره، فكتبه في علم الكلام وأصول الفقه والخلاف والجدل والمناظرة مليئة بالقواعد المنطقية والأقيسة الشرطية، والاستدلالات العقلية، وهذا لم يتأت له إلا من بعد جهد ومعاناة في قراءة المنطق وتحصيل موضوعاته.\rأما الفلسفة فكان إمام الحرمين على اطلاع واسع بمسائلها وإشكالياتها، والمتتبع لمصنفاته في علم الكلام، يجد كثيرا من الردود على الفلاسفة اليونانيين، والبراهمة، والطبائعيين. والجويني نفسه لا يخفي تمكنه من علوم الأوائل منطقا كانت أم فلسفة، فهويقول: «لقد قرأت خمسين ألفا، ثم خليت أهل الإسلام بإسلامهم فيها، وعلومهم الظاهرة، وركبت البحر الخضم، وغصت في الذي نهي أهل الإسلام عنها، كل ذلك في طلب الحق» 2.\rوالمعلوم أن علوم المنطق والفلسفة كان منهيا عنها منذ أيام الإمام الشافعي (204 ه‍/ 819 م) وتفسيره للفساد العقدي الشائع في عصره باشتغال الناس بلسان أرسطاطاليس 3.\rلكن السؤال الذي يتبادر إلى الذهن، أين حصل الجويني هذه العلوم وعمن أخذها وهذا مما تصعب الإجابة عنه، إذ لم تشر المصادر إلى ذلك، لكن يمكن أن يكون الجويني قد حصل علوم الأوائل في أثناء رحلاته إلى أصبهان ومرووبغداد، إضافة إلى التحصيل الذاتي لها.\rولم يفت الجويني الاشتغال بالتصوف وطرقه 4، رغم أنه لم يترك مؤلفا في ذلك، وكان «الجويني في مجالسة الصوفية يبكي الحاضرين ببكائه،\r_______________\r1) السبكي، طبقات الشافعية ج 5 ص 185.\r2) ابن الجوزي، المنتظم ج 9 ص 19، والذهبي، سير أعلام النبلاء ج 18 ص 471.\r3) الذهبي، تاريخ الإسلام، حوادث (201 - 210) ص 339.\r4) ابن خلكان، وفيات الأعيان ج 3 ص 169، وطاش كبرى زادة، مصباح السعادة ج 2 ص 299."], [69, "لاحتراقه في نفسه وتحققه بما يجري من دقائق الأسرار» 1. فكأن الفترة التي أمضاها في مكة بين الصفا والمروة كانت فترة ممارسة الأحوال الصوفية، ليرتقي بنفسه بين مقاماتهم وما يترتب عليها من أحوال 2. ويمكن أن يكون تصوف الجويني مؤثرا في سير تلميذه الغزالي على هذا الطريق في ختام حياته الفكرية.\rمما سبق يتبين لنا أن إمام الحرمين كان عالما موسوعيا، تمكن من ثقافة عصره عمقا واتساعا، وأغناها بآرائه الفقهية والأصولية.\r*أخلاقه ومناقبه:\rاتصف الجويني بالعديد من الصفات الخلقية الحميدة، والمناقب العالية، التي تجعله مثال العالم بحق. وقد كان للتربية الصالحة التي عاشها الجويني في كنف والده، أثر عظيم في تهذيب نفسه، وتخلقه بالآداب الرفيعة، فقد حرص الشيخ أبومحمد على أن يوفر لابنه عبد الملك بيئة أسرية محصنة بالمعايير والمبادئ الإسلامية، ويظهر ذلك واضحا في موقف الوالد من المصة التي رضع فيها إمام الحرمين من جارية الجيران، وإنكاره ذلك، وحمل ابنه على التقيؤ ليتخلص من شبهة الحرام التي لحقت بهذه المصة 3.\rوسار الجويني على طريقة حميدة من أول عمره إلى آخره، وكان عاشقا للعلم محبا للعلماء، ويطلب العلم للعلم والعمل، ففي العلم والتعلم كان يجد نفسه ومتعته. وكان من شدة تواضع الجويني لأصحابه وتلامذته أنه كان لا يجد ضيرا أوحرجا في التعلم منهم، ومن صور هذا التواضع: أخذه عن تلميذه أبي نصر القشيري مسائل الحساب في الفرائض والدور والوصايا 4، وقراءته بعد ما اشتهر وذاع صيته لكتاب إكسير الذهب في صناعة الأدب على مؤلفه أبي الحسن المجاشعي 5 (452 ه‍/ 1060 م)، وحمله سرج دابة أبي\r_______________\r1) طاش كبرى زادة، مفتاح السعادة ج 2 ص 299.\r2) فوقية حسين، الجويني ص 39.\r3) انظر ص 60.\r4) ابن عساكر، تبيين كذب المفتري ص 308.\r5) ابن العماد، شذرات الذهب ج 3 ص 359."], [70, "إسحاق الشيرازي ومشيه بين يديه كالخادم عند ما زار نيسابور 1.\rوتمسك أبوالمعالي الجويني في مسيرته العلمية بأمانة كبيرة، وروح علمية عالية، فكان لا يجد حرجا في عزو«الفائدة المستفادة إلى قائلها، ويقول: إن هذه الفائدة مما استفدته من فلان» 2. لكنه في الوقت نفسه كان لا يحابي أحدا في التزييف إذ لم يرض كلامه، ولوكان أباه أوأحدا من الأئمة المشهورين 3، إذ كثيرا ما كان يكرر في مجالسه عند القراءة من كتب والده:\r«هذه زلة من الشيخ رحمه الله» 4.\rكما عرف إمام الحرمين بكرمه، فقد كان «قانعا باليسير في حياته، منفقا ما كان له من الدخل على أجراء المتفقهة» 5.\rوقد انعكست الصفات الخلقية التي تحلى بها هذا الإمام على عاداته الشخصية، إذ كان يقول: «أنا لا أنام ولا آكل عادة، وإنما أنام إذا غلبني النوم ليلا كان أونهارا، وآكل إذا اشتهيت الطعام أي وقت كان» 6.\r*مكانته وثناء العلماء عليه:\rعاش إمام الحرمين في عصر كثر فيه العلماء الأعلام من مختلف المذاهب بعامة، والأقطاب الشافعية والأشاعرة بخاصة، إلا أنهم لم يبلغوا من الشهرة الدرجة التي بلغها الجويني، ففي وقت قصير نسبيا، تمكن بواسع علمه، وعمق ثقافته، من دفع أقرانه من الشافعية والأشاعرة على حد سواء، إلى الاعتراف بعلومكانته، وأقروا له بزعامتهم ورئاستهم، إذ «قلد زعامة الأصحاب ورياسة الطائفة» 7.\r_______________\r1) السبكي، طبقات الشافعية ج 4 ص 222.\r2) المصدر نفسه ج 5 ص 180.\r3) المصدر نفسه ج 5 ص 180.\r4) ابن العماد، شذرات الذهب ج 3 ص 360.\r5) السبكي، طبقات الشافعية ج 5 ص 175 - 176.\r6) المصدر نفسه ج 5 ص 179.\r7) السبكي، طبقات الشافعية ج 5 ص 177."], [71, "كذلك تولى الجويني مناصب أخرى، كان أغلب معاصريه يحرصون على توليها، ومن هذه المناصب: أمور الأوقاف، والمحراب، والمنبر، ومجلس التذكير يوم الجمعة، والخطابة 1.\rومما يؤكد المكانة العالية التي تبوأها هذا الإمام، أنه عند ما بنيت نظامية نيسابور، طلب إليه تولي إدارتها، والتدريس بها، والخطابة والمناظرة بها 2.\rوكان لتولي الجويني أمر هذه النظامية دور كبير في نجاحها، وإقبال الطلبة عليها من كل حدب وصوب، ويذكر المؤرخون أن أعداد الطلبة في هذه المدرسة أيام إمام الحرمين كان يصل إلى نحومن أربعمائة رجل من الأئمة والطلبة 3.\rوقد أطنب أصحاب الطبقات والتراجم في ذكر عبارات المديح والثناء، وكذلك الأشعار في حق الإمام الجويني، وأكثرهم مبالغة في ذلك مؤرخ الأشاعرة والشافعية تاج الدين السبكي، ومن عبارات المبالغة في المديح والثناء التي حشد بها السبكي ترجمة إمام الحرمين:\r«إمام الأئمة على الإطلاق عجما وعربا. . . هوالبحر وعلامة درره الفاخرة، والسماء وفوائده التي أنارت الوجود نجومها الزاهرة». وفي موضع آخر يقول: «من ظن أن في المذاهب الأربعة من يداني فصاحته، فليس على بصيرة من أمره، ومن حسب أن في المصنفين من يحاكي بلاغته فليس ما يدري ما يقول» 4. ثم نظم فيه شعرا فقال:\rأبدا على طرف اللسان جوابه فكأنما هي دفعة من صيب\rيغدومساجله بعزة صافح ويروح معترفا بذله مذنب 5\rولأبي إسحاق الشيرازي أقوال تبين تقديره لإمام الحرمين، إذا قال له في\r_______________\r1) ابن خلكان، وفيات الأعيان ج 3 ص 168.\r2) المصدر نفسه ج 3 ص 168.\r3) الأسنوي، طبقات الشافعية ج 1 ص 199.\r4) السبكي، طبقات الشافعية ج 5 ص 165.\r5) المصدر نفسه ج 5 ص 165."], [72, "أثناء زيارته لنيسابور: «أنت الآن إمام الأئمة» 1. وفي مناسبة أخرى قال له:\r\r«يا مفيد أهل المشرق والمغرب، لقد استفاد من علمك الأولون والآخرون» 2.\rثم خاطب جمعا من أهل نيسابور قائلا: «تمتعوا بهذا الإمام فإنه نزهة هذا الزمان» 3.\rأما أبوعثمان الصابوني، وقد سمع كلام إمام الحرمين في أحد المحافل فقد قال: «صرف الله المكاره عن هذا الإمام، فهواليوم قرة عين الإسلام، والذاب عنه بحسن الكلام» 4.\rولا يعيب مديح الجويني أنه صدر من تلميذ له هوأبوالقاسم القشيري، إذ قال فيه: «لوادعى إمام الحرمين اليوم النبوة لاستغني بكلامه هذا عن إظهار المعجزة» 5.\rوقد بالغ الباخرزي صاحب الدمية كثيرا عند ما قال في الجويني: «ولم يخرج مثله المفتيان، عنيت النعمان بن ثابت ومحمد بن إدريس، فالفقه فقه الشافعي، والأدب أدب الأصمعي، وحسن بصره بالوعظ للحسن البصري. . .\rإذا تصدر للفقه فالمزني من مزنته قطرة، وإذا تكلم فالأشعري من فروته شعرة» 6.\rأما أبومحمد الجرجاني فقد وصفه قائلا: «إمام عصره، ونسيج وحده، ونادرة دهرة، عديم المثل في حفظ لسانه» 7.\rومن الأشعار التي قيلت مدحا لإمام الحرمين:\r_______________\r1) ابن خلكان، وفيات الأعيان ج 3 ص 168.\r2) الذهبي، سير أعلام النبلاء ج 18 ص 470.\r3) السبكي، طبقات الشافعية ج 5 ص 173.\r4) المصدر نفسه ج 5 ص 174.\r5) ابن عساكر، تبيين كذب المفتري ص 282.\r6) السبكي، طبقات الشافعية ج 5 ص 173.\r7) المصدر نفسه ج 5 ص 173."], [73, "دعوا لبس المعالي فهوثوب على مقدار قد أبي المعالي 1\rومنها:\rلم تر عيني أحدا تحت أديم الفلك\rمثل إمام الحرمي‍ن الندب عبد الملك 2\r\r*المطاعن التي أثيرت بحق إمام الحرمين:\rأوردت بعض كتب التراجم والطبقات، جملة من المواقف الفكرية، أثارها الجويني في مصنفاته الأصولية، ومجالسه العلمية، وهذه المواقف تمسك بها بعض خصوم الأشاعرة، للحط من المكانة العلمية التي حازها هذا الإمام، وتتلخص هذه المطاعن بما يلي:\r\r*المطعن الأول: عودته إلى مذهب السلف في نهاية حياته:\r\rنقل ابن الجوزي الحنبلي، عن أبي سعد السمعاني، أن إمام الحرمين قد قال في أحد مجالسه: «قرأت خمسين ألفا في خمسين ألفا، ثم خليت أهل الإسلام بإسلامهم فيها وعلومهم الظاهرة، وركبت البحر الخضم العظيم، وغصت في الذي نهي أهل الإسلام عنها، كل ذلك في طلب الحق، وكنت أهرب في سالف الدهر من التقليد، والآن رجعت من الكل إلى كلمة الحق، عليكم بدين العجائز، فإن لم يدركني الحق بلطيف بره، فأموت على دين العجائز، ويختم عاقبة أمري عند الرحيل على نزهة أهل الحق، وكلمة الإخلاص: لا إله إلا الله، فالويل الويل لابن الجويني، يريد نفسه» 3.\rويذكر الذهبي في تاريخه رواية أخرى بالمعنى نفسه، عن أبي الفتح الطبري الفقيه فيقول: «دخلت على أبي المعالي في مرضه فقال: اشهدوا علي\r_______________\r1) السبكي، طبقات الشافعية ج 5 ص 173.\r2) ابن الجوزي، المنتظم ج 9 ص 19، والذهبي، سير أعلام النبلاء ج 18 ص 470، وتاريخ الإسلام، حوادث (471 - 480) ص 232، وابن النجار، ذيل تاريخ بغداد ص 90، والسبكي، طبقات الشافعية ج 5 ص 185.\r3) الذهبي، تاريخ الإسلام، حوادث (471 - 480) ص 236."], [74, "أني قد رجعت عن كل مقالة تخالف السلف، وإني أموت على ما تموت عليه عجائز نيسابور».\rوقد تناقلت كتب خصوم الأشاعرة أقوال الجويني هذه بقصد الحط من منزلته العلمية بخاصة، وللنيل من المذهب الأشعري بعامة، فقد فهم من هذه النقول أن إمام الحرمين قد أدار ظهره للإسلام، وفهم أهل الظاهر لقضاياه، وسار في طريق وعر لا مكان فيه إلا لما أثبته العقل، وهوطريق الفلاسفة.\rكذلك فهم خصوم الجويني والأشاعرة من هذه الأقوال، أن الجويني قد أدرك في نهاية حياته العلمية، فساد ما قضى معظم حياته يدافع عنه، وهوالمعتقد الأشعري، لذا رجع إلى صحة المعتقد المتمثل بمذهب أهل السلف، والمنعكس في بساطته بالسلوك الديني للعجائز.\rوقد دافع السبكي عن الإمام الجويني، وحاول رد هذا المطعن، مبينا أن إمام الحرمين لم يقصد في أقواله هذه، الرجوع عن الفهم الأشعري للصفات الإلهية وفق المنهج التأويلي لها، إلى الاعتقاد بهذه الصفات على مذهب أهل الظاهر، لأن ذلك يؤدي إلى التجسيم 1، والأحرى تفسير ذلك؛ بأن الإمام أراد في أقواله هذه فهم الصفات على ظاهرها، مع تنزيه صفات الخالق عن صفات المخلوقين 2.\rلكن السبكي وإن تمعر في الدفاع عن الجويني، إلا أن ما قاله لا يقوى أمام ما ذكره الجويني في العقيدة النظامية، إذ يقول: «ذهب أئمة السلف إلى الانكفاف عن التأويل وإجراء الظواهر على مواردها، وتفويض معانيها إلى الرب تعالى، والذي نرتضيه رأيا، وندين به عقلا، اتباع سلف الأمة، فالأولى الاتباع وترك الابتداع» 3.\rوفي نص آخر يقول: «وإذا انصرم عصرهم-يعني عصر الصحابة- وعصر التابعين على الإضراب عن التأويل، كان ذلك قاطعا بأنه الوجه المتبع،\r_______________\r1) السبكي، طبقات الشافعية ج 5 ص 191، 192.\r2) المصدر نفسه ج 5 ص 191.\r3) انظر ص 166."], [75, "فحق على ذي دين، أن يعتقد تنزه الباري عن صفات المحدثين، ولا يخوض في تأويل المشكلات، ويكل معناها إلى الرب تبارك وتعالى» 1.\rومن المسائل التي خالف الجويني فيها الأشاعرة، مسألة خلق أفعال العباد، إذ أثبت لقدرة العبد الحادثة تأثيرا حقيقيا في مقدورها 2. وقد دفع ذلك بعض أقطاب الأشاعرة المتأخرين إلى مهاجمته والانتصار لشيخهم الأشعري، كالشهرستاني والرازي والآمدي والجرجاني 3.\r*المطعن الثاني: جهل الجويني بالحديث:\r\rنقل الذهبي في معرض ترجمة لإمام الحرمين، أنه «مع تبحره في الفقه وأصوله، لا يدري الحديث». واستدل على ذلك بما ذكره الجويني في كتاب البرهان في أصول الفقه، من أن حديث معاذ بن جبل في القياس، عند ما أرسله الرسول صلى الله عليه وسلم قاضيا إلى اليمن: «هومدون في الصحاح، متفق على صحته» 4.\rوقد تبنت فوقية حسين دفاع السبكي ورده هذه التهمة عن الجويني، فإن كان الجويني قد أخطأ في حديث واحد أوأكثر، فهذا ليس حجة على جهل الإمام بالحديث، فالجويني قد اشتغل بالفقه وأصوله، والخلافيات، وهذا يتطلب منه دراية تامة وعميقة بالحديث وعلومه. كما أن قول الجويني إن هذا الحديث مدون بالصحيح، قد يفهم منه، أنه مدون في الصحاح غير صحيح مسلم والبخاري، كصحيح سنن المصطفى لأبي داود، والجامع الصحيح المسمى سنن الترمذي 5.\rوالحق أن الجويني لم يكن عالما متخصصا بالحديث، وفي ذلك يقول\r_______________\r1) انظر ص 166.\r2) انظر ص 193.\r3) انظر: إشكاليات الجبر والاختيار عند الأشاعرة، دراسة في نظرية الكسب للمحقق ص 178، 192، 210.\r4) الذهبي، تاريخ الإسلام، حوادث (471 - 480) ص 233، وسير أعلام النبلاء ج 18 ص 472.\r5) السبكي، طبقات الشافعية ج 5 ص 187، 188، وفوقية حسين، الجويني ص 206."], [76, "السمعاني: «وكان قليل الرواية للحديث معرضا عنه» 1. وأكد ذلك ياقوت الحموي في نقله عن السمعاني 2.\rلكن الجويني لم يكن بدعا من علماء الكلام والأصول في الإعراض عن الحديث وروايته، وإنما كان ذلك حال أغلب المتكلمين والأصوليين، وكان الكثير منهم لا يجد ضيرا من رواية الحديث بالمعنى لا بلفظه الثابت.\rوالجويني لم يدع أنه كان محدثا من الطراز الأول، فإذا حكمنا على الجويني بالجهل في الحديث من خلال حديث واحد، والحديث ليس صناعته، فما الحكم الذي نصدره على محدثين كبارا جمعوا في سننهم ومسانيدهم ومعاجمهم أحاديث ضعيفة، وأحيانا موضوعة، ظانين أنها أحاديث صحيحة.\r\r*المطعن الثالث: قول الجويني إن الله لا يعلم الجزئيات:\rنقل عن أبي عبد الله المازري، شارح كتاب البرهان في أصول الفقه، أن الجويني ذكر فيه: أن الله تعالى يعلم الكليات لا الجزئيات» 3. ويعقب المازري على ذلك قائلا: «وددت لومحوتها بدمي» 4. ثم يضيف قائلا «إن الإمام الأشعري الكبير أبا القاسم القشيري حلف لا يكلمه أبدا، ونفي بسببها فجاور وتاب» 5.\rويرد السبكي هذا المطعن، مبنيا أنه هذه الروايات خرافات من طلبة الحنابلة، ثم بين أن «الأشاعرة قد أجمعوا على تكفير من يعتقد هذه المقالة، والإمام الجويني قد نص في كتبه الكلامية بأسرها على كفر من ينكر العلم بالجزئيات، وإنما وقع في البرهان في أصول الفقه شيء استطرده القلم إليه،\r_______________\r1) السمعاني، الأنساب ج 2 ص 130.\r2) ياقوت الحموي، معجم البلدان ج 2 ص 193.\r3) الذهبي، تاريخ الإسلام، حوادث (471 - 480) ص 233، وسير أعلام النبلاء ج 18 ص 472.\r4) الذهبي، تاريخ الإسلام، حوادث (471 - 480) ص 233، وسير أعلام النبلاء ج 18 ص 472.\r5) الذهبي، تاريخ الإسلام، حوادث (471 - 480) ص 233."], [77, "فهم منه المازري ثم أمر هذا» 1.\rثم عقد السبكي فصلا مطولا لينفي هذه التهمة عن الجويني 2، وأنكر في الوقت نفسه أن يكون القشيري قد هجر الجويني يسبب ذلك، وما هذه الرواية عن القشيري إلا من تخرصات ابن دحية الذي لا تقبل روايته، فهومن وضاع الحديث 3. ولا يجد السبكي في مؤلفات إمام الحرمين ما يؤكد هذه التهمة، إذ يقول: «لقد فحصت عن كلمات هذا الإمام في كتبه الكلامية فوجدت إحاطة علم الله تعالى عنده بالجزئيات أمرا مفروغا منه، وأصلا مقررا يكفر من خالفه فيه» 4.\rأما ما ذكر عن الجويني في البرهان، فلم يكن نصا صريحا في عدم علم الله تعالى بالجزئيات، وإنما هومن باب استنتاجات المازري في شرحه للبرهان، والمازري من المغاربة، والمغاربة شديد والتعظيم لأبي الحسن الأشعري والإمام مالك، ويمكن أن يكون قد هاله معارضة الجويني للأشعري والإمام مالك في بعض المسائل الأصولية التي عرضت في البرهان 5، لذا كان ما ذكر من باب التحامل على هذا الإمام.\rإن هذا الدفاع، وإن صدر من أشعري متحمس لا ينفي موضوعيته إلى درجة كبيرة خصوصا إذا أخذنا بعين الاعتبار، الصمت التام عن هذه المسألة من الأشاعرة المتأخرين عن الجويني، وهؤلاء لم يعتادوا السكوت عن مثل هذه المخالفات لمذهب الأشعري، خصوصا وأن هؤلاء المتأخرين كالشهرستاني والرازي والآمدي والجرجاني، لم يغفروا للجويني قوله بنظرية الأحوال البهشمية، ومخالفته للشيخ الأشعري في القدرة الحادثة، وكونها مؤثرة حقيقة في الفعل الإنساني 6.\r_______________\r1) السبكي، طبقات الشافعية ج 5 ص 188.\r2) المصدر نفسه ج 5 ص 192 - 207.\r3) المصدر نفسه ج 5 ص 185.\r4) المصدر نفسه ج 5 ص 193، وانظر: فوقية حسين، الجويني ص 207.\r5) السبكي، طبقات الشافعية ج 5 ص 192 - 193.\r6) انظر: إشكاليات الجبر والاختيار عند الأشاعرة للمحقق ص 115."], [78, "*المطعن الرابع: حيرته في مسألة الاستواء على العرش:\r\rسئل الإمام الجويني عن قول الله تعالى: الرحم?ن على العرش استوى? 1 فحاص وباص وقال: «كان الله ولا عرش، وهوالآن على ما كان عليه، فرد عليه أحد العارفين، لكن الضرورة في قلوبنا تطلب العلوولا نلتفت يمنة ولا ميسرة، وما قال عارف قط يا رباه إلا وسبقه نظره إلى فوق، فما كان من إمام الحرمين إلا أن ضرب بكمه على السرير، وصاح بالحيرة والدهشة» 2.\rويبدي السبكي الدهشة من هذه الرواية، فهل يعقل أن من له مثل هذه المكانة في العلم بعامة، وفي علم الكلام بخاصة أن يعجز عن الإجابة عن هذه المسألة التي لا تحتاج إلا أن نقول: «لا يقول عارف يا رباه إلا قد غابت عنه الجهات، ولوكانت جهة فوق مطلوبة لما منع المصلي من النظر إليها، وشدد عليه في الوعيد عليها» 3. ثم يتهم السبكي ناقلي الرواية بالدس والكذب، خاصة وأن فيهم قدرا من التحامل على الأشعري وأصحابه 4.\r\r*المطعن الخامس: رجوعه عن علم الكلام:\rروي عن الجويني أنه قال في أواخر حياته: «لا تشتغلوا بالكلام، فلوعرفت أن الكلام يبلغ بي ما بلغ ما اشتغلت به» 5. وهذا يعني أن الجويني قد أضاع عمره بعلم لا ينفع، وما العلم النافع إلا ما اشتغل به أهل السلف بعيدا عن الكلام.\rويدفع السبكي هذا المطعن بأن بين أن هذه الرواية من المكذوبات على الإمام، وأن ناقليها متحاملون عليه 6. ثم لا يجد السبكي ضيرا إن رجع\r_______________\r1) سورة طه، الآية 5.\r2) السبكي، طبقات الشافعية ج 5 ص 190، والذهبي، تاريخ الإسلام، حوادث (471 - 480) ص 236، 238.\r3) المصدر نفسه ج 5 ص 190،191.\r4) المصدر نفسه ج 5 ص 190.\r5) السبكي، طبقات الشافعية ج 5 ص 186، وابن الجوزي، المنتظم ج 9 ص 19، والذهبي، تاريخ الإسلام، حوادث (471 - 480) ص 235.\r6) السبكي، ج 5 ص 186 - 187، وفوقية حسين، الجويني ص 209."], [79, "الجويني عن الكلام إن ظهر له الحق في هذا الرجوع 1.\rويمكن القول: إن الجويني لم يترك الكلام والاشتغال به، لكنه في أواخر حياته العلمية، قد مال إلى الاقتصاد في الكلام، وهذا يظهر جليا في آخر مؤلفاته العقدية وهوالعقيدة النظامية، إذ نجده يقف موقفا وسطيا ما بين الأشاعرة وأهل السلف في أغلب القضايا الكلامية التي عالجها في هذا الكتاب.\r\r*وفاة الجويني:\rأصيب الجويني قبل وفاته بمرض اليرقان عدة أيام، انقطع خلالها عن المجالس وحلقات التدريس بالنظامية 2. ثم تعافى من المرض ورجع إلى التدريس والمناظرة، وأضفى ذلك سرورا بالغا على تلامذته ومحبيه 3. لكن المرض عاوده من جديد واشتد عليه، فزاد ضعفه، ولم يقوعلى مزاولة أعماله ثم نقل إلى بلدة بشتقان إحدى قرى نيسابور، وكانت معروفة باعتدال هوائها 4. إلا أن المرض تمكن منه، وبدت عليه أحوال الموت، ثم توفي في هذه البلدة وقت صلاة العشاء في الخامس والعشرين من شهر ربيع الآخر من سنة ثمان وسبعين وأربع مائة للهجرة 5، وكان عمره تسعا وخمسين سنة 6.\rثم نقل جثمان الجويني في تلك الليلة إلى نيسابور، وحمل في يوم الأربعاء بين الصلاتين إلى ميدان الحسين في المدينة 7، وتقدم ابنه أبوالقاسم المظفر الحشود الضخمة التي سارت في جنازته، وصلى عليه بعد جهد كبير لكثرة الجموع 8. ثم أعيد إلى داره ودفن فيها، لكن جثمانه نقل فيما بعد إلى\r_______________\r1) السبكي، طبقات الشافعية ج 5 ص 187.\r2) محمد الحسني، العقد الثمين ج 5 ص 507.\r3) السبكي، طبقات الشافعية ج 5 ص 180.\r4) السمعاني، الأنساب ج 1 ص 357، وابن خلكان، وفيات الأعيان ج 3 ص 169.\r5) ابن الجوزي، المنتظم ج 9 ص 20.\r6) الأسنوي، طبقات الشافعية ج 1 ص 198.\r7) السبكي، طبقات الشافعية ج 5 ص 181.\r8) الأسنوي، طبقات الشافعية ج 1 ص 198."], [80, "مقبرة الحسين في نيسابور ودفن إلى جانب والده 1.\rوكان لوفاة الجويني وقعا شديدا على أهالي نيسابور، والبلاد المجاورة بعامة، وعلى تلامذته ومحبيه بخاصة، ففي يوم وفاته أغلقت الأسواق، وقعد الناس أياما للعزاء «ووضعت المناديل عن الرؤوس عاما، بحيث ما اجترأ أحد على ستر رأسه من الرؤوس الكبار» 2\rأما تلامذته الذين كانوا يناهزون الأربعمائة، فقد غلب عليهم الحزن الشديد، وكسروا منبر الجويني بالجامع، ثم كسروا أقلامهم ومحابرهم، وكانوا يطوفون الشوارع وهم في حالة من الجزع المفرط 3. وقد دفعت هذه الأعمال مبغضي الجويني إلى النيل منه والتعريض به 4.\r_______________\r1) ابن خلكان، وفيات الأعيان ج 3 ص 169.\r2) المصدر نفسه ج 3 ص 169.\r3) السبكي، طبقات الشافعية ج 5 ص 181.\r4) انظر: الذهبي، تاريخ الإسلام، حوادث (471 - 480) ص 239."]], "pg": [54, 80]}, "474.6": {"x": [[81, "الفصل الخامس: شيوخ الجويني وتلامذته\r\r*أولا: شيوخه\rدأب إمام الحرمين منذ صغره على تحصيل العلم، وبذل من أجل ذلك جهدا عظيما، فكان «يصل الليل بالنهار» 1 تلقيا عن كبار علماء ومشايخ عصره، واستمر الجويني في ذلك حتى بعد أن قعد للتدريس في مجلس والده، إذ كان يغتنم الفرص التي يكون فيها متحررا من أعباء التدريس والوعظ والخطابة، ويذهب إلى مجالس العلماء. وفي ذلك ذكرت المصادر أنه بعد فراغه من التدريس كان يتوجه إلى المدرسة البيهقية، ويدرس الأصول على أبي القاسم الإسكاف الإسفراييني 2.\rوكان الجويني أيضا، لا يجد حرجا في تحصيل العلم بعد أن ملأت شهرته الآفاق، إذ نجده قبل وفاته بتسع سنين، يذهب يوميا إلى دار أبي الحسن المجاشعي، ويقرأ عليه النحومن كتابه إكسير الذهب في صناعة الأدب 3.\rكذلك كان إمام الحرمين لا يستصغر أحدا في علمه إلا من بعد أن يسمع له، فإن أبان له عن علم واسع وعمق معرفة، أخذ عنه صغيرا كان أم كبيرا 4. لذا نجده يأخذ عن تلامذة له، وينسب ما يأخذه إليهم 5.\r_______________\r1) السبكي، طبقات الشافعية ج 5 ص 175.\r2) ابن خلكان، وفيات الأعيان ج 3 ص 168.\r3) ابن العماد الحنبلي، شذرات الذهب ج 3 ص 359.\r4) المصدر نفسه ج 3 ص 360.\r5) الأسنوي، طبقات الشافعية ج 1 ص 197."], [82, "ويلاحظ في هذا المقام، قلة عدد العلماء الذين حصل إمام الحرمين العلم عنهم، إذا ما قورن بعدد مشايخ بعض العلماء المعاصرين له، كالخطيب البغدادي (463 ه‍/ 1070 م) والحافظ أبي بكر البيهقي (458 ه‍/ 1065 م).\rويمكن عزوقلة مشايخ الجويني، إلى أنه قد حدد منذ بداية تلقيه العلم، اهتماماته العلمية بالفقه، وأصوله، وأصول الدين، ولواحقهما من جدل وخلاف ومناظرة. أما العلوم الأخرى التي تتطلب كثرة السماع من الشيوخ، كالحديث، والقراءات، فقد كان معرضا عنها، إلا فيما تتطلبه العلوم السابقة.\r\rومن مشايخ إمام الحرمين:\r*والده، أبومحمد الجويني، وقد تقدمت ترجمته 1.\r*أبوالقاسم الإسفراييني 2 (452 ه‍/ 1060 م):\rهوعبد الجبار بن علي بن محمد بن حسكان، الأصم، الإسفراييني، المعروف بالإسكاف نسبة إلى بلده إسكاف، كان من رؤساء متكلمي الأشاعرة، وأعيان الشافعية، والمبرزين في الفتوى، وكان يميل إلى الزهد والورع، وله قدم في النظر والتدريس مع ميل إلى طريق السلف. ومن غرائبه أنه قال؛ لوأن رجلا وطئ زوجته معتقدا أنها أجنبية فعليه الحد. تتلمذ على الشيخ أبي إسحاق الشيرازي، وكان إمام الحرمين يلازمه ويقرأ عليه الأصول حتى تخرج بطريقته.\r*أبوعبد الله الخبازي 3 (372 ه‍449 ه‍/ 982 - 1057 م):\rمحمد بن علي بن محمد بن الحسن، المقرئ، النيسابوري، الخبازي،\r_______________\r1) انظر ص 58.\r2) مصادر ترجمته: ابن عساكر، تبيين كذب المفتري ص 265، والذهبي، تاريخ الإسلام، حوادث (441 - 460) ص 328، والسبكي، طبقات الشافعية ج 5 ص 99، وابن قاضي شهبة، طبقات الشافعية ج 1 ص 229، والصريفيني، المنتخب من السياق ص 342.\r3) مصادر ترجمته: ابن عساكر، تبيين كذب المفتري ص 263، وابن نقطة، التقييد ص 90، والذهبي، تذكرة الحفاظ ج 3 ص 1127، وابن الجزري، غاية النهاية ج 2 ص 207، والصفدي، الوافي بالوفيات ج 4 ص 130."], [83, "ولد بنيسابور وقرأ القرآن على والده، وعلى أبي بكر الطرازي. وسمع أبي الحسن الماسرجي، وأبي محمد المخلدي، وأبي أحمد الحاكم، وسمع صحيح البخاري من الكشميهني. اختص بالقراءة حتى أصبح شيخ القراء في عصره، وتخرج به كثير من العلماء. وكان الخبازي على علاقة وطيدة مع السلطان محمود الغزنوي، إذا واظب على زيارته في غزنة. صنف الخبازي كتاب الأبصار، وضمنه أصول الروايات وغرائبها. روى عنه الفراوي، وأبوالقاسم الهذلي. وكان إمام الحرمين يبكر كل يوم قبل الاشتغال بالتدريس إلى مجلس الخبازي، ويقرأ عليه القرآن.\r\r*القاضي حسين 1 (462 ه‍/ 1069 م):\rحسين بن محمد بن أحمد، أبوعلي المروذي (المروروذي)، المعروف بالقاضي حسين. كان فقيه خراسان في عصره وشيخا للشافعية، ويقال له: حبر الأمة. وهومن وجوه المذهب الشافعي، كبير القدر، غواص على المعاني الدقيقة والفروع المستفادة.\rتفقه على أبي بكر القفال ولازمه، وكان من أنجب تلامذته وأوسعهم فقها، صنف أسرار الفقه والفتاوى، وشرح الفروع، وله التعليق الكبير. أخذ عنه أبوسعد المتولي وأبومحمد محيي الدين البغوي، وتفقه عليه إمام الحرمين، وكان يقول فيه: إنه حبر المذهب على الحقيقة.\r\r*أبونعيم الأصبهاني 2 (430 ه‍/ 1038 م):\rأحمد بن عبد الله بن أحمد بن إسحاق، أبونعيم الأصبهاني الحافظ، كان من كبار الصوفية والمحدثين الحفاظ الثقات، والفقهاء الكبار، وأتقن الحديث دراية ورواية.\r_______________\r1) مصادر ترجمته: العبادي، طبقات فقهاء الشافعية ص 112، والنووي، تهذيب الأسماء واللغات ج 1 ص 164، والسمعاني، الأنساب ج 5 ص 262، وابن خلكان، وفيات الأعيان ج 2 ص 134، والذهبي، تاريخ الإسلام، حوادث (461 - 470) ص 62.\r2) مصادر ترجمته: ابن خلكان، وفيات الأعيان ج 1 ص 91، وابن عساكر، تبيين كذب المفتري ص 246، وابن الجوزي، المنتظم ج 8 ص 100، والذهبي، تذكرة الحفاظ ج 3 ص 1092، والسيوطي، طبقات الحفاظ ص 423."], [84, "ولد بأصبهان، ورحل كثيرا طلبا للحديث، فكثر شيوخه، ومنهم: أبوالعباس الأصم، وأبوبكر الآجري، وجعفر الخلدي، والطبراني، وابن شوذب. وممن روى عنه: أبوسعد الماليني، والخطيب البغدادي، وهبة الله بن محمد الشيرازي. من تصانيفه المشهورة: حلية الأولياء، ودلائل النبوة، وتاريخ أصبهان، ومعرفة الصحابة، والمستخرج على البخاري ومسلم. أخذ عنه إمام الحرمين وحصل على الإجازة منه.\r\r*أبوالقاسم الفوراني 1 (463 ه‍/ 1070 م):\rعبد الرحمن بن محمد بن فوران، أبوالقاسم المروزي، الفوراني. كان شافعي المذهب ومقدم الشافعية في مرو. أخذ الفقه عن أبي بكر القفال الشاشي، واشتغل بالفقه وأصوله، وله مصنفات كثيرة في المذهب والأصول والخلاف والجدل والملل والنحل، ومنها: كتاب الإبانة، وكتاب العمد. ومن تلامذته: أبوسعد المتولي، وإمام الحرمين.\rوقد كان الجويني يحضر درسه وهوشاب بمرو، لكن الفوراني كان لا يلتفت إليه، ولا ينصفه، فحمل الجويني ذلك في نفسه، وكان يشير إليه في كتابه نهاية المطلب وكأنه يتجاهله بقوله: وقال بعض المصنفين، أوالمتفقهين -للحط من شأنه-حتى قال عنه في مسألة الأذان: «والرجل غير موثوق بنقله» مما دفع بعض العلماء إلى النيل من الجويني بسبب ذلك. وربما فعل الجويني هذا بشيخه الفوراني، لأن هذا الشيخ قدم نيسابور معزيا بوالد إمام الحرمين، فحسبه أنه قد جاء ليأخذ مكان والده في مجالسه العلمية.\r\r*أبوالحسن المجاشعي 2 (452 ه‍/ 1060 م):\rعلي بن فضال بن علي بن طالب، أبوالحسن، النحوي، المجاشعي.\r_______________\r1) مصادر ترجمته: النووي، تهذيب الأسماء واللغات ج 2 ص 280، والسمعاني، الأنساب ج 4 ص 405، وابن خلكان ج 3 ص 132، والذهبي، سير أعلام النبلاء ج 18 ص 264، وابن قاضي شهبة، طبقات الشافعية ج 1 ص 248.\r2) مصادر ترجمته: ابن الجوزي، المنتظم ج 9 ص 33، وابن كثير، البداية والنهاية ج 12 ص 132، والباخرزي، دمية القصر ج 1 ص 133، والذهبي، سير أعلام النبلاء ج 18 ص 528، واليافعي، مرآة الجنان ج 2 ص 12، والداودي، طبقات المفسرين ج 1 ص 421."], [85, "ولد بهجر، وطاف بالبلدان حتى حطت به الرحال في غزنة، فصحب الوزير نظام الملك، وأقبل على درسه أكابر العلماء.\rاشتهر بالنحو، لذا يقال له: النحوي. صنف العوامل والهوامل، وشرح عنوان الإعراب، والإشارة في تحسين العبارة. وعند ما قدم المجاشعي نيسابور، اقترح عليه إمام الحرمين أن يصنف باسمه كتابا في النحو، ووعده بألف دينار، فصنف المجاشعي الكتاب وسماه: إكسير الذهب في صناعة الأدب، ثم قرأه الجويني عليه، وعند ما فرغ من قراءته، انتظره المجاشعي أن يدفع إليه ما وعده، فلم يعطه شيئا، فأرسل إليه المجاشعي: إنك إن لم تف بما وعدت هجوتك، فبعث إليه الجويني رسولا قائلا له: نكثتها، عرضي فداؤك، ولم يعطه حبة، لذا غضب ورحل عن نيسابور، وحط في بغداد، وترك الكلام في النحو.\r\r*أبوسعيد الميهني 1 (440 ه‍/ 1048 م):\rفضل الله (الفضل) بن أحمد بن محمد بن أبي الخير الصوفي، أبوسعيد الميهني، نسبة إلى ميهنة بخراسان. كان صاحب أحوال وكرامات. غمز الذهبي من قناته في الاعتقاد فقال: ولكن في اعتقاده شيء. وتكلم فيه ابن حزم الأندلسي. لكن السبكي رد اتهام أستاذه الذهبي قائلا: وكان صحيح الاعتقاد، حسن الطريقة، أحواله تبهر العقول. . . ولكنه أشعري صوفي، فمن ثم نال منه الرجلان، وباءا بإثمه. روى عنه: زاهر بن أحمد السرخسي، وأبوالقاسم الأنصاري، وإمام الحرمين الجويني. ويمكن أن تكون نفحة الصوفية التي لازمت إمام الحرمين بفعل أبي سعيد الميهني.\r*ومن مشايخ الحديث الذين روى عنهم إمام الحرمين: أبوسعد عبد الرحمن بن الحسن بن عليك 2 (431 ه‍/ 1039 م)، وأبومحمد\r_______________\r1) مصادر ترجمته: السمعاني، الأنساب ج 5 ص 439، والذهبي، سير أعلام النبلاء ج 17 ص 622، وتاريخ الإسلام، حوادث (421 - 440) ص 487، والصريفيني، المنتخب ص 409، والسبكي، طبقات الشافعية ج 5 ص 306.\r2) مختلف في وفاته، قيل سنة 428 ه‍، وقيل 431 ه‍. انظر: الذهبي، تاريخ الإسلام، حوادث (421 - 440) ص 237."], [86, "الجوهري 1 (454 ه‍/ 1062 م)، ومنصور بن رامش 2 (427 ه‍/ 1035 م)، وأبوسعد النضروي 3 (433 ه‍/1041 م)، وأبوعبد الرحمن النيلي 4 (436 ه‍/ 1044 م).\rوقد ذكرت فوقية حسين، أن الإمام البيهقي هومن شيوخ إمام الحرمين، وترجمت له في قائمة شيوخه، ونقل عنها ذلك دون أن يشير إليها محمد الزحيلي 5. وهذا ليس بصحيح، فلم تشر المصادر التي اطلعت عليها، ومن ضمنها المصادر التي ذكرها هذان الباحثان في معرض تقريرهما أن الجويني قد أخذ عن البيهقي. ويمكن أن يكون قد أشكل عليهما العبارة التي ذكرت أن الجويني كان يذهب إلى المدرسة البيهقية ليتلقى الأصول عن أبي القاسم الإسكاف، فأدرجا البيهقي في قائمة شيوخ إمام الحرمين.\rكذلك ذكر ابن قاضي شهبة نقلا عن السبكي، أن إمام الحرمين قد تتلمذ على المتكلم الأشعري والفقيه الشافعي أبي منصور التميمي البغدادي 6، وأخذ عنه الفرائض. وهذا أيضا يصعب الأخذ به أوتصديقه، ذلك لأن البغدادي قد توفي عام (429 ه‍/ 1037 م) بإسفرايين، أما الجويني فقد ولد عام 419 ه‍/ 1028 م في نيسابور، ولم تذكر المصادر أن والد الجويني قد ارتحل\r_______________\r1) هوالحسن بن علي بن محمد بن الحسن، أبومحمد الجوهري الشيرازي. انظر ترجمته في: الخطيب البغدادي، تاريخ بغداد ج 7 ص 393، والذهبي، سير أعلام النبلاء ج 18 ص 68، وابن نقطة، التقييد ص 235.\r2) هومنصور بن رامش بن عبد الله بن زيد، أبوعبد الله النيسابوري. انظر ترجمته في: الخطيب البغدادي، تاريخ بغداد ج 3 ص 86، والذهبي، سير أعلام النبلاء ج 17 ص 540، والصريفيني، المنتخب ص 438.\r3) هوعبد الرحمن بن حمدان بن محمد، أبوسعد النصروي النيسابوري. انظر ترجمته في: السمعاني، الأنساب ج 5 ص 494، والذهبي، سير أعلام النبلاء ج 17 ص 533، والصريفيني، المنتخب ص 307.\r4) هومحمد بن عبد العزيز بن عبد الله بن محمد النيلي، من الشافعية. انظر ترجمته في: العبادي، طبقات فقهاء الشافعية ص 101، والسبكي، طبقات الشافعية ج 4 ص 178، والصريفيني، المنتخب ص 31، والذهبي، حوادث (421 - 440) ص 438.\r5) فوقية حسين، الجويني ص 29، ومحمد الزحيلي، الإمام الجويني ص 76.\r6) ابن قاضي شهبة، طبقات الشافعية ج 1 ص 211."], [87, "بابنه إلى إسفرايين وهوفي هذه السن المبكرة، ليمكنه من تعلم علم الفرائض.\rكذلك فإن المصادر كافة التي عالجتها بما فيها طبقات السبكي لم تأت على ذكر هذه الرواية، إلا إذا كان السبكي قد ذكر ذلك في طبقاته الوسطى 1.\r\r*ثانيا: تلامذته\rلا خلاف بين أصحاب التراجم، بأن الجويني قد أصبح في نيسابور محط أنظار العلماء والتلامذة، لذا رحل إليه الطلبة والمشايخ من مختلف الأرجاء، وثابروا على حضور مجالسه العلمية، وحلقات درسه، فتخرج به كثير من العلماء. ومما ساهم في كثرة تلامذة إمام الحرمين؛ تسلمه عمادة أمر النظامية التي بنيت في نيسابور والتدريس بها، واستمر على هذا الحال زهاء عشرين عاما، وكان يجلس في حلقات درسه كل يوم نحوثلاثمائة رجل من الطلبة والأئمة 2.\rوفي السنة التي توفي بها الجويني، كان عدد تلامذته في النظامية قريبا من أربعمائة طالب علم، وتلامذة الجويني في أغلبهم لم يكونوا من العلماء المغمورين، وإنما قد اشتهر كثير منهم، وذاع صيته، وأصبح علما للعلم في ميدانه، ومن هؤلاء التلامذة:\r\r*الإمام الغزالي 3 (450 ه‍505 ه‍/ 1058 - 1111 م):\rهومحمد بن محمد بن محمد، الطوسي، حجة الإسلام، أبوحامد الغزالي. ولد بطوس، وكان والده غزالا. بدأ حياته العلمية بطوس، ودرس مع أخيه أحمد على أحد المتصوفة، وأخذ الفقه عن أبي حامد الراذكاني. ثم\r_______________\r1) ومما يوهن ذلك أيضا: أن النسختين المخطوطتين لطبقات الشافعية لابن قاضي شهبة المثبتتين في الحاشية لم تذكرا هذه الرواية. انظر: ابن قاضي شهبة، طبقات الشافعية ج 1 ص 211، حاشية رقم 9.\r2) ابن قاضي شهبة، طبقات الشافعية ج 1 ص 255 - 256.\r3) مصادر ترجمته: ابن عساكر، تبيين كذب المفتري ص 291، وياقوت الحموي، معجم البلدان ج 3 ص 541، وابن الصلاح، طبقات الشافعية ج 1 ص 249، وابن خلكان، وفيات الأعيان ج 4 ص 216، وسبط ابن الجوزي، مرآة الجنان ج 8 ص 25."], [88, "انتقل من طوس إلى جرجان، ودرس على الإمام أبي نصر الإسماعيلي، وعلق عنه.\rبعد ذلك اتجه الغزالي إلى نيسابور حاضرة العلم والعلماء في المشرق الإسلامي وقتذاك، وهناك لازم درس الإمام الجويني، وتخرج عليه في مدة قصيرة، وأصبح من أخص أصحابه، واتخذه مساعدا له، ومعيدا لدرسه، حيث فاق أقرانه وظهر نبوغه وذكاؤه.\rثم ترك الغزالي نيسابور فقصد بغداد والشام، وحج البيت الحرام، ويقال إنه زار مصر، وعاد منها إلى خراسان، حيث انكب على التصنيف. لكن نظام الملك ألح عليه بالتدريس بنظامية نيسابور فلبى الغزالي هذا الطلب، إلا أنه ترك نيسابور وعاد إلى طوس وتوفي بها.\rجمع الغزالي بين الفقه وأصوله، وعلم الكلام والفلسفة، والتصوف، وغيرها من علوم عصره. وبدأ حياته عقلي المنهج، وختمها بمنهج السالكين المتصوفة. ومن أهم مؤلفاته: الإحياء، والمنقذ من الضلال، والاقتصاد في الاعتقاد، وتهافت الفلاسفة، وفضائح الباطنية، المستصفى في الأصول، والبداية، وغيرها.\rكان الغزالي على مذهب الأشعري في الكلام، وشافعي الفروع، لذا قام بجهد بالغ إلى جانب أستاذه إمام الحرمين في الدفاع عن العقيدة الأشعرية، إلا أن أكبر أثر تركه الغزالي هوإسهامه غير المباشر في تحريض الفقهاء ضد كل من يشتغل بعلوم الأوائل وملاحقتهم بالتفسيق والتبديع.\r\r*أبونصر القشيري 1 (514 ه‍/ 1120 م):\rعبد الرحيم بن عبد الكريم بن هوازن، أبونصر القشيري، ابن الأستاذ أبي القاسم القشيري. تخرج بوالده، ثم لازم إمام الحرمين، فأتقن عليه\r_______________\r1) مصادر ترجمته: ابن عساكر، تبيين كذب المفتري ص 308، والسبكي، طبقات الشافعية ج 7 ص 159، وابن الصلاح، طبقات الفقهاء الشافعية ج 1 ص 546، والأسنوي، طبقات الشافعية ج 2 ص 149، وابن قاضي شهبة، طبقات الشافعية ج 1 ص 285، وابن خلكان، وفيات الأعيان ج 3 ص 307.\r(1/ 85)\r---"], [89, "الأصول والفروع، والخلاف. وكان للقشيري منزلة عظيمة عند إمام الحرمين، حتى إنه نقل عنه في كتاب الوصية من النهاية، مع كونه شابا إذ ذاك وتلميذا له.\rأقام القشيري في بغداد فترة، وعقد له مجلس الوعظ في نظاميتها، ولازمه في ذلك الشيخ أبوإسحاق الشيرازي. لكن القشيري كان شديدا على الحنابلة فكان ينال منهم في مجالس وعظه، مما أدى إلى فتنة عظيمة بين الحنابلة من جهة والشافعية والأشاعرة من جهة أخرى، وسالت الدماء بين الطرفين، فتدخل نظام الملك لتسكين أوار هذه الفتنة، وطلب من القشيري العودة إلى نيسابور، فبقي فيها ملازما للتدريس والإفتاء حتى توفاه الله تعالى.\r\r*الكياهراسي 1 (504 ه‍/ 1110 م):\rعلي بن محمد بن علي، أبوالحسن، البصري، الكياهراسي، الملقب عماد الدين. والكيا: هوالرجل الكبير القدر المقدم بين الناس. كان الكياهراسي فقيها شافعيا، وأصوليا أشعريا.\rولد بطبرستان، ثم قدم نيسابور وتفقه على إمام الحرمين مدة برع فيها، وعين معيدا له، ومن نيسابور قصد بيهق ودرس بها مدة، ثم اتجه إلى بغداد وتولى التدريس بالمدرسة النظامية، وبقي فيها إلى أن وافته المنية.\rاتصل الكياهراسي بخدمة مجد الملك بركياروق بن ملكشاه السلجوقي، وحظي عنده بالمال والجاه، وتولى منصب القضاء للسلاجقة.\rجمع الكياهراسي بين الفقه والأصول والحديث، وكان يستعمل الحديث بمهارة عجيبة في مناظراته. وجاهر في رأيه بيزيد بن معاوية، وصرح بفسقه، فيقول: «وكيف لا يكون كذلك، وهواللاعب بالنرد، والمتصيد بالفهود، ومدمن الخمر، وشعره في الخمر معلوم».\r_______________\r1) مصادر ترجمته: ابن عساكر، تبيين كذب المفتري ص 288، وابن الجوزي، المنتظم ج 9 ص 167، والسبكي، طبقات الشافعية ج 7 ص 231، والأسنوي، طبقات الشافعية ج 2 ص 292، وابن قاضي شهبة، طبقات الشافعية ج 1 ص 288، وابن خلكان، وفيات الأعيان ج 3 ص 286."], [90, "وكان بعض العلماء يقدمون الكياهراسي على الغزالي ويقولون: «بل آصل وأصلح، وأطيب في الصوت والنظر». من تصانيفه: نقض مفردات أحمد، وكتاب شفاء المسترشدين، وأصول الدين، وهوكتاب ضخم يقع في ثلاثمائة ورقة مخطوطة.\r\r*عبد الغافر الفارسي 1 (529 ه‍/ 1134 م):\rعبد الغافر بن إسماعيل بن عبد الغافر بن محمد، أبوالحسن، النيسابوري، الفارسي، الحافظ. كان إماما في الحديث، والعربية، وعلوم القرآن. لازم إمام الحرمين أربع سنين وأخذ عنه الفقه، والخلاف. وسمع الحديث من: أبي القاسم القشيري، وجدته فاطمة بنت أبي علي الدقاق، ووالده أبي عبد الله إسماعيل بن عبد الغافر.\rخرج عبد الغافر من نيسابور إلى خوارزم، وعقد له المجلس بها، ثم توجه إلى غزنة والهند، وقف راجعا منها إلى نيسابور، فولي الخطابة فيها إلى أن توفي بها. له تصانيف مشهورة منها: المفهم لشرح غريب صحيح مسلم، والسياق لتاريخ نيسابور، ومجمع الغرائب في غريب الحديث.\r\r*أبوالمظفر الخوافي 2 (500 ه‍/ 1106 م):\rأحمد بن محمد بن المظفر، أبوالمظفر الخوافي، الشافعي. ولد بخواف من أعمال نيسابور. لازم إمام الحرمين، وأخذ عنه الفقه، وحظي عنده بالتقدير والإعجاب، إذ كان الجويني معجبا بفصاحته وحسن كلامه، لذا جعله معيدا لدرسه.\r_______________\r1) مصادر ترجمته: ابن خلكان، وفيات الأعيان ج 3 ص 225، والسبكي، طبقات الشافعية ج 7 ص 171، والأسنوي، طبقات الشافعية ج 2 ص 132، وابن قاضي شهبة، طبقات الشافعية ج 1 ص 305، والذهبي، سير أعلام النبلاء ج 20 ص 16.\r2) مصادر ترجمته: ابن عساكر، تبيين كذب المفتري ص 288، وابن خلكان، وفيات الأعيان ج 1 ص 96، والسبكي، طبقات الشافعية ج 6 ص 93، وابن قاضي شهبة، طبقات الشافعية ج 1 ص 262، والذهبي، تاريخ الإسلام، حوادث (491 - 500) ص 312."], [91, "ولي الخوافي قضاء طوس، وكان بارعا في المناظرة والعبارة الحسنة المهذبة، والتضييق على الخصم وإلجائه إلى الانقطاع.\r\r*أبوعبد الله الفراوي 1 (530 ه‍/ 1135 م):\rمحمد بن الفضل بن أحمد بن أبي العباس، أبوعبد الله الفراوي، الصاعدي، النيسابوري، ويعرف بفقيه الحرم، ولد بفراوة في خراسان، ونشأ بين الصوفية، وأخذ الأصول عن أبي القاسم القشيري.\rثم التحق بمجلس إمام الحرمين، وتفقه عليه، وعلق عنه الأصول، وصار من جملة أصحابه. ثم رحل إلى بغداد، وعقد له مجلس الوعظ بها، وقصد بلاد الحجاز وأخذ يتنقل بين الحرمين، وينشر العلم، ويسمع الحديث، ويعظ الناس، ويذكرهم إلى أن عاد إلى نيسابور، فقعد للتدريس بالمدرسة الناصحية.\rسمع الحديث من مشايخ كثيرين، كالبيهقي، وعبد الغفار الفارسي، والشيرازي، والقشيري. وتفرد برواية بعض كتب البيهقي. وقيل فيه: «للفراوي ألف راوي»، وله كتاب في المذهب فيه غرائب. توفي بنيسابور.\r\r*أبوالقاسم الأنصاري 2 (512 ه‍/ 1118 م):\rسلمان بن ناصر بن عمران، أبوالقاسم الأنصاري، ويرجع نسبه إلى ميمون بن مهران. كان فقيها متصوفا، وإماما في التفسير، وعلم الكلام.\rصحب أبا القاسم القشيري مدة، ثم درس على الجويني فأتقن عليه الأصول.\rورحل إلى بغداد والشام والحجاز، ثم عاد إلى نيسابور ليتولى خزانة الكتب بنظاميتها. وكان له قدم في التصوف والطريقة، وقيل عنه: إنه كان يحدث\r_______________\r1) مصادر ترجمته: ابن خلكان، وفيات الأعيان ج 4 ص 290، وابن الجوزي، المنتظم ج 10 ص 65، والسبكي، ج 6 ص 166، والأسنوي، طبقات الشافعية ج 2 ص 133، وابن قاضي شهبة، طبقات الشافعية ج 1 ص 312، وابن نقطة، التقييد ص 102.\r2) ابن عساكر، تبيين كذب المفتري ص 307، والسبكي، طبقات الشافعية ج 7 ص 96، والأسنوي، طبقات الشافعية ج 1 ص 42، وابن الصلاح، طبقات الفقهاء الشافعية ج 1 ص 477، وابن قاضي شهبة، طبقات الشافعية ج 1 ص 283، والذهبي، سير أعلام النبلاء ج 19 ص 412."], [92, "الجن. من تصانيفه: الغنية، وشرح الإرشاد لأستاذه الجويني في مجلدين ضخمين.\r\r*أبومحمد الأستراباذي 1 (490 ه‍/ 1096 م):\rسعد بن عبد الرحمن، أبومحمد الأستراباذي، الفقيه البارع. درس الفقه بمروعلى ناصر العمري، ثم خرج إلى القاضي حسين المروذي، وأقام عنده، وتخرج به. ثم لازم إمام الحرمين، وأصبح من أركان مجلسه، توفي بنيسابور.\r\r*أبوسعد بن أبي صالح المؤذن 2 (532 ه‍/ 1137 م):\rإسماعيل بن أحمد بن عبد الملك النيسابوري، كان إماما كبيرا، وفقيها بارزا. أخذ الفقه عن: الشيخ أبي إسحاق الشيرازي، وأبي المظفر السمعاني، وإمام الحرمين الجويني، وقرأ عليه الأصول من كتابه الإرشاد. سكن كرمان، وكان له منزلة خاصة عند واليها. روى عنه: ابن الجوزي، وابن أبي عصرون، وأبوالقاسم ابن عساكر. توفي بكرمان.\r\r*أبوالقاسم الحاكمي 3 (529 ه‍/ 1134 م):\rإسماعيل بن عبد الملك بن علي، أبوالقاسم الحاكمي، ولد بطوس، وكان إماما متقنا، وله قدم في الفقه، حسن السيرة. رحل إلى نيسابور، وأخذ الفقه عن إمام الحرمين. ثم سافر إلى بغداد، وكان رفيقه في هذه الرحلة الإمام الغزالي، وكان شريكه في الدرس، والغزالي يجله ويقدمه عليه، ويخدمه لأنه كان أكبر سنا منه. ثم رجع إلى طوس وتوفي بها، ودفن إلى جانب الغزالي.\r_______________\r1) مصادر ترجمته: الذهبي، تاريخ الإسلام، حوادث (481 - 490) ص 335، والسبكي، طبقات الشافعية ج 4 ص 382، والأسنوي، طبقات الشافعية ج 1 ص 42، وابن قاضي شهبة، طبقات الشافعية ج 1 ص 264.\r2) مصادر ترجمته: ابن عساكر، تبيين كذب المفتري ص 325، وابن نقطة، التقييد ص 209، وابن الصلاح، طبقات الفقهاء الشافعية ج 1 ص 424، والسبكي، طبقات الشافعية ج 7 ص 44، والأسنوي، طبقات الشافعية ج 2 ص 219، والذهبي، تاريخ الإسلام، حوادث (521 - 540) ص 271.\r3) مصادر ترجمته: السبكي، طبقات الشافعية ج 7 ص 47، والأسنوي طبقات الشافعية ج 1 ص 207، وابن كثير، البداية والنهاية ج 13 ص 209"], [93, "الفصل السادس: مؤلفات الجويني\r"]], "pg": [81, 93]}, "474.7": {"x": [[93, "تميز إمام الحرمين عن سائر أقرانه بغزارة علمه، وسعة اطلاعه، وعمق ثقافته، إذ أتى على أغلب العلوم التي كانت سائدة في عصره تحصيلا وتصنيفا، وقد انعكس ذلك بوفرة في المؤلفات النفيسة التي تركها.\rولما كان الجويني شافعي الفروع، أشعري الأصول، فقد حرص على أن تكون هذه المؤلفات دفاعا عن المذهب الشافعي، والعقيدة الأشعرية، وتأصيلا لهما. وقد أعاد إمام الحرمين النظر في مؤلفات والده تهذيبا وشرحا وتنقيحا، مما أدى إلى كثرة عدد الكتب التي نسبت إليه، لذا فإن كتب الوالد التي نسبت إلى إمام الحرمين لن يؤتى على ذكرها في هذا العرض.\r\r*أولا: مؤلفاته في العقيدة:\r*لمع الأدلة في قواعد أهل السنة والجماعة 1:\rوهوكتاب مختصر في العقيدة الأشعرية، ألفه الجويني تلبية لرغبة بعض أصحابه أوطلابه، إذ يقول في مقدمته: «هذا وقد استدعيتم، أرشدكم الله عز وجل ذكر لمع من الأدلة في قواعد أهل السنة والجماعة، فاستخرت الله\r_______________\r1) يوجد لهذا الكتاب نسخة خطية بدار الكتب المصرية ضمن مجموع تحت رقم 618 مجاميع، ونسخة أخرى في مكتبة برلين تحت رقم 2073، وقد نشر هذا الكتاب لأول مرة فوقية حسين عام 1965 م، وصدر عن المؤسسة العامة المصرية للتأليف، ثم صورته بالأوفست دار عالم الكتب ببيروت عام 1987 م. انظر: فوقية حسين، لمع الأدلة ص 67، 68، وnehsibarA reD ethcihseG,nnamlekcorB . (093) 884 . P. l. lov. rutarettiL"], [94, "تعالى في إسعافكم بمناكم، والله المستعان وعليه التكلان» 1. ويمكن أن يكون هذا الكتاب أول مؤلف للجويني في العقيدة، إذ زاده شرحا وتوسعا في كتابيه الآخرين الشامل في أصول الدين، والإرشاد إلى قواطع الأدلة، ومما يزيد هذا الاحتمال أنه لم يذكر في متن اللمع أي كتاب آخر له، على عكس عادته في الكتب الأخرى.\r\r*الإرشاد إلى قواطع الأدلة في أصول الاعتقاد 2:\rألف الجويني هذا الكتاب، قاصدا منه بيان الأدلة القطعية، والقضايا العقلية، التي تحصن المعتقد الأشعري وتبين رجاحته، كما تدعم الذب عن هذا المعتقد في مواجهة الفرق الأخرى، فقد جاء في مقدمته: «ولما رأينا أدلة التوحيد، عصاما للتسديد، ورباطا لأسباب التأبيد،، وألفينا في الكتب المبسوطة المحتوية على القواطع الساطعة، والبراهين الصادعة، لا تنهض لدركها همم أهل هذا الزمان، وصادفنا المعتقدات عرية عن قواطع البرهان، رأينا أن نسلك مسلكا يشتمل على الأدلة القطعية، والقضايا العقلية، متعليا عن رتب المعتقدات، منحطا عن حلة المصنفات» 3. والكتاب بمثابة تلخيص لكتاب الجويني الشامل في أصول الدين 4.\r\r*الشامل في أصول الدين 5:\rوهوكتاب ضخم في أصول الدين، أثار الجويني فيه المسائل الكلامية\r_______________\r1) الجويني، لمع الأدلة، تحقيق فوقية حسين (النسخة البيروتية) ص 85.\r2) يوجد لهذا الكتاب ثلاث نسخ خطية، الأولى والثانية بدار الكتاب المصرية برقم 819، 1179 توحيد، والثالثة بالمكتبة الأحمدية بحلب رقم 764 توحيد، وللكتاب شروح عديدة ذكرها بروكلمان في تاريخه للأدب العربي، وقد نشر الكتاب لأول مرة المستشرق لوسياني عام 1938 م اعتمادا على ثلاث نسخ بالجزائر 616، وباريس 1628، وتونس، ثم نشره محمد يوسف موسى عن نسخة لوسياني ونسخة حلب ونسختي دار الكتب، وصدر عن مكتبة الخانجي بمصر عام 1950 م.\r3) الجويني، الإرشاد، تحقيق محمد يوسف موسى ص 1.\r4) ابن خلدون، المقدمة ص 465.\r5) يقع الكتاب في خمس مجلدات مخطوطة، نشر المستشرق هلموت كلوبفر الجزء-"], [95, "نفسها التي بحثها في اللمع، والإرشاد، ولكن مع زيادة شرح وتفصيل. ويعد هذا الكتاب أهم مؤلفات إمام الحرمين في العقيدة، لذا كان الأشاعرة يتدارسونه في مجالسهم، ويحرصون على اقتنائه، ويفتخرون بحفظه 1، وقد اختصره الجويني في كتابه الإرشاد إلى قواطع الأدلة 2.\r\r*شفاء الغليل في بيان ما وقع في التوراة والإنجيل من التبديل 3:\rوالكتاب كما يظهر من عنوانه، هوفي الرد على اليهود والنصارى، وبيان أن الرسول محمد صلى الله عليه وسلم قد ورد ذكره في أصول التوراة والإنجيل، لكن هذه الأصول قد بدلت. ويعتذر الجويني عن عدم الإكثار في الاطلاع على ما جاء في هذين الكتابين، لأن الرسول صلى الله عليه وسلم غضب عند ما رأى عمر بن الخطاب ينظر في التوراة، وقال له: «لوكان موسى حيا لما وسعه إلا اتباعي» 4.\r\r*رسالة في أصول الدين 5:\rوهي رسالة مختصرة في مسائل التوحيد، ولعل هذه الرسالة هي لمع\r5) -الأول منه اعتمادا على نسخة له في مكتبة كوبرولوفي إستانبول، لكن هذه النشرة غير دقيقة، وقد صدر عن دار العرب بالقاهرة عام 1961 م، ثم قام علي سامي النشار وتلميذاه سهير مختار وفيصل عون بنشر هذا الجزء اعتمادا على النسخة التركية، ونسخة أخرى بدار الكتب المصرية رقم 1290 علم كلام. وقد ذكر الباحث الإيراني صدر الدين محقق، أن الكتاب نشر كاملا في إيران في محاضرة له بالمعهد العالي للدراسات الإسلامية ببيروت.\r_______________\r1) انظر: السبكي، طبقات الشافعية ج 8 ص 86.\r2) ابن خلدون، المقدمة ص 465.\r3) يوجد لهذا الكتاب نسختان خطيتان في مكتبة آيا صوفيا رقم 2246 و2247، ويوجد عنه مصورة في معهد المخطوطات العربية رقم 159 توحيد، وقد نشره ميشيل آلار ببيروت عن دار المشرق عام 1968، وأحمد حجازي السقا وصدر عن مكتبة الكليات الأزهرية عام 1948 م.\r4) الجويني، شفاء الغليل، تحقيق أحمد حجازي السقا ص 15.\r5) يوجد لهذا الكتاب نسختان خطيتان، الأولى في المكتبة الوطنية بباريس رقم 672 ضمن مجموع، والثانية بدار الكتب المصرية رقم 940 وعنوانها: رسالة في التوحيد. انظر: محمد الزحيلي، الإمام الجويني ص 112، ومقدمة فوقية حسين للكافية في الجدل ص 20"], [96, "الأدلة نفسها، لأنه لم يأت على ذكرها كمصنف مستقل لإمام الحرمين في كتب التراجم والطبقات.\r\r*مسائل الإمام عبد الحق الصقلي وأجوبتها 1:\rوالكتاب بمثابة جملة من الردود على مسائل عقدية أثارها عبد الحق الصقلي حول حدوث العالم، والأعراض، والمثلين والغيرين، وقدرة الله تعالى، وصدق الأنبياء، والمعجزات والتنجيم.\r\r*مختصر الإرشاد للباقلاني 2:\rوهذا الكتاب يدور حوله جدل كبير بين الباحثين والعلماء، ويتساءلون، هل ترك الباقلاني كتابا في الأصول أسماه الإرشاد، ثم قام الجويني باختصاره أم أن الكتاب هوالإرشاد إلى قواطع الأدلة، ثم قام الجويني باختصاره. لذا بادرت إلى استحضار مصورة عنه محفوظة في معهد المخطوطات بجامعة الدول العربية، وقرأته على مهل، فوجدت أن المؤلف يذكر إمام الحرمين في أكثر من موضع، ويختصر مسائل كلامية ذكرت في الإرشاد. لذا فإن هذا الكتاب ليس اختصارا لكتاب ألفه الباقلاني، وإنما هواختصار لكتاب الإرشاد إلى قواطع الأدلة الذي ألفه الجويني. وقد يكون هذا الكتاب هو«نكتة الإرشاد في الاعتقاد» لأبي إسحاق الأوسي المالكي (616 ه‍/ 1219 م).\r\r*العقيدة النظامية:\rوهوالجانب العقدي من كتاب النظامية في الأركان الإسلامية، وسنتكلم عنه بالتفصيل إن شاء في الفصل القادم.\r\r*كتاب النفس:\rلم يأت أحد ممن ترجم للجويني قديما على ذكر هذا الكتاب ضمن\r_______________\r1) يوجد لهذا الكتاب نسخة خطية بدار الكتب المصرية رقم 11، والكتاب ما زال مخطوطا. انظر: فهرس المخطوطات بمعهد المخطوطات العربية، فقه مالكي رقم 11.\r2) انظر: فهرس المخطوطات العربية، رقم 211 توحيد."], [97, "مؤلفاته، وإنما عرفناه من الجويني نفسه، إذ أشار إليه في العقيدة النظامية، وفي هذا الصدد يقول: «ولوذهبت-أطال الله بقاء مولانا-أتكلم في الروح لطال المرام، وقد جمعت فيه كتابا سميته النفس، وهويشتمل على قريب من ألف ورقة» 1.\r\r*كتاب الكرامات:\rوهذا الكتاب مثل سابقه، لم نتعرف إليه إلا من خلال إشارة إمام الحرمين إليه في العقيدة النظامية، في الفصل الذي عقده لبيان الكرامات. وفي ذلك يقول: «فقد كثر خبط الناس في إثباتها ونفيها، وقد ألفت في إثباتها، والرد على منكريها كتابا، وأنا أذكر الآن لبابه في أسطر إن شاء الله جل وعز» 2.\r\r*مدارك العقول:\rوقد يكون هذا الكتاب آخر كتب إمام الحرمين في العقيدة، لأنه لم يتمه، وقد ذكره الجويني نفسه في غياث الأمم، إذ يقول في خاتمته: «وإنما جعلت هذا الفصل منقطع الكلام، لأنني افتتحت باسم مولانا-نضر الله أيامه وأسبغ على ساحته السامية أنعامه-كتابا مضمونه ذكر مدارك العقول» 3.\rأما ما ذكرته فوقية حسين، ومحمد الزحيلي نقلا عنها، من أن رسالة إثبات الاستواء والفوقية هي من ضمن مؤلفات إمام الحرمين، فهذا وهم، لأن الرسالة مثبتة ضمن مؤلفات والده أبي محمد الجويني، وقد نشرت مؤخرا في بيروت وصدرت عن المكتب الإسلامي بشرح ابن شيخ الحزاميين.\r\r*ثانيا: كتبه في الفقه وأصوله:\rكان إمام الحرمين في عصره علما بارزا في الفقه وأصوله، وكان يدرسه إلى جانب علم الكلام في المدرسة النظامية طوال عشرين عاما. ومما ساعده\r_______________\r1) انظر ص 247.\r2) انظر ص 227.\r3) انظر: الجويني، غياث الأمم ص 526، والذهبي، تاريخ الإسلام، حوادث (471 - 480) ص 236، وابن خلكان، وفيات الأعيان ج 3 ص 169."], [98, "على اعتلائه هذه المنزلة الرفيعة في الفقه وأصوله، تأثره بوالده أبي محمد الجويني، الذي قام بمحاولة جادة، عزم فيها على تأليف كتاب في الفقه لا يتقيد فيه بمذهب من المذاهب، فأنهى منه عدة أجزاء، لكن الحافظ البيهقي وضع حدا لهذه المحاولة، إذ وقعت هذه الأجزاء بين يديه، فقرأها، ثم بعث للجويني الأب رسالة بين له فيها الأخطاء الحديثية التي وقع بها في هذه الأجزاء، فما كان من أبي محمد إلا أن توقف عن إكمال مشروعه الرائد 1.\rوقد انعكس ذلك على إمام الحرمين، فكان في الفقه أوأصوله لا يقبل رأيا إلا إذا بني على أدلة قطعية عقلية كانت أم نقلية، حتى لوكان هذا الرأي للشافعي نفسه. وقد استخدم لهذا المنهج الدقيق معيارا محددا، هوموافقة المسائل الفقهية لأدلتها التفصيلية. ومع ذلك بقي أبوالمعالي مخلصا للمذهب الشافعي، وبذل جهدا عظيما لترجيحه على بقية المذاهب الفقهية الأخرى.\rوقد ترك الجويني مؤلفات قيمة في هذا الباب ومنها:\r\r*نهاية المطلب في دراية المذهب 2:\rوهومن الكتب النفيسة في الفقه الشافعي، ويقال له شهرة واختصارا:\r«النهاية». وقد بدأ الجويني بتأليف هذا الكتاب عند ما كان مجاورا في مكة المكرمة، وحرره في نيسابور 3 في عدة مجلدات. وقد وصفه السبكي قائلا:\r«النهاية في الفقه، لم يصنف في المذهب مثلها فيما أجزم به» 4. وقد لاقى الكتاب قبولا واسعا بين العلماء والفقهاء، فتناولوه بالدرس والاختصار.\r_______________\r1) السبكي، طبقات الشافعية ج 5 ص 77.\r2) يوجد لهذا الكتاب نسخة خطية غير كاملة في مكتبة أحمد الثالث رقم 1130، ويوجد عنها مصورة بمعهد المخطوطات العربية رقم 315 - 349، ونسخة بدار الكتب المصرية رقم 300، 301، 378، 546، ونسخة بمكتبة الإسكندرية رقم 44 فقه شافعي، ونسخة بآيا صوفيا رقم 1500، وقام بتحقيقه ونشره عبد العظيم الديب.\r3) ابن قاضي شهبة، طبقات الشافعية ج 1 ص 256.\r4) السبكي، طبقات الشافعية ج 5 ص 171."], [99, "*مختصر النهاية 1:\rوهومختصر لنهاية المطلب الذي سبق ذكره، اختصره الإمام الجويني نفسه.\r\r*مناظرة في الاجتهاد في القبلة 2:\rوهي رسالة صغيرة تقع في خمس ورقات، أوردها السبكي في طبقاته الكبرى، ومضمونها: مناظرة وقعت بين الشيخ أبي إسحاق الشيرازي، وإمام الحرمين في نيسابور.\r\r*مناظرة في إجبار البكر البالغة على الزواج 3:\rوقد نشرها السبكي أيضا في طبقاته كملحق لترجمة إمام الحرمين، والمناظرة حصلت أيضا في نيسابور بين الجويني والشيخ أبي إسحاق الشيرازي، وكان الشيرازي يرى جواز إحبار البكر البالغة على الزواج من قبل وليها، فاعترض عليه إمام الحرمين مستدلا على عدم جواز ذلك.\r\r*السلسلة في معرفة القولين والوجهين 4:\rجمع الجويني في هذا الكتاب الأقوال والوجوه في المذهب الشافعي، سواء كانت هذه الوجوه والأقوال للإمام الشافعي نفسه، أوكانت لأصحابه من فقهاء الشافعية.\r\r*رسالة في الفقه 5:\rوهي رسالة صغيرة في الفقه، جمع فيها الجويني بعض أقواله وآرائه الفقهية، التي تفرد بها في المذهب.\r_______________\r1) يوجد نسخة خطية منه في المكتبة الظاهرية بدمشق رقم 2227. انظر: محمد الزحيلي، الإمام الجويني ص 128 حاشية رقم 2.\r2) انظر: السبكي، طبقات الشافعية ج 5 ص 209.\r3) انظر: المصدر نفسه ج 5 ص 214.\r4) يوجد له نسخة خطية بمكتبة أحمد الثالث بتركيا رقم 1206، وعنها مصورة بمعهد المخطوطات رقم 184 فقه شافعي. انظر: فوقية حسين، الجويني ص 91، ومحمد الزحيلي، الإمام الجويني ص 124، وقد حققه ونشره عبد العظيم الديب.\r5) يوجد عنها نسخة بالموصل، مدرسة الحجبات رقم 38. انظر: فوقية حسين، الجويني ص 91، ومحمد الزحيلي، الإمام الجويني ص 124."], [100, "*البرهان في أصول الفقه 1:\rوصف السبكي هذا الكتاب قائلا: «اعلم أن هذا الكتاب، وضعه الإمام في أصول الفقه على أسلوب غريب، لم يقتد فيه بأحد، وأنا أسميه لغز الأمة، لما فيه من مصاعب الأمور، وأنه لا يخلي مسألة عن إشكال، ولا يخرج إلا عن اختيار يخترعه لنفسه، وتحقيقات يستبد بها، وهذا الكتاب من مفتخرات الشافعية، وأنا أعجب لهم، فليس منهم من انتدب لشرحه، ولا للكلام عليه إلا مواضع يسيرة» 2.\rوقد عرض هذا الكتاب الجويني لانتقادات حادة، لأنه كان يخضع أقوال سابقيه من الأئمة والأصوليين للنقد، ولم يعبأ في هذه الانتقادات إلى مكانة من ينتقد، كالإمام مالك في المصالح المرسلة، والإمام الأشعري 3.\r\r*الورقات 4:\rوهوكتيب صغير، يقع في عشر أوراق، ضمنها الجويني مسائل في أصول الفقه باختصار شديد، وقد اعتنى العلماء بهذا الكتاب، وقاموا بوضع العديد من الشروحات له.\r_______________\r1) يوجد له نسخة خطية بدار الكتب المصرية رقم 714 أصول الفقه، وبمكتبة الأزهر رقم 913 أصول الفقه، ويوجد عنه مصورة في معهد المخطوطات العربية رقم 18 أصول فقه. انظر: فوقية حسين، الجويني ص 62، وreD ethcihseG,namlekcorB 376 . P. loV. puS,rutarettiL nehsibarA  ونشر الكتاب عبد العظيم الديب بقطر عام 1399 ه‍.\r2) السبكي، طبقات الشافعية ج 5 ص 192.\r3) المصدر نفسه ج 5 ص 192،193.\r4) ويوجد له نسخ خطية كثيرة منها نسخة في برلين برقم 435، ونسخة في هامبورغ برقم 128، ونسخة بباريس برقم 672، ونسخة في المتحف البريطاني برقم 252، ونسخة في الجزائر برقم 213، ونسخة في مكتبة الأسكوريال برقم 102. انظر: 784.  P. loV. hseG, 176 . P. l. loV. puS,rutarettiL nehsibarA reD ethcihseG,nnamlekcorB  وقد طبع الكتاب بتحقيق عبد اللطيف العبد، وصدر عن مكتبة التراث ببيروت عام 1971 م."], [101, "*رسالة في التقليد والاجتهاد 1:\rوهذه الرسالة في أصول الفقه، وليست في الفقه كما ذكرت فوقية حسين في مقدمتها لكتاب لمع الأدلة 2.\r*كتاب التحفة 3:\rوهوفي أصول الفقه، وحدد موضوعه، السبكي في طبقاته الوسطى.\r*التلخيص في أصول الفقه 4:\rوقد نشر جزء منه ككتاب مستقل، وهوالجزء الخاص بالمجتهدين. ألف الجويني هذا الكتاب في الفترة التي كان مجاورا بها بمكة.\r\r*مؤلفاته في الخلاف والجدل والسياسة:\r*مغيث الخلق في اختيار الأحق 5:\rوهوكتاب يتضمن ترجيح المذهب الشافعي على المذاهب الأخرى، وقد أعلن الجويني غايته من وراء تأليف هذا الكتاب قائلا: «وقد بنيت في عامة مصنفاتي في أصول الفقه، وجه تقديم مذهب الشافعي رضي الله عنه على المذاهب كلها، والآن أردت وضع كتاب موجز في هذا الغرض، ليطلع عليه العام والخاص» 6.\r_______________\r1) يوجد له نسختان خطيتان: الأولى بالمكتبة الآصفية، حيدرآباد الدكن ضمن مجموع برقم 1720، والثانية بمكتبة باتنا برقم 2976، 376  P. l. l. loV. puS,nnamlekcorB،  ومحمد الزحيلي، الإمام الجويني ص 168، وقام بتحقيقه ونشره عبد العظيم الديب.\r2) الجويني، لمع الأدلة، المقدمة ص 54.\r3) السبكي، طبقات الشافعية الكبرى ج 5 ص 172، حاشية رقم 2.\r4) وقد صدر هذا الكتاب مؤخرا ببيروت عن دار البشائر عام 1996 م بتحقيق عبد الله النيبلي، وشبير العمري.\r5) يوجد له نسخة خطية بمكتبة برلين برقم 4853، ونسخة بباريس رقم 5896، ونسخة بالمكتبة الظاهرية بدمشق، ونسخة بدار الكتب المصرية برقم 395/ 1، وقد طبع الكتاب ونشر لأول مرة في مصر وصدر عن المطبعة المصرية عام 1934 م. انظر: 376.  P. l. loV. puS,rutarattiL nehsibarA reD ethsihseG,nnamlekcorB ،  وسماه مغيث الخلق في بيان الأحق.\r6) الجويني، مغيث الخلق ص 2."], [102, "*الدرة المضية فيما وقع من خلاف بين الشافعية والحنفية 1:\r\r*غنية المسترشدين:\rوالكتاب لم يعثر على نسخه المخطوطة، وهوفي الخلاف أيضا 2.\r\r*الأساليب في الخلاف 3:\rأشار الجويني إلى هذا الكتاب في أكثر من موضع في كتابه البرهان في أصول الفقه، ولم يعثر بعد على نسخه الخطية.\r\r*الكافية في الجدل 4:\rوهوكتيب ألفه إمام الحرمين في أساليب الجدل وآدابه 5.\r\r*العمد 5:\rوهذا الكتاب في علم الخلاف، أشار إليه الجويني نفسه في كتابه البرهان في أصول الفقه، لكن نسخه المخطوطة لم يعثر عليها بعد.\r\r*غياث الأمم في التياث الظلم 6:\rويسمى أيضا الغياثي شهرة واختصارا، والغياثي نسبة إلى غياث الدولة المعروف بنظام الملك، وموضوع الكتاب في الفقه السياسي، أوالإمامة والأحكام السلطانية. جمع فيه الجويني الأحكام المتعلقة بالإمامة من جهة ماهيتها ووجوبها وثبوتها، وغيرها من المسائل الشرعية المرتبطة بالإمامة العظمى.\r_______________\r1) يوجد عنه نسخة خطية بالمتحف البريطاني برقم 7574. انظر:  reD ethsihseG,nnamlekcorB 376 . P. l. loV. puS,rutarattiL nehsibarA  ثم قام عبد العظيم الديب بتحقيقه ونشره مؤخرا.\r2) ابن خلكان، وفيات الأعيان ج 3 ص 169، والسبكي، طبقات الشافعية ج 5 ص 172، حاشية رقم 4، والجويني، لمع الأدلة، مقدمة المحقق ص 54.\r3) انظر: الجويني، البرهان في أصول الفقه ج 2 ص 1417.\r4) ويوجد عنه نسخة خطية في جامعة الأزهر برقم 84، ونسخة أخرى برقم 1063، آداب البحث، وعنه يوجد مصورة بمعهد المخطوطات العربية برقم 187 توحيد، وقد قامت فوقية حسين بتحقيقه ونشره، وصدر عن مكتبة عيسى البابي الحلبي عام 1979 م.\r5) انظر: الجويني، البرهان في أصول الفقه ج 1 ص 588.\r6) نشره عبد العظيم الديب معتمدا على ست نسخ خطية له، وصدر عن الشؤون الدينية بقطر عام 1400 ه‍، ونشر الكتاب لأول مرة مصطفى حلمي وفؤاد عبد المنعم، وصدر عن دار الدعوة بالإسكندرية عام 1979 م.\rالفصل السابع"], [103, "وصف المخطوط وتحليله\r*اسم المخطوط ونسبته إلى الجويني:\rتقع النسخة الخطية التي اعتمدتها لإعادة نشر العقيدة النظامية، ضمن مجموع في علم الكلام، مصور في معهد المخطوطات العربية، كتب على صفحتها الأولى: العقيدة النظامية في الأركان الإسلامية، تأليف الإمام الأجل إمام الحرمين أبي المعالي عبد الملك بن عبد الله بن يوسف الجويني، النيسابوري رحمه الله تعالى.\rوقد أجمع المؤرخون لحياة الجويني على نسبة هذا الكتاب إلى إمام الحرمين، إلا أنهم اختلفوا في تحديد اسمه، ومن الأسماء التي وردت لهذا المصنف: الرسالة النظامية، والرسالة النظامية في الأحكام الإسلامية 1، والعقيدة النظامية 2 والنظامي.\rأما الجويني نفسه فقد ذكر في مقدمة الكتاب: «وقد صدرتها بقواعد من العقائد، على أساليب لم أسبق إليها، ثم أتبعتها بما لا يسوغ الذهول عنه من أركان الإسلام، وسميتها: النظامية في الأركان الإسلامية» 3. وفي كتابه غياث الأمم في التياث الظلم، المشهور بالغياثي، ذكر النظامية أكثر من مرة باسم النظامي 4، إذ يقول: «وقد تقدم الكتاب النظامي محتويا على العجب\r_______________\r1) ابن قاضي شهبة، طبقات الشافعية ج 1 ص 256، والذهبي، تاريخ الإسلام، حوادث (471 - 480) ص 236.\r2) ابن خلكان، وفيات الأعيان ج 3 ص 169، وابن كثير، البداية والنهاية ج 12 ص 128.\r3) انظر ص 122 - 123.\r4) الجويني، الغياثي ص 7، 88، 190، 408."], [104, "العجاب، ومنطويا على لباب الألباب» 1. ويقول في موضع آخر: «وهذا؛ إذا تم غياث الأمم في التياث الظلم، فليشتهر بالغياثي، كما شهر الأول بالنظامي» 2.\rوقال فيه أيضا: «ومن رام اقتصادا، وحاول ترقيا عن التقليد واستبدادا، فعليه بما يتعلق بعلم التوحيد من الكتاب المترجم بالنظامي» 3. ثم ختم كلامه هذا المؤلف قائلا: «وقد ذكرت طرقا صالحة من ذلك في الكتاب النظامي» 4.\rمن كل ذلك يتبين أن الجويني قد ألف كتابا شاملا في الأركان الإسلامية سماه: «النظامية في الأركان الإسلامية». وقد عدها الجويني بمثابة رسالة مهداة إلى نظام الملك، لذلك سماها بعض المترجمين له: الرسالة النظامية. واشتهر بين العلماء كما يقول الجويني بالنظامي. فالنظامي أوالرسالة النظامية، هوكتاب شامل يضم خلاصة المعتقد الذي استقر عليه الجويني قبل وفاته، والفروع في المذهب الشافعي، وصدرها إمام الحرمين بالكلام عن أصول العقيدة. وعند ما تدارسها العلماء، وجدوا فيها تحولا في المواقف الاعتقادية لهذا الإمام، وقد تضمن هذا التحول انحيازا إلى موقف أهل السلف، لذا خصوا قسم العقيدة من النظامية بالاهتمام، وأفردوها بالنسخ والنشر، وسموها العقيدة النظامية. وقد ألف الجويني العقيدة النظامية عام 460 ه‍/ 1067 م، إذ جاء في معرض كلامه عن معنى الإعجاز في القرآن الكريم «فقصرت قدر الخلق المعارضة في أربعمائة وستين ونيف» 5.\rويرجع تسمية الكتاب الأصل الجامع للعقيدة وغيرها من الأركان بالنظامية، نسبة إلى نظام الملك الوزير الأول لدولة السلاجقة زمن السلطان ألب أرسلان، اعترافا من الجويني بفضله عليه ونصرته للأشاعرة والشافعية.\r*نسخ المخطوط ووصفه:\rيوجد لهذا المخطوط نسخة في مكتبة الإسكوريال الثانية بإسبانيا 6 برقم\r_______________\r1) الجويني، الغياثي ص 7.\r2) المصدر نفسه ص 18.\r3) المصدر نفسه ص 190.\r4) المصدر نفسه ص 408.\r5) انظر ص 236.\r6) 376.  P. l. loV. puS,rutarattiL nehsibarA reD ethsihseG,nnamlekcorB"], [105, "1514/ 6، 5، وفي مكتبة أحمد الثالث بتركيا 1 برقم 1238. ويوجد عن هذين الأصلين مصورتان في معهد المخطوطات العربية: توحيد 167، 168 2.\rونسخة الإسكوريال منسوخة بخط أندلسي جميل، منقولة عن نسخة كتبها الإمام القاضي أبوبكر ابن العربي، الذي سمع العقيدة عن الإمام الغزالي 3.\rفالنسخة تمتاز بقدمها وتحريرها من علماء كبار كابن العربي والإمام الغزالي، لكن هذا الامتياز يشينه كثرة الأخطاء فيها، إذ وصفها الكوثري قائلا:\r«فوجدت النسخة غير سليمة وإن كانت منقولة عن أصل ابن العربي» 4.\rوقد نشر العلامة محمد زاهد الكوثري هذه النسخة عام 1948 م، ثم قام المستشرق الألماني هلموت كلوبفر بنشرها وترجمها إلى الألمانية 5.\rثم أعيد نشرها مرة ثانية في مصر عام 1399 ه‍/ 1979 م اعتمادا على النسخة التركية، وصدرت عن المكتبة الأزهرية للتراث، وكتب على صفحة الغلاف: تحقيق وتعليق محمد زاهد الكوثري، ولم يذكر اسم من أعاد نشرها، وكأن الناشر لم يجن ربحا من إعادة نشرها باسم أحمد حجازي السقا 6، فأسقطه وصدرها مرة ثانية باسم الكوثري نفسه، مع أن الكوثري لم ير النسخة التركية هذه.\rأما نسخة أحمد الثالث التركية، فتقع ضمن مجموع رقمت صفحاته حديثا، وتبدأ العقيدة النظامية بالرقم 118 وتنتهي بالرقم 149، وتتألف هذه النسخة من 31 لوحة، وتتكون كل لوحة من صفحتين بمقاس 17 * 26 سم،\r_______________\r1) انظر: فهرس المخطوطات بمعهد المخطوطات العربية، توحيد رقم 167.\r2) المصدر نفسه، توحيد ص 167، 168.\r3) الجويني، العقيدة النظامية، مقدمة المحقق الكوثري ص 5، وانظر أيضا ص 70، حاشية رقم 2.\r4) المصدر نفسه ص 5.\r5) فوقية حسين، الجويني ص 87.\r6) للأمانة العلمية نقول: إن السقا لم يقرأ النسخة التركية قراءة سليمة، ولم يبذل الجهد الكافي لبيان الفروق بين النسختين التركية والأندلسية، رغم أن هذه الفروق كثيرة جدا، وكأنه اكتفى بقراءة الكوثري للنسخة الأندلسية، وسحب هذه القراءة نفسها على النسخة التركية، وهذا ليس بعمل علمي، وتشويه للنصوص التراثية التي وصلت إلينا."], [106, "وفي كل صفحة 23 سطرا، وقد كتبت بخط نسخي واضح، وتنتهي العقيدة النظامية بمنتصف اللوحة 27 ب، أما باقي اللوحات وحتى اللوحة 31 ب فهي تتناول مسائل في فروع المذهب الشافعي وترجيحه.\rذكر اسم هذا الكتاب مباشرة في منتصف الصفحة التي انتهى بها الكتاب الأول من المجموع، وجاء ذكر العنوان على النحوالآتي: «العقيدة النظامية في الأركان الإسلامية، تأليف الإمام الأجل، إمام الحرمين أبي المعالي عبد الملك بن يوسف الجويني النيسابوري رحمه الله تعالى».\rتمتاز هذه النسخة أيضا بقدمها وقربها من عصر المؤلف، فقد جاء في نهاية الصفحة الأخيرة: «وكان الفراغ من نسخها التاسع من شعبان سنة أربع وخمسمائة» 1.\rأي أنها كتبت بعد وفاة الجويني بست وعشرين سنة. وهكذا تكون هذه النسخة أقدم من النسخة الأندلسية، فتأريخ نسخها يدل على أنها كتبت قبل وفاة الإمام الغزالي بسنة واحدة، لذا فقد اعتمدتها أصلا في التحقيق.\rوتخلوهذه النسخة من السقط إلا ما ندر، أما خطها فهونسخي واضح ومقروء، إلا أن بعض الكلمات اختلف رسمها عن رسمنا المعاصر لهذه الكلمات. ويلاحظ كذلك أن هذه النسخة قد روجعت وصححت، وأثبتت الكلمات الدالة على التصحيح والمراجعة في الهوامش، وكذلك الحال بالنسبة للجمل والكلمات الساقطة من المتن.\rكما أغفل الناسخ ترقيم لوحات المخطوط، لذا نجد ترقيما أجنبيا قد أضيف إليها. ومما يعيب هذه النسخة كثرة الأخطاء فيها، وكأنها كتبت بيد هاوفي علم الكلام، أوبيد ناسخ جاهل في هذا الميدان.\rومن اللافت للنظر، أن صفحة من هذه العقيدة محفوظة بمكتبة برلين برقم 1946 م بعنوان عقيدة 2، وقد عدها عبد المجيد تركي جزءا من عقيدة السلف لأبي إسحاق الشيرازي 3. وقد نشرتها أيضا تحت هذا العنوان كملحق ثان\r_______________\r1) انظر اللوحة الأخيرة المصورة من المخطوط.\r2) 076.  P. lS. 684 . P. lG,nnamlekcorB .\r3)  الشيرازي، المعونة في الجدل، مقدمة المحقق ص 88، 89، حاشية رقم 1."], [107, "لكتاب الإشارة إلى مذهب أهل الحق للشيرازي 1. لكنني عند ما قارنت نص هذه القطعة بما جاء في العقيدة النظامية لإمام الحرمين 2، وجدت أن هذه القطعة ما هي إلا صفحة مستقلة من النظامية وليست عقيدة لأبي إسحاق الشيرازي.\r\r*منهج التحقيق:\r*قارنت نص العقيدة النظامية كما ورد في النسخة الأحمدية، بنصها الذي تضمنته النسخة الأندلسية، والذي نشره الكوثري. فأثبت في المتن أصح القراءتين، ذاكرا في الحواشي القراءة المستثناة، وأشرت إليها بأرقام غربية، وقد رمزت للنسخة الأحمدية بالرمز «أ»، أما نسخة الكوثري فقد أشرت إليها بالرمز «ط».\r*قارنت ما ورد في العقيدة النظامية من مسائل كلامية بآراء إمام الحرمين في كتبه السابقة، كالإرشاد، واللمع، وما هومطبوع من الشامل، وبكتب الأشاعرة المتقدمين عليه.\r*قدمت تراجم مختصرة للأعلام الذين وردوا في النص، وعرفت لبعض الفرق التي ذكرها الجويني تعريفا موجزا.\r*علقت على بعض المسائل الكلامية التي أثارها الجويني، ووضحت آراء الفرق التي تعرض لها الجويني في عرضه لهذه المسائل.\r*ضبطت النص وقومته، وأكملت ما سقط منه، ووضعت ما أضفته بين قوسين مركنين، ثم أدخلت على النص علامات الترقيم اللازمة.\r*خرجت الآيات القرآنية الواردة بالنص، والأحاديث النبوية التي استشهد بها إمام الحرمين، فأشرت إلى مواضع ورودها في كتب الصحاح والسنن.\r*وضعت فهارس تفصيلية لهذا الكتاب حتى أسهل لقارئه الوصول إلى مبتغاه من نص الجويني.\r_______________\r1) الشيرازي، الإشارة إلى مذهب أهل الحق ص 303.\r2) قارن نص العقيدة في الإشارة إلى مذهب أهل الحق ص 303، والمعونة في الجدل ص 88 بما ذكره الجويني ص 142 - 143 من هذا الكتاب."], [108, "*تحليل العقيدة النظامية:\rيرجع تسمية هذا المصنف بالعقيدة النظامية نسبة إلى نظام الملك كما أسلفنا، وهذا الوزير لم يأل جهدا في إعادة الاعتبار للأشاعرة بعد الضائقة التي حلت بهم في نيسابور، واعترافا بهذا الجميل من جهة، وللعلاقة الوطيدة التي ربطت إمام الحرمين بهذا الوزير من جهة أخرى، ألف له الجويني النظامي والغياثي ليستمر ذكره عبر الزمان.\rوقد استفاد الجويني إفادة عظيمة من اطلاعه على علوم الأوائل من منطق وفلسفة، إذ لا نجد له مؤلفا في الأصول إلا وقد حشد فيه الكثير من الاستدلالات والأقيسة العقلية 1. ويمكن القول: إن الجويني قد مهد لطريقة المتأخرين من الأشاعرة في تناول المسائل الأصولية 2، كما كان الباقلاني رائد طريقة المتقدمين التي اختزلت بالقاعدة التي تقول: إن بطلان الدليل يؤذن ببطلان المدلول 3.\rوقد ظهرت طريقة المتأخرين واضحة مع تلميذ إمام الحرمين، الإمام الغزالي، ومن بعده فخر الدين الرازي، وسيف الدين الآمدي، لكن الرازي والآمدي وغيرهما من المتأخرين توغلوا في المزج بين المسائل الكلامية وقضايا المنطق والفلسفة 4، بحيث أصبح متعذرا في مؤلفاتهم التمييز بين ما هوكلامي وما هوفلسفي 5.\rبدأ الجويني التصنيف في علم الكلام بكتابه: الشامل بالأدلة العقلية وأصول المسائل الدينية، ثم لخصه في كتابه: الإرشاد إلى قواطع الأدلة في أصول الاعتقاد 6، ثم لخص الإرشاد في كتابه: لمع الأدلة في قواعد أهل\r_______________\r1) جلال موسى، نشأة الأشعرية وتطورها ص 321.\r2) ابن خلدون، المقدمة ص 465، وسعيد العلوي، الخطاب الأشعري ص 8.\r3) ابن خلدون، المقدمة ص 465، وسعيد العلوي، الخطاب الأشعري ص 8.\r4) سعيد العلوي، الخطاب الأشعري ص 8 - 9.\r5) محمد علي أبوريان، تاريخ الفكر الفلسفي في الإسلام ص 56.\r6) ابن خلدون، المقدمة ص 465."], [109, "السنة والجماعة، بناء على طلب من أصحابه وتلامذته الذين سئموا من المطولات الكلامية 1.\rأما العقيدة النظامية، فكان يظن عند البعض أنها آخر مؤلف لإمام الحرمين 2، فيما ذهب آخرون إلى أنها آخر مؤلف له في العقيدة. والحقيقة أنها ليست بهذا ولا ذاك، وإنما يعد كتاب مدارك العقول هوآخر مؤلف للجويني سواء في العقيدة أوغيرها، إذ ذكر الجويني في خاتمة الغياثي أنه افتتح كتابا باسم نظام الملك أيضا «مضمونه ذكر مدارك العقول» 4. وقال في المدارك: «سأنخل فيها ثمرات الألباب، وأنتزع من ملتطم الشبهات صفوة اللباب، وأتركه عبرة في ارتباك المشكلات، واشتباك المعضلات» 5. لكن الجويني قد توفي قبل أن يتم مدارك العقول. لذا فإن العقيدة النظامية، هي آخر مؤلف لإمام الحرمين وصل إلينا.\rوالقصد من هذا الاهتمام بالترتيب الزمني لمؤلفات الجويني الكلامية، هومعرفة التطور العقدي عند هذا الإمام بدءا بالشامل وانتهاء بالعقيدة النظامية، أما مدارك العقول فلا نعرف له ذكرا في فهارس المخطوطات الإسلامية.\rتعد العقيدة النظامية جزءا من كتاب أشمل هوالنظامية في الأركان الإسلامية، لكن هذا الكتاب لم يصل إلينا كاملا، وكأن العلماء قد أولوا العقيدة جل اهتمامهم، وأغفلوا بقية الكتاب، التي بحث فيها إمام الحرمين مسائل فقهية: كالصلاة، والصوم، والزكاة، والحج، واكتفوا بما ذكره حول هذه المسائل في كتبه الفقهية الأخرى 6.\rوتكمن أهمية العقيدة النظامية بأنها شاهد حي على التحول غير الجذري الذي ختم به إمام الحرمين آراءه الكلامية، إذ يقول في مقدمتها: «وقد صدرتها\r_______________\r1) الجويني، لمع الأدلة ص 85.\r2) المذاري، اللمعة في الاعتقاد ص 54.\r3) محمد الزحيلي، الإمام الجويني ص 108.\r4) الجويني، غياث الأمم ص 526.\r5) المصدر نفسه ص 526.\r6) الجويني، العقيدة النظامية، مقدمة المحقق الكوثري ص 4."], [110, "بقواعد من العقائد على أساليب لم أسبق إليها» 1. لكن ما هي هذه القواعد التي استحدثها هذا الإمام في النسيج العقدي له، وختم بها مواقفه العقدية\rبدأ أبوالمعالي تحولاته العقدية بمسألة حدوث العالم، فقد ذهب في كتبه السابقة كالشامل والإرشاد واللمع 2، إلى أن الموجودات الحادثة تنقسم انقساما ذهنيا إلى الثنائية التقليدية المتوارثة وهما الجوهر والعرض. لكنه في النظامية، قرر أن الموجودات الحادثة، هي أجسام محدودة ومتناهية، وأعراض قائمة بها، كألوانها وهيئاتها في تركيباتها وسائر صفاتها، وحدوث هذه الأجسام بحدوث التغير في أعراضها، وهذا يؤدي إلى إثبات الجواز أوالإمكان، ولما كان كل ممكن أوجائز يحتاج إلى موجد يحدثه، ثبت أن العالم محدث بمؤثر مختار أوقعه على مقتضى مشيئته 3.\rوفي باب الإلهيات ينقلب الجويني على ما تمسك به في الإرشاد، إذ دافع فيه بحماس شديد عن نظرية الأحوال البهشمية 4، وضرورة استخدامها لبيان الصفات الإلهية.\rأما في النظامية فإنه يختصر البحث في العلم بالصفات قائلا: «من انتهض لطلب مدبره، فإن اطمأن إلى موجود انتهى إليه فكره فهومشبه، وإن اطمأن إلى النفي المحض فهومعطل، وإن قطع بموجود واعترف بالعجز عن درك حقيقته فهوموحد» 5.\rثم ينتقل الجويني إلى البحث فيما يجب لله تعالى من صفات 6، وهوهنا لا يضيف جديدا عما ذكره في الإرشاد واللمع، فالله تعالى له صفات نفسية وصفات معنوية، ثم يهاجم المعتزلة الذين قرروا أن إرادة الله\r_______________\r1) انظر ص 122 - 123.\r2) قارن: الجويني، الإرشاد ص 22 - 27، واللمع ص 87 - 92، وص 129 من هذا الكتاب.\r3) انظر ص 130 - 131.\r4) الجويني، الإرشاد ص 80.\r5) انظر ص 142 - 143.\r6) انظر ص 138 - 150 من هذا الكتاب، وقارن به: الإرشاد ص 79، 87، 88، واللمع ص 93 - 102."], [111, "حادثة 1. . . ويستدل الجويني على قدم الإرادة بأدلة سبقه إليها من تقدمه من الأشاعرة كالأشعري نفسه، والباقلاني 2.\rويناقش إمام الحرمين المعتزلة في صفة الكلام نقاشا مطولا، وكرر هنا آراءه السابقة 3، وآراء المتقدمين عليه من الأشاعرة 4. ودافع بحماس شديد عن كون صفة الكلام صفة ذات قديمة قائمة بذات الله تعالى، أما ما هومسموع وما هومقروء وما هومكتوب في المصاحف من حروف وكلمات فهي مدركات، والمدرك كصوت القارئ فهوحادث، أما المفهوم من هذه المدركات فهوالكلام الأزلي «لا يفارق الذات ولا يزايلها» 4. ثم يعترض الجويني على من سماهم الحشوية والذين قالوا: «إن كلام الله في المصاحف، فسبقوا إلى اعتقاد ثبوت وجود الكلام الأزلي في الدفاتر» 5.\rونسي هؤلاء «أن الكلام لا ينتقل من متكلم إلى دفتر، ولا ينقلب معنى النفس إلى الأصوات سطورا ورسوما وأشكالا ورقوما» 6.\rويوضح الجويني ما أراده بأن ضرب مثل الذي يسمع رسالة الملك فيقول: سمعت الملك ورسالته، لكن الحقيقة أنه لم يسمع صوت الملك ولا حديث نفسه. أما الذي يزعم أنه سمع الكلام الإلهي، فهويضع نفسه في منزلة موسى عليه السلام، الذي سمع كلام الله تعالى بلا واسطة 7.\rأما الآيات التي يوحي ظاهرها بالتشبيه، فإن إمام الحرمين يبتعد في فهمها عما قرره في كتبه السابقة 8، وما قرره الأشاعرة من وجوب تأويل هذه\r_______________\r1) انظر ص 148 من هذا الكتاب وقارن به: الإرشاد ص 94، واللمع ص 95، 96.\r2) انظر ص 149 من هذا الكتاب، وقارن به: ابن فورك، مجرد مقالات الأشعري ص 69، والباقلاني، التمهيد ص 49.\r3) قارن ص 151 من هذا الكتاب بما جاء في الإرشاد ص 104 - 107، وابن فورك، مجرد مقالات الأشعري ص 59 - 61، والباقلاني، الإنصاف ص 31، 32.\r4) انظر ص 159.\r5) انظر ص 160.\r6) المصدر نفسه ص 160 - 161.\r7) انضر ص 157 - 158.\r8) انظر: الإرشاد ص 155، ولمع الأدلة ص 104."], [112, "الآيات وعدم الأخذ بدلالاتها الظاهرة 1، وهوهنا يعلن صحة موقف أهل السلف من هذه الآيات، ويلتزم بهذا الموقف إذ يقول: «وذهب أئمة السلف إلى الانكفاف عن التأويل، وإجراء الظواهر على مواردها، وتفويض معانيها إلى الرب تعالى، والذي نرتضيه رأيا، وندين الله به عقلا، اتباع سلف الأمة، فالأولى الاتباع وترك الابتداع، والدليل السمعي القاطع في ذلك: إن إجماع الأمة حجة متبعة» 2.\rويرى الجويني أن هذا الإجماع قد تمثل في موقف الصحابة والتابعين، الذين أعرضوا عن تأويل هذه الآيات، وإدراك ما فيها، ولوكان التأويل مسوغا، لبادر هؤلاء إليه، لذا «فحق على كل ذي دين، أن يعتقد تنزه الباري عن صفات المحدثين، ولا يخوض في تأويل المشكلات، ويكل معناها إلى الرب تبارك وتعالى» 3. ومن ذلك يتضح أن الجويني قد هجر تأويل الصفات الإلهية الخبرية كما هوأس عند الأشاعرة، وانضم إلى سلف الأمة في تفويض أمرها إلى الله تعالى.\rويدعي الجويني أنه قد أصاب كبد الحقيقة عند ما قرر أن أفعال الله مجردة عن الخير والشر، فجميع الأفعال في حكمه متساوية، أما الاختلاف في مراتبها فهو«بالإضافة إلى العباد» 4. وإمام الحرمين هنا لم يضف شيئا جديدا، ولم يصب شيئا، فهوإما أن يكون قد اطلع على ما ذكره الباقلاني في كتابه الرائع «الإنصاف»، وتجاهل ذلك عمدا، ونسب ذلك إلى نفسه، وهذا مخجل بحق إمام له مثل هذه المنزلة. وإما أن يكون لم يحظ بهذا الاطلاع، وهذا مستبعد تماما، لأنه يعترف صراحة أنه حفظ الكثير مما كتبه الباقلاني، إذ يقول: «ما تكلمت في علم الكلام كلمة حتى حفظت من كلام القاضي أبي بكر وحده اثنتي عشرة ألف ورقة» 5.\rقرر الباقلاني أن أفعال الله في دائرة التكليف مجردة عن الخيرية\r_______________\r1) ابن فورك، مجرد مقالات الأشعري ص 42، والباقلاني، الإنصاف ص 21.\r2) انظر ص 166.\r3) انظر ص 166.\r4) انظر ص 171.\r5) السبكي، طبقات الشافعية ج 5 ص 185."], [113, "والشرية، وهاتان الصفتان تضافان إلى هذه الأفعال بعد تعلق أفعال العباد بأوامر الله تعالى ونواهيه، فإذا تعلقت إرادة العبد بأحد هذه الأفعال المجردة، وفق ما أمر الله تعالى فقد هذا الفعل حياده، واتصف بالخيرية، أما إذا تلبست هذه الإرادة بفعل نهى الله تعالى عنه، اكتسب هذا الفعل صفة الشرية 1.\rوقد بحث إمام الحرمين مسألة الرؤية باقتضاب شديد، ولم يخرج فيما قرره هنا عن آرائه وآراء الأشاعرة السابقين له، فالرؤية جائزة، وقد سبق تقدم إجماع سلف الأمة على ذلك 2.\rأما في فصل الوحدانية فقد استخدم أبوالمعالي ما اصطلح الأصوليون على تسميته بالغيرين والمثلين في إثبات الوحدانية لله تعالى، وهوهنا لا يتجاوز ما ذكره في الإرشاد، إذ كرر فيه الدليل الذي اعتادت الأشاعرة على سوقه لإثبات استحالة وجود إلهين، وهوحتمية تعارض إرادتيهما 3.\rبين الجويني أولا أن الله تعالى لا يناسب الأجرام المتحيزة، والأجسام المتحيزة لا تناسبه، وإذا افترض موجودان متحيزان، كانا متغايرين وإن اشتركا بصفة التميز، وذلك لانفراد حيز كل منهما كل منهما عن الآخر. وإن افترض موجودان غير متحيزين فهما متساويان في انتفاء صفة التحيز عنهما، لأن أحدهما ليس مختصا بالثاني اختصاص الصفة بالموصوف، فإن لم يختص أحدهما بحيز عن الثاني، ولم يختص بالثاني لم يتعددا قطعا 4.\rويعقد الجويني بابا مطولا لبحث مسألة خلق أفعال العباد، تحت عنوان العبودية والصفات المرعية في ثبوت الطلبات التكليفية، ويكاد يكون هذا الباب أهم ما جاء في هذه العقيدة، إذ أعلن فيه صراحة بتأثير القدرة الحادثة في العبد في مقدورها، وبذلك يكون خالف ما ذكره في الإرشاد واللمع 5، وما\r_______________\r1) الباقلاني، الإنصاف ص 147، 149.\r2) انظر ص 177 من هذا الكتاب، وقارن به: الإرشاد ص 176، واللمع ص 115.\r3) قارن ص 181 - 182 من هذا الكتاب، والإرشاد ص 52.\r4) انظر ص 182.\r5) ذهب الجويني في الإرشاد ص 209، ولمع الأدلة ص 121، إلى أن القدرة الحادثة لا تؤثر في مقدورها وحصر دورها في اكتساب الفعل المخلوق بقدرة الله تعالى."], [114, "أثر عن الأشعري وغيره من الأشاعرة، الذين نفوا أي تأثير لهذه القدرة في مقدورها سوى كسبه 1، فالفعل يقع خلقا من الله تعالى، وكسبا من العبد.\rوقد عرض ذلك الأشعري إلى التشنيع الشديد، وضرب خصومه المثل في استحالة الكسب، وعدوه من محالات الكلام فقالوا؛ محالات الكلام ثلاثة: طفرة النظام وأحوال أبي هاشم وكسب الأشعري» 2.\rوكان هؤلاء الخصوم يتندرون في ذلك ويقولون: «أدق من كسب الأشعري» 3.\rيقول الجويني في النظامية أن من «استراب في أن أفعال العباد واقعة حسب إيثارهم، واختيارهم، واقتدارهم، فهومصاب في عقله، أومستمر على تقليده، مصمم على جهله، ففي المصير إلى أنه لا أثر لقدرة العبد في فعله، قطع طلبات الشرائع، والتكذيب بما جاء به المرسلون» 3.\rولم يكتف إمام الحرمين بذلك، وإنما انتقد ما اعتقده الأشاعرة في الكسب قائلا: «لوأن قائلا قال: العبد مكتسب، وأثر قدرته الاكتساب، والرب تبارك وتعالى مخترع، خالق لما العبد مكتسب له، قيل له: فما الكسب وما معناه وأديرت الأقسام المتقدمة على هذا القائل، فلا يجد عنها مهربا» 4.\rثم يعقد الجويني بابا للنبوات، يرد فيه على منكريها من البراهمة، ثم يعرف المعجزة ويذكر شروطها، وهوهنا يكرر ما جاء في الإرشاد، وما جاء في التمهيد للباقلاني، وينقل الجويني هنا وعلى الأخص في فصل بيان وجه دلالة المعجزة نصوصا كاملة من الإرشاد، ويكرر الأمثلة نفسها التي وردت فيه 5.\r_______________\r1) انظر: اللمع للأشعري ص 118 - 121، وابن فورك، مجرد مقالات الأشعري ص 91، 92، والبغدادي، أصول الدين ص 134، والباقلاني، التمهيد ص 341 - 353.\r2) ابن تيمية، منهاج السنة ج 1 ص 127، وأبوعذبة، الروضة البهية ص 56، وابن قيم الجوزية، شفاء العليل ج 1 ص 147.\r3) انظر ص 185 - 186.\r4) انظر ص. . .\r5) انظر ص 189 - 190، وقارن به: الإرشاد ص 307، ولمع الأدلة ص 124."], [115, "أما في الفصل الخاص بإثبات نبوة سيدنا محمد صلى الله عليه وسلم، فقد انقلب على ما ذكره في الإرشاد، ونفى أن يكون وجه الإعجاز في القرآن الكريم قد حصل بالنظم، والبلاغة، والجزالة، والإنباء عن قصص الأولين، والإخبار بالمغيبات 1، ثم يحصر هذا الإعجاز في صرف العباد ومنعهم من الإتيان بمثله، إذ يقول: «فتبين قطعا أن الخلق ممنوعون من مثل ما هوفي مقدورهم، وذلك أبلغ عندنا من خرق العوائد بالأفعال البديعة في أنفسها. ثم يقول: «فإذا لم تجر المعارضة، لم يبق لامتناعها مع توفر الدواعي عليها محمل إلا صرف الله الخلق» 2. وهوهنا يقترب من موقف بعض المعتزلة 3.\rوفي الفصل الذي خصصه الجويني للإيمان، قسمه إلى أربعة أركان:\rبحث في الأول منها حقيقة الإيمان، وفي الثاني العصاة من أهل الإيمان، وفي الثالث زيادة الإيمان ونقصانه، وهوفي هذه الأركان الثلاثة إرشادي، بمعني أنه كرر ما ذكره بخصوصها في الإرشاد ولم يضف جديدا 4.\rأما الركن الرابع فقد بحث فيه مسألة الاستثناء وقول من سلف: إنا مؤمنون إن شاء الله عز وجل. وهنا يؤكد الجويني أن جماهير أهل السنة، خواصهم وعوامهم «على عقد صحيح في الدين يتعلق بالمعتقد على ما هوبه» 5. ثم يبين أن هذا العقد ليس بمعرفة، وأن الله تعالى لم يكلف عباده «حقيقة معرفته ودرك اليقين في الدين».\rويستدل على ذلك، بأن الصحابة لم يطالبوا بالبحث عن الأدلة، «وإنما\r_______________\r1) انظر: الإرشاد ص 349، ولمع الأدلة ص 125.\r2) انظر ص 237، وقارن به: القاضي عبد الجبار، المغني في التوحيد والعدل ج 16 ص 322 - 328.\r3) انظر: الباقلاني، إعجاز القرآن ص 99 وفيه نقلا عن بعض المعتزلة: «ليس في نظم القرآن وتأليفه إعجاز، وإنه يمكن معارضته، وإنما صرفوا عنه ضربا من الصرف». وانظر أيضا: والشهرستاني، نهاية الإقدام ص 423، والملل والنحل 56، 57، 103، والأشعري، مقالات الإسلاميين ص 225، عبد الرحمن بدوي، مذاهب الإسلاميين ج 1 ص 219.\r4) قارن ص 257 من هذا الكتاب، بالإرشاد ص 396.\r5) انظر ص 267."], [116, "طولبوا بعقد مصمم وشهادة والتزام أحكام» 1. ومن ذلك يتبين لنا أن الجويني قد تراجع عما تمسك به في الإرشاد من ضرورة النظر ووجوبه 2.\rوقول السلف: إنا مؤمنون إن شاء الله، ناتج من أن عقد الإيمان ليس علما، لذا لم يدر المعتقد أن المأتي به من الإيمان على الحد المطلوب، لذا حسن الاستثناء. وقول المعتقد: أنا مؤمن إن شاء الله 3. أما وجه الاستثناء عند العارف، فذلك لأنه قد تعتريه حالات «يعدم فيها مذاق اليقين» 4.\rويختم الجويني عقيدته النظامية بفصل في أحكام التوبة وماهيتها وشروطها ووجوبها. والجديد الذي أضافه هنا، هوتمييزه بين توبة العارف بالله وتوبة المعتقد بالله، فالعارف بالله تكون معصيته بالذهول الذي يعتريه عن صفوة المعرفة، لذا فإن توبته تكون بالعودة إلى حضور الذهن، فمن «حضرته المعرفة، وسطعت عليه أنوارها، لم يصر على ذنب من الذنوب» 5.\rأما المعتقد بالله، فتكون معصيته مرتبطة بشهواته، فإن ضعفت شهوته في معصية ما قوي فيه عقده، ولاحق توبته» 6، مع استمراره في المعصية التي ما زالت قوة الشهوة ملازمة له باتجاهها 7.\rأما تبويب العقيدة فمضطرب تماما، وأحيانا نجد الباب قد قسم إلى عدة أقسام، والقسم وزع على مجموعة فصول، وأحيانا أخرى، نجد أن الباب دون لا يتضمن أقساما أوفصولا. كذلك أغفل الجويني وضع عناوين لبعض فصول وأقسام العقيدة، لذا اجتهدت في وضح عناوين مناسبة لها.\r_______________\r1) انظر ص 267.\r2) الجويني، الإرشاد ص 18.\r3) انظر ص 268.\r4) انظر ص 268.\r5) انظر ص 276.\r6) انظر ص 276.\r7) انظر ص 276.\r(1/ 113)"], [119, "بسم الله الرحمن الرحيم\rرب يسر بعونك\r[المقدمة]\r"]], "pg": [93, 119]}, "474.8": {"x": [[119, "الحمد لله كفاء إفضاله، والصلاة على خير خلقه محمد، وعلى آله.\rهذا؛ وقد ملك الله مولانا الصاحب/الأجل، السيد، نظام الملك 1، قوام الدين، سيد الوزراء، غياث الدولة، وصي أمير المؤمنين-أدام الله علاه-مقاليد الممالك، وذلل له ما توعر على الأولين من المسالك، وقذفت إليه الأرض أفلاذ أكبادها، وألقت إليه أهلها أزمتها في إصدارها رب يسر بعونك: ليست في ط.\rفي أ: كفا، واعتاد الناسخ على عدم كتابة الهمزة إذا سبقت بمدود، أما إذا كانت في وسط الكلمة فإنه يكتبها ياء.\rكتبت في الأصل: والصلوة.\r_______________\rالسيد: ليست في ط.\rقوام الدين: ليست في ط.\rفي ط: معتمد.\rفي ط: أعمالك.\rفي ط: أهلوها.\r_______________\r1) نظام الملك (- 486 ه‍/ 1093 م): هوأبوعلي الحسن بن علي بن إسحاق بن العباس، قوام الدين، الملقب نظام الملك وغياث الدولة، من بلدة نوقان بنواحي طوس، وكان من أولاد الدهاقين واشتغل بالحديث والفقه، عمل بخدمة السلطان ألب أرسلان وولده ملكشاه، كان على مذهب الشافعي في الفروع وعلى مذهب الأشعري في الأصول، لذا بنى المدارس النظامية لتدريس الفقه الشافعي والأصول الأشعري، وكان يكرم إمام الحرمين وأبا القاسم القشيري في مجالسه، اختلف في سبب مقتله فقيل: إن ملكشاه دس له السم فمات لهيمنته على شؤون الدولة. انظر في ترجمته: وفيات الأعيان لابن خلكان ج 8 ص 128، وتاريخ الإسلام لذهبي، وفيات (481 - 490) ص 142، والمنتظم ج 9 ص 64، وطبقات الشافعية للسبكي ج 3 ص 135."], [120, "وإيرادها، واستكان له دانيها وقاصيها، وتوطأت لسنابك خيله صياصيها 1، وأضحت رقاب الملوك نحوارتسام مراسمه صورا.\rوامتلأت طباق الآفاق بإشراق عدله نورا، ومعالم المظالم قفرا بورا، وأخذت الأرض زخرفها، ونشرت المسرة مطرفها 2، وحقق الدهر مواعيده، وأنجز ببهائه وراء كل مأمول مزيده، واستمدت من نور سعادته الشمس، وتاق إلى سنائه الغد فالتفت إلى الأمس.\rوباهت الغبراء 3 به مناط القمرين 4، وتضاءلت دون غرته الشماء أعالي الشعريين 5، ورفلت ملة الحق بيمنه من جلابيب الجلال في أسبغها وأضفاها 6، ورقت من يفاع 7 العز إلى ذراها، بعد ما كان انفل غربها 8 وشباها 9، وحييت به رسوم المآثر الدواثر 10، وانتعشت بعلوقدره في ط: فاستكان.\r_______________\rبإشراف: ليست في ط. في ط: بعدله.\rفي ط: الظلم. في ط: دائرة. في ط: أضاف الكوثري بعدها رويدا رويدا.\rفي ط: بصفائه. في ط: مزيدا.\rفي أ: والتفتت، والمثبت من ط. العز إلى: في ط العوالي.\rرسوم: ليست في ط. في الأصل: الماآثر.\r_______________\r1) الصياصي: مفردها صيصة، وهي الحصون، وكل شيء امتنع به وتحصن به، ويقال صياصي البقر: قرونها.\r2) مطرفها: المطرف هوالثوب من الخز.\r3) الغبراء: الأرض لكثرة غبارها.\r4) هما الشمس والقمر.\r5) الشعريان: هما كوكبا العبور في الجوزاء، والغميصاء التي في الذراع، تزعم العرب أنهما أختا سهيل، وقد عبدت العرب العبور وهي التي ورد فيها قوله تعالى: وأنه هورب الشعرى? (49) سورة النجم، الآية 49.\r6) الإضفاء: سعة العيش. انظر لسان العرب مادة ضفا.\r7) اليفاع: جمع يفوع، وهوكل ما ارتفع من الأرض.\r8) غربها: حدها، وانفل غربها: انثلم حدها.\r9) شباها: مفردها شبوة، والشبوة حد كل شيء وطرفه. لسان العرب، مادة شبا ج 14 ص 420.\r10) الدواثر: الدوارس."], [121, "جرود 1 المفاخر العواثر، وتأرجت بعليائه 2 سطور الدفاتر.\rوانخرط في سلك سامي رأيه الدين والدنيا، ولاذ ببابه المنيف وجنابه الشريف كافة الورى، واجتمع بواحد الدهر شتات الأهواء، وانضم منتشر الآراء، ووثق الأعداء بعدله ثقة الأولياء بفضله، واستن أمر الملك في الأسلوب الأوضح واللقم 3 الأفيح.\rوطنت دائرة الآفاق بنبأ المعارضة 4، فضاقت الأرض برحبها، ومادت بعطفي شرقها وغربها، وزلزلت الأرض زلزالها، وقطعت المبيرات 5 أوصالها، وطبقت الهموم التي تذيب العظام، وتنشئ الكرب العظام، طبقات الأرض غدوها وآصالها، وقطب دين الحق غرته البهية، ورجفت من العلياء البنية، وارتجت أركانه العلية 6.\rثم تدارك الله الإسلام والأنام، لما استفاض أنها انجابت 7 انجياب الغمام، وأعقبت الإبلال على التمام 8، فأراد خادم الدعاء أن يطير\r_______________\rفي ط: وأرجت. في ط: نشر. في الأصل: الآراا.\rفي أ: المسرة، والمثبت من ط. في ط: من طبقات.\rفي ط: السقام. في ط: وأراد.\r•-------------•\r1) جرود: جمع جرد، وهي أعالي الجبال.\r2) تأرجت بعليائه: فاحت منه رائحة طيبة.\r3) اللقم: وسط الطريق.\r4) يشير الجويني هنا إلى المحنة التي حلت بأشاعرة نيسابور على يد عميد الملك الكندري.\r5) المبيرات: المهلكات.\r6) وكأن الجويني في هذه الفقرة يصور المحنة التي لحقت بالأشاعرة في بغداد والمشرق الإسلامي أيام السلطان طغرلبك ووزيره الكندري.\r7) انجابت: انكشفت وزالت.\r8) يشير إمام الحرمين هنا إلى زوال المحنة التي طالت الأشاعرة وأهل السنة بعد مقتل الوزير الكندري. . . وإعادة الاعتبار إلى الأشاعرة وبناء المدارس لهم من قبل نظام الملك."], [122, "بجناح المهزة 1 إلى مخيم العلى والعزة، معتزيا إلى مواقف الخدم، معتزا بالمثول في المجلس الأبهى في غمار الجشم 2، وصار لا يبرم عقدة العزم إلا حل القضاء بحلها /، ولا يقدم قدما للنهوض إلا نزل القضاء فأزلها، وما استأخر استئخار الواني، ولكن الأقدار دافعة في صدور الأماني.\rعلى أنه رأى المثابرة على الأدعية، وما هوبصدده من الوظائف التي رتب 3 لها، أولى عند من أفاض عليه بسبب معاليه وأولى، ثم قدم تذكرة إلى المجلس الأسمى لتنوب عنه في تمهيد معاذيره، وتشعر ببذله المجهود في الخدمة وتشميره.\rوقد زففتها عروسا 4 تختال في أثوابها، وترفل في جلبابها إلى أكرم أكفائها وخطابها، وإن أبت على مفترعها 5 إباء البكر، ذللتها صفوة الفكر، وغض من شماسها 6 وشراسها 7 كثرة دراسها 8، ومهرها أن تقع من السدة السامية موقع القبول، ومتضمنها عقائد العقول ونخب الشرع المنقول.\rوقد صدرتها بقواعد العقائد على أساليب لم أسبق إليها، ولم أزحم.\r_______________\rفي ط: بأجنحة\rفي ط: الهزة.\rفي ط: العلاء.\rفي ط: بالمنزل.\rفي ط: الحشم.\rفي أ: وصار لا ينبرم عقد العزم الأجل القضاء فجلها، والمثبت من ط.\rإلى المجلس: كررها الناسخ في الأصل.\rفي ط: الأسنى.\rفي ط: عقائل.\rفي ط: بقواعد عن.\r•--------------•\r1) المهزة: الحركة.\r2) الجشم: الأمر الثقيل.\r3) رتب لها: تصدر لها وانتصب.\r4) يقصد بذلك النظامية في الأركان الإسلامية.\r5) مفترعها: الذي يريد فض بكارتها، وهويقصد بأنه لم يقلد أحدا في هذه النظامية وإنما جمع فيها أبكار الأفكار التي لم يتوصل إليها غيره.\r6) شماسها: إبائها وامتناعها.\r7) شراسها: تعنتها.\r8) دراسها: اقترافها والمداومة عليها.\r(1/ 119)\r---\r123 عليها، ثم أتبعتها بما لا يسوغ الذهول عنه من أركان الإسلام، وسميتها:\r\rالنظامية في الأركان الإسلامية، وها هي:\r\rولم أزحم عليها: ليست في ط.\r\rفي أ: في والمثبت من ط.\r\rوها هي: ليست في ط.\r(1/ 120)\r---"], [123, "عليها، ثمم أتبعتها بما لا يسوغ الذهول عنه من اركان الإسلام، وسميتها: النظامية في الأركان الإسلامية, وها هي:"]], "pg": [119, 123]}, "474.9": {"x": [[124, "القول فيما تجب معرفته في قاعدة الدين\r\rفصل: [أقسام العلم والنظر]\rالنظر 1 في مدارك العقول إذا تم على صحته وسداده، أفضى إلى العلم بجواز جائز، أووجوب واجب، أواستحالة مستحيل.\rوهذه العلوم، يختص بدركها، ذووالعقول السليمة، وأولوالفطنة المستقيمة، ثم كل قسم منها ينقسم إلى: ما تحيط به بديهة العقل، من غير نظر واعتبار، وطلب وافتكار، وإلى ما تقدمه نظر، وكل نظر تجريه العقول في ضرب من هذه الضروب، فلا بد له من مستند ضروري، ومعتقد بديهي 2.\r_______________\rفصل: ليست في ط.\rفي أ: ذووا.\rفي أ: وألوا.\rفي ط: الفطر.\rفي ط: يجريه العاقل.\rفي أ: مستندن والمثبت من ط.\r•------------•\r1) النظر في اصطلاح المتكلمين: هوالفكر الذي يطلب به من قام به علما أوغلبة ظن، وهوينقسم إلى قسمين: الصحيح، وهوكل ما يؤدي إلى العثور على الوجه الذي منه يدل الدليل، والفاسد: ما عدا ذلك. انظر الإرشاد لإمام الحرمين ص 3، ومصباح السعادة لطاش كبرى زادة ج 1 ص 281، وانظر أيضا التمهيد للباقلاني ص 29، 30، وشرح الأصول الخمسة للقاضي عبد الجبار الهمذاني ص 43، والمبين في ألفاظ المتكلمين للآمدي ص 103، 104، والغنية للمتولي ص 52، ومعالم أصول الدين للرازي ص 22، والمحصل ص 56.\r2) ينقسم العلم إلى: العلم القديم وهوصفة الله تعالى المتعلق بما لا يتناهى من المعلومات، والعلم الحادث وينقسم إلى العلم الضروري، وهوالعلم الذي يلزم ذات الفرد مما لا يستطيع الانفكاك منه أوالشك فيه، كعلم الإنسان بنفسه وحالته"], [125, "وبيان ما رتبناه بالمثال في كل قسم: فالجواز البديهي، الذي يعلمه العاقل من غير عبر وفكر ونظر، هوما يحيط به العاقل، إذا رأى بناء من جواز حدوثه، فيعلم قطعا على الارتجال، أن حدوث ذلك البناء من الجائزات، وكان لا يمتنع في العقل أن لا يبنى، ثم يطرد حكم الجواز في صفاته وسماته، وارتفاعه واجتماعه، وطوله وعرضه، واختصاصه بما هوعليه من أشكاله، وفنون أحواله.\rثم ينظر في تجويز العقل إلى تخصيصه بأوقاته، فلا يخطر العاقل بباله شيئا من أحواله، إلا عارضه إمكان مثله، أوخلافه، فيستبين على الاضطرار، أنه كان يجوز أن لا ينبى ما بني، وإن بني، كان يجوز/أن يبنى على خلاف ما هوعليه من الهيئات.\rوتنسحب هذه التقديرات في التقدم والتأخر الآيلين إلى الأوقات. فهذه مدارك في جواز الجائزات على الضرورة، من غير احتياج إلى تدبر دلالات، ومباحثة عن آيات في المعقولات.\rومثال النظري في هذا القسم، ما يعلمه اللبيب من جواز تداور في ط: يبتدره العقل.\r_______________\rمن: ليست في أ.\rفي أ: يمنع من.\rفي ط: يطرح.\rإلى: ليست في ط.\rفي أ: بنا، والمثبت من ط.\rفي ط: وإذ.\rفي ط: تزيد.\rفي أ: تدوار، والمثبت من ط.\r•------------•\r2) -الوجدانية من رضى أوغضب، والعلم البديهي: وهوقريب من الضروري إلا أنه لا يرتبط بنفع أوحاجة كالعلم باستحالة اجتماع الضدين مثل اجتماع الحركة والسكون أوالسواد والبياض، والقسم الثالث هوالعلم الكسبي، وهوالعلم الحاصل بالقدرة الحادثة عن نظر واستدلال. انظر في ذلك: التمهيد للباقلاني ص 26، والإنصاف له ص 13، والإرشاد للجويني ص 13، 14، والغنية لأبي سعيد المتولي ص 51، وأصول الدين للبغدادي ص 8، 9، والمحصل للرازي ص 148، 149، والمواقف ص 11 - 14، وشرح الأصول الخمسة ص 48، 50.\r(1/ 122)\r---"], [126, "الأفلاك في جهاتها، فإذا استقامت عبره واستد نظره، وتأمل الأجرام العلوية، وهي دائبة في حركاتها المتناسبة، جائية وذاهبة، وشارقة وغاربة، وتحقق أن الجهات في قضيات العقول متساوية، وأن الذي يدور منها من الشرق إلى الغرب، لا يستحيل في العقل انعكاسه من الغرب إلى الشرق، فإن منخرقها 1 من الهواء لا يختلف، بسبب انعكاسها، ومدارها في الارتفاع والانخفاض لا يتفاوت، بتقدير شروقها في جهة غروبها، وهذا باب يتسع فيه المجال، والإكثار منه يورث الملال.\rومعرفة الجواز في القسم النظري إذا حصل، يلتحق بالمرتبة البديهية، إذ يستحيل أن تكون معرفة أثبت من معرفة، غير أن العاقل لا يفتقر إلى مزيد فكر في الأبنية إذا شاهدها تشاد وتنقض وتعاد، وحركات العلويات لم تعهد إلا على قضية واحدة، والاستمرار على حكم الاعتياد يعمي الذاهل عن سبل الرشاد 2.\rفأما المستحيلات، فمثال المدرك البديهي منها، سبق العقل إلى القطع بأن السواد والبياض لا يجتمعان، ولا يكون الجسم في حالة واحدة في ط: شارقة.\r_______________\rفي ط: من المشرق إلى المغرب.\rفي ط: من المغرب إلى المشرق.\rفي ط: مخترقها.\rفي ط: اليمين.\rفي أ: لسبب.\rفي ط: التي يشاهدها.\rفي أ: الاعتبار، والمثبت من ط.\rفي ط: سبيل.\rفي ط: وأما.\rفي أ: العاقل.\rفي أ: أو، والمثبت من ط.\r_______________\r1) المنخرق: الممر. انظر اللسان ج 10 ص 75.\r2) وفي الشامل ص 17: «والذي ارتضاه المحققون أن العلوم المرتبطة بضروب النظر لا تختلف ولا تتفاوت، إذ لا يتصور علم أبين من علم، إذ العلم تبيين العلوم ومعرفته واستيقانه. . . والعلم بالشيء الواقع نظرا يماثل به بديهة وضرورة كما تتماثل الحركة الضرورية الحركة الكسبية، والحركتان متماثلتان، ومن حكم المتماثلين وجوب استوائهما في صفات النفس.\rوتماثل الحركة الذي عناه الجويني هنا هوأن الأولى تقع معجوزا عنها والثانية تقع مقدورا عليها إلا أنهما يتماثلان في كونهما حركة."], [127, "متحركا إلى مكان ساكنا في غيره، إلى غير ذلك مما يطول تعداده 1.\rومثال النظري من هذا القسم، العلم باستحالة وقوع جائز من غير مقتض يقتضيه، فإذا تحرك الشيء، وعلم أن تحريكه جائز، وكان يجوز أن يستمر به السكون الذي عهد لجنسه في الزمن المتقدم، ثم قيل: أيجوز أن يفترض تحركه من غير سبب ومقتضى ومعنى غير إيثار ومؤثر تبين للعاقل بأدنى نظر ينبه ذهنه عن الذهول، أن تقدير وقوع جائز من غير مقتض أومؤثر مستحيل، غير ممكن 2.\rوأما الواجبات العقلية، فمثال الضروري منها، العلم بأن صانع الشيء وموجده/، يجب أن يكون قادرا على فعله، إلى غير ذلك.\rومثال النظري منها، العلم بأن مخترع الأشياء يجب أن يكون عالما بتفاصيل أفعاله، كما سيأتي شرح ذلك 3، إن شاء الله عز وجل.\r_______________\rوماقضى في أ: النظر.\rفي أ: وإذا.\rفي أ: تحركه.\rفي أ: له حسنه.\rفي ط: ثم إذا.\rفي أ: يفرض، والمثبت من ط.\rفي ط: إيثار مؤثر.\rفي ط: العاقل.\rفي ط: محال.\rفي ط: الله تعالى.\r_______________\r1) انظر في ذلك: التمهيد للباقلاني ص 6، والغنية لأبي سعيد المتولي ص 51، وأصول الدين للبغدادي ص 8.\r2) ذلك إن لم يطرأ مقتضى فالأولى بقاء الجائز على ما هوعليه، أما حصول الجائز دون مقتضى فهوإلغاء للسنن الكونية، فتصبح الأمور في حال جوازه لا ضابط لها، والمعلوم أن الأشاعرة قد نفوا أي سببية سواء فيما يتعلق بالضرورة الداخلية للعالم، أوترتب الأسباب والمسببات في الفعل الإلهي لغرض الصلاح، لكن هذا لا يعني أن الأشاعرة لم يقولوا بنظام في العالم، وإنما أرجعوا هذا النظام للإرادة الإلهية التي تخصص الجائزات بمحض المشيئة، والعالم متناسق ومنظم رجوعا للقدرة الإلهية مباشرة.\rانظر الغزالي، الاقتصاد في الاعتقاد ص 53، والمواقف للإيجي ص 485.\r3) انظر ذلك ص 191، واستندت الأشاعرة على هذا المبدأ في نفي كون الإنسان خالقا لأفعاله كما قالت المعتزلة، فالخالق للفعل لا بد أن يكون عالما بتفاصيل هذا الفعل"], [128, "العقل بوجوب ثبوته، استحال انتفاؤه، وما تضمن نظر العقل استحالة ثبوته، وجب انتفاؤه.\rفهذه مقدمات لا يتمارى فيها عاقل غير ذاهل عن سنن السداد، وجميع قواعد الدين تتشعب عن هذه القضايا العقلية، على ما سنرتبها أبوابا، مستعينين بالله عز وجل، وهوخير معين.\r_______________\rعاقل: ليست في ط.\rفي ط: أبوابا إن شاء الله.\rمن قوله: مستعينين. . . إلى قوله: معين، ليست في ط.\r_______________\r3) -وحركاته المتتالية، والإنسان يجهل هذه التفاصيل، فدل ذلك على أن خلق الفعل ليس للعبد إليه سبيل وإنما الخالق له هوالله تعالى. انظر في ذلك: مجرد مقالات الأشعري ص 94، واللمع ص 101، والتمهيد للباقلاني ص 342، والإرشاد للجويني ص 190، وأصول الدين للبغدادي ص 136، والمحصل للرازي ص 281، وغاية المرام للآمدي ص 325، والغنية للمتولي ص 118."], [129, "باب القول في حدث العالم\r"]], "pg": [124, 129]}, "474.10": {"x": [[129, "العالم كل موجود سوى الله تعالى 1، وهوأجسام محدودة متناهية المنقطعات، وأعراض قائمة بها، كألوانها وهيئاتها في تركيبتها وسائر صفاتها.\rوما شاهدنا منها، واتصلت به حواسنا، وما غاب منها عن مدارك حواسنا، متساوية في ثبوت حكم الجواز لها، فلا شكل يعاين أويفرض، مما صغر أوكبر، أوقرب أوبعد، أوغاب أوشهد، إلا والعقل قاض بأن تلك الأجسام المتشكلة لا يستحيل فرض تشكلها على هيئة أخرى.\rوما سكن منها، لم يخل العقل تحركه، وما تحرك، لم يخل سكونه، وما صودف مرتفعا إلى منتهى سمك من الجو، لم يبعد تقدير انخفاضه،\r_______________\rفي ط: تركيباتها.\rفي أ: مدرك والمثبت من ط.\rفي ط: إحساسنا.\rفي ط: بلا.\rفي أ: يغاير، والمثبت من ط.\rفي ط: منا.\rفي أ: وكبر وقرب، والمثبت من ط.\rفي أ: المشكلة، والمثبت من ط.\rفي أ: تشككها، والمثبت من ط.\rفي أ: لما، والمثبت من ط.\rفي أ: وسمك من الحق، والمثبت من ط.\r_______________\r1) في الإرشاد ص 17: «العالم، وهوكل موجود سوى الله تعالى وصفة ذاته، وقد عرف الأشعري العالم بأنه جملة المخلوقات جواهرها وأعراضها». انظر مجرد مقالات الأشعري لابن فورك ص 37، وأصول الدين للبغدادي ص 33."], [130, "وما استدار على النطاق 1، لم يبعد فرض تدواره نائيا عن مجراه. وترتب الكواكب على أشكالها يجوز على خلاف هيئاتها وأحوالها، فيتضح بأدنى نظر، استمرار مقتضى الجواز على جميعها 2، وما ثبت جوازه، استحال الحكم بوجوبه.\rولا ينساغ في عقل موفق، اعتقاد قديم عن وفاق، وهومجوز غير ممتنع تقديره على خلاف ما هوعليه، فإذا لزم العالم حكم الجواز، استحال القضاء بقدمه، وتقرر أنه مفتقر إلى مقتضى اقتضاه على ما هوعليه 3.\rوإنما يستغنى عن المؤثر ما قضى العقل بوجوبه، فيستقل بوجوبه ولزومه عن مقتضى يقتضيه، فأما ما ثبت جوازه، وتعارضت فيه جهات الإمكان، فمن المحال ثبوته اتفاقا على جهة منها من غير مقتضى 4.\r_______________\rفي أ: استدل، والمثبت من ط.\rفي ط: تداوره.\rفي ط: فيستغني.\rفي أ: يقضيه، والمثبت من ط.\r_______________\r1) أي ما ثبت على مجراه.\r2) في الإرشاد ص 28: «فالحادث جائز وجوده وانتفاؤه، وكل وقت صادفه وقوعه كان من المجوزات تقدمه عليه بأوقات، ومن الممكنات استئخار وجوده عن وقته بساعات».\r3) في الإرشاد ص 28: «فإذا وقع الوجود الجائز بدلا عن استمرار العدم المجوز، قضت العقول ببداهتها بافتقاره إلى مخصص خصصه بالوقوع». وانظر أيضا مقالات الأشعري لابن فورك ص 37، والتمهيد للباقلاني ص 41، 43، وأصول الدين للبغدادي ص 69، والغنية للمتولي ص 56، 57، والاقتصاد في الاعتقاد للغزالي ص 14، والجويني هنا ينقل عما ذكره الباقلاني في التمهيد ص 43.\r4) فالحوادث منها المتقدم ومنها المتأخر مع جواز تأخر المتقدم وتقدم المتأخر، ولا يجوز أيضا أن يكون التقدم والتأخر راجع إلى ذات المحدث، لأنه ليس التقدم بصحة تقدمه أولى من التأخر بصحة تأخره، وهذا يوجب الدلالة على فاعل مؤثر مختار صرف الجائزات في الوجود على ما هي عليه. انظر الإنصاف للباقلاني ص 16، والشامل في أصول الدين للجويني (تحقيق كلوبفر) ص 145."], [131, "فإن قيل: بم تنكرون على من يزعم/أن العالم بما فيه قديم لا مبتدأ لكونه، ولا مفتتح لوجوده ولاختصاصه بما هوعليه، بمقتضى قديم هوفي حكم العلة، والعالم في حكم المعلول، والعلة والمعلول، والموجب والموجب يتلازمان، ولا يسبق أحدهما الآخر\rوإذا انتهى مولانا إلى هذا المنتهى، تثبت قليلا، وتأمل برأيه الثاقب الوقاد، على رسل واتئاد، وابتهل إلى الله جلت قدرته، وهوولي التأييد والإرشاد.\rفنقول، والله المستعان وعليه التكلان: إذا بطل ثبوت الجائزات من غير مقتضى، قسمنا الكلام وراء ذلك وقلنا: مقتضى العالم، لا يخلوإما أن يكون موجبا من غير إيثار واختيار، وإما أن يكون مؤثرا مختارا.\rفإن كان موجبا من غير إيثار، كان ذلك مستحيلا، فإن الموجب الذي لا يؤثر، يستحيل أن يقتضي شيئا دون مماثلة، وهذا يتضح، بأن نضرب فاسد مذهب الطبائعيين مثلا، فنقول: إذا قال من ينتحل القول بآثار الطبائع: إن دواء مخصوصا يجذب المرة الصفراء 1 دون غيرها من الأخلاط 2، يستحيل عنده أن يجذب جزءا من المرة من قطر، ولا يجذب جزءا آخر في مثل [ذلك القطر] بعد ذلك المجذوب، مع ارتفاع الموانع واستواء الأحوال، هذا محال تخيله.\r_______________\rفي أ: لا مبدأ، والمثبت من ط.\rفي ط: لاختصاصه.\rفي أ: الثاني.\rفي ط: الله تعالى.\rفي ط: فهو.\rوعليه التكلان: ليست في ط.\rفي ط: مؤثر مريدا مختارا.\rفي أ: وإن، والمثبت من ط.\rشيئا: مكرره.\rفي أ: يصح، والمثبت من ط.\rفي أ: الطبائعي، والمثبت من ط.\rفي أ: كان، والمثبت من ط.\rبآثار: ليست في ط.\rفي أ: مستحيل.\rالزيادة من ط.\r_______________\r1) المرة: خلط من أخلاط البدن وسميت بالمرة الصفراء للونها.\r2) أخلاط الجسد عند القدماء هي: الدم والبلغم والصفراء والسوداء."], [132, "وإذا تقرر ذلك قلنا: العالم بجملته قار في جومعلوم، وتقديره واقعا في ذلك الخلاء، يماثل تقديره في خلاء عن اليمين أوعن الشمال. وهذا يقرب من مدارك البدائه.\rوإذا تماثلت الأحياز والجهات، استحال اعتقاد موجب يخصص العالم بقطر تماثله سائر الأقطار، فإن الموجب لا يخصص شيئا من أمثاله، والمؤثر المختار، هوالذي يتحيز بإرادته ومشيئته مثلا من أمثال، فلاح بطلان المصير إلى موجب قديم لا اختيار له 1.\rولوقيل: العالم قديم، وموجبه مؤثر مختار.\rقلنا: هذا باطل قطعا، فإن القديم يستحيل أن يكون ثبوته بإرادة، إذ الموقع المخصص الذي لم يكن فكان هوالمراد، فأما ما لم يزل واقعا، فيستحيل ارتباط كونه بإرادة في الإيقاع.\rوعلى الجملة [الواقع] /بالإرادة فعل يؤثره المريد، فيوقعه على حسب إرادته، وما كان ثابتا أزلا، فليس فعلا، حتى يقال: وقع بالإرادة\r_______________\rعلى في أ: لقنا، والمثبت من ط.\rفي أ: و، والمثبت من ط.\rكتبت في الأصل: البداية.\rفي أ: تخصيص، والمثبت من ط.\rفي أ: يماثله.\rفي أ: وهو، والمثبت من ط.\rفي ط: يحيز.\rفي ط: الأمثال.\rلا اختيار له: في أ الاختيار له، والمثبت من ط.\rفي ط: فإن.\rفي ط: بإرادته.\rفي أ: يمكن، والمثبت من ط.\rالزيادة من ط.\rفي أ: فالإرادة، والمثبت من ط.\rفي أ: يؤثر، والمثبت من ط.\r_______________\r1) في نهاية الإقدام في علم الكلام للشهرستاني ص 13: «واعتمد إمام الحرمين رضي الله عنه طريقة أخرى فقال: الأرض عند خصومنا محفوفة بالماء، والماء بالهواء والنار، والنار بالأفلاك، وهي أجرام متحيزة شاغلة جوا وحيزا، وبالاضطرار نعلم أن فرض هذه الأجسام متيامنة عن مقرها أومتياسرة، أوأكبر مما وجدت شكلا وعظما، أوأصغر من ذلك ليس من المستحيلات، وكل مختص بوجه من وجوه الجواز دون سائر الوجوه مع استواء الجائزات وتماثل الممكنات احتاج إلى مخصص بضرورة العقل»."], [133, "هذا الوجه 1.\rفإذا فسد القول بقدم العالم، مع ظهور الجواز في أحكامه من غير موجب ومؤثر، بطل كونه قديما عن موجب قديم، واستحال استناده مع قدمه إلى إرادة، لم يبق إلا القطع بأن العالم فعل موقع على وجه [دون وجه] من وجوه الجواز بإرادة مؤثر مختار، أوقعه على مقتضى مشيئته.\rوهذا الفصل في إثبات حدث العالم، أنجع وأوقع من طرق حوتها مجلدات، وهوخير لفاهمه من الدنيا بحذافيرها، لوساوقه التوفيق.\r_______________\rفي ط: مؤثر وموجب.\rفي ط: وبطل.\rالزيادة من ط.\rفي ط: وأرفع.\rفي أ: بحذاريفها.\r_______________\r1) انظر مثل هذا الدليل في الإرشاد للجويني ص 28، 29، ومعالم أصول الدين للرازي ص 42، والغنية في أصول الدين للمتولي ص 58، 59.\r(1/ 130)"], [134, "فصل: في ترتيب تراجم العقائد بعد تمهيد حدث العالم\r"]], "pg": [129, 134]}, "474.11": {"x": [[134, "محصول الكلام بعد ذكره، تحصره ثلاثة أبواب، ثم ينقسم كل باب فصولا:\r\r"]], "pg": [134, 134]}, "474.12": {"x": [[134, "باب: في العلم بأحكام الإله.\r"]], "pg": [134, 134]}, "474.13": {"x": [[134, "وباب: في مناط التكليف من صفات العباد.\r\rوباب: في النبوات التي بها تتصل الأوامر التكليفية بالعباد، وبها ترتبط الأمور السمعية في الحشر والنشر، والوعد والوعيد، المشعرين بالثواب والعقاب، إلى غيرهما مما أشاعه المرسلون، وأخبر عنه الصادقون، تنتجز قواعد الدين بنجاز هذه الأبواب.\rثم الإمامة: ليست من العقائد، ولوغفل عنها المرء لم تضره، ولكن جرى الرسم باختتام علم التوحيد بها، ونحن نذكر منها طرفا إن شاء الله، مع إيثار الاختصار والاقتصار على ما فيه مقنع وبلاغ، يشفي الغليل، ويوضح السبيل، إن شاء الله عز وجل 1.\r_______________\rفي ط: باب.\rفي الأصل: الخير والشر، وما أثبته من ط.\rفي أ: المفسرين، وما أثبته من ط.\rفي ط: أنبأ عنه المرسلون.\rفي ط: به.\rفي ط: وتجتاز.\rفي ط: مجاز.\rإن شاء الله: ليست في ط.\rعز وجل: ليست في ط.\r_______________\r1) لكن المؤلف رحمه الله عدل عن ذلك، ولم يتطرق إلى الإمامة في كتابه هذا، واعدا"], [135, "باب في الإلهيات\r"]], "pg": [134, 135]}, "474.14": {"x": [[135, "نصدر هذا الباب قبل تفصيله بإثبات العلم بالصانع المختار فنقول:\rإذا ثبت حدث العالم، ووجب افتقاره إلى موقع يوقعه على ما هوعليه، واستحال وقوعه بنفسه، لم يخل موقعه؛ إما أن يكون موجبا لا إيثار له، أويكون مختارا.\rوباطل أن يكون موجبا لا إيثار له، فإنه لا يخلو؛ إما أن يكون قديما، أوحادثا، فإن كان قديما، وجب قدم موجبه وأثره، واستحال تخصص أثره بوقت دون وقت، وقد اتضح مما سلف حدث العالم.\rوإن كان موجبه/حادثا، افتقر هوإلى موقع، ويتسلسل القول فيه إلى أعداد غير متناهية، وهذا يستحيل ببداهة العقول. وما يتسلسل لا يتحصل، ومن أثبت حوادث منفصلة لا نهاية لها إلى غير أول، فقد جمع بين في ط: انتهاؤنا.\r_______________\rفي ط: من.\rفي أ: للإيثار، والمثبت من ط.\rإما: ليست في ط.\rفي ط: وتسلسل.\rفي ط: وهوالمستحيل.\rفي أ: ببداية.\rفي ط: تسلسل.\rفي ط: مفصلة.\r_______________\r1) -نظام الملك بأن يفرد لها كتابا مستقلا يذكر فيه المسائل المتعلقة بها والأحكام السلطانية، وفعلا فقد ألف الجويني كتاب غياث الأمم في التياث الظلم، وسماه البعض بالإمامة الكبرى، وقد صدر الكتاب أولا في مصر، ثم قام بنشره عبد العظيم الديب نشرة علمية، إذ اعتمد في ذلك على أربع نسخ مخطوطة لهذا المؤلف النفيس، وصدر الكتاب في قطر سنة 1400 ه‍، وانظر التعليق عليه أيضا في مؤلفات الجويني ص 67."], [136, "الحدوث والحكم بالقدم 1.\rومن انتهى معتقده إلى إثبات حوادث أزلية، فقد انسل عن مقتضى العقول، فإن مقتضى الحوادث الابتداء عن عدم، والأزل يشعر بنفي الأولية، فبطل أن يكون موقع العالم موجبا لا إيثار له، ووجب القول بصانع مختار مريد وقع العالم على موجب مشيئته.\rولاح بما قدمناه وجوب قدمه، إذ لوكان صانع العالم محدثا، لافتقر إلى محدث، افتقار العالم إليه، ثم ينجر القول إلى ما سبق وضوح استحالته 2.\r_______________\rفي ط: علمه.\rفي ط: حكم.\rفي ط: ببقاء الأزلية.\rفي ط: فقد بطل.\rفي أ: مريدا.\rفي ط: قد أوقع.\rفي ط: حادثا.\r_______________\r1) انظر ذلك أيضا في التمهيد للباقلاني ص 45، والشامل للجويني ص 145، والإرشاد له ص 28، والغنية ص 64، 65، والمحصل للرازي ص 121، وغاية المرام للآمدي ص 72.\r2) الطريق الذي سلكه المتكلمون في إثبات الصانع، هوأنهم استدلوا أولا على حدوث العالم وإمكانه، فكل ما هومحدث ممكن لا بد له من محدث أحدثه على هيئته دون غيرها، أما بيان حدوث العالم فذلك لأنه مركب من جواهر وأعراض وهي من الممكنات، ذلك أن هذه الجواهر اختصت بأعراض دون أخرى، وهذا يوجب احتياجها إلى مخصص، وكل ما يحتاج إلى مخصص فهوممكن، وكل ممكن حادث، وكل حادث له محدث، لأن كل محدث جائز الوجود لذاته، لأنه كان قبل وجود معدوما، ومن يتساوى فيه الوجود والعدم يقتصر إلى المحدث المؤثر، ولا يمكن أن يكون هذا المؤثر أمرا داخليا وإلا لزم أن يكون علة لنفسه وهذا ممتنع، فيترتب على هذا أن يكون المحدث المؤثر خارجا عن جميع مجموع المحدث (العالم)، وبالتالي يجب انتهاء جميع الممكنات (المحدثات) إلى موجود واجب لذاته. انظر في ذلك: اللمع للأشعري ص 82، ومجرد مقالات الأشعري ص 37، والتمهيد للباقلاني ص 45، وأصول الدين للبغدادي ص 69."], [137, "فإذا تمهد صدر الباب، فالكلام بعده ينقسم ثلاثة أقسام:\rقسم في ذكر ما يستحيل على الله سبحانه.\rوقسم فيما يجب لله سبحانه.\rوقسم فيما يجوز [في] أحكامه.\rفآلت مدارك الإلهيات إلى الاستحالة والوجوب والجواز، كما سبق في صدر هذا المعتقد.\r--------------------\rسبحانه: ليست في ط.\rسبحانه: ليست في ط.\rالزيادة من ط.\rفي أ: والجواب فيما سبق، والمثبت من ط."], [138, "["]], "pg": [135, 138]}, "474.15": {"x": [[138, "القسم الأول]\rالكلام فيما يستحيل على الله عز وجل\rنقدم قولا وجيزا يحوي الغرض، فإن رأيناه كافيا، اجتزينا به، وإن رأينا أن نبسط طرفا من الكلام، جرينا فيه على ما تجري به المقادير، والله سبحانه ولي التيسير.\rفنقول: كل صفة في المخلوقات دل ثبوتها على مخصص يؤثرها ويريدها، ولا يعقل ثبوتها دون ذلك، فهي مستحيلة على الإله، فإنها لوثبتت له، لدلت على افتقارها إلى مخصص دلالتها في حق المحدث المخلوق 1.\rوضبط القول في الصفات المفتقرة: ما تمهد أولا من تقدير حكم الجواز، فكل صفة فارقها الجواز، فهي مستحيلة في نعت الإله تعالى، فإن القدم والجواز متناقضان.\rوتفصيل ذلك: إن الحدوث فينا منعوت بالجواز، فيقدس الإله عنه، والتركيب، والتصور، والتقدر في صفاتنا، موسومة بالجواز، فلا تركب، سبحانه: ليست في ط.\r_______________-------\rفي أ: من.\rفي ط: الله تعالى.\rفي ط: افتقاره.\rفي أ: الحارث.\rفي ط: فتقدس.\rفي ط: والتركيب.\rفي ط: والتقدر والتصور.\rفي ط: مرسومة.\r----------------------\r1) انظر ذلك مطولا في الإرشاد ص 34، وانظر أيضا الإنصاف للباقلاني ص 28، 29، والتمهيد له ص 44، والغنية للمتولي ص 80، 81، ونهاية الإقدام للشهرستاني ص 103."], [139, "139 ولا يجوز فرض خلافه. فلا قد، ولا قدر، ولا حد، ولا طول، ولا عرض، إلا والعقل يجوز/أمثالها وخلافها.\rوهذه الصفات لجوازها، افتقرت إلى تخصيص بارئها، فتعالى الصانع عنها، وهذا معنى قول سيد البشر، خاتم النبيين صلى الله عليه وسلم، إذ قال: «من عرف نفسه عرف ربه» 1. أراد من عرف نفسه بصفات الافتقار، عرف استغناء الرب عن صفاته، فإنه تقدست أسماؤه مستكفي الحاجة، وهوبريء عنها.\rوعلى هذا الأصل، يجب تقدس صانع العالم عن الاختصاص ببعض الجهات، فإن العقل قاض بجواز الكون في جهة دون أمثالها، كما يقضي بجواز التصور والتقدر، ثم لزم انتفاء الاختصاص بالأقدار عن ذاته، من حيث كانت جائزة، والتخصص بالجهات والأقطار في قضية الجواز، كالاختصاص بالأقدار 2.\r*-----------------------*\rفي أ: الخلافة، والمثبت من ط.\rقذ: ليست في ط.\rفي ط: ولا حد ولا قدر.\rفي ط: مفتقرة.\rخاتم النبيين: ليست في ط.\rفي ط: عليه السلام.\rإذ قال: ليست في ط.\rبصفات: ليست في ط.\rفي ط: بالافتقار.\rفي أ: استغنى، والمثبت من ط.\rفي ط: الرب تعالى.\rفي ط: أسماؤه من أن تنتهي إلى الحاجة.\r________________________\r1) في المقاصد الحسنة للسخاوي ص 657، قال أبوالمظفر السمعاني: إنه لا يعرف مرفوعا، وإنما يحكى عن يحيى بن معاذ الرازي يعني من قوله، وكذا قال النووي: إنه ليس بثابت، وقيل في تأويله: من عرف نفسه بالحدوث عرف نفسه بالقدم، ومن عرف نفسه بالفناء عرف ربه بالبقاء. وفي كشف الخفاء للعجلوني ج 2 ص 361: قال ابن تيمية: موضوع، وقال ابن الغرس: كتب الصوفية مشحونة به، يسوقونه مساق الحديث، كالشيخ محيي الدين بن عربي وغيره، وأنه رواه من طريق الكشف. وللسيوطي مؤلف في حديث من عرف نفسه فقد عرف ربه وهومتضمن بالحاوي للفتاوى، وفي أدب الدنيا والدين للماوردي ص 65 عن عائشة: سأل النبي صلى الله عليه وسلم: من أعرف الناس بربه قال: «أعرفهم بنفسه».\r2) وترى الأشاعرة، أن الله تعالى متقدس عن الاختصاص بالجهات، والاتصاف بصفات ="], [140, "وهذا مزلة الأقدام، ومثار ضلال الأنام، وعنده افترق جماهير الخلق فرقتين، وثبتت الفرقة المحقة الناجية. ولا بد من التنبيه على سبب الافتراق، وإيضاح ما استحث أهل الحق على الثبات، واجتناب الشتات.\rفذهبت طوائف إلى وصف الرب بما تقدس في جلاله عنه عن التحيز بالجهة، حتى انتهى غلاة إلى التشكيك، أوالتمثيل، تعالى الله عن قول الزائغين 1.\r-------------\rفي ط: فهذا.\rفي ط: فهذا.\rفي ط: الناجية المحقة.\rفي ط: فلا.\rفي ط: من.\rفي أ: بالجهالة، وفي ط: في الجهة.\rفي ط: التشكيل والتمثيل.\r--------------\r=-المحدثات، وكذلك لا يوصف بالتحول والانتقال، ولا القيام ولا القعود، لقوله تعالى: ليس كمثله شيء وقوله تعالى: ولم يكن له كفوا أحد (4) ولأن هذه الصفات تدل على الحدوث، والله تعالى يتقدس عن ذلك. انظر الإنصاف للباقلاني ص 36، والإرشاد للجويني ص 39، والغنية لأبي سعيد المتولي ص 74، وأصول الدين للبغدادي ص 73، وأساس التقديس للرازي ص 16\r1) من هذه الطوائف: الهشامية من الروافض أتباع هشام بن الحكم، وزعموا أن معبودهم سبعة أشبار بشبر نفسه، وأنه جسم ذوحد ونهاية، وأنه طويل عريض عميق. ومنهم الهشامية أتباع هشام بن سالم الجواليقي، الذي زعم أن معبوده على صورة الإنسان ولكنه ليس بلحم ولا دم، بل هونور ساطع بياضا. ومن المجسمة أيضا الكرامية: أتباع أبي عبد الله محمد بن كرام، الذي زعم أن الله-تعالى عن قوله- جسم له حد ونهاية من تحته، والجهة التي منها يلاقي عرشه، وأن الله مماس لعرشه وأن العرش مكان له. ومنهم البيانية: أتباع بيان بن سمعان، الذي زعم أن معبوده إنسان من نور على صورة الإنسان في أعضائه، وأنه يفنى كله إلا وجهه. ومنهم المغيرية: أتباع المغيرة بن سعيد العجلي الذي زعم أن معبوده ذوأعضاء، وأن أعضاءه على صور حروف الهجاء ومنهم الجوارية: أتباع داود الجواري الذي وصف معبوده بجميع أعضاء الإنسان إلا الفرج واللحية. انظر في هذه الفرق، وفرق المجسمة: الفرق بين الفرق للبغدادي ص 48، 202، 214، والتبصير في الدين للإسفراييني ص 42، 99، 116، ومقالات الإسلاميين للأشعري ص 31 - 33، 34، واعتقادات فرق المسلمين للرازي ص 96، وانظر أيضا التجسيم عند المسلمين «مذهب الكرامية» لسهير مختار.\r\r."], [141, "والذي دعاهم إلى ذلك، طلبهم ربهم من المحسوسات، وما يتشكل في الأوهام، ويتقدر في مجاري الوساوس، وخواطر الهواجس. وهذا حيد بالكلية عن صفات الإلهية، وأي فرق بين هؤلاء، وبين من يعبد بعض الأجرام العلوية!.\rولواجتمع الأولون والآخرون على أن يدركوا بهذا المسلك الروح- وهوخلق الله تعالى-لم يجدوا إليه سبيلا، فإنه معقول غير محسوس، وقد قال تبارك وتعالى في محكم كتابه، الذي لا يأتيه الباطل من بين يديه ولا من خلفه: ويسئلونك عن الروح قل الروح من أمر ربي وم?ا أوتيتم من العلم إلا? قليلا (85) 1.\rوذهبت طائفة إلى التعطيل 2، من حيث تقاعدت عقولهم عن درك حقيقة في ط: طلبتهم.\r--------------------\rفي أ: لهذا، والمثبت من ط.\rتبارك وتعالى: ليست في ط.\r-------------------\r1) سورة الإسراء، الآية 85.\r2) التعطيل: مصطلح فني كلامي وضعه أهل السنة لبيان موقف المعتزلة وأسلافهم من الصفات الإلهية، ومعناه نفي الصفات القديمة القائمة بالذات، وأول من عطل ونفى الصفات عن الذات الإلهية الجعد بن درهم (- 124 ه‍)، وعنه أخذ هذه المقالة الجهم بن صفوان (- 128 ه‍)، ولما ظهرت المعتزلة سارت على خطى الجهمية في نفي الصفات فقالوا: إن الله عالم بذاته، قادر بذاته، حي بذاته، لا بعلم وقدرة وحياة كصفات قديمة ومعان قائمة به، لأنه لوشاركت هذه الصفات الذات في القدم الذي هوأخص وصف لها، لشاركته في الألوهية وتعددت الآلهة. أي أن المعتزلة لا تنكر الصفات كوجوه واعتبارات عقلية كذات واحدة، ولكنها تنكر إثبات صفات هي ذوات موجودات أزلية قديمة قائمة بذات الله تعالى، وقد عرفت المعتزلة الله باللائية، أي وصفه بصفات السلب لنفى كل تصور بشري عن الذات، ومرجعهم في ذلك قوله تعالى: ليس كمثله شيء.\rانظر في ذلك: مقالات الإسلاميين للأشعري ص 155، 164، 165، 494، وشرح الأصول الخمسة للقاضي عبد الجبار ص 160 - 168، والفرق بين الفرق ص 93، 94، والتبصير في الدين للإسفراييني ص 60، 96، 97، والملل والنحل للشهرستاني ص 44، ونهاية الإقدام ص 199، والمعتزلة لجار الله ص 69، 71، 72."], [142, "الإله، وظنوا أن ما لا يحويه الفكر منتف. ولووفقوا، لعلموا أنه لا/تبعد معرفة موجود مع العجز عن درك حقيقته.\rوالذي ضربناه في الروح مثلا، يعارض به هؤلاء، فليس لوجود الروح خفاء، وليس إلى درك حقيقته سبيل، ولا طريق إلى جحد وجوده، للعجز عن درك حقيقته.\rوالأكمه، يعلم بالتسامع والاستفاضة الألوان، ولا يدرك حقيقتها، فهذا سبب زيغ المعطلة، وهم على مناقضة المشبهة.\rوأما فئة الحق، فهدوا إلى سواء الطريق، وسلكوا جدد التحقيق، وعلموا أن الجائزات تفتقر إلى صانع لا يتصف بالصفات الدالة على الافتقار، وعلموا أنه لواتصف الصانع بها، لكان شبيها بمصنوعاته. ثم لم يميلوا إلى النفي من حيث لم يدركوا حقيقة الإله، ولم يبعدوا وجود موجود يجب القطع بكونه، مع العجز عن درك حقيقته، إذ وجدوا في ذهنهم مخلوقا 1 لم يستريبوا في وجوده، ولم يدركوا حقيقته.\rونحن الآن نذكر عبارة حرية بأن يتخذها مولانا في هذا الباب هجيراه 2، فهي لعمري المنجية في دنياه وأخراه، فنقول: من انتهض لطلب مدبره، فإن اطمأن إلى موجود انتهى إليه فكره، فهومشبه. وإن اطمأن إلى.\r----------------\rفي ط: معرفته بوجود\rفي أ: عن ذلك حقيقة.\rكتبت في أ: هاولاى، وهكذا درج الناسخ في كتابة هذه الكلمة.\rفي ط: بوجود.\rفي أ: والأمة تعلم.\rفي ط: بالسماع.\rفي أ: هدوا.\rفي أ: لمصنوعاته، والمثبت من ط.\rفي أ: أن، والمثبت من ط.\rفي أ: يبعدوا موجودا، والمثبت من ط.\rفي أ: بلونه، والمثبت من ط.\rفي أ: أو، والمثبت من ط.\rفي أ: اهنهم، والمثبت من ط.\rفي ط: إلى طلب.\r---------------\r1) يقصد الجويني بالمخلوق هنا: الروح التي سبق أن ضرب بها المثل.\r2) هجيراه: دأبه وشأنه."], [143, "النفي المحض، فهومعطل. وإن قطع بموجود، واعترف بالعجز عن درك حقيقته، فهوموحد. وهومعنى قول الصديق رضي الله عنه إذ قال: العجز عن درك الإدراك إدراك.\rفإن قيل: فغايتكم إذن حيرة ودهشة.\rقلنا: العقول حائرة في درك الحقيقة، قاطعة بالوجود المنزه عن صفات الافتقار. وهذا ما أردناه في هذا الفن، وقد تجاوزنا الحد المعزوم عليه قليلا.\r------------------\rفي أ: موجود، والمثبت من ط.\rإذ قال: ليست في ط.\rفي أ: المعجز عن ذلك.\rمن قوله: فإن اطمأن إلى موجود. . . إدراك، وردت في قطعة مخطوطة بمكتبة برلين برقم 1946، وسميت خطأ بعقيدة السلف للشيرازي.\rوالمقارنة الدقيقة تبين أنها جزء من العقيدة النظامية لإمام الحرمين وليست من عقيدة السلف للشيرازي.\rفي أ: وقايتكم إذا.\rمن قوله: وهذا ما أردناه. . . قليلا، ليست في ط."], [144, "["]], "pg": [138, 144]}, "474.16": {"x": [[144, "القسم الثاني]\rالكلام فيما يجب لله تبارك وتعالى\rمن أحاط بالصفات الجائزة للمخلوقات، أرشدته إلى ما يجب لصانعها وبارئها من الصفات، فدل جواز الحوادث، على وجوب وجود صانعها، فإن الجائز لا يقع بنفسه-كما سبق-ولا يتصف وجود صانعه بالجواز، فإنه/لوكان جائزا، لا فتقر افتقار صنعه، وقد تقرر تقدير ذلك 1.\rثم يدل جواز الحادثات على كون بارئها قادرا، فإنا على الاضطرار، نعلم أن المؤثر الفعال، يجب أن يكون مقتدرا على فعله، ويجب أن يكون مريدا له، فإن القدرة لا توقع الفعل لعينها، بل يفعل القادر بالقدرة متى أراد 2.\rثم يستحيل أن يريد ما لا يعلمه 3، ثم يستحيل الاتصال بهذه الصفات دون الاتصاف بالحياة، فلاح أن جواز الصفات الثابتة للحوادث، دال على وجوب هذه الصفات للصانع 4.\r-------------------\rفي ط: من المخلوقات.\rفي أ: تكرر، والمثبت من ط.\rفي أ: في، والمثبت من ط.\rفي ط: اضطرار.\rفي ط: للمقادر، والمثبت من ط.\rفي ط: الصفة الثانية للحوادث دال.\r--------------------\r1) انظر مثل هذا الدليل في لمع الأدلة للجويني ص 93، والإرشاد له ص 32، والتمهيد للباقلاني ص 45، والإنصاف ص 29، والاقتصاد في الاعتقاد للغزالي ص 13، ونهاية الإقدام للشهرستاني ص 170.\r2) ذلك أن الإرادة تخصص أمرا ما لحصوله ووجوده، كما في قوله تعالى: إنم?ا أمره إذ?ا أر?اد شيئا أن يقول له كن فيكون (82). والقدرة هي الصفة التي تمكن الحي من إنجاز الفعل المراد.\r3) واتفق المتكلمون عامة على أن ركائز الفعل ووقوعه هي: العلم والإرادة والقدرة. انظر كتاب إثبات القدر (مقدمة المحقق) ص 122.\r4) انظر ذلك أيضا في الإرشاد للجويني ص 61 - 63."]], "pg": [144, 144]}, "474.17": {"x": [[145, "فصل\r[في الحياة والعلم والقدرة]\r\rاعترف كل من انتمى إلى الإسلام، بكونه تعالى حيا 1 عالما 2\r---------------------------\rلم يضع المؤلف عنوانا لهذا الفصل وبعض الفصول القادمة، فوضعت عناوين لها اجتهادا.\r_________________________\r1) صفة الحياة عند الأشاعرة هي صفة ذات أزلية قديمة، لا يجوز أن يوصف الباري عز وجل بضدها، فالله تعالى حي بحياة زائدة على ذاته قائمة به، ولا يقال إن الحياة هي المسمى ولا إنها غير المسمى، فهي كبقية الصفات الذاتية التي استحقها الله تعالى فيما لم يزل ولا يزال، وطريق ثبوتها العقل والسمع، فالعقل يحيل صدور الأفعال ممن لا يتصف بالحياة، والله تعالى خالق الأشياء وفاعلها، فوجب أن يكون حيا، أما الأدلة السمعية فهي كثيرة كقوله تعالى: لا? إل?ه إلا? هوالحي القيوم وقوله: وعنت الوجوه للحي القيوم. انظر في ذلك: اللمع للأشعري ص 87، والإنصاف للباقلاني ص 31، والتمهيد ص 45، والاعتقاد للبيهقي ص 61، وأصول الدين للبغدادي ص 105، والغنية للمتولي ص 86، والإرشاد للجويني ص 72، والاقتصاد في الاعتقاد للغزالي ص 47، وإحياء علوم الدين للغزالي ص 155، ومعالم أصول الدين للرازي ص 59، والأربعين له ص 154، والمطالب العالية ج 3 ص 217.\r2) ترى الأشاعرة أن علم الله محيط بكل شيء حاضرا كان أوماضيا أومستقيلا، ويتعلق بجميع المعلومات الواجب منها والجائز بل والمستحيل أيضا، وهوعلم واحد قديم لا تتجدد له صفة، ولا يتعاقب عليه حال، لأن القديم لا يطرأ عليه التغيير، ووظيفة العلم أن يدرك المعلوم على ما هوعليه من غير أن يكسبه أويكتسب منه صفة، والمعلومات إنما تختلف لذاتها لا بتعلق العلم بها، وتعلق العلم بها لا يؤدي إلى اختلافه باختلافها، والعلم عند الأشاعرة صفة ذات فهوعالم بعلم. انظر اللمع للأشعري ص 88، 89، والتمهيد للباقلاني ص 46، 48، والإرشاد ="], [146, "قادرا 1. ثم نفى العلم والحياة والقدرة طوائف 2، وطال النزاع في ذلك بين الفرق، وتفاقم الخطب، وانتهى غالون إلى التكفير والتبريء.\rوالقول في ذلك [قريب] المدارك عندنا، فنقول: إذا وصفتم الباري تعالى وتقدس بكونه قادرا حيا عالما، فلا معنى للعلم إلا كون العالم عالما.\rفإن اعترفتم بكونه عالما، فلا معنى للعلم إلا أن يكون العالم عالما، وإن اعترفتم بكونه عالما، فهوالعلم بعينه، فسبحان من أغوى أمما في اعتقاد نفي العلم.\r--------------\rفي ط: والقدرة والحياة.\rفي ط: الغالون.\rالزيادة من ط.\rتعالى وتقدس: ليست في ط.\rمن قوله: فإن اعترفتم. . . عالما، ليست في ط.\rفي ط: فإذا.\r__________________________\r=للجويني ص 61، 62، ولمع الأدلة ص 94، وأصول الدين للبغدادي ص 95، والاقتصاد للغزالي ص 47، والملل والنحل للشهرستاني ص 120، ونهاية الإقدام ص 295، والأشعري لحمودة غرابة ص 105، ونشأة الأشعرية لجلال موسى ص 218\r\r1) صفة القدرة هي من الصفات الإيجابية كالحياة والعلم، على معنى إنها صفات وجودية زائدة على ذاته، وقدرة الله عامة تعم كل المقدورات بما فيها أفعال الإنسان الإرادية، ودليل الأشاعرة على صفة القدرة، هوأن الله تعالى «لوكان لم يزل حيا غير قادر لوجب أن يكون لم يزل عاجزا موصوفا بضد القدرة، ولوكان عجزه قديما لاستحال أن يقدر وأن تحدث الأفعال منه»، والأشاعرة إجمالا تعتقد أن صفات الذات كالحياة والعلم والقدرة والإرادة لا يجوز أن يقال هي هو، ولا هوهي، ولا هوغيرها، ولا هي غيره، لأنها لوكانت هي هولكانت الصفة الواحدة موصوفة بجميع الصفات الأخرى، والصفة لا تقوم بالصفة. انظر التمهيد للباقلاني ص 49، والإنصاف ص 31، والإشارة إلى مذهب أهل الحق للشيرازي ص 234، والاقتصاد للغزالي ص 38، والغنية للمتولي ص 85.\r2) وهم الباطنية الذين قالوا: إنا لا نقول إن الباري هوموجود، ولا لا موجود، ولا عالم ولا جاهل، ولا قادر ولا عاجز، وكذلك في جميع الصفات، إذ إن الإثبات الحقيقي يقتضي في نظرهم شركة بين الخالق ومخلوقاته، وذلك تشبيه، لذا قيل فيهم إنهم نفاة الصفات حقيقة، معطلة الذات عن جميع الصفات. انظر الملل والنحل للشهرستاني ص 192،193، والإرشاد للجويني ص 37."], [147, "وما اعترفوا به من كونه عالما، هوعين ما أنكروه، فلا معنى للعلم إلا كون العالم [عالما] بمعلوماته على ما هي عليها.\r---\rالزيادة من ط.\rفي ط: ما هوعليه."], [148, "فصل\r[في الإرادة]\r"]], "pg": [145, 148]}, "474.18": {"x": [[148, "الصانع لم يزل مريدا 1 في أزله، كما سيكون فيما يزال، وكونه مريدا عين إرادته.\rوضلت طائفة من المبتدعة ضلالا بعيدا 2، فزعموا أنه لم يكن مريدا في أزله، ثم أحدث لنفسه فيما يزال، إرادات للكائنات التي يريدها، فصار مريدا بتلك الإرادات الحادثة 3.\r---------------\rفي أ: آزاله لما، وما أثبته من ط.\rفي ط: لا يزال.\rفي أ: آزاله، والمثبت من ط.\r___________________\r1) الإرادة عند الأشاعرة صفة ذاتية قديمة، وأن الله لم يزل مريدا بها، ودليلهم على قدم الإرادة، هوأنها «لوكانت محدثة لأحدثها في نفسه أوفي غيره أوتقوم بنفسها، ويستحيل أن يحدثها في نفسه، لأن نفسه ليست محلا للحوادث، ويستحيل أن تقوم بنفسها لأنها صفة، والصفة لا تقوم بالصفة، ويستحيل أن يحدثها في غيره لأن ذلك يوجب أن يكون هذا الغير مريدا بإرادة الله، فلما استحالت هذه الوجوه التي لا تخلومنها الإرادة لوكانت محدثة، صح وثبت أنها قديمة، وأن الله لم يزل مريدا بها». انظر اللمع للأشعري ص 10، والإرشاد للجويني ص 94، 95، والغنية للمتولي ص 95، والاقتصاد للغزالي ص 50، ونهاية الإقدام للشهرستاني ص 240، ومعالم أصول الدين للرازي ص 63.\r2) وقد سماهم الجويني في الإرشاد ص 64، 94 فقال: «وذهب بعض معتزلة البصرة إلى أن الباري تعالى مريد للحوادث بإرادة حادثة لا في محل، وزعموا أن كل حادث من أفعاله مرادا له بإرادة حادثة، وكل مأمور به من أفعال العباد مرادا له، ولا تتعلق إرادة واحدة بمرادين عندهم، ثم الإرادات تقع حادثة غير مرادة».\r3) انظر قول المعتزلة في إرادة الله الحادثة وردهم على من قال بالإرادة القديمة، شرح"], [149, "وهذا انسلال عن ربقة الدين، فإن الإرادة لوكانت حادثة، لافتقرت إلى إرادة لها بها تتخصص، وإن استغنت وهي حادثة مختصة عن مخصص؛ لزم استغناء العالم بما فيه عن مريد مخصص 1.\r------------\rفي ط: تختص وإذا.\rفي أ: تخصص.\r_______________________\r=الأصول الخمسة للقاضي عبد الجبار ص 440 - 454، والمغني في التوحيد والعدل ج 6 ص 137 - 149.\r\r1) وفي الإرشاد ص 94: «إن إرادته لوكانت حادثة لافتقرت إلى تعلق إرادة بها، فإن كل فعل ينشئه الفاعل وهوعالم به وبإيقاعه على صفة مخصوصة في وقت مخصوص، فلا بد أن يكون قاصدا إلى إيقاعه، ونفي القصد إلى إيقاع فعل مع العلم به، يلزم صاحبه نفي المقصود إلى إيقاع جميع الأفعال»."], [150, "فصل\rمما يجب لله تعالى: الاتصاف بالكلام "]], "pg": [148, 150]}, "474.19": {"x": [[150, "1\rوقد تقطعت المهرة في إثبات العلم بوجوب وصف/الباري سبحانه بالكلام، وهوخارج عن القاعدة التي هي مستند هذه العقيدة فنقول:\rكما نعلم بعقولنا، أن تردد الخلق على صنوف التغاير من الجائزات،.\r-------------------------------\rفي ط: المرة\rفي ط: الله تعالى.\rفي أ: على، وما أثبته من ط.\rفي ط: ضروب المقادير.\r___________________________\r1) يرد الجويني في هذا الفصل على الجهمية والمعتزلة الذين قالوا بخلق القرآن، وأول من قال بأن القرآن مخلوق هوالجعد بن درهم نزيل دمشق، فزعم أن الله لم يكلم موسى تكليما ولم يتخذ إبراهيم خليلا، فقتله صلبا خالد بن عبد الله القسري أمير بني أمية، ويقال: إن الجهم بن صفوان أخذ عن الجعد مقالته بخلق القرآن، واستمر القول بخلق القرآن مع المعتزلة بمدرستيها البصرية والبغدادية، ثم عمل المعتزلة على جعل هذا الاعتقاد، مذهبا للسلطة السياسية العباسية ممثلة بشخص الخليفة المأمون، وأخذوا يمتحنون العباد في ذلك، فتعرض الإمام أحمد بن حنبل للمحنة نتيجة تحديه للقول بخلق القرآن، وبالإجمال فقد قام أهل السنة فقهاء ومحدثين ومتكلمين بالتصدي للجهمية والمعتزلة وبينوا في كتبهم فساد هذا القول. انظر في ذلك: الملل والنحل للشهرستاني ص 87، والرد على الجهمية لأحمد بن حنبل ص 120، وشرح أصول السنة للخلال ج 3 ص 365، والكامل في التاريخ لابن الأثير ج 5 ص 104، وتاريخ الإسلام للذهبي، وفيات (101 - 120) ص 337، 338، وحوادث (121 - 140) ص 65، والبداية والنهاية لابن كثير ج 9 ص 350، والفتاوى لابن تيمية ج 5 ص 20، ومنهاج السنة ج 1 ص 84، ولسان الميزان لابن حجر العسقلاني ج 2 ص 105، 142، والخطط للمقريزي ج 4 ص 182 - 184، والمعتزلة لزهدي جار الله ص 70، 83، وفجر الإسلام لأحمد أمين ص 287، ونشأة الأشعرية لجلال موسى ص 99، وأحمد بن حنبل والمحنة لولتر باتون."], [151, "فكذلك تصرفهم تحت أمر مطاع، ونهي متبع، ليس من المستحيلات. وإذا قطع العقل بجواز ذلك، كما قضى بجواز جريان الخلائق على اختلاف الأحوال والطرائق، فكل جائز من صفات الخلق يستدل [به] إلى صفة واجبة للخالق، فيجب من جواز انسلاكهم في الأوامر والزواجر، اتصاف ربهم بالأمر، والنهي، والوعد، والوعيد، وهوالملك حقا.\rولا يتم وصف الملك دون الاتصاف بالاقتدار على تغيير الخلق قهرا، وإمكان توجه الأمر والنهي عليهم تعبدا وتكليفا، فتقرر بذلك وجوب كونه تعالى وتقدس متكلما 1.\rوظن من لم يحصل علم هذا الباب، أن القدرية وصفوا الرب تبارك وتعالى بكونه متكلما، وزعموا أن كلامه مخلوق.\rوليس هذا مذهب القوم، بل حقيقة معتقدهم، أن الكلام فعل من أفعال الله عز وجل، كخلقه الجواهر وأعراضها، ولا يرجع إلى حقيقة وجوده حكم من الكلام 2. فمحصول أصلهم: أنه ليس لله-تعالى عن في ط: قطع.\r---------------------\rفي ط: يستند.\rأضفتها اجتهادا.\rجواز: ليست في ط.\rفي أ: يوجبه، والمثبت من ط.\rفي ط: فيتقرر.\rتعالى وتقدس: ليست في ط.\rمن قوله: وظن من لم يحصل. . . متكلما، ليست في ط.\rعز وجل، ليست في ط.\rفي ط: فلا.\rفي أ: حقيقة وجود محكم الكلام.\r_________________________\r1) انظر دليلا مشابها ذكره الجويني في الإرشاد ص 73، وقارن ذلك بما ذكره الأشعري في اللمع ص 95.\r2) ما ذكره الجويني هنا أشارت إليه المعتزلة على وجه مخصوص، وهواتصال خلق القرآن بباب العدل، فيقولون: «ووجه اتصاله بباب العدل هوأن القرآن فعل من أفعال الله، يصح أن يقع على وجه فيقبح، وعلى وجه آخر فيحسن» شرح الأصول الخمسة للقاضي عبد الجبار ص 527، أما حقيقة مذهبهم فقد لخصه القاضي عبد الجبار بقوله: «وأما مذهبنا في ذلك، فهوأن القرآن كلام الله تعالى ووحيه، وهو-"], [152, "قولهم -كلام، وليس قائلا آمرا ناهيا، وإنما يخلق أصواتا في جسم من الأجسام دالة على إرادته 1.\rوليس يخفى على ذي بصيرة، أن آيات القرآن نصوص في اتصاف الرب تبارك وتعالى بالقول، فكم في سياق الآي من إخبار الرب عن نفسه بالاتصاف بالقول، كما قال تعالى: ق?ال الل?ه ه?ذ?ا يوم ينفع الص?ادقين صدقهم 2.\rوقال تبارك وتعالى: ي?ا ن?ار كوني بردا وسلا?ما 3. وقال جل وعز: وق?ال ربكم ادعوني أستجب لكم 4.\r-----------------------\rتعالى عن قولهم: ليست في ط.\rفي أ: من، والمثبت من ط.\rتبارك وتعالى، ليست في ط.\rمن قوله: وكم في سياق. . . تعالى، ليست في ط.\rتبارك وتعالى، ليست في ط.\rجل وعز، ليست في ط.\rأستجب لكم ليست في ط.\r____________________\r= مخلوق يحدث، أنزله الله على نبيه ليكون علما ودالا على نبوته، وجعله دلالة لنا على الأحكام لنرجع إليه في الحلال والحرام. . . وإذن هوالذي نسمعه اليوم ونتلوه، وإن لم يكن محدثا من جهة الله تعالى فهومضاف إليه على الحقيقة، كما يضاف ما ننشده اليوم من قصيدة امرئ القيس على الحقيقة وإن لم يكن محدثا لها من جهته الآن» شرح الأصول الخمسة ص 528.\r\r1) ذهب فريق من المعتزلة إلى أن كلام الله عرض من الأعراض، بينما ذهب الفريق الثاني إلى أنه جسم، ولا يخفى أن الأعراض أوالأجسام تتطلب محلا تقوم به، ولا يمكن أن يكون هذا المحل ذات الله تعالى، وإلا أصبحت هذه الذات محلا للحوادث، ولا يجوز أن يحدث الله كلامه لا في محل لأن ذلك يخالف طبيعة الأعراض والأجسام، فلا يبقى إلا أن يحدث الله كلامه في محل، وهذا المحل خارج عن ذاته، فيسمع هذا الكلام من هذا المحل، ثم اشترطوا أن يكون هذا المحل جمادا حتى لا ينسب هذا الكلام لمن به حياة. انظر المغني في التوحيد والعدل للقاضي عبد الجبار ج 16 ص 137، وشرح الأصول الخمسة ص 559، وانظر مقالات الأشعري لابن فورك ص 191 - 193، والمعتزلة لجار الله ص 85، 86.\r2) سورة المائدة، الآية 119.\r3) سورة الأنبياء، الآية 69.\r4) سورة غافر، الآية 60."], [153, "ومن لزم الإنصاف، وجانب الاعتساف، تبين أن هذه الآيات مصرحة باتصاف الرب بقوله، ومن أحدث أصواتا في جسم، دالة على غرض له، لا يقال [له]: قال كذا وكذا.\rومما يوضح الحق في ذلك، أن من أصل هؤلاء: أنه لا معنى لكون المتكلم متكلما، إلا أنه فاعل/للكلام 1.\rومساق هذا يقتضي، أن من لم يعلم كون المتكلم فاعلا لكلامه، لا يعلمه متكلما. ونحن على اضطرار، نعلم أن من نراه يتكلم متكلما، قبل أن يخطر ببالنا كونه فاعلا، ولولم يكن لكونه متكلما معنى إلا أنه فاعل للكلام، لما علمه متكلما من لم يعلمه فاعلا.\rوليس الأمر كذلك، فإن سبيل معرفة الله تبارك وتعالى متكلما، كسبيل معرفة المتحرك متحركا، ومن رأى جسما يتحرك، اعتقد أنه متحركا، ولم يتوقف عقده على النظر في أنه فاعل للحركة 2.\rكذلك من سمع رجلا [يتكلم] اعتقده متكلما، ثم نظر في كونه فاعلا للكلام أوغير فاعل، وإذا تقرر أن الكلام صفة للمتكلم، وليس المراد به كونه فاعلا، فما كان صفة لله تعالى، لم تخل؛ إما أن تكون حادثة،\r-------------------\rأوفي ط: الصيغ. في ط: الباري.\rالزيادة من ط. في ط: وسياق ذلك.\rفي ط: للكلام. في ط: أن نعلم كون ما نراه.\rفي أ: سبل. في ط: المتكلم.\rتبارك وتعالى: ليست في ط.\rفي أ: أوسبيل، والمثبت من ط.\rفي ط: متحركا. في ط: اعتقده.\rفي: ليست في ط. في ط: تحركه.\rالزيادة من ط. في أ: اعتقد، والمثبت من ط.\rفي ط: من.\r_______________________\r1) انظر استدلال المعتزلة على ذلك في شرح الأصول الخمسة للقاضي عبد الجبار ص 535 - 537.\r2) انظر رد المعتزلة على هذا الاعتراض في شرح الأصول الخمسة ص 536."], [154, "قديمة. فإن كانت قديمة، فهوالحق الذي انتحله أهل الحق.\rوإن كانت حادثة، لم تخل؛ إما أن تقوم به -تعالى الله عن قول المبطلين -فيؤدي هذا إلى القول بأنه محل للحوادث، وما قبل الحوادث [حادث] كالأجسام، وإما أن تقوم بجسم وهومذهب المخالف 1.\rفكل صفة قامت بجسم، رجع الحكم منها إلى ذلك الجسم، كالحركة والسكون وما عداهما من الأعراض، ولوكان الرب تعالى بخلق كلام في جسم متكلما، لكان بخلق الصوت فيه مصوتا 2.\r----------------\rفي أ: في أهل، والمثبت من ط. في ط: بالله تعالى.\rتعالى الله عن قول المبطلين: ليست في ط.\rفي أ: الحوادث. في ط: الحادث.\rالزيادة من ط. في ط: وكل.\rفي ط: الكلام. في أ: كلاما، والمثبت من ط.\r__________________\r1) انظر ص 152 هامش رقم 1.\r2) وترد المعتزلة على ذلك بقولها: «لوكان للمتكلم بكونه متكلما حال وصفه، لكان يجب أن يسبق العلم بتلك الحال قبل العلم بالكلام، كما في كونه عالما، فإن العالم لما كان له بكونه عالما حال، يسبق علمنا بكونه عالما على العلم بما يوجبه وهوالعلم، وكذلك في المتحرك، فإن المتحرك لما كان له بكونه متحركا حالة أوصفة، حصل العلم بكونه متحركا قبل العلم بالحركة، كذلك يجب مثله في مسألتنا، فكان يجب أن نعلم كون المرء متكلما وإن لم يخطر ببالنا الكلام، والمعلوم خلافه، فإنا ما لم نعلم تعلق الكلام به تعلق الفعل بفاعله، لم نعلم كونه متكلما» شرح الأصول الخمسة للقاضي عبد الجبار ص 536، 537."], [155, "فصل\r[معتقد أهل الحق في كلام الله تعالى]\r"]], "pg": [150, 155]}, "474.20": {"x": [[155, "ثم [من] معتقد أهل الحق، أن كلام الله تبارك وتعالى ليس بحروف منتظمة، ولا أصوات مقطعة، وإنما هوصفة قائمة بذاته [تعالى]، يدل عليها قراءة القرآن، كما يدل قول القائل: [الله]، على الوجود الأزلي، ويعتبر المسمى أصوات، والمفهوم منها الرب تبارك وتعالى 1.\rفإن قيل: إذا قضيتم بأن كلام الله تبارك وتعالى أزلي، لزمكم أن تصفوه بكونه [أزليا] آمرا ناهيا قبل وجود المخاطبين، وثبوت الأمر قبل وجود المأمورين محال 2.\r-----------------\rالزيادة من ط. تبارك: ليست في ط.\rفي ط: حروفا منظمة. في ط: أصواتا.\rالزيادة من ط. الزيادة من ط.\rفي ط: وتعبيره المعين. في ط: منه.\rتبارك: ليست في ط. الزيادة من ط.\rفي أ: المأمور وما أثبته من ط.\r_____________________\r1) فرقت الأشاعرة ما بين كلام الله النفسي وهوقديم ليس بحادث، وكلام الله المتعلق بالأمر والنهي والخبر وهوحادث، والكلام النفسي ليس بصوت ولا حرف وإنما هومعنى قائم بذات الله تعالى، يعبر عنه باللفظ، أما الحادث من الكلام فهوالحروف والأصوات. انظر الإشارة إلى مذهب أهل الحق للشيرازي ص 143، ومجرد مقالات الأشعري لابن فورك ص 59، والإرشاد للجويني ص 133، ونهاية الإقدام للشهرستاني ص 313، والأربعين للرازي ص 181، والإنصاف للباقلاني ص 98.\r2) انظر أيضا شرح الأصول الخمسة ص 554، وانظر هذا القول من المعتزلة ورد الجويني عليه في الإرشاد ص 119."], [156, "قلنا: ما لبس به المخالف، يدرأه ضرب مثال: وهوأن من يعزم على مفاوضة صاحب له بعد شهر، فالمعاني التي سيوردها/عند جريان الحوار، يجدها بأعيانها قائمة في نفسه، ثم إذا حان الوقت أداها وأنهاها [إليه].\rوالعالم بأنه سيكلم فلانا، لا تخلونفسه عن وجود معنى ذلك الكلام، على تقدير وجوده، ثم العبارات حين المفاوضة تبلغ تلك المعاني.\rوالرب في أزله، كان عالما بأن يتعبد عباده إذا وجدوا، وهوالعالم المقدس عن أن يسهو، أويهفو، فلا يخلووجوده الأزلي عن معنى ما سيصل إلى العباد إذا وجدوا 1.\rوسبيل ذلك الكلام القائم بنفسه، كسبيل قدرته القديمة ولم تزل، وإن كان يستحيل وجود مقدوراتها أولا، فإن المقدور حادث مستفتح، ولكنه كان منعوتا أزلا بصفة صالحة، لتعلق القدرة بالمقدورات فيما لا يزال 2.\r-----------------\rفي ط: مثل. في أ: معاوضة، والمثبت من ط.\rفي أ: والمعاني، والمثبت من ط. في ط: الحديث.\rالزيادة من ط. في أ: ثبوت، والمثبت من ط.\rفي أ: في، والمثبت من ط. في أ: من حين، والمثبت من ط.\rفي أ: المعاوضة، والمثبت من ط.\rفي ط: والله تعالى. في ط: و.\rفي ط: فسبيل. في ط: التي لم تزل.\r__________________________\r1) يرى الأشعري أن الكلام الأزلي لم يزل متصفا بكونه أمرا نهيا خبرا، والمعدوم مأمور بالأمر الأزلي على تقدير الوجود، والأمر القديم في نفسه على صفة الاقتضاء ممكن سيكون إذا كانوا. انظر مجرد مقالات الأشعري ص 65، 66، 67، والإرشاد للجويني ص 120، والمغني للمتولي ص 105.\r2) في الإرشاد ص 121: ثم الرب سبحانه في أزله كان قادرا، ومن حكم كون القادر قادرا أن يكون له مقدور، والمقدور هوالجائز الممكن، وإيقاع الأفعال في الأزل ="], [157, "فصل\r[معنى القول: بأن كلام الله تعالى مسموع]\r"]], "pg": [155, 157]}, "474.21": {"x": [[157, "يجب إطلاق القول: بأن كلام الله تبارك وتعالى مسموع، وليس المراد بذلك، تعلق الإدراك بالكلام الأزلي القائم بالباري تعالى، ولكن المدرك صوت القارئ، والمفهوم عند قراءته كلام الله سبحانه 1.\rولا يعد في تسمية المفهوم عند مسموع مسموعا، فهذا بمثابة ما لوبلغ مبلغ رسالة ملك، فيحسن ممن بلغته الرسالة أن يقول: سمعت [كلام] الملك ورسالته، وكلام الملك حديث نفسه وأصواته، ومن بلغ الرسالة، لم ينقل صوت مرسله، ولا حديث نفسه.\rومن زعم أنه يسمع كلام الله تعالى من غير واسطة، فلا فرق بينه وبين في ط: تعالى.\r--------------------\rفي ط: وهذا. الزيادة من ط.\rفي ط: ورسالاته.\r_______________\r= مستحيل متناقض، فإذا لم يبعد كونه قادرا أزلا مع اختصاص المقدور بما لا يزال، لم يبعد أن يتصف بكلام هواقتضاء ممن سيكون. وانظر أيضا الغنية للمتولي ص 106.\r1) في الإنصاف للباقلاني ص 83: إن المسموع فهوكلام الله القديم، صفة لله تعالى، قديمة موجودة بوجود قبل سمع السامع لها، وإنما الموجود بعد أن لم يكن هوسمع السامع وفهم الفاهم لكلام الله تعالى، يحدث الله تعالى له سمعا إذا أراد أن يسمعه كلامه، وفهما إذا أراد أن يفهمه كلامه، لأن المسموع لم يكن ثم كان عند السمع والفهم. وانظر أيضا مجرد مقالات الأشعري لابن فورك ص 59، والإرشاد للجويني ص 133، والمغني للمتولي ص 108."], [158, "158 موسى عليه السلام، الذي خصصه الله تبارك وتعالى من بين عالمي زمانه بتكليمه، واصطفاه بإسماعه عزيز كلامه 1.\r----------------------\rعليه السلام: ليست في ط.\r_____________________\r1) رتب الباقلاني إسماع الله تعالى لخلقه الكلام على ثلاث مراتب، الأولى: الإسماع بغير واسطة لكن من وراء حجاب للخلق، كسماع موسى عليه السلام لكلام الله تعالى كما جاء في القرآن وكلم الل?ه موسى? تكليما، والثانية: الإسماع بواسطة، وهواستماع الخلق من الرسول صلى الله عليه وسلم عند قراءته للصحابة وقراءة الصحابة للتابعين، وهلم جرا إلى يومنا هذا، والثالثة: الإسماع من غير واسطة ولا حجاب، كتكليم الله تعالى لسيدنا محمد صلى الله عليه وسلم في حادثة المعراج إذ قال تعالى: فأوحى? إلى? عبده م?ا أوحى?. انظر الإنصاف للباقلاني ص 83 - 85، ومجرد مقالات الأشعري لابن فورك ص 59، والمغني للمتولي ص 108، والإرشاد للجويني ص 134."], [159, "فصل [معنى القول: كلام الله مكتوب في المصاحف مقروء بالألسنة، محفوظ بالصدور]\r"]], "pg": [157, 159]}, "474.22": {"x": [[159, "كلام الله تبارك وتعالى مكتوب في المصاحف، مقروء بالألسنة، محفوظ في الصدور، فلا يحل الكلام هذه المحال حلول الأعراض الجواهر، فإن كلام الله الأزلي، لا يفارق الذات ولا يزايلها.\rومن حاز طرفا من قضايا العقول، لم يسترب في أن التحول والانتقال/ والزوال، من صفات الأجسام 1.\rومن الغوائل 2 التي بلي الخلق بها، أن القول في قدم كلام الله تبارك وتعالى، وكونه مكتوبا في المصاحف، أشيع في زمن الإمام أحمد بن حنبل رحمه الله، من جهلة العوام والرعاع الهمج.\r_______________________\rتبارك: ليست في ط. في ط: ولا.\rفي ط: هذا المحل. في أ: يزايله، والمثبت من ط.\rتبارك: ليست في ط. في ط: زمان.\rرحمه الله: ليست في ط. في أ: في، والمثبت من ط.\rفي ط: والهمج.\r______________________\r1) يكرر الجويني ما ذكره في الإرشاد ص 132، وانظر في ذلك أيضا مجرد مقالات الأشعري لابن فورك ص 62، والإنصاف للباقلاني ص 82، والمغني للمتولي ص 108، 109.\r2) الغوائل: مفردها غائلة، وهي الدواهي. انظر ابن منظور، لسان العرب ج 11 ص 507."], [160, "وجرى من لا دراية له بالكلام في هذا الأصل، فسمعوا مطلقا، أن كلام الله في المصاحف، فسبقوا إلى اعتقاد ثبوت وجود الكلام الأزلي في الدفاتر، وارتبكوا في جهالات لا يبوء بها محصل 1.\rثم تطاول الدهر وتمادى العصر، فرسخ هذا الكلام في قلوب الحشوية 2، ولولا ذلك لما خفي على من معه مسكة من عقل، أن الكلام\r-----------\rفي ط: ضر في. في ط: يكون.\rفي ط: ما.\r_____________________\r1) ذهب هؤلاء إلى القول: إن الحروف والأصوات والرقوم المكتوبة قديمة أزلية، وقالوا: لا يعقل كلام ليس بحرف ولا كلم، وما دام الكلام قديما أزليا، فلا بد أن حروفه وكلماته وكتابته أزلية، واستدلوا على ذلك بما رووه عن النبي صلى الله عليه وسلم: «ينادى الله تعالى يوم القيامة بصوت يسمعه الأولون والآخرون» وقالوا: إن موسى عليه السلام كان يسمع كلام الله كجر السلاسل، واستدلوا على ذلك أيضا بإجماع السلف على أن القرآن غير مخلوق، ومن قال هومخلوق فهوكافر بالله، ولا نعرف من القرآن إلا ما هوبين أظهرنا فنبصره ونسمعه ونقرؤه ونكتبه. انظر في ذلك: الملل والنحل للشهرستاني ص 106، والفصل في الملل والنحل لابن حزم ج 4 ص 100، وشرح الأصول الخمسة للقاضي عبد الجبار ص 527، والفرق بين الفرق للبغدادي ص 217، 218، والإرشاد للجويني ص 128 - 130، والإنصاف للباقلاني ص 98، ونشأة الفكر الفلسفي في الإسلام للنشار ج 1 ص 288.\r2) الحشوية: مصطلح عام له معان مختلفة، فهناك حشوية الحديث، الذين أدخلوا (حشوا) في أحاديث رسول الله صلى الله عليه وسلم ما هوغريب وشاذ وإسرائيليات، وقد قام علماء الحديث السنة بجهود رائعة لمقاومة الحشوفي حديث رسول الله سواء من جهة الرواية أوالدراية، ومن أجل ذلك سارعوا إلى جمع الحديث وفق قواعد وشروط محددة، ثم وضعوا علم الجرح والتعديل وعلم مصطلح الحديث قاصدين من ذلك إبعاد كل ما هوحشوودخيل على أحاديث رسول الله صلى الله عليه وسلم.\rوهناك حشوية المتكلمة الذين صرحوا بالتشبيه والتجسيم، فقد أجازوا على الله تعالى الملامسة والمصافحة، وأن المسلمين المخلصين يعانقون الله في الدنيا والآخرة إذا بلغوا في الرياضة والاجهاد إلى حد الإخلاص والاتحاد المحض. كذلك قالوا بجسمية الله تعالى، فهوجسم ولحم ودم وله جوارح وأعضاء. . . كما أجروا الاستواء والوجه واليدين والإتيان والفوقية على ظاهر الألفاظ كما يفهم عند إطلاق ذلك على الأجسام. وهناك من رأى أن هذا المصطلح قد أخذ من كلام للحسن ="], [161, "لا ينتقل من متكلم إلى دفتر، ولا ينقلب معنى النفس إلى أصوات: سطورا ورسوما وأشكالا ورقوما.\rفإذا نقول، بعد الإحاطة بحقيقة هذه الفصول: كلام الله تبارك وتعالى في المصاحف مكتوب، وعلى ألسنة القراء مقروء، وفي الصدور محفوظ، وهوقائم بذات الباري وجودا 1.\r------------------\rفي أ: والأصوات، والمثبت من ط.\rفي ط: أورسوما. في الأصل: مقرو.\rفي ط: الله تعالى.\r_______________________\r= البصري، عند ما حضر بعض رواة الحديث مجلسه فتكلموا بالسقط عنده، فضاق صدره بهم ثم صاح: ردوا هؤلاء إلى حشا الحلقة. أما موقف الحشوية من كلام الله فقد سبق أن ذكرناه في الهامش السابق. انظر الملل والنحل للشهرستاني ص 105، وتبيين كذب المفتري (مقدمة الكوثري) ص 10، 11، ونشأة الفكر الفلسفي للنشار ج 1 ص 286، 287.\r1) في الإرشاد للجويني ص 132: «وكلام الله تعالى مكتوب في المصاحف، محفوظ في الصدور، وليس حالا في مصحف ولا قائما بقلب، والكتابة قد يعبر بها عن حركات الكاتب، وقد يعبر بها عن الحروف المرسومة والأسطر المرقومة، وكلها حوادث. وعلى الإجمال فإن الجويني في النظامية قد كرر ما جاء عند من سبقه من الأشاعرة، ولخص ما ذكره في كتاب الإرشاد، لذا فإن من يروم توسعا في هذه المسألة فعليه بالإرشاد ص 99 - 137."], [162, "فصل\r[في كون الله تعالى سميعا بصيرا]\r"]], "pg": [159, 162]}, "474.23": {"x": [[162, "يجب وصف الباري تعالى بكونه سميعا بصيرا 1، والدليل عليه: أن الواحد إذا أبصر، فإنه يجري منه تحديق في جهة المرئي، واتصال أشعة به على مجرى العادة. وإذا سمع، يقرع الهواء صماخيه 2. والإدراك الحقيقي يقع وراء الاتصالات التي ذكرناها، وذلك الإدراك له مزية على العلم بالمغيب الذي لم يدرك.\r------------------\rفي ط: الله. في أ: لكونه، والمثبت من ط.\rكتبت في أ: مراي. في ط: فقد يقرع.\rفي ط: ثم الإدراك.\r_______________\r1) استخدمت الأشاعرة قياس الغائب على الشاهد لإثبات كون الله تعالى سميعا بصيرا، فالحي إذا لم يتصف بآفة تمنعه من إدراك المسموعات والمبصرات إذا وجدت فهوسميع بصير، فلما كان الله تعالى حيا لا يجوز عليه الآفات من الصمم والعمى وغير ذلك، إذ إن الآفات تدل على حدوث من جازت عليه، صح أن الباري عز وجل سميع بصير. انظر اللمع للأشعري ص 77، 88. ومجرد مقالات الأشعري لابن فورك ص 44، والإنصاف للباقلاني ص 32، 33، والتمهيد للباقلاني ص 46، وأصول الدين للبغدادي ص 96، 97، والإرشاد للجويني ص 72، 73، ولمع الأدلة للجويني ص 97، والغنية في أصول الدين للمتولي ص 87، والاعتقاد للبيهقي ص 40، 62، ونهاية الإقدام للشهرستاني ص 343، والملل والنحل ص 107، والإشارة إلى مذهب أهل الحق لأبي إسحاق الشيرازي ص 145.\r2) الصماخ من الأذن: الخرق الباطن الذي يفضي إلى الرأس، ويقال: إن الصماخ هوالأذن نفسها. لسان العرب ج 3 ص 34."], [163, "فالرب تعالى، يدرك المبصر والمسموع على الحقيقة التي ندركه عليها، ويتعالى عما تتصف به الحواس، والحدق، والأصمخة. كما يعلم من غير نظر واستدلال، ويقدر من غير فرض جارحة وأداة. فمن وصف الإله بما ذكرناه من تحقيق الإدراك، فقد وافق في المعنى.\rونحن نقطع باستحالة اتصافه بالإحساس والتحديق والإصاخة 1. فإن أنكر منكر كونه مدركا لحقيقة /الأشياء، فقد أثبت للمخلوق في الإحاطة والدرك مزية على الخالق، ولا خفاء ببطلان ذلك، وكيف يصح في العقل، أن يخلق الرب للعبد الدرك الحقيقي، وهولا يدرك حقيقة ما خلق للعبد إدراكه\r-------------------\rفي ط: وكما. في: ليست في ط.\rفي أ: الإحساس، والمثبت من ط.\rكونه: ليست في ط. في ط: بحقائق.\r________________________\r1) الإصاخة: الاستماع والإنصات. لسان العرب ج 3 ص 35."], [164, "فصل\r[في صفة البقاء]\r\r"]], "pg": [162, 164]}, "474.24": {"x": [[164, "يجب القطع بأن الله تعالى باق 1، وما وجب قدمه استحال عدمه، فإن القديم هوالذي قضى العقل بوجوب وجوده، إذ لوكان وجوده جائزا لوقت، لحكم بحدوثه، كما سبق تقريره.\r--------------\rفي أ: قضا. في ط: جائزا.\rفي ط: لوجب. في ط: الحكم.\r_________________________\r1) قال قدماء الأشاعرة: إن صفة البقاء هي صفة أزلية قائمة بالله تعالى، ولأجلها صح وصفه بأن الله تعالى باق، ومنع الباقلاني من كون البقاء معنى أكثر من وجود الشيء، وقال: إن الله باق لنفسه، وكل باق يجوز فناؤه إلا الله وصفاته القائمة، واستدلت الأشاعرة أيضا على وجوب هذه الصفة لله تعالى بأنه تعالى قديم، والقديم يستحيل عدمه، وإذا ثبت ذلك وجب وصفه بالبقاء، إلا أن البقاء استمرار الوجود، أما دليلهم النقلي على هذه الصفة فهوقوله تعالى: ويبقى? وجه ربك. انظر في ذلك: أصول الدين للبغدادي ص 108 - 190، والغنية (المغني) في أصول الدين للمتولي ص 89، 90."], [165, "فصل\r[في الإضراب عن تأويل المشكلات]\r\r"]], "pg": [164, 165]}, "474.25": {"x": [[165, "قد اختلف مسالك العلماء في الظواهر التي وردت في الكتاب والسنة، وامتنع على أهل الحق اعتقاد فحواها، وإجراؤها على موجب ما تبتدره أفهام أرباب اللسان منها.\rفرأى بعضهم تأويلها، والتزم هذا المنهج في آي الكتاب، وما يصح من سنن الرسول صلى الله عليه وسلم.\rوذهب أئمة السلف إلى الانكفاف عن التأويل، وإجراء الظواهر على مواردها، وتفويض معانيها إلى الرب تعالى 1.\r---------------\rفي ط: تبرزه. في ط: والتزام.\rفي ط: النبي. في ط: وذهبت.\rفي ط: سبحانه.\r__________________\r1) نشأ هذه الخلاف عند ما بحث علماء المسلمين في الآيات القرآنية المتشابهات، وخصوصا في تلك الآيات الواردة في الصفات، وانقسموا في ذلك إلى ثلاث فرق: الأولى: قررت أنه لا مدخل للتأويل فيها، بل تجري على ظاهرها، وهؤلاء هم المجسمة والمشبهة، والثانية: ذهبت إلى أن لها تأويلا، ولكنها تمسك عنه، مع تنزيه الاعتقاد عن الشبه والتعطيل، وهذا التأويل لا يعلمه إلا الله، وهذا قول السلف، والثالثة: ذهبت إلى تأويلها بما يليق بجلاله تعالى، وهذا مذهب الخلف من معتزلة وأشاعرة وماتريدية، ومن هذه الآيات المتشابهات قول الله تعالى: الرحم?ن على العرش استوى? (5) وقوله: ويحذركم الل?ه نفسه وقوله: وجاء ربك والملك، وغيرها. وقول رسول الله صلى الله عليه وسلم: «قلب المؤمن بين إصبعين من أصابع الرحمن». انظر في ذلك: البرهان في علوم القرآن للزركشي ج 2 ص 78، 79، ومعالم التنزيل للبغوي ج 1 ص 279، 280، والجامع في أحكام القرآن للقرطبي ج 4 ص 14."], [166, "والذي نرتضيه رأيا، وندين الله به عقدا، اتباع سلف الأمة، فالأولى الاتباع، وترك الابتداع. والدليل السمعي القاطع في ذلك؛ أن إجماع الأمة حجة متبعة، وهومستند معظم الشريعة 1.\rوقد درج صحب رسول الله صلى الله عليه وسلم، ورضي عنهم، على ترك التعرض لمعانيها، ودرك ما فيها، وهم صفوة الإسلام، والمستقلون بأعباء الشريعة، وكانوا لا يألون جهدا في ضبط قواعد الملة، والتواصي بحفظها، وتعليم الناس ما يحتاجون إليه منها. فلوكان تأويل هذه الظواهر مسوغا ومحتوما، لأوشك أن يكون اهتمامهم بها فوق اهتمامهم بفروع الشريعة.\rوإذا انصرف عصرهم، وعصر التابعين [رضي الله عنهم]، على الإضراب عن التأويل، كان ذلك قاطعا، وأنه الوجه المتبع، فحقت على ذي الدين أن يعتقد تنزه الباري عن صفات المحدثين، ولا يخوض في تأويل المشكلات، ويكل معناها إلى الرب تبارك وتعالى.\rوعد إمام القراء وسيدهم نافع 2، الوقوف على قوله\r---------------------\rفي أ: عقلا. في ط: النبي.\rورضي عنهم: ليست في ط. في ط: الأي.\rفي أ: محبوبا. في أ: عرضهم، والمثبت من ط.\rالزيادة من ط. في ط: بأنه.\rفي ط: بحق. في ط: تنزيه الرب.\rتبارك: ليست في ط. في ط: وعند.\rنافع: ليست في ط. في ط: الوقف.\r_____________________\r1) كان إمام الحرمين قبل العقيدة النظامية يلتزم بما قرره الأشاعرة السابقون له في تأويل الآيات المتشابهة بما يليق بذات الله تعالى، لكنه في هذا النص نلحظ انضمامه إلى موقف أهل السلف وابتعاده عن معتقد الأشعري في هذه المسألة بالذات. انظر الإرشاد للجويني ص 155، 157 - 160، والإتقان في علوم القرآن للسيوطي ج 2 ص 6.\r2) نافع (- 59 ه‍/ 678 م): هونافع بن عبد الرحمن بن أبي نعيم، أبورويم المقرئ، أحد القراء السبعة، كان ="], [167, "تبارك وتعالى: وما يعلم تأويله إلا الله 1 من العزائم 2، ثم الابتداء بقوله تعالى: والراسخون في العلم 3.\rومما استحسن من كلام إمام دار/الهجرة رضي الله عنه-وهومالك بن أنس-أنه سئل عن قوله تبارك وتعالى: الرحم?ن على العرش استوى? (5) 4 فقال: الاستواء معلوم، والكيفية مجهولة، والسؤال عنه بدعة 5.\r----------------------\r\rتبارك: ليست في ط. تعالى: ليست في ط.\r\rكلام: ليست في ط. رضي الله عنه وهو: ليست في ط.\r\rتبارك وتعالى: ليست في ط. كتبت في أ: الاستوى.\r___________________________________\r= إمام أهل المدينة، وأصله من أصبهان، قرأ على أبي ميمونة مولى أم سلمة زوج رسول الله، وكان له راويان: ورش وقنبل، توفي بالمدينة. قارن عنه وفيات الأعيان لابن خلكان ج 5 ص 368، وغاية النهاية لابن الجزري ج 2 ص 330، وتهذيب الكمال ج 2 ص 281، وميزان الاعتدال للذهبي ج 4 ص 242.\r1) سورة آل عمران، الآية 7.\r2) وإلى ذلك ذهب عبد الله بن مسعود وعبد الله بن عمر وعبد الله بن عباس وأبي بن كعب وعائشة وعروة بن الزبير والكسائي والأخفش والفراء. انظر جامع البيان للطبري ج 3 ص 121، والجامع لأحكام القرآن للقرطبي ج 4 ص 16، والإتقان للسيوطي ج 2 ص 3.\r3) سورة آل عمران، الآية 7.\r4) سورة طه، الآية 5.\r5) في الأسماء والصفات للبيهقي ج 2 ص 150، 151: «الاستواء غير مجهول، والكيف غير معقول والإيمان به واجب، والسؤال عنه بدعة». وانظره أيضا في شرح أصول اعتقاد أهل السنة والجماعة لأبي القاسم اللالكائي ج 3 ص 397، والجامع لأحكام القرآن للقرطبي ج 7 ص 220، ومعالم التنزيل للبغوي ج 2 ص 165، وحلية الأولياء لأبي نعيم الأصفهاني ج 6 ص 325، 326، وترتيب المدارك للقاضي عياض ج 1 ص 170، 171، وتاريخ الإسلام للذهبي، وفيات (171 - 180) ص 328."], [168, "فلتجر آية الاستواء 1، والمجيء، وقوله: لما خلقت بيدي 2 [و] ويبقى وجه ربك 3 وقوله: تجري بأعيننا 4، وما صح من أخبار الرسول عليه السلام، كخبر النزول 5 وغيره، على ما ذكرناه، فهذا بيان ما يجب لله تعالى.\r---------------\rالزيادة من ط. في ط: ذكرنا.\r_______________________\r1) اختلفت مذاهب الإسلاميين في معنى الاستواء وتوزعت على الاستقرار، والقهر والغلبة، والاستيلاء، والعلو، والصعود. انظر ذلك في الإشارة إلى مذهب أهل الحق للشيرازي ص 139، والأسماء والصفات للبيهقي ج 2 ص 152 - 154.\r2) سورة ص، الآية 75.\r3) سورة الرحمن، الآية 27.\r4) سورة القمر، الآية 14.\r5) كقول الرسول صلى الله عليه وسلم: «ينزل ربنا تبارك وتعالى كل ليلة إلى السماء الدنيا حين يبقى ثلث الليل الآخر يقول: من يدعوني فأستجيب له، من يسألني فأعطيه، من يستغفرني فأغفر له». الجامع الصحيح للبخاري ج 2 ص 66، باب التهجد بالليل 15، وصحيح مسلم بشرح النووي، كتاب المسافرين ص 168 - 170، وسنن أبي داود، كتاب السنة 19، وسنن الترمذي، كتاب الصلاة 211، والدعوات 78، وسنن ابن ماجه، كتاب الإقامة 182، وسنن الدارمي، كتاب الصلاة 168، وموطأ مالك، قرآن 30، ومسند أحمد ج 2 ص 264، 267، 282، 419، 487، 504."], [169, "[القسم الثالث]\rالكلام فيما يجوز في أحكام الله سبحانه\r\r"]], "pg": [165, 169]}, "474.26": {"x": [[169, "قال المحققون: الجائز في حكم الله تبارك وتعالى، ينقسم إلى القول في أفعاله، وإلى جواز رؤيته، فهما قسمان، فلتقع البداية بأفعاله، فنقول: كل ما قضى العقل بجوازه وإمكان حدوثه، فالرب تعالى موصوف بالاقتدار عليه، ولوفرض إحداثه إياه، كان مسوغا في العقل غير ممتنع، [و] هذا الآن يستمد من بحر في الأصول، لا ينزف، وهوالقول في التقبيح والتحسين 1.\r---------------------\rتبارك: ليست في ط. في أ: كلما، والمثبت من ط.\rفي ط: لما كان ممتنعا ولكان مسوغا في العقل.\rالزيادة من ط. في ط: يغترف.\r_________________________\r1) اختلفت مقالات الإسلاميين في معتمد الحكم على الأفعال من حيث الحسن أوالقبح، فقد ذهبت المعتزلة إلى أن حسن الأفعال أوقبحها إنما يعلم ببداهة العقول، كذلك فإن الحكم على الفعل أنه حسن أوقبيح إنما يبنى على أمور ترجع إلى الفعل نفسه، ولا يبنى على مجرد أن الله تعالى قد أمر به أونهى عنه، فالصدق حسن لصفة ترجع إلى الصدق نفسه، وليس لكون الله تعالى قد أمر به، والكذب قبيح لصفة عائدة إلى الكذب نفسه، وليس لأن الله تعالى قد نهى عنه. أما الأشاعرة فقد قررت أن العقل لا يوجب ولا يحسن ولا يقبح، بل الحسن ما حسنته الشريعة، والقبيح ما قبحته الشريعة، وإن كل ما كان منا مخالفا لأمر الرب تعالى فهوقبيح وإن كانت صورته حسنة من حيث الحس والنظر والسمع، ونحوذلك، وإن كل ما كان منا حسنا إنما كان كذلك لأنه موافق لأمر الرب تعالى، لا من حيث الصورة والحس لكن الأشاعرة لم تنف قدرة العقل على إدراك الحسن والقبيح. انظر في ذلك: المغني في أبواب التوحيد والعدل للقاضي عبد الجبار ج 6 ص 20، ="], [170, "وتتبع المذاهب في ذلك يطول، ويخرج عن الحد المقصود، فالوجه الاقتصار على نكتة واحدة قاطعة، ولا يبقى على فاهمها إشكال ألبتة.\rفالذي اعتقده أهل الأهواء 1 حسنا لعينه؛ كالإيمان وشكر المنعم، والذي اعتقدوه قبيحا لعينه؛ كالكذب والظلم، إنما ينفصل وينقسم على من يقبل الضر والنفع، وحقيقة الضر: الألم، وحقيقة النفع: اللذة. والهموم واستشعار الخوف، من الآلام. والسرور والارتياح، من اللذات.\rوالرب باتفاق المعترفين بالصانع، متقدس عن قبول النفع والضرر، فلا يسره وفاق، ولا يضره شقاق. وإذا كان كذلك استحال أن [يظن به قبول النفع والضر]، [وأن] تختلف الأفعال في حقه، حتى يقضى بأنه يوقع بعضها، ولا يجوز في حكمه إيقاع بعضها 2.\rوإذا قال الذاهل عن [سر] هذا الأمر الجلي: إنه تعالى لا يفعل القبيح لعلمه بقبحه، وغناه عن فعله 3.\r----------------------\rفي ط: نكتة فاخرة قاطعة لا تبقى.\rفي ط: يتفصل. وحقيقة الضر والألم: ليست في ط.\rفي ط: واللذة. في ط: استشعار.\rفي ط: الضر. الزيادة من ط.\rأضفتها اجتهادا. في ط: تسر. الزيادة من ط.\r__________________________\r= 102، وج 14 ص 150، وشرح الأصول الخمسة ص 306، والتمهيد للباقلاني ص 149، 150، 384، والإنصاف ص 138، 149، والإشارة إلى مذهب أهل الحق للشيرازي ص 132، والإرشاد للجويني ص 258، والغنية للمتولي ص 135، وأصول الدين للبغدادي ص 131، ونهاية الإقدام للشهرستاني ص 370، ومحصل أفكار المتقدمين للرازي ص 293، والأربعين في أصول الدين ص 246، ومجرد مقالات الأشعري ص 96، 97، وتبصرة الأدلة للنسفي ج 2 ص 661، وانظر موقف الحنابلة من هذه المسألة في المعتمد في أصول الدين لأبي يعلى ص 42، والرسالة التدمرية لابن تيمية ص 117، 118.\r1) قصد الجويني هنا المعتزلة.\r2) انظر ذلك أيضا في الإرشاد للجويني ص 269، 270، والتمهيد للباقلاني ص 361.\r3) في المجموع في المحيط للقاضي عبد الجبار ج 1 ص 257: «إنه تعالى عالم بقبح ="], [171, "قلنا: لا يتحقق القبيح بالإضافة إلى الله تبارك وتعالى، فإنه لا يتضرر به كما لا ينتفع بنقيضه 1.\rولولا أنه شاع في ألفاظ عصبة الحق، أنه [تعالى] خالق الخير والشر، لكان أمر التوحيد/يوجب أن يقال: ليس في أفعال الله تبارك وتعالى خير ولا شر بالإضافة إلى حكم الإلهية، فإن الأفعال متساوية في حكمه، وإنما تختلف مراتبها بالإضافة إلى العباد 2.\rوهذا المقدار مقنع في هذا الأصل العظيم، لا حاجة معه إلى غيره. وقد نبه على هذا المعنى رسول الله صلى الله عليه وسلم، إذ قال في مساق حديث طويل: «قسم الله\r---------------\rفي ط: نتحقق. تبارك: ليست في ط.\rفي أ: بنقضيه، والمثبت من ط.\rالزيادة من ط. في ط: وفي هذا.\rرسول الله: ليست في ط.\rفي ط: سياق. في ط: في قسم.\r______________________\r= القبيح وبغناه عنه، أوإنه عالم بقبح القبيح عالم بأنه غني عنه وإن من هذه حاله لا يختار القبائح أصلا».\r1) في الإرشاد ص 269: «فإن الرب تعالى يتقدس عن الانتفاع والضرر، إذ لا معنى للنفع والتضرر والآلام واللذة، والرب متعال عنهما». وقارن بالغنية في أصول الدين للمتولي ص 140، والتمهيد للباقلاني ص 361، 362.\r2) لم يأت الجويني بما قرره هنا بشيء جديد، فقد سبقه إلى ذلك الإمام الباقلاني عند ما لجأ إلى نظرية الأحوال البهشمية في تقرير أن خلق ذوات الأفعال يضاف إلى الباري عز وجل مجردا من الجهات العقلية والاعتبارات الذهنية العامة والخاصة المتعلقة بالفعل نفسه، كالوجود والحدوث والعرضية واللونية، ولكن عند ما تتعلق إرادة الإنسان وقدرته المحدثة بهذه الأفعال المحايدة، فإنها تكتسب صفة الحسن أوالقبح، ففعل الإيمان المخلوق لله هوفعل محايد، وعند ما يختار الإنسان الإيمان بالله، فإن هذا الفعل الإيماني يكون حسنا، أما إذا تلبست إرادة الإنسان بالإيمان بالطاغوت أوغيره مما نهى الله عنه، فإن فعله الإيماني هذا يصبح قبيحا. انظر الإنصاف للباقلاني ص 148، ونهاية الإقدام للشهرستاني ص 75، 76، والمطالب العالية للرازي ج 9 ص 10، والروض الباسم لابن الوزير ص 195، والملل والنحل للشهرستاني ص 98."], [172, "الأرواح، فوقف الأرواح السعداء على يمين العرش، وأرواح الأشقياء على يسار العرش، ثم قال: هؤلاء أهل الجنة ولا أبالي، وهؤلاء أهل النار ولا أبالي» 1.\rفإن موه المخالف فقال: الكيس المعظم، قد يلقى غريبا مهينا لا ينتفع بإكرامه وإيوائه، ولا يتضرر في تركه في مضيعة، ثم الحكمة تستحثه على مكارم الأخلاق فيه. وهذا تلبيس لا تحصيل له، فإن الصورة التي [ذكرها اتفاق، وغيرها مما يلبسون به. فيحصر ذلك أمران، أحدهما: أن المكارم التي] ذكرها، سببها الاهتزاز بحسن الثناء في الغالب، وقد يستمر المرء لعلة على أمر في ط: يوقف.\r------------------\rفي ط: عارض. في ط: بتركه.\rفي ط: مضيقة. في أ: الحكم، والمثبت من ط.\rالزيادة من ط. في ط: ثم قد.\rفي أ: لعة.\r____________________\r1) المشهور في نصه: «خلق الله آدم ثم خلق الخلق من ظهره، ثم قال: هؤلاء للجنة ولا أبالي، وهؤلاء للنار ولا أبالي». رواه الآجري في الشريعة ص 183، والبيهقي في الأسماء والصفات ج 2 ص 58، واللالكائي في شرح أصول السنة ج 4 ص 606، والحاكم في المستدرك ج 1 ص 31 وصححه، ووافقه الذهبي في التلخيص ج 4 ص 606، وأحمد بن حنبل في المسند ج 4 ص 186، وقال الهيثمي في مجمع الزوائد ج 7 ص 186: رواه أحمد ورجاله ثقات، وذكره البيهقي موقوفا على أبي بكر في كتاب إثبات القدر ص 282، وقد ذكره ابن حجر في تعجيل المنفعة ص 256 (ترجمة عبد الرحمن بن قتادة) وقال: رواه عنه راشد بن سعد وفيه اضطراب، وذكره أيضا في الإصابة ج 2 ص 411 وأشار إلى أن الاضطراب في سنده لا يضر ما دام عبد الرحمن بن قتادة ثبتت صحبته، وقد ذكر أكثر من واحد أن سند هذا الحديث مضطرب منهم: ابن عبد البر وابن السكن، إذ إنه يروى مباشرة عن عبد الرحمن عن النبي صلى الله عليه وسلم، وأحيانا بواسطة بين عبد الرحمن والنبي، وأحيانا بواسطتين.\rانظر السنة لابن أبي عاصم ج 3 ص 74، والإصابة لابن حجر ج 2 ص 411، وقد ذكره البيهقي في كتاب إثبات القدر من طرق مختلفة لا يخلوأغلبها من ضعف ص 282، 402 - 404."], [173, "ويتعوده، حتى ينتهي الأمر فيه إلى مبلغ يعسر عليه مخالفته، وللعادات آثار غير منكورة في الجبلات.\rوالثاني: إن الإنسان قد تناله رقه الجنسية، وتستحثه على إنقاذ الغرقى، وإنجاء الهلكى، ولولم ينهض لها، لتضور تضورا بينا، والرب تبارك وتعالى يتقدس عن هذه الصفات جمع. ومن تخيل تفصيل الأفعال في حق الإله، فقد تعلق بطرف من التشبي\rوالصائرون إلى التجسيم، وإثبات الجهة، متمسكون بما يفضي إلى التشبيه في الوجود الأزلي، وهؤلاء مشبهون في الأفعال 1.\r-----------------------\rفي ط: المرء على أمر لعلة ويعتاده. في ط: يعسر.\rفي ط: استنقاذ. في أ: وانجى، وما أثبته من ط.\rفي ط: ولولم يقتض له التضرر ضررا بينا.\rفي ط: والرب تعالى متقدس. في أ: السنة، والمثبت من ط.\rفي ط: فالصائرون. في ط: التشبيه.\rفي ط: يتمسكون.\r____________________\r1) مشبهة الأفعال: هم أولئك الذين أجازوا على الباري عز وجل النزول والصعود والمجيء والذهاب والهرولة والمصافحة والمعانقة والفرح والسرور. . وغير ذلك من الأفعال التي تصدق في حق العباد. وهناك مشبهة الذات الذين قالوا: إن الله تعالى يشبه مخلوقاته من جهة الجسمية والجوارح والجهة والتحيز في المكان. وقد ابتدأ التشبيه مع مقاتل بن سليمان (- 150 ه‍) المفسر المشهور، واستمر مع محمد بن كرام (- 255 ه‍) وأتباعه من الكرامية، وتعد السالمية أيضا من الفرق المشبهة وهم أتباع محمد بن سالم وابنه أحمد بن محمد بن سالم (- 350 ه‍).\rانظر مقالات الإسلاميين للأشعري ص 152، 153، والبدء والتاريخ للمقدسي ج 5 ص 139، والفرق بين الفرق للبغدادي ص 214، والتبصير في الدين للإسفراييني ص 99 - 105، والمعتمد في أصول الدين للقاضي أبي يعلى ص 44، 72، والملل والنحل للشهرستاني ص 103، والكامل في التاريخ لابن الأثير ج 10 ص 52، وتاريخ الإسلام للذهبي، وفيات (441 - 460) ص 461 - 463، ودائرة المعارف الإسلامية ج 11 ص 19، والتجسيم عند المسلمين لسهير مختار، ونشأة الفكر الفلسفي في الإسلام للنشار ج 1 ص 285 - 308."], [174, "والفئتان زائغتان عن مدرك الحق، فالرب لا يناسب وجوده وجود، ولا يشبهه في امتناع قبول الضرر والنفع فاعل، فهذا-حرس الله مولانا- لباب التوحيد.\r-----------------\rفي أ: يتناسب، والمثبت من ط."]], "pg": [169, 174]}, "474.27": {"x": [[175, "فصل\rالحادثات كلها مرادة لله تبارك وتعالى 1\r\rوهذا مقتضب من القاعدة التي ذكرناها آنفا، فإذا تقرر أن الأفعال لا تتفاوت في حق الإله تبارك وتعالى، فتعلق الإرادة بها على قضية واحدة لا تختلف.\rونخصص هذا الفصل بأمر قاطع، منزل على ما يرتضيه مولانا، فنقول: ضلكم تنزيل أحكام /الله تبارك وتعالى عل مجاري أفعال الحكماء [منا]. وليس يخفى أن من علم [أنه] لوأمد عبدا من عبيده بالمال، وضروب العدد، لفسق وفجر، وانتهك الحرمات، واقتحم الكبائر والموبقات، فلوأمده مع علمه البات في ذلك، ثم زعم أنه أراد بإمداده بعتاده، أن يستمد به في تبارك: ليست في ط.\r---------------\rفي ط: الله تعالى. في أ: أحجام، والمثبت من ط.\rتبارك: ليست في ط. في ط: الجاري في.\rالزيادة من ط. الزيادة من ط.\rفي أ: بامتداده، والمثبت من ط.\r_____________________\r1) تعتقد الأشاعرة أن الله تعالى مريد بإرادة قديمة أزلية، فجميع ما يجري في العالم من خير أوشر، أونفع وضرر، أوطاعة ومعصية، فبإرادة الباري عز وجل، لاستحالة أن يجري في ملكه ما لا يريده، لأن وقوع ما لم يشأ الله وقوعه يؤدي إلى نقصه وعجزه. انظر اللمع للأشعري ص 100، والإشارة إلى مذهب أهل الحق للشيرازي ص 129، والغنية للمتولي ص 95، والاقتصاد في الاعتقاد للغزالي ص 50، ونهاية الإقدام للشهرستاني ص 240، ومعالم أصول الدين للرازي ص 63."], [176, "أبواب الخيرات، ويتخذه ذريعة في القربات، كانت هذه الإرادة، مع العلم بنقيضها مشعرة بنهاية السفه والخبط في العقل، سيما إذا علم أنه لوقطع عنه مادته لاشتغل بما يعنيه. ورب الأرباب يمد الكفار 1 بما يشد أزرهم، ويقوي متنهم، ويكمل عدتهم.\rوإذا مهدنا المسلك، فلا معنى للإطناب، بعد وضوح الغرض، وقد لاح للموفق ما أردناه، انتجز الغرض في أحد قسمي الجواز في أحكام الإلهية.\r---------------------\rفي ط: لا سيما. في أ: يشيد، والمثبت من ط.\rفي ط: منتهم. في أ: ويجمل، والمثبت من ط.\rفي ط: شهدنا. في ط: للمريد.\rفي ط: وانتهى.\r____________________\r1) بعد أن ذكر الله تعالى صفات الكافرين في الآيات 6 - 14 من سورة البقرة قال في حقهم في الآية 15: الل?ه يستهزئ بهم ويمدهم في طغي?انهم يعمهون (15). وقد حدد الله تعالى في سورة الإسراء، الآيات 18 - 20 قاعدة العطاء الإلهي للعباد بقوله: من ك?ان يريد الع?اجلة عجلن?ا له فيه?ا م?ا نش?اء لمن نريد ثم جعلن?ا له جهنم يصلا?ه?ا مذموما مدحورا (18) ومن أر?اد الآخرة وسعى? له?ا سعيه?ا وهومؤمن فأول?ئك ك?ان سعيهم مشكورا (19) كلا نمد ه?ؤلا?ء وهؤلا?ء من عط?اء ربك وم?ا ك?ان عط?اء ربك محظورا (20)."], [177, "["]], "pg": [175, 177]}, "474.28": {"x": [[177, "فصل]\r[في جواز رؤية الباري عز وجل]\rفأما القسم الثاني، وهوالقول في جواز رؤية الإله تبارك وتعالى 1.\r----------------\rتبارك: ليست في ط.\r____________________\r1) تعتقد الأشاعرة بجواز رؤية الله تعالى من جهة الفعل، وهي واجبة للمؤمين في الآخرة، واعتمدت في الاستدلال على ذلك بأدلة نقلية وأخرى عقلية، ومن الأدلة النقلية قول الله تعالى في قصة موسى عليه السلام: رب أرني أنظر إليك فقد سأل موسى ربه الرؤية، ومن المحال أن يسأل النبي ربه ما يستحيل في حقه، وقوله تعالى: لن تر?اني إنما تضمن عدم وجود الرؤية عند السؤال، لا استحالة الرؤية. ومن الأدلة السمعية قول الله تعالى: وجوه يومئذ ن?اضرة (22) إلى? ربه?ا ن?اظرة (23) فناضرة بمعنى مشرقة، وناظره بمعنى رآئية، ومنها حديث الرؤية، وهوقوله صلى الله عليه وسلم: «خرج علينا رسول الله صلى الله عليه وسلم ليلة البدر فقال: إنكم سترون ربكم يوم القيامة كما ترون هذا لا تضامون في رؤيته». انظر اللمع للأشعري ص 110، والإبانة ص 30، ومجرد مقالات الأشعري لابن فورك ص 79، والإنصاف للباقلاني ص 42، 156، والتمهيد ص 301، وأصول الدين للبغدادي ص 97، والفرق بين الفرق ص 324، والاعتقاد للبيهقي ص 95، والإرشاد للجويني ص 166، ولمع الأدلة ص 115، والغنية للمتولي ص 142، والملل والنحل للشهرستاني ص 100، ونهاية الإقدام ص 356، والاقتصاد في الاعتقاد للغزالي ص 30، وإحياء علوم الدين ج 1 ص 187، والأربعين للرازي ص 189، ومعالم أصول الدين ص 73، والمحصل في أفكار المتقدمين ص 272، وغاية المرام للآمدي ص 270، وأبكار الأفكار (مخطوط) م 2 ل 192 أ، والمواقف للإيجي ص 299، وفي علم الكلام لأحمد صبحي ج 2 ص 66، ونشأة الأشعرية لجلال موسى ص 258، ومذاهب الإسلاميين لعبد الرحمن بدوي ص 548.\rوانظر موقف الماتريدية من هذه المسألة في التوحيد للماتريدي ص 77، وتبصرة الأدلة لأبي المعين النسفي ج 1 ص 387، والتمهيد في أصول الدين ص 38. ="], [178, "وهذا قد طال فيه ارتباك طبقات الخلق، وحسبه الشادون 1 من الجليات، والانتهاء إلى درك القطع فيه عسير جدا، فإن الإحاطة بحقائق الإدراكات من أدق أحكام المعقولات. ونحن نستعين بالله ونذكر ما يشهد العقل له بالسداد.\rفليعلم الناظر في هذا الفصل، أن الذين أحالوا رؤية الإله، بنوا عقدهم على ظن فاسد 2، وذلك أنهم ظنوا أن الإحساس الذي هوتحديق في صوب المرئي، هوالذي يدعي أهل الحق تعلق قبيله بوجود الإله، وهذا زلل وسوء ظن بعصبة أهل الحق-تعالى الله أن يحس-ولكن ما أحسسناه من المرئيات ندرك حقيقته، وإدراكنا حقيقته ليس هوالمحسوسات المفسرة بمقابلة واتصال أشعة 3 4.\rفقال أهل الحق: لا يمتنع في قدرة الله سبحانه، أن يخصص من أراد بصفة، هي في التعلق بوجوده بالإضافة إلى العلم، كالإدراك المتعلق\r-------------\rفي ط: مثله. في ط: الإحساس المفسر.\rفي ط: تعالى. في أ: التعليق، والمثبت من ط.\rفي أ: المعلق، والمثبت من ط.\r_______________\r= وانظر رأي أهل السلف في الرد على الجهمية لأحمد بن حنبل ص 127، والعقيدة لأحمد بن حنبل (رواية الخلال) ص 111، والعقيدة الواسطية لابن تيمية ص 39، والمعتمد للقاضي أبي يعلى ص 82، ورد الإمام الدارمي ص 413، وشرح الطحاوية ص 163، 195، وشرح الأصول لأبي القاسم اللالكائي ج 3 ص 470، والسنة لابن أبي عاصم ص 188 - 204، ومعالم السنن للخطابي ج 4 ص 302، والإيمان لابن منده ج 2 ص 779، والشريعة للآجري ص 251، وانظر أيضا كتاب الرؤية (مخطوط) للدارقطني، وهناك مخطوط للجويني يحمل عنوان «مسألة في الرؤية» وهوموجود بمكتبة الإمبروزيانا.\r1) هم المتعاملون أوالمتفيهقون الذين لا نصيب كبير لهم في العلم.\r2) عنى الجويني هنا المعتزلة.\r3) انظر مناقشة القاضي عبد الجبار لما ذهبت إليه الأشاعرة في الرؤية، شرح أصول الخمسة ص 232 - 277، وانظر ما ذكره الجويني هنا في المصدر نفسه ص 248، والمغني في أبواب التوحيد والعدل ج 4 ص 36 وما بعدها.\r4) قارن بالإرشاد للجويني ص 171،172."], [179, "بالمدركات، شاهد بالإضافة إلى العلم بها على الغيب من غير درك. ثم تلك الصفة من مقدورات الباري تبارك وتعالى، وهي لا تتناهى، وما لم يحله العقل التحق بالجائزات، سيما إذا اعتقد بالنصوص القاطعة في الكتاب والسنة.\rوأقوى متمسك في السمع شيئان، أحدهما: سؤال موسى عليه السلام الرؤية 1، مع الوفاق على أن [كل] من كان في منصب النبوة، يستحيل أن يعتقد في حكم ربه ما يوجب تضليلا 2.\rونفاة الرؤية، إذا اقتصدوا ولم يبوحوا بسوء اعتقادهم في الخصوم، اقتصروا على تضليلهم. وكيف يستجيز منتم إلى الدين، أن يفضل سفلة نفاة الرؤية 3 في معرفة الله تبارك وتعالى على موسى صلى الله عليه وسلم!\rنعم، لا يمتنع أن يذهل النبي [صلى الله عليه وسلم] عن الغيب، ويستفزه الوله على سؤال ما علم جوازه 4 وإن لم يبلغه دخول وقته، وهذا أحد الشيئين.\r------------------\rفي ط: مشاهدة. تبارك: ليست في ط.\rفي ط: اعتضد. في ط: وأحرى.\rفي ط: صلى الله على نبينا وعليه وسلم.\rالزيادة من ط. في أ: من، والمثبت من ط.\rحكم: ليست في ط. في أ: بسر، والمثبت من ط.\rفي أ: عقدهم، والمثبت من ط.\rتبارك: ليس في ط.\rصلى الله عليه وسلم: ليست في ط.\rالزيادة من ط. في ط: المغيب. في أ: ويستقره. في ط: فهذا.\r____________________\r1) وفي ذلك ورد قول الله تعالى: ولما جاء موسى لميقاتنا وكلمه ربه قال رب أرني أنظر إليك قال لن تراني ولكن انظر إلى الجبل فإن استقر مك?انه فسوف تراني فلما تجلى ربه للجبل جعله دكا وخر موسى صعقا فلما أفاق قال سبحانك تبت إليك وأنا أول المؤمنين (143) سورة الأعراف، الآية 143.\r2) يكرر الجويني هنا ما ورد في الإبانة للأشعري ص 34، والإنصاف للباقلاني ص 156، والتمهيد ص 302، والغنية للمتولي ص 146.\r3) في الإرشاد ص 183 «حثالة المعتزلة».\r4) في الإبانة للأشعري ص 34: «ولا يجوز أن يكون موسى عليه السلام قد ألبسه الله تعالى جلباب النبيين، وعصمه بما عصم به المرسلين، قد سأل ربه ما يستحيل عليه، ="], [180, "والثاني: أنا نعلم قطعا، علم من لا يتمارى، أن الأولين، كانوا مبتهلين إلى الله تبارك وتعالى في سؤال الرؤية، ابتهالهم إليه في سؤال كل ممكن من ثواب أومغفرة، ومن جحد هذا هومعاند، والأمة معصومة لا تجتمع على الضلالة 1.\rولسنا ندعي الإجماع مع ظهور الخلاف الآن، ولكننا ندعي بقدم الإجماع من سلف الأمة قبل ظهور الآراء واختلاف الأهواء. فذلك ما أردناه في هذا الفصل، وقد نجز بانتهاء هذا الفصل، غرضنا من هذا المعتقد في أقسام الأحكام الإلهية.\r---------------\rفي أ: أن، وما أثبته من ط. علم: ليست في ط.\rفي ط: يتمارى فيه. في سؤال الرؤية ابتهالهم إليه: ليست في ط.\rفي أ: مغاور، وما أثبته من ط. الآن: ليست في ط.\rفي ط: فهذا. في ط: في.\r_________________________\r= وإذا لم يجز ذلك على موسى فقد علمنا أنه لم يسأل ربه مستحيلا، وأن الرؤية جائزة على ربنا عز وجل، ولوكانت الرؤية مستحيلة على ربنا كما زعمت المعتزلة، ولم يعلم ذلك موسى عليه السلام، وعلموا هم، لكانوا على قولهم أعلم بالله من موسى عليه السلام، وهذا ما لا يدعيه مسلم». وانظر أيضا اللمع للأشعري ص 192، والإنصاف للباقلاني ص 160، والتمهيد ص 302، والإرشاد للجويني ص 183، ولمع الأدلة ص 118، 119، وأصول الدين للبغدادي ص 99، والغنية في أصول الدين للمتولي ص 146.\r\r1) وفي ذلك ورد قوله صلى الله عليه وسلم: «إن الله لا يجمع أمتي (أوقال) أمة محمد صلى الله عليه وسلم على ضلالة، ويد الله مع الجماعة، ومن شذ شذ في النار». وقال الترمذي فيه كتاب الفتن 7 ج 4 ص 466 رقم 2167: «هذا حديث غريب من هذا الوجه» إذ رواه من طريق سليمان المدني عن عبد الله بن دينار. ورواه الدارمي في السنن، المقدمة 8 ج 1 ص 42: «وإن الله عز وجل وعدني في أمتي وأجارهم من ثلاث ألا يعمهم بسنة، ولا يستأصلهم عدو، ولا يجمعهم على ضلالة».\rوفي سنده معاوية بن صالح تكلم فيه يحيى بن سعيد وأبوإسحاق الفزاري، ووثقه آخرون. انظر تهذيب الكمال للمزي ج 28 ص 189، 190، وفي سنده أيضا عبد الله بن صالح، تكلم فيه الإمام أحمد بن حنبل رضي الله عنه، وتكلم فيه أيضا آخرون. انظر تهذيب الكمال ج 15 ص 102، وفي مسند أحمد بن حنبل ج 5 ص 145: «فإن الله لن يجمع أمتي إلا على هدى»."], [181, "فصل في الوحدانية\r\r"]], "pg": [177, 181]}, "474.29": {"x": [[177, "[فصل]\r[في جواز رؤية الباري عز وجل]\rفأما القسم الثاني، وهوالقول في جواز رؤية الإله تبارك وتعالى 1.\r----------------\rتبارك: ليست في ط.\r____________________\r1) تعتقد الأشاعرة بجواز رؤية الله تعالى من جهة الفعل، وهي واجبة للمؤمين في الآخرة، واعتمدت في الاستدلال على ذلك بأدلة نقلية وأخرى عقلية، ومن الأدلة النقلية قول الله تعالى في قصة موسى عليه السلام: رب أرني أنظر إليك فقد سأل موسى ربه الرؤية، ومن المحال أن يسأل النبي ربه ما يستحيل في حقه، وقوله تعالى: لن تر?اني إنما تضمن عدم وجود الرؤية عند السؤال، لا استحالة الرؤية. ومن الأدلة السمعية قول الله تعالى: وجوه يومئذ ن?اضرة (22) إلى? ربه?ا ن?اظرة (23) فناضرة بمعنى مشرقة، وناظره بمعنى رآئية، ومنها حديث الرؤية، وهوقوله صلى الله عليه وسلم: «خرج علينا رسول الله صلى الله عليه وسلم ليلة البدر فقال: إنكم سترون ربكم يوم القيامة كما ترون هذا لا تضامون في رؤيته». انظر اللمع للأشعري ص 110، والإبانة ص 30، ومجرد مقالات الأشعري لابن فورك ص 79، والإنصاف للباقلاني ص 42، 156، والتمهيد ص 301، وأصول الدين للبغدادي ص 97، والفرق بين الفرق ص 324، والاعتقاد للبيهقي ص 95، والإرشاد للجويني ص 166، ولمع الأدلة ص 115، والغنية للمتولي ص 142، والملل والنحل للشهرستاني ص 100، ونهاية الإقدام ص 356، والاقتصاد في الاعتقاد للغزالي ص 30، وإحياء علوم الدين ج 1 ص 187، والأربعين للرازي ص 189، ومعالم أصول الدين ص 73، والمحصل في أفكار المتقدمين ص 272، وغاية المرام للآمدي ص 270، وأبكار الأفكار (مخطوط) م 2 ل 192 أ، والمواقف للإيجي ص 299، وفي علم الكلام لأحمد صبحي ج 2 ص 66، ونشأة الأشعرية لجلال موسى ص 258، ومذاهب الإسلاميين لعبد الرحمن بدوي ص 548.\rوانظر موقف الماتريدية من هذه المسألة في التوحيد للماتريدي ص 77، وتبصرة الأدلة لأبي المعين النسفي ج 1 ص 387، والتمهيد في أصول الدين ص 38. ="], [178, "وهذا قد طال فيه ارتباك طبقات الخلق، وحسبه الشادون 1 من الجليات، والانتهاء إلى درك القطع فيه عسير جدا، فإن الإحاطة بحقائق الإدراكات من أدق أحكام المعقولات. ونحن نستعين بالله ونذكر ما يشهد العقل له بالسداد.\rفليعلم الناظر في هذا الفصل، أن الذين أحالوا رؤية الإله، بنوا عقدهم على ظن فاسد 2، وذلك أنهم ظنوا أن الإحساس الذي هوتحديق في صوب المرئي، هوالذي يدعي أهل الحق تعلق قبيله بوجود الإله، وهذا زلل وسوء ظن بعصبة أهل الحق-تعالى الله أن يحس-ولكن ما أحسسناه من المرئيات ندرك حقيقته، وإدراكنا حقيقته ليس هوالمحسوسات المفسرة بمقابلة واتصال أشعة 3 4.\rفقال أهل الحق: لا يمتنع في قدرة الله سبحانه، أن يخصص من أراد بصفة، هي في التعلق بوجوده بالإضافة إلى العلم، كالإدراك المتعلق\r-------------\rفي ط: مثله. في ط: الإحساس المفسر.\rفي ط: تعالى. في أ: التعليق، والمثبت من ط.\rفي أ: المعلق، والمثبت من ط.\r_______________\r= وانظر رأي أهل السلف في الرد على الجهمية لأحمد بن حنبل ص 127، والعقيدة لأحمد بن حنبل (رواية الخلال) ص 111، والعقيدة الواسطية لابن تيمية ص 39، والمعتمد للقاضي أبي يعلى ص 82، ورد الإمام الدارمي ص 413، وشرح الطحاوية ص 163، 195، وشرح الأصول لأبي القاسم اللالكائي ج 3 ص 470، والسنة لابن أبي عاصم ص 188 - 204، ومعالم السنن للخطابي ج 4 ص 302، والإيمان لابن منده ج 2 ص 779، والشريعة للآجري ص 251، وانظر أيضا كتاب الرؤية (مخطوط) للدارقطني، وهناك مخطوط للجويني يحمل عنوان «مسألة في الرؤية» وهوموجود بمكتبة الإمبروزيانا.\r1) هم المتعاملون أوالمتفيهقون الذين لا نصيب كبير لهم في العلم.\r2) عنى الجويني هنا المعتزلة.\r3) انظر مناقشة القاضي عبد الجبار لما ذهبت إليه الأشاعرة في الرؤية، شرح أصول الخمسة ص 232 - 277، وانظر ما ذكره الجويني هنا في المصدر نفسه ص 248، والمغني في أبواب التوحيد والعدل ج 4 ص 36 وما بعدها.\r4) قارن بالإرشاد للجويني ص 171،172."], [179, "بالمدركات، شاهد بالإضافة إلى العلم بها على الغيب من غير درك. ثم تلك الصفة من مقدورات الباري تبارك وتعالى، وهي لا تتناهى، وما لم يحله العقل التحق بالجائزات، سيما إذا اعتقد بالنصوص القاطعة في الكتاب والسنة.\rوأقوى متمسك في السمع شيئان، أحدهما: سؤال موسى عليه السلام الرؤية 1، مع الوفاق على أن [كل] من كان في منصب النبوة، يستحيل أن يعتقد في حكم ربه ما يوجب تضليلا 2.\rونفاة الرؤية، إذا اقتصدوا ولم يبوحوا بسوء اعتقادهم في الخصوم، اقتصروا على تضليلهم. وكيف يستجيز منتم إلى الدين، أن يفضل سفلة نفاة الرؤية 3 في معرفة الله تبارك وتعالى على موسى صلى الله عليه وسلم!\rنعم، لا يمتنع أن يذهل النبي [صلى الله عليه وسلم] عن الغيب، ويستفزه الوله على سؤال ما علم جوازه 4 وإن لم يبلغه دخول وقته، وهذا أحد الشيئين.\r------------------\rفي ط: مشاهدة. تبارك: ليست في ط.\rفي ط: اعتضد. في ط: وأحرى.\rفي ط: صلى الله على نبينا وعليه وسلم.\rالزيادة من ط. في أ: من، والمثبت من ط.\rحكم: ليست في ط. في أ: بسر، والمثبت من ط.\rفي أ: عقدهم، والمثبت من ط.\rتبارك: ليس في ط.\rصلى الله عليه وسلم: ليست في ط.\rالزيادة من ط. في ط: المغيب. في أ: ويستقره. في ط: فهذا.\r____________________\r1) وفي ذلك ورد قول الله تعالى: ولما جاء موسى لميقاتنا وكلمه ربه قال رب أرني أنظر إليك قال لن تراني ولكن انظر إلى الجبل فإن استقر مك?انه فسوف تراني فلما تجلى ربه للجبل جعله دكا وخر موسى صعقا فلما أفاق قال سبحانك تبت إليك وأنا أول المؤمنين (143) سورة الأعراف، الآية 143.\r2) يكرر الجويني هنا ما ورد في الإبانة للأشعري ص 34، والإنصاف للباقلاني ص 156، والتمهيد ص 302، والغنية للمتولي ص 146.\r3) في الإرشاد ص 183 «حثالة المعتزلة».\r4) في الإبانة للأشعري ص 34: «ولا يجوز أن يكون موسى عليه السلام قد ألبسه الله تعالى جلباب النبيين، وعصمه بما عصم به المرسلين، قد سأل ربه ما يستحيل عليه، ="], [180, "والثاني: أنا نعلم قطعا، علم من لا يتمارى، أن الأولين، كانوا مبتهلين إلى الله تبارك وتعالى في سؤال الرؤية، ابتهالهم إليه في سؤال كل ممكن من ثواب أومغفرة، ومن جحد هذا هومعاند، والأمة معصومة لا تجتمع على الضلالة 1.\rولسنا ندعي الإجماع مع ظهور الخلاف الآن، ولكننا ندعي بقدم الإجماع من سلف الأمة قبل ظهور الآراء واختلاف الأهواء. فذلك ما أردناه في هذا الفصل، وقد نجز بانتهاء هذا الفصل، غرضنا من هذا المعتقد في أقسام الأحكام الإلهية.\r---------------\rفي أ: أن، وما أثبته من ط. علم: ليست في ط.\rفي ط: يتمارى فيه. في سؤال الرؤية ابتهالهم إليه: ليست في ط.\rفي أ: مغاور، وما أثبته من ط. الآن: ليست في ط.\rفي ط: فهذا. في ط: في.\r_________________________\r= وإذا لم يجز ذلك على موسى فقد علمنا أنه لم يسأل ربه مستحيلا، وأن الرؤية جائزة على ربنا عز وجل، ولوكانت الرؤية مستحيلة على ربنا كما زعمت المعتزلة، ولم يعلم ذلك موسى عليه السلام، وعلموا هم، لكانوا على قولهم أعلم بالله من موسى عليه السلام، وهذا ما لا يدعيه مسلم». وانظر أيضا اللمع للأشعري ص 192، والإنصاف للباقلاني ص 160، والتمهيد ص 302، والإرشاد للجويني ص 183، ولمع الأدلة ص 118، 119، وأصول الدين للبغدادي ص 99، والغنية في أصول الدين للمتولي ص 146.\r\r1) وفي ذلك ورد قوله صلى الله عليه وسلم: «إن الله لا يجمع أمتي (أوقال) أمة محمد صلى الله عليه وسلم على ضلالة، ويد الله مع الجماعة، ومن شذ شذ في النار». وقال الترمذي فيه كتاب الفتن 7 ج 4 ص 466 رقم 2167: «هذا حديث غريب من هذا الوجه» إذ رواه من طريق سليمان المدني عن عبد الله بن دينار. ورواه الدارمي في السنن، المقدمة 8 ج 1 ص 42: «وإن الله عز وجل وعدني في أمتي وأجارهم من ثلاث ألا يعمهم بسنة، ولا يستأصلهم عدو، ولا يجمعهم على ضلالة».\rوفي سنده معاوية بن صالح تكلم فيه يحيى بن سعيد وأبوإسحاق الفزاري، ووثقه آخرون. انظر تهذيب الكمال للمزي ج 28 ص 189، 190، وفي سنده أيضا عبد الله بن صالح، تكلم فيه الإمام أحمد بن حنبل رضي الله عنه، وتكلم فيه أيضا آخرون. انظر تهذيب الكمال ج 15 ص 102، وفي مسند أحمد بن حنبل ج 5 ص 145: «فإن الله لن يجمع أمتي إلا على هدى»."], [181, "فصل في الوحدانية\r\r"]], "pg": [177, 181]}, "474.30": {"x": [[181, "فإن قيل: [لم] لم تدرجوا إثبات الوحدانية في قسم من الأقسام الثلاثة\rقلنا: ذكرنا ما يجب لله تبارك وتعالى، و [ما] يستحيل عليه، ويجوز في حكمه، فالسؤال عن تقدير مدبر ثان، يقع وراء الضبط المقصود، فانسل هذا الفصل المقصود عن ترتيب المعتقد. ونحن نذكر فيه بعد هذا التنبيه ما يستقل به اللبيب إذا وقف على معانيه.\rفإن قيل: فهلا رتبتم هذا الفصل على ما يجب لله تعالى، فإن الوحدانية صفته الواجبة.\rقلنا: محصول الوحدانية، يؤول إلى نفي من سوى الواحد، فليست صفة ثابتة.\rفإن قيل: فهل ألحقتم القول في ذلك بما يستحيل، فإن تقدير الثاني محال.\rقلنا: نحن ضمنا هذا الفصل ما يستحيل في صفات الإله، ولم يلتزم أن يذكر كل محال، وليس تقدير الثاني متعلقا بصفة الإله الحق، وسبيل من\r----------------\rالزيادة من ط. الزيادة من ط.\rفي ط: على تقرير. في ط: مديد كان.\rفي أ: وانسل.\rإذا وقف على معانيه، ليست في ط.\rفي أ: هلا. الواجبة: ليست في ط.\rفي ط: ثانية. في أ: فهل.\rفي ط: صفة. في ط: يلزم أن نذكر."], [182, "انتهى إلى هذا الموضع ألا يتبرم بترديد القول في الترتيب، فإن أسرار المعقولات تتلقى من سداد ترتيبها.\rوقد حان بعد ذلك أن نذكر معتمدا وجيزا في الوحدانية، يشفي غلة الصدور، وينفس/عن كل مصدور 1.\rفليعلم العاقل أن الإله تعالى لا يناسب الأجرام المتحيزة، والأجسام لا تناسبه، فابتنى على ذلك اتساق إطلاق القول بتغاير المتحيز، والموجود الأزلي الذي لا يناسب الحيز.\rوإذا فرضنا موجودين متجيزين، كانا متغايرين وإن اتصفا بأصل التحيز، لانفراد كل واحد بحيزه عن الثاني، ولوقدرنا موجودين لا يتحيز واحد منهما، [فهما] متساويان في انتفاء التحيز عنهما، فلا يتصور أن ينفرد أحدهما بحيز عن الثاني، وليس أحدهما مختصا بالثاني اختصاص الصفة بالموصوف، فلا يعقلان متميزين تميز اختصاص، فإن لم يختص أحدهما [بحيز] عن الثاني، ولم يختص بالثاني، لم يتعددا قطعا.\rوها أنا أذكر نكتة، يسعد والله من يعيها، ويفوز الفوز الأكبر من يدريها، وهي: أن استحالة موجودين متغايرين، لا يختص أحدهما عن الثاني بحيز، ولا يختص به في الخروج عن المعقول كفرضين متحيزين في\r-------------------\rفي ط: أن لا. في أ: فيشفي، والمثبت من ط.\rمن قوله: والأجسام. . . المتحيز، ليست في ط.\rفي أ: الوجود، والمثبت من ط.\rالزيادة من ط.\rفي أ: مستويان، وما أثبته من ط.\rيتصور أن: ليست في ط.\r8) فلا يعقلان متميزين تميز اختصاص، ليست في ط، وكرر الناسخ بعدها قوله: وليس أحدهما مختصا بالثاني اختصاص الصفة بالموصوف.\r\rفي ط: فإذا. الزيادة من ط.\rفي أ: يعقلا، وما أثبته من ط.\rفي أ: لفظة، وما أثبته من ط.\rوالله: ليست في ط. في ط: كفرضى.\r________________\r1) المصدور: الذي يشتكي صدره. انظر لسان العرب ج 4 ص 446 مادة (صدر)."], [183, "حيز واحد 1.\rفيا سعادة من أنعم فكره في هذا قليلا، ولم يتجاوزه حتى تنضجه نار الفكرة، وتنقده يد السبر!\r----------------\rفي ط: حد.\r______________________\r1) اعتمد الجويني في بيانه هذا على مسألة أصولية كانت محل اختلاف بين الأشاعرة والمعتزلة، وهي مسألة المثلين والغيرين، والمثلين عند الأشاعرة هما ما سد أحدهما مسد صاحبه وجاز عليه جميع ما جاز عليه نحوالحركتين، لأنه لا يصح وجودهما معا في محل واحد في وقت واحد، والاشتراك في الأخص يوجب الاشتراك فيما عداه من الصفات غير المعللة، وحد الغيرين كل شيئين تجوز مفارقة أحدهما الآخر بوجه من وجوه المفارقات، ووجوه المفارقات ثلاثة، مفارقة بالزمان، ومفارقة بالمكان، ومفارقة بالعدم والوجود. ويعتمد الجويني في إثبات وحدانية الله تعالى على إثبات المفارقة بالمكان (التحيز). انظر الإشارة إلى مذهب أهل الحق للشيرازي، الملحق رقم (1) ص 180، والإرشاد للجويني ص 34 - 37، والغنية للمتولي ص 79، 80."], [184, "باب في العبودية والصفات المرعية\rفي ثبوت الطلبات التكليفية\r\r"]], "pg": [181, 184]}, "474.31": {"x": [[184, "القول في إمكان التكليف وجوازه عقلا، يتعلق بأربعة أركان نذكرها مفصلة، ولا نقدم رسم ترجمتها، فإن العبارة قبل التفصيل قد يقعد عن بعضها، وإذا وضح الغرض نذكر تفصيلها، فهوالوفاء بالمقصود.\rالركن الأول: في قدرة العبد وتأثيرها في مقدورها "]], "pg": [184, 184]}, "474.32": {"x": [[184, "1، فنقول:\r---------------\rولا: ليست في ط. في ط: أهم.\rفي أ: تتعقد، والمثبت من ط.\rفي ط: يذكر.\r___________________\r1) هذه المسألة فرع قاعدة خلق أفعال العباد التي بحثت فيها الأشاعرة إشكاليات الجبر والاختيار في الفعل الإنساني، وقد قررت الأشاعرة أن عناصر هذا الفعل ثلاثة هي العلم والإرادة والقدرة، وفيما يتعلق بالعلم فلا خلاف بين تقريراتهم وما ذهبت إليه المعتزلة بهذا الخصوص، أما فيما يتعلق بالإرادة فقد ذهبت الأشاعرة إلى أن الله مريد للأفعال جميعا خيرها وشرها، وأن الإرادة الإنسانية لا تتخطى في مراداتها الإرادة الإلهية عملا بما أجمعت عليه الأمة «ما شاء الله كان وما لم يشأ لم يكن»، وقوله تعالى: وم?ا تش?اؤن إلا? أن يش?اء الل?ه، كذلك ميزت الأشاعرة بين الإرادة الكونية التي ليس للإنسان نصيب في دفعها، والإرادة التشريعية التي حفظت للإرادة الإنسانية نصيبا من حرية الاختيار. أما المعتزلة فقد نفت أن تكون الإرادة الإلهية قديمة وإنما هي حادثة، وأن الله تعالى لا يريد ما قبح من الأفعال، وتقع هذه بإرادة الإنسان وبمعزل عن إرادة الخالق. وفيما يتعلق بالعنصر الثالث من عناصر الفعل الإنساني وهوالقدرة، فقد تفاوت موقف الأشاعرة منها، فمنهم من نفى تأثير القدرة بمقدوراتها، ومنهم من قال: إنها تؤثر في حالة معينة في المقدور، ومنهم قرر صراحة بحصول هذا التأثير انظر إشكاليات الجبر والاختيار عند الأشاعرة ص 68، 102."], [185, "قد تقرر عند كل حاظ بعقله، مترق عن مراتب التقليد في قواعد التوحيد، أن الرب سبحانه وتعالى مطالب عباده بأعمالهم في حياتهم، وداعيهم إليها، ومبتليهم ومعاقبهم عليها في مآلهم.\rوتبين بالنصوص التي لا تتعرض للتأويلات، أنه أقدرهم على الوفاء بما طالبهم به، ومكنهم من التوصل إلى امتثال الأمر، والانكفاف عن مواقع الزجر. ولوذهبت أتلوالآي المتضمنة لهذه/المعاني لطال المرام، ولا حاجة إلى ذلك مع قطع اللبيب المنصف به.\rومن نظر في كليات الشرائع وما فيها من الاستحثاث على المكرمات، والزواجر عن الفواحش الموبقات، وما نيط ببعضها من الحدود والعقوبات، والتفت إلى الوعد والوعيد، وما يجب عقده من تصديق المرسلين، في الإنباء عما يتوجه على المردة العتاة من الحساب والعقاب، وسوء المنقلب والمآب، وقول الله تبارك وتعالى لهم: لم اعتديتم وعصيتم وأبيتم وقد أرخيت لكم الطول 1، وفسحت لكم المهل، وأرسلت الرسل، وأوضحت المحجة لئلا? يكون للن?اس على الل?ه حجة بعد الرسل 2.\rفمن أحاط بذلك كله، ثم استراب في أن أفعال العباد واقعة على حسب إيثارهم واختيارهم واقتدارهم 3، فهومصاب في عقله، أومستقر\r___________________________-\rفي أ: مترقي، والمثبت من ط.\rسبحانه: ليست في ط. في أ: حالهم وأداعيهم.\rفي أ: ما الهم. في أ: كتاب.\rفي ط: ثم التفت. في أ: على.\rفي أ: والعناد. في ط: تعديتم.\rالله: ليست في ط. في ط: وأحاط.\rفي ط: مستمر.\r___________________\r1) الطول: الحبل. لسان العرب ج 11 ص 412، انظر (مادة طول).\r2) سورة النساء، الآية 165.\r3) نسب نفي القدرة عن الإنسان في إيقاع أفعاله إلى الجهم بن صفوان، إذ أجمعت النصوص على أنه سلب عن الإنسان القدرة على أفعاله، فهوأشبه بالريشة في مهب ="], [186, "على تقليده مصمم على جهله. ففي المصير إلى أنه لا أثر لقدرة العبد في فعله قطع طلبات الشرائع، والتكذيب بما جاء به المرسلون.\rفإن زعم زاعم ممن لم يوفق لمنهج الرشاد، أنه لا أثر لقدرة العبد في مقدورها أصلا 1، فإذا طولب بمتعلق طلب الله تعالى بفعل العبد تحريما في ط: فإن زعم من.\r-------------------\rفي أ: مقدوره.\r_______________________\r= الريح لا حول له ولا قوة، وكان هذا منه حتى ينتفي الشبه بين الخالق والمخلوق، فالله سبحانه هوالقادر وهوخالق أفعال العباد، أما العباد فهم محل لأثر هذه القدرة، ولا قدر لهم لأن ثبوتها لهم يؤدي إلى تشبيه الخلق بالخالق. وهذا ما جاء في المصادر، لكن مشاركة الجهم في الثورة ضد بني أمية ومقتله، وبالتالي الانفصام بين موقفه العقدي ومسلكه، يجعل من درء الشك في هذه النصوص أمرا عسرا، أوأنه يمكن القول: إن الجهم قد غير من موقفه العقدي في مسألة أفعال العباد، وأثبت قدرة الإنسان على أفعاله وإمكان تغيير الواقع بالسعي إلى ذلك. انظر الشهرستاني، الملل والنحل ص 87، والإسفراييني التبصير في الدين ص 96.\r\r1) اشتهر هذا القول عن أبي الحسن الأشعري، الذي نادى بالكسب لتفسير أفعال العباد، وفسر الكسب بأنه ما وقع بالقدرة الحادثة، فعند ما تتعلق إرادة الإنسان بفعل ما فإن الله يخلق فيه قدرة تكسب الفعل، لكن هذه القدرة لا أثر لها في مقدورها إلا من باب الاكتساب. أما إيجاد الفعل فهوخلق من الله تعالى، فالفعل الإنساني يقع من جهتين مختلفتين، فهويقع من جهة الله تعالى خلقا، ومن جهة الإنسان كسبا، لذا بادر خصوم الأشعري إلى التشنيع بقوله هذا وعدوه من محالات الكلام فقالوا: محالات الكلام ثلاث: طفرة النظام وأحوال أبي هاشم وكسب الأشعري.\rلكن القارئ لكتب الأشعري نفسه التي وصلت إلينا لن يقف على نص له في منع تأثير القدرة في مقدورها، وإنما سيجد تحرزا من القول بأن المقدور يوجد بالقدرة الحادثة مستقلة في ذلك عن القدرة الإلهية، خوفا من الوقوع بما ذهبت إليه المعتزلة بأن القدرة الحادثة تستقل في إيجاد مقدورها. وقد بين ابن فورك في كتابه مجرد مقالات الأشعري حقيقة موقف الأشعري من الكسب وأثر القدرة في مقدورها، ومن النصوص التي ذكرها ابن فورك عن الأشعري: «وكان يذهب في تحقيق معنى الكسب-والعبارة عنه-أنه ما وقع بقدرة محدثة» «وكان يقول إن عين الكسب وقع على الحقيقة بقدرة محدثة ووقع على الحقيقة بقدرة قديمة» «وكان يقول إن الإنسان يصح أن يوصف بأنه مقدر على الحقيقة، ولكن تقديره يكون مخلوقا لله تبارك وتعالى» والأشعري إجمالا أجاز وقوع مقدور بين قادرين ومنع حصول فعل بين فاعلين. انظر مجرد المقالات لابن فورك ص 91 - 98."], [187, "وفرضا؛ ذهب [في] الجواب طولا وعرضا، وقال: لله أن يفعل ما يشاء، ولا يتعرض للاعتراض عليه المعترضون لا? يسئل عم?ا يفعل وهم يسئلون 1.\rقيل [له]: ليس لما جئت به حاصل، كلمة حق أريد بها باطل، نعم؛ يفعل الله ما يشاء، ويحكم ما يريد، ولكن يتقدس عن الخلف 2، ونقيض الصدق. وقد فهمنا بضرورات العقول من الشرع المنقول، أنه-عزت قدرته - طالب عباده بما أخبر أنهم متمكنون من الوفاء به، ولم يكلفهم إلا على مبلغ الطاقة والوسع في موارد الشرع 3.\rومن زعم أنه لا أثر للقدرة الحادثة في مقدورها، كما لا أثر للعلم في معلومه 4، فوجه مطالبته العبد بأفعاله عنده، كوجه مطالبته أن يثبت في نفسه\r----------------\rالزيادة من ط. الزيادة من ط.\rعزت قدرته، ليست في ط وكتب بدلا عنها: تعالى.\rعلى: ليست في ط. في أ: من.\r_______________________\r1) سورة الأنبياء، الآية 23.\r2) لما قاله الله تعالى: فأم?ا من أعطى? واتقى? (5) وصدق بالحسنى? (6) فسنيسره لليسرى? (7) وأم?ا من بخل واستغنى? (8) وكذب بالحسنى? (9) فسنيسره للعسرى? (10) سورة الليل، الآيات 5 - 10.\r3) أجازت الأشاعرة تكليف الله لعباده بما لا يطاق عقلا، لكنهم نفوا أن يكون قد ورد في الشرع ما كلف الله عباده بما لا يطيقونه عملا بقوله تعالى: لا? يكلف الل?ه نفسا إلا? وسعه?ا وإلا كان الدعاء بقوله تعالى: ولا? تحملن?ا م?ا لا? ط?اقة لن?ا به لا معنى له. وإجمالا ذهب الأشعري إلى أن التكليف بما لا يطاق على ضربين، الأول: هوما لا يستطيعه الإنسان لأنه مشغول بضده وصرف جهده عنه، وهذا التكليف جائز، لأن العجز عن الفعل في هذه الحالة هواختياري أوهوجبر مبني على اختيار الإنسان والمسؤولية قائمة فيه. والثاني: هوالذي يعجز عنه العبد لعدم القدرة عليه ابتداء، وهذا النوع لا يكلف الله به أحدا.\rانظر اللمع للأشعري ص 136، 137، والإبانة ص 142 وما بعدها، ومجرد المقالات لابن فورك ص 111، والتمهيد للباقلاني ص 332، وأصول الدين للبغدادي ص 212.\r4) وفي ذلك يقول الأشعري: «إن تعلق القدرة يختلف دون تعلق العلم والسمع والبصر والذكر والخبر، لأن تعلقها مختص بأن يحصل المقدور بها على صفة، فيحصل"], [188, "ألوانا وإدراكات 1. وهذا خروج عن حد الاعتدال، إلى التزام الباطل والمحال، وفيه إبطال/الشرع ورد ما جاء به النبيون عليهم السلام.\rفإذن؛ لزم المصير إلى أن القدرة الحادثة تؤثر في مقدورها، واستحال إطلاق القول بأن العبد خالق أعماله، فإن فيه الخروج عما درج عليه سلف الأمة، واقتحام ورطات الضلال.\rولا سبيل إلى المصير إلى وقوع فعل العبد بقدرته الحادثة والقدرة القديمة 2، فإن الفعل الواحد يستحيل حدوثه بقادرين 3، إذ الواحد لا ينقسم، فإن وقع بقدرة الله سبحانه استقل بها، وسقط أثر القدرة الحادثة.\rويستحيل أن يقع بعضه بقدرة الله جل وعز، فإن الفعل الواحد لا بعض له.\rوهذه مهواة لا يسلم من غوائلها إلا مرشد موفق، إذ المرء بين أن في ط: الصلاة والسلام.\r--------------------\rفي ط: فإذا. في أ: مهولة، وما أثبته من ط.\r________________________\r= بقدرة الله على صفة الحدوث وبقدرة المحدث على صفة الاكتساب. . . [و] العلم لا يختص معلوما والقدرة تختص مقدورا، فوجد أن لها من الحكم ما ليس للعلم من التساوي في التعلق، كما لم يكن لها التساوي في تعميم النوع والجنس» المجرد لابن فورك ص 92.\r\r1) وفي أصول الدين للبغدادي ص 136: «ويدل على بطلان قولهم من القياس، إن الخالق للشيء يجب أن يكون قادرا على إعادته، كالخالق للأجسام والألوان قادر على إعادتها».\r2) وقد ضرب الأشاعرة على ذلك مثلا بالحجر الكبير قد يعجز عن حمله رجل ويقدر آخر على حمله منفردا به، إذ اجتمعا جميعا على حمله كان حصول الحمل بأقواهما ولا خرج أضعفها بذلك عن كونه حاملا، كذلك العبد لا يقدر على الانفراد بفعله، ولوأراد الله الانفراد بإحداث ما هوكسب للعبد قدر عليه ووجد مقدوره، فوجوده على الحقيقة بقدرة الله تعالى، ولا يخرج مع ذلك المكتسب من كونه فاعلا وإن وجد الفعل بقوة الله تعالى» أصول الدين للبغدادي ص 134.\r3) كان أبوالحسن الأشعري: «لا يمنع من إطلاق القول بمقدورين قادرين أحدهما خالقه والآخر مكتسبه، وكان يمنع إطلاق القول بفعل بين فاعلين حقيقة» المجرد لابن فورك ص 92."], [189, "يدعي الاستبداد بالخلق 1، وبين أن يخرج نفسه عن كونه مطالبا بالشرائع- وفيه إبطال دعوة الأنبياء عليهم السلام -وبين أن يثبت نفسه شريكا لله تبارك وتعالى في إيجاد الفعل الواحد.\rوهذه الأقسام بجملتها باطلة، ولا ينجي من هذا البحر الملتطم ذكر اسم محض، ولقب مجرد من غير تحصيل معنى. وذلك أن قائلا لوقال: العبد مكتسب وأثر قدرته الاكتساب، والرب تبارك وتعالى مخترع وخالق لما العبد مكتسب له 2.\r----------------\rعليهم السلام: ليست في ط.\rفي أ: من، وما أثبته من ط.\rتبارك وتعالى: ليست في ط.\rفي ط: المتلطم. في ط: مختص.\rفي أ: خالق. في ط: مكتسبه.\r________________\r1) وفي ذلك إشارة إلى المعتزلة الذين ادعوا أن الإنسان مريد لأفعاله حقيقة، موجد لها بقدرته على الحقيقة، ولا علاقة لإرادة الله وقدرته في صدور هذه الأفعال، فالإنسان سيد أفعاله يختارها بنفسه دون تدخل إلهي. انظر الإبانة للأشعري ص 146، وشرح الأصول الخمسة للقاضي عبد الجبار ص 348، 349، والمغني في التوحيد والعدل ج 8 ص 257، ودي بور، تاريخ الفلسفة ص 101.\r2) هذا قول الأشاعرة بعامة مقتدين في ذلك بشيخهم أبي الحسن الأشعري الذي قرر أن خلق الفعل على الحقيقة يتم بقدرة الله المطلقة، أما اكتسابه على الحقيقة فإنه يتم بقدرة حادثة خارجة عن الذات وزائدة عليها، وقد أخذ بذلك كل من أبي إسحاق الإسفراييني، وابن فورك والبيهقي وعبد القاهر البغدادي وأبي إسحاق الشيرازي وأبي سعيد المتولي والكياهراسي والشهرستاني والفخر الرازي وسيف الدين الآمدي وعضد الدين الإيجي.\rوكان هؤلاء الأشاعرة بمثابة شراح لما قرره شيخهم الأشعري ومدافعين عن نظريته في الكسب أمام الخصوم من الفرق الأخرى ومنتقدي الأشعري، حتى إن هؤلاء قد وسعوا دائرة نقدهم لتطال بعض زملائهم من الأشاعرة كالباقلاني والجويني ومحاولتهما لتطوير نظرية الكسب، فقد افترق الباقلاني عن الأشعري بأن أثبت تأثير خاصا لهذه القدرة في صفة الفعل أوحاله، فالقدرة المحدثة وإن لم يكن لها تأثيرا في إيجاد الفعل نفسه من جهة الوجود، إلا أن لها تأثيرا في إيجاد الفعل على صفة معينة، فالحركة وهي جنس عام مخلوق لله تعالى وواقع بقدرته، أما الأنواع التي تنضوي تحت هذا الجنس الأعم، ككون «هذه الحركة طاعة أومعصية، قياما أوقعودا، إقداما أوإحجاما، كفرا أوإيمانا، فهي واقعة بقدرة العبد»."], [190, "قيل له: فما الكسب، وما معناه وأديرت الأقسام المتقدمة على هذا القائل، فلا يجد عنها مهربا 1.\rفإن قيل: لم تذكروا قولا مقنعا في الرد على من يزعم أن العبد مخترع، خالق لأفعاله.\rقلنا: المسلمون بأجمع قاطبة، قبل أن ظهرت البدع والآراء، ونبع أصحاب الأهواء، على أنه لا خالق إلا الله، كما لهجوا بأنه لا إله إلا الله. وتمدح الله سبحانه وتعالى بالخلق في آي من كتابه منها:\rقوله تبارك وتعالى: أفمن يخلق كمن لا يخلق 2. وقوله تبارك وتعالى: خ?الق كل شيء 3.\r-------------------\rفي أ: المقدرة، وما أثبته من ط.\rفي ط: عنه. في ط: قد أجمع المسلمون.\rقاطبة: ليست في ط.\rفي ط: أن. في ط: الله تعالى.\rفي ط: لهجوبلا إله.\rسبحانه وتعالى: ليست في ط.\rفي أ: الكتاب. تبارك وتعالى: ليست في ط.\rتبارك وتعالى: ليست في ط.\rخالق كل شيء: ليست في ط.\r____________________________\r= انظر في ذلك: مجرد مقالات الأشعري لابن فورك ص 92، والتمهيد للباقلاني ص 347، وأصول الدين للبغدادي ص 133، والغنية في أصول الدين للمتولي ص 117، والاقتصاد في الاعتقاد للغزالي ص 43، وأصول الدين للكياهراسي (مخطوط) ل 173 ب، ونهاية الإقدام في علم الكلام للشهرستاني ص 69، وإثبات القدر للبيهقي (مخطوط) ل. . .، والإشارة إلى مذهب أهل الحق للشيرازي ص 207، 297، ومعالم أصول الدين للرازي ص 89، والمطالب العالية ج 9 ص 10، 40، وغاية المرام لسيف الدين الآمدي ص 214، وأبكار الأفكار في أصول الدين (مخطوط) ج 1 ل 211 أ، والمواقف لعضد الدين الإيجي ص 312.\r\r1) يكرر الجويني الاعتراض نفسه الذي حاول القاضي عبد الجبار الهمذاني من خلاله بيان عدم معقولية الكسب، وما دام الكسب ليس معقولا فلا يمكن تعريفه. انظر عبد الجبار الهمذاني، شرح الأصول الخمسة ص 365، 367.\r2) سورة النحل، الآية 17.\r3) سورة الأنعام، الآية 102، سورة الرعد، الآية 16، وسورة الزمر، الآية 62، وسورة غافر، الآية 62."], [191, "وقوله: وخلق كل شيء 1. وقوله تبارك وتعالى: هل من خ?الق غير الله 2.\rولا يشك لبيب أن من وصف نفسه بكونه خالقا على التحقيق، فقد أعظم الفرية، وأتى ما لونطق به ناطق في الأولين، لتعرض للكسر العظيم والرد البليغ.\rوكيف يتصف العبد بكونه خالقا وهولا يحيط علما بتفاصيل أفعاله 3 ومن لم يعلم حقيقة ما صدر منه، ولم يحط بمقداره ومبلغه، كيف يكون خالقه والعلم بالشيء أقرب من خلقه، وهذا معنى قوله سبحانه وتعالى:\rوأسروا قولكم أواجهروا به إنه عليم بذ?ات الصدور (13) 4 [و] أ لا? يعلم من خلق 5. فدل مقتضى الآية أن العالم بحقائق الحادثات بارئها وخالقها 6. وقد تقرر في قضايا العقول، أن الأفعال دالة على علم خالقها بها، فإذا صدرت أفعال من العبد في حالة ذهوله عنها، فهي غير دالة على علم العبد بها، فإنه غير عالم بما جرت يده به في حال غفلته وذهوله، والنائم غير شاعر تبارك وتعالى:\r---------------\rليست في ط. في ط: كونه.\rمن قوله: وأتى ما لونطق. . . العبد، ليست في ط، وحل محلها: لكونه ادعى كونه.\rفي ط: لكونه. سبحانه: ليست في ط.\rالزيادة من ط. في ط: ذهول.\r_______________________\r1) سورة الأنعام، الآية 101.\r2) سورة فاطر، الآية 3.\r3) هذا الاعتراض هوالمعول عليه عند الأشاعرة لإبطال ما ذهبت إليه المعتزلة في كون العبد خالقا لأفعاله، وأول من قال به أبوالحسن الأشعري. انظر مجرد مقالات الأشعري لابن فورك ص 93، والتمهيد للباقلاني ص 342، والإرشاد للجويني ص 191، 192، والغنية في أصول الدين للمتولي ص 118.\r4) سورة الملك، الآية 13.\r5) سورة الملك، الآية 14.\r6) ينقل الجويني هنا ما أورده الباقلاني في التمهيد ص 344، وانظر أيضا اللمع للأشعري ص 127."], [192, "بتقلباته في غلبات النوم وغمراته. فإذا وجب أن تدل الأفعال على علم خالقها، ثم لم تدل على علم العبد في حال نومه وذهوله، دل أنها دالة على علم خالقها ومقدرها، وهورب العالمين 1.\rفإن قيل: ما ذكرتموه إبطال منكم لأقسام الكلام، وتتبع للمذاهب، ولم توضحوا ما هوالحق بعد.\rقلنا: ليس بمدرك الحق [خفاء] لمن وفق له. وها نحن نبديه بالجرأة من غير تعريض وتعريج على تقليد فنقول: قدرة العبد مخلوقة لله تبارك وتعالى باتفاق القائلين بالصانع، والفعل المقدور بالقدرة الحادثة واقع بها قطعا، ولكنه مضاف إلى الله تبارك وتعالى تقديرا وخلقا، فإنه وقع بفعل الله تبارك وتعالى وهوالقدرة، وليست القدرة فعلا للعبد، وإنما هي صفته، وهي ملك لله تبارك وتعالى وخلق له.\rوإذا كان موقع الفعل خلقا لله، فالواقع به مضاف خلقه للرب تبارك وتعالى وتقديرا، وقد ملك الله العبد اختيارا يصرف به القدرة، فإذا أوقع بالقدرة شيئا آل الواقع إلى حكم الله [تعالى] من حيث أنه وقع بفعل الله تعالى 2.\r---------------\rفي ط: نومه. الزيادة من ط.\rفي ط: بما يحصن به، وكتبت في أ: بجرية.\rفي أ: تقليل، والمثبت من ط.\rفي أ: العالمين. تبارك: ليست في ط.\rفي ط: خلق الله تعالى. في ط: خلقا.\rفي ط: إلى الله تعالى. الزيادة من ط.\r_________________\r1) يكرر الجويني هنا ما ذكره أيضا في الإرشاد ص 190.\r2) ينقلب الجويني هنا على ما ذكره في الإرشاد ص 208 - 210، إذ انتصر لشيخه الأشعري، وقرر أن القدرة الحادثة لا تؤثر في مقدورها أصلا. وهذه الفقرة هي الإسهام الأصيل من قبل الجويني في تطوير نظرية الكسب كما وضعها الأشعري، لذا فقد تعرض الجويني نتيجة قوله هذا لانتقادات الأشاعرة المتأخرين عنه والذين وصفناهم فيما سبق بشراح نظرية الكسب. انظر ص 189 هامش 2."], [193, "ولواهتدت لهذه الفرقة الضالة لما كان بيننا وبينهم خلاف، ولكنهم ادعوا سدادا بالاختراع، وانفرادا بالخلق/والابتداع، فضلوا وأضلوا 1.\rونبين تميزنا عنهم بتفريع المذهبين: فإنا لما أضفنا فعل العبد إلى تقدير الإله، قلنا: أحدث الله تبارك وتعالى القدرة في العبد على أقدار أحاط بها علمه، وهيأ أسباب الفعل، وسلب العبد العلم بالتفاصيل، وأراد من العبد أن يفعل، فأحدث فيه دواعي مستحثة، وخيرة، وإرادة، وعلم أن الأفعال ستقع على قدر معلوم، فوقعت بالقدرة التي اخترعها للعبد على ما علم وأراد.\rوللعباد اختيارهم واتصافهم بالاقتدار، والقدرة خلق الله [تعالى] ابتداء، ومقدورها مضاف إليه مشيئة وعلما وقضاء وخلقا وفعلا، من حيث إنه نتيجة ما انفرد بخلقه وهوالقدرة، ولولم يرد وقوع مقدوره لما أقدره عليه، ولما هيأ أسباب وقوعه 2. ومن هدي لهذا استمر له الحق المبين.\r----------------\rفي أ: اهتديت، والمثبت من ط.\rفي ط: الله تعالى. في أ: القدر، وما أثبته من ط.\rفي أ: الله، والمثبت من ط. الزيادة من ط.\rفي ط: مضاف إلى الله تعالى تقديرا وخلقا.\rفي أ: بخالقه، والمثبت من ط.\rفي ط: أقدر.\r______________________\r1) وقد علق الشهرستاني في نهاية الإقدام ص 78 على قول الجويني قائلا: «وغلا إمام الحرمين، حيث أثبت للقدرة الحادثة أثرا هوالوجود، غير أنه لم يثبت للعبد استقلالا بالوجود ما لم يستند إلى سبب آخر، ثم تتسلسل الأسباب في سلسلة الترقي إلى الباري سبحانه وهوالخالق المبدع المستقل بإبداعة من غير احتياج إلى سبب، وإنما سلك في مسلك الفلاسفة حيث قالوا: بتسلسل الأسباب وتأثير الوسائط الأعلى في القوابل الأدنى».\r2) إن رفض الأشاعرة المتأخرين لرأي الجويني هذا قد قابله قبول تام وثناء في أوساط علماء أهل السنة السلفيين كابن تيمية وابن قيم الجوزية، فابن تيمية عند ما بحث هذه المسألة لم يأت بجديد، وإنما كرر أقوال الجويني السابقة إذ يقول: «والعباد فاعلون حقيقة، والله خالق أفعالهم»، وفي نص آخر يقول: «اعلم أن العبد فاعل على الحقيقة». أما ابن قيم الجوزية، وبعد أن نقل نص الجويني في تأثير قدرة العبد في"], [194, "فالعبد فاعل مختار مطالب مأمور منهي، وفعله تقدير لله، ومراد له، وخلق مقضي له.\rونحن نضرب في ذلك مثلا شرعيا يستروح إليه الناظر في ذلك فنقول:\rالعبد لا يملك أن يتصرف في مال سيده، ولواستبد بالتصرف فيه لم ينفذ تصرفه، فإذا أذن له في بيع ماله فباعه نفذ. والبيع في التحقيق معزي إلى السيد من حيث إن سببه إذنه، فلولا إذنه لم ينفذ التصرف، ولكن العبد يؤمر بالتصرف وينهى ويوبخ على المخالفة ويعاقب. فهذا والله الحق [المبين] الذي لا عطاء دونه، ولا مراء فيه لمن وعاه حق وعيه، ولا يكابر فيه.\rوأما الفرقة الضالة 1؛ فإنهم اعتقدوا انفراد العبد بالخلق، ثم صاروا إلى في أ: والعبد، والمثبت من ط.\r--------------\rفي أ: وفعله تقدير له، مراد له خلق مقضي.\rفي ط: يعزى. في أ: لولا، والمثبت من ط.\rالزيادة من ط. من قوله: لا عطاء. . . يكابر فيه، ليست في ط.\r_______________\r= فعلها تأثيرا حقيقيا، عقب عليه قائلا: «وهذا توسط بين الفريقين. . . وإن كانت قدرة العبد واختياره مؤثران في إيجاد الفعل عنده بإقدار الرب سبحانه وقد أصاب في هذا وأجاد». انظر ابن تيمية، العقيدة الواسطية ص 47، والقضاء والقدر ص 129، وابن قيم الجوزية، شفاء العليل في مسائل القضاء والقدر ص 215.\r\r1) قصد الجويني بقوله هذا القدرية بعامة والمعتزلة بخاصة. . . والمعتزلة ترى إجمالا أن الله تعالى مريد لأفعال العبادات التي أمر بها، أما المباحات فالله تعالى لا يريدها ولا يكرهها، أما الأفعال المتعلقة بالمحرمات التي نهى الله تعالى عنها فهولا يريدها، ذلك أن مريد السفه سفيه، فالإرادة الإنسانية تستقل بإرادة القبيح والمحرم بمعزل عن الإرادة الإلهية.\rأما فيما يتعلق بالقدرة الإنسانية الحادثة فقد أجمعت المعتزلة على أن العباد يقدرون على أفعالهم بقدرة مخلوقة لهم من الله تعالى، وهم عند ما يقولون إن هذه القدرة خالقة لمقدورها فلا يعني ذلك عندهم تساوي دلالة فعل الخلق بين الخالق والمخلوق، فالقدرة الإلهية توجد مقدورها من العدم وتنفرد بذلك، من أجل عرض لوحة التحكم ثانية، انقر على أحد رموزها."], [195, "أنه إذا عصى فقد انفرد بخلق فعله، والرب تبارك وتعالى كاره له فكان العبد على هذا الرأي الفاسد مزاحما لربه في التدبير، موقعا ما أراد إيقاعه، شاء الرب تعالى-على قولهم -أوكره.\rفإن قيل: على ما ذا تحملون آيات الطبع والختم والإضلال في القرآن وهي متضمنة اضطرار الرب تعالى الأشقياء إلى ضلالتهم/.\rقلنا: إذا أتاح الله تعالى حل هذا الإشكال، والجواب عن هذا السؤال، لم يبق على ذوي البصائر بعده غموض. فنقول أولا: من أنبأ الله تعالى عن الطبع على قلوبهم، كانوا مخاطبين بالإيمان، مطالبين بالإسلام، والتزام الأحكام، مطالبة تكليف ودعاء، مع وصفهم بالتمكن والاقتدار والإيثار 1، كما تبارك وتعالى:\r________________\rليست في ط. على قولين: ليست في ط.\rفي أ: ما، وما أثبته من ط. في أ: هل، والمثبت من ط.\rفي ط: سبحانه.\r____________________\r1) -أما قدرة الإنسان الحادثة فهي لا توجد مقدورها من العدم، وهي بالتالي وإن انفردت بإيجاد مقدورها فإنها مخلوقة لله تعالى، إذ لم يوجبوا وقوع المقدور بها، ولوكان الأمر كذلك لأصبح تأثير القدرة في مقدورها تأثير العلة بالمعلول، وهذا ما نفته المعتزلة. انظر ديوان الأصول لأبي رشيد النيسابوري ص 319، والمغني في التوحيد والعدل للقاضي عبد الجبار ج 4 ص 331 - 334.\r1) قررت الأشاعرة أن الله تعالى قد أضاف لنفسه أسباب الهداية والضلال وترك للعبد حرية الأخذ بهذه الأسباب أوالعزوف عنها، فالاهتداء أوالضلال هما كسب للإنسان وفعل له، أما الهداية والإضلال فهما فعل لله تعالى، وقد استدلت الأشاعرة على ذلك بأدلة نقلية وأخرى عقلية، فالهداية بمعنى الدعاء إلى الحق وإقامة الأدلة عليه (البيان والدعوة) تضاف إلى الرسل، وكل داع إلى سبيل الله، وهي عامة لجميع العباد، ودليلهم على ذلك قوله تعالى: والل?ه يدعوا إلى? د?ار السلا?م ويهدي من يش?اء إلى? صر?اط مستقيم (25) وقوله: إنم?ا أنت منذر ولكل قوم ه?اد وقوله: وإنك لتهدي إلى? صر?اط مستقيم. أما المعنى الآخر للهداية وهوخلق الاهتداء في قلوب العباد فهي خاصة بالمؤمنين المهتدين، وفي ذلك ورد قوله تعالى: فمن يرد الل?ه أن يهديه يشرح صدره للإسلا?م وقوله تعالى: إنك لا? تهدي من أحببت ول?كن الل?ه يهدي من يش?اء. أما الطبع والختم والقفل كما في قوله تعالى: ختم الل?ه على? قلوبهم بل طبع الل?ه عليه?ا بكفرهم وجعلن?ا على? قلوبهم أكنة فقد فسرت الأشاعرة ذلك بأن جعلت هذه"], [196, "سبق تقريره في صدر الفصل 1.\rومن اعتقد أنهم كانوا ممنوعين مأمورين، مصدودين قهرا ومدعوين، فالتكليف إذن عنده بمثابة ما لوشد من الرجل يداه ورجلاه رباطا، وألقي في البحر، ثم قيل له: لا تبتل 2. وهذا منتهى لا يحمل شرائع الرسل عليه إلا عابث بنفسه، متجرئ على ربه.\rولا فرق عند هذا القائل، بين أمر التسخير والتكوين في قوله تعالى:\rكونوا قردة خاسئين 3، وقوله تبارك وتعالى: أن يقول له كن فيكون 4، وبين أمر التكليف 5. نعوذ بالله من الركون إلى كل ما ينطق به اللسان من غير مباحثة عن أسرار المعقولات.\rوإذا بطل ذلك، فالوجه في الكلام على هذه الآية-وقد غوى في معانيها أكثر الفرق-أن نقول: إذا أراد الله بعبد خيرا أكمل عقله،\r---------------\rوأتم في ط: أول. في أ: أم مدعو، والمثبت من ط.\rفي أ: إذا، وما أثبته من ط. في ط: بمنزلة.\rفي ط: أمر. تبارك وتعالى: ليست في ط.\rفي أ: ينطلق، والمثبت من ط. في ط: فإذا.\r_____________________\r1) -الأمور مترتبة على سابق اختيار من العبد وانشغاله بأفعال الكفر وارتكاب المعاصي. انظر الإبانة للأشعري ص 160 - 162، ومجرد المقالات لابن فورك ص 102، 103، وأصول الدين للبغدادي ص 140، 141، وإثبات القدر للبيهقي ص 325 ل 32 أ، والإرشاد للجويني ص 271، والتمهيد للباقلاني ص 357.\r1) انظر ص 185.\r2) وفي ذلك قيل: ألقاه في اليم مكتوفا وقال له: إياك إياك أن تبتل بالماء وقد عزي ذلك إلى الحلاج (من تعليقات الكوثري على الطبعة الأولى للنظامية).\r3) سورة البقرة، الآية 65، وسورة الأعراف، الآية 166.\r4) سورة يس، الآية 82.\r5) ذلك أن أمر التسخير والتكوين لا بد أن يكون، ولا مرد له، ويقع جبرا حتما لازما على الإنسان وغيره، أما أمر التكليف فالإنسان له الحرية الكاملة في الامتثال له فيكسب الطاعات أوعدم الامتثال له والعصيان فيكتسب السيئات."], [197, "بصيرته، ثم صرف عنه العوائق والدوافع، وأزاح عنه الموانع، ووفق له قرناء الخير، وسهل له سبيله، وقطع الملهيات عنه، وأسباب الغفلات والذهول، وقيض له ما يقربه إلى القربات فيوافيها، ثم يعتادها ويمرن عليها 1.\rوإذا أراد بعبد شرا، قدر له ما يبعده عن الخير ويقصيه، وهيأ له تماديه في الغي، وحبب إليه التشوق إلى الشهوات، وعرضه للآفات، وكلما غلبت دواعي الشر خنست دواعي الخير. ثم يستمر على الشرور على مر الدهور، هاويا في مهاويها، وتتعاون عليه الوساوس، ونزغات الشيطان، ونزوات النفس الأمارة بالسوء 2، فتنشئ الغفلة غشاوة على قلبه 3 بقضاء الله تبارك/وتعالى وقدره 4، فذلك الطبع-عافاكم الله -والختم في ط: عنه الملهيات.\r---------------------\rفي ط: يقرب. في أ: ممر.\rفي ط: ويتعاقب. في ط: الوسواس.\rفي ط: الشياطين ونزعات.\rفي ط: فتنسج.\rتبارك وتعالى: ليست في\rعافاكم الله: ليست في ط.\r_____________________\r1) وهذا هومفهوم التوفيق من الله عند الأشاعرة. انظر مجرد مقالات الأشعري ص 123، ونهاية الإقدام للشهرستاني ص 412.\r2) وهذا هومفهوم الخذلان عند الأشاعرة. انظر مجرد مقالات الأشعري ص 123، ونهاية الإقدام للشهرستاني ص 412.\r3) كما في قوله تعالى: ختم الل?ه على قلوبهم وعلى سمعهم وعلى أبصارهم غشاوة سورة البقرة، الآية 7، وقوله تعالى: وختم على سمعه وقلبه وجعل على بصره غشاوة سورة الجاثية، الآية 23.\r4) القضاء عند الأشاعرة له معان متعددة فهوبمعنى الخلق كما في قوله تعالى: فقضاهن سبع سماوات في يومين، وبمعنى التسليط كما في قوله تعالى: فلما قضينا عليه الموت وبمعنى الإخبار والإعلام كما في قوله تعالى: وقضينا إلى بني إسرائيل في الكتاب لتفسدن في الأرض مرتين ويأتي بمعنى الأمر كما في قوله: وقضى? ربك ألا تعبدوا إلا إياه ويكون بمعنى الحكم والإلزام كما يقال: قضى القاضي على فلان.\rوالأشاعرة تطلق الرضا بقضاء الله وقدره، بمعنى أنه لا يعترض على حكمه السابق وإرادته الأزلية، فهم يرضون بقضاء الله الذي هوخلقه وأخبر به ومدح على فعله ووعد عليه الثواب، لكنهم لا يرضون بقضاء الله الذي خلقه الله مذموما قبيحا ولا يرضونه دينا وشرعا. ="], [198, "والأكنة 1. وأنا أضرب في ذلك مثلا فأقول:\rلوفرضنا شابا حديث [السن قريب] العهد بحلمه، لم تهذبه المذاهب، ولم تحنكه التجارب، وهوعلى نهاية في غلمته 2 وشهوته، وقد استمكن من بلغة 3 من الحطام، وخص بمسحة من الجمال، ولم يقم عليه قوام يزعه 4 عن ورطات الردى، ويمنعه عن الارتباك في شبكات الهوى،\r------------\rالزيادة من ط.\rفي أ: نهايته، والمثبت من ط.\r____________\r=انظر الإنصاف للباقلاني ص 147، ومجرد المقالات لابن فورك ص 91، واللمع للأشعري ص 123، 124. أما الإيمان بالقدر فهوعندهم: الإيمان بتقدم علم الله سبحانه بما يكون من أكساب الخلق وغيرها من المخلوقات، وصدور جميعها عن تقدير منه وخلق لها خيرها وشرها. الاعتقاد للبيهقي ص 105. والقدر عندهم له معان متعددة، منها: القدر بمعنى الإخبار كما في قوله عز وجل: إلا امرأته قدرن?ا إنه?ا لمن الغ?ابرين، وبمعنى الضيق كما في قوله: الل?ه يبسط الرزق لمن يش?اء ويقدر، وبمعنى الجعل كما في قوله: وقدر فيه?ا أقو?اته?ا، وبمعنى القدرة. انظر مجرد مقالات الأشعري لابن فورك ص 90، 91، واللمع للأشعري ص 123.\r1) وفي ذلك ورد قوله تعالى: وجعلن?ا على? قلوبهم أكنة أن يفقهوه وفي آذ?انهم وقرا سورة الأنعام، الآية 25، وسورة الإسراء، الآية 26، وقوله تعالى: وق?الوا قلوبن?ا في أكنة مم?ا تدعون?ا إليه وفي آذ?انن?ا وقر سورة فصلت، الآية 5. والأكنة: جمع كنان، وهوما وقى شيئا وستره، والفعل منه كننت وأكننت.\rولم تحمل الأشاعرة الكنان على أن الله تعالى منع الكفار عن الإيمان، وإنما ربطوا الكنان بالباعث على الفعل أوالداعي إليه وهومن العبد. انظر التفسير الكبير للرازي ج 12 ص 196، 197، والمفردات في غريب القرآن للراغب الأصفهاني ص 442، والإبانة للأشعري ص 148.\r2) الغلمة: هيجان شهوة النكاح من المرأة والرجل، والاغتلام: مجاورة الإنسان حد ما أمر به من خير أوشر، وجاء في قول لعلي كرم الله وجهه: «تجهزوا لقتال المارقين المغتلمين» أي الذين تجاوزوا الحد. لسان العرب ج 12 ص 440 (مادة غلم).\r3) بلغة من الحطام: على قدر لا بأس به من متاع الدنيا. انظر اللسان ج 8 ص 421 (مادة بلغ).\r4) يزعه: يمنعه من المهلكات."], [199, "فوافاه أخدان 1 [السوء و] الفساد، وهوفي غلواء شبابه، يحدث نفسه بالبقاء أمدا بعيدا. فما أقرب من هذا وصفه، من خلع العذار 2، والبدار 3 إلى شيم الأشرار، وهومع ذلك كله مؤثر مختار، ليس مجبرا على المعاصي والزلات، ولا مصدودا عن الطاعات، ومعه من العقل ما يستوجب به اللائمة إذا عصى.\rفمن هذا سبيله، لا يستحيل في العقل تكليفه، فإنه ليس ممنوعا، ولكن إن سبق له من الله تبارك وتعالى سوء القضاء، فهوصائر إلى حكم الله الجزم، وقضائه الفصل، محجوجا بحجة الله تعالى، إلا أن يتغمده الله برحمته، وهوأرحم الراحمين 4.\rوهذا الذي ذكرته بين في معاني الآيات، لا يتمارى فيه موفق، تبارك وتعالى: ثم قست قلوبكم من بعد ذ?لك [فهي كالحج?ارة أوأشد قسوة] 5، أراد\r--------------\rالزيادة من ط. تبارك وتعالى: ليست في ط.\rتعالى: ليست في ط. في أ: فيها، والمثبت من ط.\rفي ط: الله تعالى. الزيادة من ط.\r________________\r1) أخدان: جمع خدن وخدين، وهوالصديق أوالذي يكون معك في أمر ظاهر وباطن، والمقصود بأخدان الفساد: أقران السوء. اللسان ج 13 ص 139 (مادة خدن).\r2) خلع العذار: خلع الحياء. لسان العرب ج 4 ص 550، (مادة عذر).\r3) البدار: العجلة في طلب الشيء. لسان العرب ج 4 ص 48 (مادة بدر).\r4) ترى الأشاعرة عموما أن أعمال العباد ليست موجبة للسعادة أوالشقاء، فهم يرددون في كتبهم قول الشافعي: «أعمالنا أعلام الثواب والعقاب» فالأعمال أمارات من جهة العلم الظاهر وليست بموجبات، فالله عز وجل طوى علم الغيب عن خلقه وحجبهم عن دركه، فالأشاعرة لا يوجبون على الله شيئا، ويروون في ذلك حديث رسول الله صلى الله عليه وسلم: «لن ينجي أحدا منكم عمله، قالوا: ولا أنت يا رسول الله قال: ولا أنا، إلا أن يتغمدني الله منه بفضل ورحمة، ولكن قاربوا وسددوا وأبشروا» رواه البخاري في الجامع الصحيح، كتاب الرقائق 18 ج 8 ص 128 وكتاب المرضى 19 ج 7 ص 157، ومسلم في الجامع الصحيح، كتاب المنافقين 77 ج 17 ص 159. وانظر أيضا مجرد مقالات الأشعري ص 99، وإثبات القدر للبيهقي ص 513، ومعالم السنن للخطابي ج 4 ص 293، 294.\r5) سورة البقرة، الآية 74."], [200, "أنهم استمروا على المخالفات، وأصروا على انتهاك الحرمات، فقست قلوبهم. وقال عز من قائل: ولا? تطع من أغفلنا قلبه عن ذكرنا واتبع هواه 1 إلى غير ما ذكرناه.\rفقد جمعت-حرس الله مولانا-بين تفويض الأمور كلها: نفعها وضرها، خيرها وشرها إلى الإله جلت قدرته، وبين تبقية حقائق التكليف، وتقرير قواعد الشرائع على الوجه المعقول. أ لست في هذا أهدى سبيلا، وأقوم قيلا، ممن يقدر الطبع منعا، والختم صدا ودفعا، ثم ينفي التكاليف بزعمه\rوقد افترق الخلق في هذا المقام: فذهب ذاهبون إلى أن المخذولين ممنوعون ومدفوعون، لا اقتدار لهم على إجابة دعاة الحق، وهم مع ذلك ملزمون 2. وهذا خطب جسيم، وأمر/عظيم، وهوطعن في الشرائع، وإبطال\r---------------\rفي ط: حكم المخالفات. في أ: وأصروا بانتهاك.\rفي ط: وقال تعالى. واتبع هواه: ليست في ط.\rفي ط: ذكرنا. في ط: إلى الله تعالى.\rفي ط: فيها. في ط: مدفوعون وممنوعون.\r________________\r1) سورة الكهف، الآية 28.\r2) هم طائفة الجبرية أتباع الجهم بن صفوان (- 128 ه‍)، فقد بادر الجهم إلى نفي الصفات القديمة القائمة بالذات الإلهية والتي يمكن إطلاقها على العباد كالحياة والعلم والكلام، ثم أثبت الصفات التي اختص بها الله وحده ولم يشاركه بها خلقه كالخلق والقدرة والإرادة، وكان نتيجة لهذا الموقف العقلي للجهم أن نفى عن الإنسان صفة القدرة والفاعلية، فالإنسان في نظره لا يقدر على شيء ولا يوصف بالاستطاعة، وإنما هومجبور في أفعاله لا قدرة له ولا إرادة، والله تعالى يخلق فيه الأفعال كما يخلقها في سائر الجمادات والعجماوات، وتنسب الأفعال إلى الإنسان مجازا كما تنسب إلى الجمادات كما يقال: أثمرت الشجرة، وجرى الماء وتحرك الحجر. وقد شارك الجهم في هذا الموقف بعض الصوفيين الذين قرروا أن في الزنا والسرقة وسائر المعاصي طاعة لله، إذ إن في ذلك يكمن الرضا والتسليم بالقدر.\rونقل عنهم القول: «من نظر إلينا بعين الشريعة مقتنا، ومن نظر إلينا بعين الحقيقة عذرنا». ="], [201, "للدعوات. وقال تبارك وتعالى: وم?ا منع الن?اس أن يؤمنوا 1. وقال لإبليس: ما منعك أن تسجد 2.\rنعوذ بالله من سوء النظر في مواقع الخطر.\rوذهبت طوائف من [أهل] الضلال، إلى أن العبد يعصي والرب لما يأتي به كاره 3، وهذا خبط في أحكام الإلهية، ومزاحمة في الربوبية. ولولم يرد الرب من الفجار ما علمه منهم في أزله، لما فطرهم مع علمه بهم، كيف؛ وقد أكمل قواهم وأمدهم بالعدد والعدد والعتاد، وسهل طريق الحيد عن السداد. فإن قيل: فعل ذلك بهم ليطيعوه.\r--------------\rفي ط: وقد قال تعالى. في ط: ألا.\rفي ط: مواضع. في ط: طائفة.\rالزيادة من ط. في أ: فهذا، والمثبت من ط.\r______________\r= انظر الأنساب للسمعاني ج 2 ص 66، والبداية والنهاية لابن كثير ج 1 ص 350، 351، والتبصير في الدين للإسفراييني ص 96، والفصل في الملل والنحل لابن حزم ج 3 ص 22، 23، ونهاية الإقدام للشهرستاني ص 87، ومقالات الإسلاميين للأشعري ص 276، والفلسفة الصوفية في الإسلام لعبد القادر محمود ص 371، وشفاء العليل لابن القيم ص 149.\r1) سورة الكهف، الآية 55.\r2) سورة ص، الآية 75.\r3) هذا هومذهب المعتزلة، حيث نفت أن تكون إرادة الله صفة ذات، فالله ليس مريدا بذاته أومريدا بإرادة وإرادته ذاته، وإرادة الله ليست قديمة، وإنما محدثة لا في محل، والله ليس بمريد بذاته لأنها تكون عندئذ صفة ذاتية يجب تعميمها وتعميم تعلقها، وبذلك يكون الله مريدا للفواحش وذلك باطل، ولوكانت الإرادة قديمة لتعلقت بالكائنات كلها خيرها وشرها، ولكان الله موصوفا بالخيرية والشرية، وهذا خطل في القول، فالله تعالى يريد من أفعال العباد كل ما أوجبه عليهم من طاعات الواجبات والنوافل، أما المباح والمعاصي فإنه لا يجوز أن يريدها ويكره المعاصي».\rانظر المجموع في المحيط للقاضي عبد الجبار ج 1 ص 275، 285، والمغني في التوحيد والعدل ج 6 ص 215، 222، 225، وشرح الأصول الخمسة ص 456، 460."], [202, "قلنا: أنى يستقيم ذلك وقد علم أنهم يعصونه، ويهلكون أنفسهم، ويهلكون أولياءه وأنبياءه، ويشقون شقاوة لا يسعدون بعدها أبدا.\rولوعلم سيد عن وحي أوإخبار نبي، أنه لوأمد عبده بالمال لطغى وأبق 1، وقطع الطريق، فأمده بالمال، زاعما أنه يريد منه ابتناء القناطر والمقابر والمساجد، وهومع ذلك يقول: أعلم أنه لا يفعل ذلك قطعا، فهذا السيد مفسد عبده، وليس مصلحا له باتفاق من أرباب الألباب.\rفقد زاغت الفئتان، وضلت الفرقتان 2، واعترضت إحداهما على القواعد الشرعية، وزاحمت الأخرى أحكام الربوبية.\rواقتصد الموفقون 3 فقالوا: أراد الله تعالى من عباده ما علم أنهم إليه يصيرون، فالله لم يسلبهم قدرهم، ولم يمنعهم مراشدهم، فقرت الشريعة في نصابها، وجرت العقيدة في أحكام الإلهية على صوابها.\rفإن قيل: كيف يريد الحكيم السفه فقد سبق في ذلك قدر كاف شاف لصدر كل ذي لب، وأوضحنا أن الأفعال متساوية في حق من لا ينتفع ولا يتضرر، ولكن إذا أخبر أنه مكلف مطالب عباده، مزيح عللهم، فقوله الحق، وكلامه الصدق.\rوأقرب أمر يعارضون به: أن الحكيم منا إذ رأى جواريه وعبيده يموج بعضهم في بعض، وهم على مخازيهم بمرأى منه في ط: بها.\r--------------\rفي أ: زاعم، والمثبت من ط.\rالمقابر: ليست في ط. في أ: مصالحا، والمثبت من ط.\rفي أ: مراد. في ط: ولكن.\rفي ط: الأحكام. شاف: ليست في ط.\rفي أ: يتصرف، والمثبت من ط. في أ: عليهم، وفي ط: علله، وما أثبته اجتهادا.\rفي أ: يمرج، وما أثبته من ط. في ط: محارمهم.\r___________________\r1) أبق: هرب من سيده من دون خوف أوكد عمل. اللسان ج 10 ص 3 (مادة أبق).\r2) هما الجبرية والمعتزلة كما بيناه سابقا.\r3) قصد هنا الأشاعرة الذين ينتمي إليهم الجويني."], [203, "ومسمع، فلا يحسن تركهم على ما هم/عليه، والرب مطلع على سوء أفعال العباد، ويستدرجهم من حيث لا يعلمون 1.\rوقد أطلت أنفاسي قليلا، ولكن-حرس الله مولانا-لووجدت في اقتباس هذا العلم، من يسرد لي هذا الفصل، لكان-وحق القائم على كل نفس بما كسبت-أحب إلي من ملك الدنيا بحذافيرها طول أمدها، فهذا ركن واحد من أركان التوحيد.\rالركن الثاني: من القول في هذا، وهومقتضب مما تقدم، قريب المأخذ بعد الإحاطة بما سبق، وذلك أنه يشترط [في] توجيه التكليف على العبد، حضور عقله الذي يستمكن به من فهم الخطاب. إذ لولم يكن كذلك، لا يتصور قصد امتثال الأمر قبل فهمه، والعلم بالآمر تعالى، ولكان ذلك تكليف ما لا يطاق، وهومستحيل 2.\rوتقريب القول فيه: إن من ضرورة توجيه الأمر على المخاطب تكليفه فهم الخطاب، وتكليف من يستحيل أن يفهم [الأمر] محال، وهوبمثابة تكليف البهائم والجمادات، ولا معنى لبسط الكلام في الجليات 3.\rوأما البلوغ، فهومشروط مع العقل في استمرار التكليف، ولكن مدرك\r----------------\rفي أ: ومستمع، وما أثبته من ط.\rفي ط: والرب سبحانه.\rفي ط: أفعالهم. في ط: هذا لقول.\rفي أ: كتبت المااخذ.\rالزيادة من ط. في ط: يتمكن.\rفي ط: دون. في ط: والعلم بالأمر وإلا كان.\rالزيادة من ط.\r___________________________\r1) ينقل الجويني هنا ما أورده الأشعري في كتابه اللمع ص 107.\r2) انظر موقف الأشاعرة من التكليف بما لا يطاق ص 187 هامش رقم 3، وانظر أيضا الإحكام في أصول الأحكام للآمدي ج 1 ص 179.\r3) اتفقت الأشاعرة على أن شرط المكلف أن يكون عاقلا فاهما للتكليف، لأن التكليف خطاب، وخطاب من لا عقل له ولا فهم محال كالجماد والبهيمة. انظر الإحكام في أصول الأحكام للآمدي ج 1 ص 199."], [204, "شرطه الشرع، ولورددنا [ه] إلى العقل، لم يستحل في مقتضاه، تكليف العاقل [المميز] من الصبيان.\rالركن الثالث: أن يكون المأمور به ممكنا [في نفسه] وجودا ووقوعا، فلا يجوز ورود التكليف بجمع الضدين، والكون في مكانين في وقت واحد.\rويستحيل ورود الأمر بالكفر بالله تبارك وتعالى، لأن من ضرورة الأمر، فهم المأمور الأمر وعلمه بالأمر. وكيف يتصور مع العلم بالله ذي الأمر، الجهل به! فهومن قبيل جمع الضدين.\rفقد خرجت هذه الأركان الثلاثة على أصل واحد هوقاعدة العقيدة، وهوأن العبد مطالب بالجائز دون المستحيل، فإنه مطالب بفعل أوإضراب عن فعل، وكلاهما جائزان. وكما لا يجري على العبد من تقدير بارئه إلا ما يجوز، فكذلك لا يطالبه إلا بما يجوز 1.\rالركن الرابع: يتعلق بالثواب والعقاب:\rذهبت طوائف من أهل الزيغ والضلال: إلى أن العبد إذا أطاع ربه، وجب على الله تبارك وتعالى أن يثيبه وجوب الحكمة 2. وإن عصاه اضطربوا\r-------------------\rالزيادة من ط. الزيادة من ط.\rفي ط: منه أن. الزيادة من ط.\rفي أ: والكفر، والمثبت من ط.\rتبارك: ليست في ط. في ط: إصدار.\rبالأمر: ليست في ط. في ط: تكليف جمع.\rفي ط: وهو. في ط: فهو.\rفي ط: و. في ط: فكما.\r________________\r1) ترى الأشاعرة أن من شرط المأمور معرفته بتوجه أمر الآمر عليه، ولا يعرف توجه أمر الآمر عليه إلا من عرف الله، ولا يصح منه الجمع بين معرفة الله وتوحيده وبين اعتقاده الكفر به، فلم يصح ذلك للتناقض والاستحالة. كذلك ترى الأشاعرة أن التكليف مستفاد بالشرع دون العقل، وإن كان العقل دالا على جواز ورود الشرع.\r2) هذه من المسائل التي قالت بها المعتزلة مما أدى إلى التشنيع بهم من قبل أهل السنة ="], [205, "في حكم الإله 1:\rفقال قائلون: يجب على الله تعالى أن يعاقبه، ولا يجوز أن يعفوعنه ما لم يتب، فإن تاب وجب عليه قبول توبته 2.\rوذهب آخرون: إلى أن العفوممنوع في العقل، والثواب واجب على الله-تبارك وتعالى عن قولهم علوا كثيرا-في هذيان طويل 3.\rوصار أهل الحق قاطبة: إلى أنه لا يجب على الله شيء، فإن أثاب وأنعم فبفضله، وإن عاقب فبعدله 4.\r--------------\rفي أ: يعف، والمثبت من ط.\rفي أ: مسوغ، والمثبت من ط.\rتبارك: ليست في ط.\r_________________\r= فقهاء ومحدثين ومتكلمين، ومن القضايا التي اعتقدت المعتزلة بوجوبها على الله تعالى، وجوب خلقه الخلق لأن خلقهم فيه نفع لهم وصلاح، ووجوب تكليف العباد، لأن التكليف هوالسبيل إلى معرفة الله، ووجوب العوض على الآلام في الدنيا للأطفال والمجانين والحيوانات، ووجوب إزاحة علل العباد من كل وجه حتى يتمكنوا من القيام بما وكلهم به، ووجوب اللطف. انظر الأشعري، مقالات الإسلاميين ص 252، 253، 262، والاقتصاد في الاعتقاد للغزالي ص 72، ونهاية الإقدام للشهرستاني ص 405، وشرح الأصول الخمسة للقاضي عبد الجبار ص 520، 503، 508 - 509، 621، والمجموع في المحيط ج 1 ص 360.\r1) انظر هذا الاضطراب عند مدرستي الاعتزال البصرية والبغدادية في شرح الأصول الخمسة للقاضي عبد الجبار الهمذاني ص 644 - 647، ومقالات الإسلاميين للأشعري ص 274 - 276.\r2) إلى ذلك ذهبت مدرسة الاعتزال البصرية. انظر شرح الأصول الخمسة للقاضي عبد الجبار ص 747،666،667.\r3) هذا القول هومن تقريرات معتزلة بغداد، إذ ذهبوا إلى القول: إن العقاب لطف من جهة الله تعالى، واللطف يجب أن يكون مفعولا بالمكلف على أبلغ وجوه، ولن يكون كذلك إلا والعقاب واجب على الله تعالى. انظر شرح الأصول الخمسة للقاضي عبد الجبار الهمذاني ص 644، 646.\r4) قررت الأشاعرة أن الثواب من الله تعالى ابتداء فضل غير مستحق للمؤمن عليه بعمله، بل عمل المؤمن بالطاعة له ابتداء فضل منه وتوفيق له. . . [وأن] العقاب ابتداء عدل="], [206, "والدليل القاطع في تحقيق ما ارتضاه أهل الحق: أن الوجوب إنما يتحقق في حق من لوفرض منه ترك الواجب لاستحق الذم واللائمة، ولوليم أوعوقب لناله ضرر، والرب تبارك وتعالى يتقدس عن قبول الضر والنفع، ولا يتحقق تفاوت الأفعال في حكمه كما سبق 1.\rومما يقطع مادة كلامهم، أن العبادات التي يقيمها العبد لا تفي بالنعم التي تتوفر عليه من ربه ناجزة، وهي تقع شكرا لأنعم الله تبارك وتعالى، بل لا تفي بأقلها. فإذا وقعت شكرا عوضا عما تعجل من نعم الله، فكيف يستمر في حكم العقل استحقاق الثواب على أعمال وقعت عوضا عن نعيم يوفاه العبد 2!\rثم قالوا: ليس على أهل الجنان شكر لنعيمها، فإنه عوض أعمال العبد، وليس للمعوض عوض.\r-------------\rفي أ: من، والمثبت من ط. في ط: وإن.\rتبارك وتعالى: ليست في ط.\rفي ط: الضرر. في ط: فلا.\rفي ط: وما يقطع بتأكده عند الفهم.\rفي ط: يقيسها. في ط: تنوب.\rفي: ناجزا. في ط: استوفاه.\rفي ط: لأعمال.\r______________________\r= من الله تعالى لم يوجبه سبب متقدم من كفر ومعصية، بل كان كفر الكافر بخذلانه وحرمانه وإضلاله، وإنه لوعفا عن الكفار جميعا وأدخلهم الجنة كان ذلك لائقا برحمته غير منكر في حكمته، ولكنا إنما قطعنا بعذابهم على طريق التأبيد للخبر المجمع على عمومه. انظر مجرد مقالات الأشعري لابن فورك ص 163.\r1) كرر الجويني هنا ما ذكره في الإرشاد ص 271، 272.\r2) يدلل الجويني هنا على صحة ما قررته الأشاعرة من أن الإيمان والكفر أمارتان للثواب والعقاب المتعلقين على الأكساب، خيرها وشرها وإيمانها وكفرها مما تعلق بها خيرا لا عقلا.\rوإجمالا ذهب أهل السنة إلى ذلك، وقرروا أن الأعمال أعلام الثواب والعقاب، وينسب هذا القول إلى الشافعي وتمسك به الأشعري والخطابي والبيهقي. انظر مجرد المقالات لابن فورك ص 99، ومعالم السنن للخطابي ج 4 ص 94، وإثبات القدر للبيهقي ص 495، وانظر تفصيل ذلك في الإرشاد للجويني ص 381، وانظر رد المعتزلة على ذلك في شرح الأصول الخمسة للقاضي عبد الجبار ص 638 - 642."], [207, "فمن أضل سبيلا ممن يوجب على الله تبارك وتعالى ثواب أعمال العبد، وهي عوض ما ينجز من النعم، ولم يوجب على العبد شكر الثواب عدا لكونه عوضا 1.\rثم من زعم أن العقل يدل على استحقاق العبد بكفر ساعة، الخلود في دركات النيران، فقد ادعى في مقتضى العقول محالا، هيهات برح الخفاء. يحكم الله ما يريد ويفعل ما يشاء.\rفإن قيل: قد بنيتم الركن الأول على تقرير الشريعة قرارها واتباع مواردها، فالثواب والعقاب في الشرائع/والملل ثابتان، وقد سماها الله تبارك وتعالى جزاء لأعمال العباد.\rقلنا: لسنا ننكرهما، ولكنهما ثبتا وعدا من الله، ووعده صدق، وقوله حق، وهذا يبينه ضرب مثل يوضح ما تقدم من الكلام، ويكشف هذا الإبهام فنقول:\rإذا خدم العبد مولاه، لم يستحق عليه أن يعتقه، ويخلصه من أسر الرق وذل العبودية. بل المقدار الذي تأسس الشرع عليه، أن يكفيه مؤونته، ولا يكلفه من العمل إلا ما يطيق. والثواب الخالد، خالص من النصب والتعب؛ ووصول إلى الروح الأبدي، وهوزائد على الحرية المزيلة للرق. فإذا كان العبد لا يستحق على مولاه-وهو [لا] يألوجهدا في خدمته آناء الليل [وأطراف] النهار-العتق، فكيف يستحق العبد على خالقه ومنشئه ورازقه في ط: العباد.\r------------------\rفي أ: العقد. في ط: والثواب.\rفي أ: والملك، والمثبت من ط.\rفي ط: الله تعالى.\rفي أ: الأعمال، والمثبت من ط.\rفي ط: القرار. في ط: العمل ما لا يطيق.\rالزيادة من ط. الزيادة من ط.\r________________\r1) لم يأت الجويني هنا بجديد في رده على المعتزلة، إذ كرر ما سبق أن ذكره في الإرشاد ص 294."], [208, "بعبادته الخلاص السرمدي 1!.\rنعم، لوقال السيد لعبده: إن فعلت كذا وكذا فأنت حر، فإذا حقق العبد ما ذكره سيده عتق بقول سيده، لا بحكم استحقاق اقتضاه عمله. فكذلك الثواب، ثابت قطعا بوعد الله تعالى، والعقاب ثابت بوعيده. وهذا معنى قول السعداء فيما أخبر الله تبارك وتعالى عنهم: وق?الوا الحمد لل?ه الذي صدقن?ا وعده وأورثنا الأرض 2. فهذا مذهب أهل الحق في الثواب والعقاب.\rوأنا الآن، أبدي سرا من أسرار التوحيد؛ لوقوبل بكل ما يدخل في مقدور البشر ميسوره، لما كان كفاء له فأقول:\rذهب الصائرون إلى أن العبد يستحق على الرب تبارك وتعالى جزاء عمله، إلى أن سبيل درك الوجوب على العبد، أن ينظر بعقله، فيخطر له أنه يؤمن أن له ربا خلقه وبرأه، وأسبغ عليه نعمه، وهوإن شكره استحق الثواب، وإن أبى واستكبر وكفر، استحق العقاب.\r------------------\rفي أ: عباداته، وما أثبته من ط.\rفي أ: كذى وكذى. تعالى: ليست في ط.\rفي ط: بوعيده ثابت. في ط: إذ قالوا.\rفي ط: وهذا. في ط: ميسورا.\rفي ط: له كفاء. في ط: الرب تعالى.\rأنه يؤمن: ليست في ط، وفي أ: يأمن.\rفي ط: شكر.\r___________________\r1) ذكر الجويني هذا المثل نفسه في الإرشاد ص 382، وهووارد في أغلب كتب الأشاعرة، والجويني لم يخرج فيما قرره هنا عن ما ذكره أعلام الأشاعرة السابقون له، فالثواب عندهم ليس بحق محتوم ولا جزاء مجزوم، وإنما هوفضل من الله تعالى، والعقاب لا يجب أيضا، والواقع منه هوعدل من الله، وما وعد الله تعالى من الثواب أوتوعد به من العقاب، فقوله الحق ووعده الصدق. انظر مجرد مقالات الأشعري لابن فورك ص 163، والإرشاد للجويني ص 386، والغنية للمتولي ص 168.\r2) سورة الزمر، الآية 74."], [209, "وإذا تعارض الخاطران وتقابلا، استحثه العقل على سلوك مسلك النجاة والتوقي من الهلكات.\rوقال أهل الحق: يجب امتثال أوامره/تبارك وتعالى إذا وردت، ولا ترشد العقول إلى درك واجب على العبد.\rوقالوا في معارضة هؤلاء: لأن كان يخطر للعبد ما ذكرتموه، فقد يعارضه مسلك آخر هولباب العقل [حقا]، وهوأن يجري في نفسه، ومجاري حدسه، أنه عبد مربوب، وربه لا ينفعه عمل، ولا يضره فعل، ولا تزيده طاعة، ولا تنقصه معصية. وهوإن أكب على الشكر والطاعة، أنهك بدن نفسه وأكداه، وقطعه عن ملاذه، ثم لا ينفع ربه به، بل يكون متصرفا في نفسه بما ينقصها، وهوملك من خلقه، وربما يتعرض بتصرفه في نفسه من غير إذن المالك لعقاب المالك، فهذا يتضمن أن يتوقف في العمل. وهذا قاطع من كلام الأئمة 1.\rثم انتهى القول بسلف الأصحاب: إلى أن أمر الله تبارك وتعالى يجب امتثاله إذا ورد لعينه، فإنه تبارك وتعالى بعزته وإلهيته، يستحق أن يمتثل في ط: فإذا.\r--------------\rفي ط: سبيل. في أ: فقال.\rفي ط: يجب الإمساك عن القول بوجوب شيء على العباد إلى ورود أوامره تعالى والعلم بأنها وردت.\rفي ط: فلا. كتب بالأصل: هاولاي.\rفي ط: وهو. الزيادة من ط.\rفي أ: مربوت، والمثبت من ط.\rمن قوله: غرر به. . . معصية، ليست في ط.\rفي أ: وأنهك. في ط: بدنه.\rبه: ليست في ط. في أ: ما، والمثبت من ط.\rفي أ: من ذلك، والمثبت من ط.\rفي ط: فهو. في ط: بعينه. في ط: فإنه تعالى لعزته وإلهيته.\r__________________\r1) انظر أيضا مجرد مقالات الأشعري لابن فورك ص 163."], [210, "أمره. وهذا موقف يجب على العاقل أن يتأنى فيه، إن كانت همته تحمله على توقي التقليد، والترقي إلى ثلج اليقين 1.\rوأنا أقول: لولا ورود الشرع بالوعيد على من ترك ما أمر به، لما فهم العبد وجوبا عليه، ولا طائل تحت قول من يقول: إن الله [تعالى] مطاع الأمر لإلهيته، وهومن الكلمات التي يرسلها من لا يغوص على مغاصات الحقائق وأمثالها، ولا يصبر على سبر العقول.\rنعم إذا استشعر العبد وعيدا، حمله عقله على معرفة وجوب ما لوتركه لأوفي على ما لا طاقة له به. ومن أسرار العبودية-وهومعقود الفصل ومقصوده-أنه كما يستحيل على الله تبارك وتعالى الأغراض، والضر والنفع، والحظوظ، وتفاوت الأفعال، يستحيل خروج العبد عن طلب الحظوظ [في] مسالك التكليف 2.\rفلولم يثبت حظ العبد في تنكب العقاب، لما تقرر في حقه في أ: فأنا، وما أثبته من ط.\r------------------------\rفي ط: لما. الزيادة من ط.\rفي أ: معاوضات.\rفي أ: أسر أن، والمثبت من ط.\rفي أ: كلما، والمثبت من ط.\rفي ط: يستحيل على العبد الخروج.\rالزيادة من ط. في أ: ومسالك.\rفي أ: خطا، والمثبت من ط.\r________________________\r1) وفي حديث عمر: حتى أتاه الثلج واليقين، والثلج: اطمئنان القلب. انظر الموطأ ج 2 ص 237.\r2) اتفقت الأشاعرة على أن الله تعالى خلق العالم بما فيه من خير وشر وجواهر وأعراض لا لعلة ولا لغرض يتوقف عليها الخلق، وحجتهم في ذلك أن العلة أوالغرض بمثابة خواطر ودواع، وهي تجوز على ذوي الحاجة الذين يصح منهم اجتلاب المنافع ودفع المضار، وهذا لا يجوز إلا على من جازت عليه الآلام واللذات وميل الطبع والنفور، وهومنتف عن القدير تعالى، والأشعرية في ذلك خالفت بعض جمهور الفقهاء والمعتزلة قاطبة. انظر التمهيد للباقلاني ص 50، 51، والشامل للجويني ص 619، ونهاية الإقدام للشهرستاني ص 397، ومحصل أفكار المتقدمين للرازي ص 296، وغاية المرام للآمدي ص 224."], [211, "الواجب، وعن هذا اضمحل قول من ادعى محبة الله حقا، فإن وجوده متعال/ عن أن يحظى به ذوحظ. والمخلوق تداوره على الحظوظ والأغراض التي يجمعها دفع الضر وجلب النفع، والمحبة من الله تبارك وتعالى غير محمولة على حقيقتها ظاهرا، فإنه متقدس عن الميل والتحيز والرقة والتوقان. فمحبة الله تبارك وتعالى لعبده إرادته الإنعام عليه، ومحبة العبد لربه، استقامته في طاعته، وهومتقدس بعز جلاله عن أن يناله حظ أوينال حظا.\rوالرؤية غاية آمال أهل السنة، وأنا أقول فيها: إن الله تبارك وتعالى يقرن بها فنا من الروح لا يوازيه روح، وهومناط الآمال، وإلا فالرؤية في عينها لا يجوز أن تكون مأمولة، وكان يجوز في قدرته، أن يقرن بها منتهى عقوبة الكفار حتى يحذرها المؤمنون كما يرجونها الآن.\rولن يجد المرء-حرس الله مولانا-حلاوة الإيمان حتى يحيط بما ذكرته علما، ولولا ثقتي بأن مولانا-[حرس الله مدته] بتوفيق الله-يبتدر برأيه الثاقب هذه الحقائق، لما بثثت إليه أسرار هذه الأبواب التي لم أضمنها شيئا من التصانيف.\rفإن قيل: فإذا عقلتم درك الوجوب باستشعار العقاب، فقد ساويتم القدرية في عقدهم.\rقلنا: هيهات! بيننا وبينهم ما بين الثريا والثرى، فإنهم زعموا أن العقول\r------------------\rفي أ: ذوا، والمثبت من ط. في ط: توادده.\rفي ط: يحملها على غير حقيقتها ظاهرها.\rفي ط: على غير حقيقتها. في أ: المثل.\rوالرقة: ليست في ط. في ط: ومحبة.\rتبارك وتعالى: ليست في ط. بعز جلاله: ليست في ط.\rفي أ: مآل، والمثبت من ط.\rفي ط: يحذروها. المؤمنون، ليست في ط.\rفي أ: فإن، والمثبت من ط. الزيادة من ط.\rفي أ: علقتم، والمثبت من ط."], [212, "توجب على الرب الثواب والعقاب، وإنهم ينفرون بدرك الواجبات بعقولهم 1.\rونحن قلنا: لا يجب على الله تبارك وتعالى شيء، ولا يدرك بالعقل وجوب عليه، ولكن إذا أراد الرب [تعالى] إلزام عبيده شيئا، أمرهم وتوعدهم على ترك المأمور، فتستحثهم عقولهم على اجتناب المحذور، فإن وعد الله حق، ووعيده صدق.\rوقد تتبعت العلوم العقلية في كل فن جهدي، فما وجدت طائفة من ذوي العقول، حائدين بالكلية عن مسلك جلي من مسالك العقول، ولكنهم يبتدرون القاعدة، ثم قد يزلون عن التفاصيل. وهذا كما أن افتقار المتغيرات إلى مدبر، لما كان من جليات العقول/لم ينكره أحد، ولكنهم اختلفوا في صفة المدبر، فسماه بعض العقلاء الطبع 2، وبعضهم العقل الكلي 3، إلى خبط لا أشغل به قريحة مولانا.\r------------------\rتبارك وتعالى: ليست في ط.\rالزيادة من ط. في ط: المحظور.\rفي ط: الألباب. في أ: قال، والمثبت من ط.\rفي ط: في. في أ: كليات، وما أثبته من ط.\r__________________________\r1) انظر المغني للقاضي عبد الجبار ج 15 ص 116، وشرح الأصول الخمسة ص 564، 565، وفيه: «إن ما تأتي به الرسل لا يكون إلا لتفصيل ما تقرر جملته في العقل، فوجوب المصلحة وقبح المفسدة مقرر في العقل، لكنه إذا أشكل علينا عقلا تمييز المصلحة من المفسدة، فاللجوء إلى التقريرات الشرعية التي جاء بها الرسل تعرفنا حال هذه الأفعال، فالرسل قد جاؤوا بتقرير ما قد ركبه الله تعالى في عقولنا وتفصيل ما قد تقرر فيها.\r2) رفضت الأشاعرة أقوال الطبائعيين الذين يقولون بأثر الموجودات الطبيعية بعضها في بعض، أوقدم الطبائع الأربع، وأن صانع العالم طبيعة من الطبائع، إذ إن الجواهر المتجانسة المتماثلة لوكانت مؤثرة فاعلة، لوجب أن يكون تأثير كل الأجسام واحدا وهوأمر مرفوض بالمشاهدة، والأعراض التي لا تبقى ولا تنتقل يستحيل أن تكون هي المؤثرة. انظر التمهيد ص 52، والشامل للجويني ص 238.\r3) هوما ذهب إليه الفلاسفة، فالعقل الكلي إما أن يكون محايث للطبيعة، ومنظم ="], [213, "ثم استبد الموفقون لمنهج الحق، ومن طال نظره في العقليات، تبين له أن مثار خلاف العقلاء، آيل إلى التفاصيل دون الأصول، والغرض من هذا التبيين أن النفوس مجبولة على طلب المحبوب، وتوقي المحذور.\rومصير القدرية إلى ذلك غير مستنكر أصلا، ولكنهم لم يحسنوا تفصيله فزلوا، ونحن جمعنا بين اعتباره، وبين تنزيه الرب سبحانه عن النفع والضر، كما جرى في معرض هوأوضح من فلق الصبح لفاهمه.\rوإذا نجز القول في أحكام الربوبية وصفات العبودية، واستبان أن مدرك التكاليف موقوف على ورود الشرائع، فقد حان الآن أن نوضح أن مدرك الشرائع التلقي من الرسل والأنبياء عليهم السلام، وهوالباب الثالث من أبواب العقيدة والله الموفق للصواب.\r--------------\rفي ط: رشد. في ط: إلى منهج.\rفي أ: التشبيه، وما أثبته من ط.\rفي ط: ولكن. في ط: تعالى.\rفي ط: والرفع. في ط: التكليف.\rعليهم السلام: ليست في ط.\rوالله الموقف للصواب: ليست في ط.\r_____________________________\r=لظواهرها والقوانين التي تحكم هذه الظواهر كما قال هيراقليطس، أوأنه مفارق لها وهوالذي يبث النظام في الطبيعة التي هي في ذاتها فوضى واضطراب. لذا فإن العقل الكلي هومصدر النظام في هذا الكون، وأنه العلة لجميع الأشياء، كما قال أنغاجوراس وأرسطووأفلاطون. انظر تاريخ الفكر الفلسفي، أبوريان ج 1 ص 85، 91."], [214, "باب النبوات\r\r"]], "pg": [184, 214]}, "474.33": {"x": [[214, "قد أنكرت طائفة النبوات يعرفون بالبراهمة 1، واعترفوا بالصانع، ونحن نشير إلى مسالكهم التي يموهون بها، ونجيب [عنها] على الإيجاز بأوضح الوجوه.\rفمما ذكروه، أن الأنبياء عليهم السلام، إن جاؤوا بما يخالف العقول فهم مردودون، وإن جاؤوا بما يوافقها، ففي العقول مقنع، وابتعاثهم عبث 2.\rقلنا: إنهم جاؤوا بما لا تنكره العقول ولا تهتدي [إليه]، فإن مناط الشرائع الوعد والوعيد، وبهما تتعلق الأحكام، والعقول لا تدركهما، ولئن تشوفت في أ: طائفة النبوات يعرفون بالبراهمة.\r--------------------------\rالزيادة من ط.\rعليهم السلام: ليست في ط.\rالزيادة من ط. في ط: تساوقت.\r______________________\r1) البراهمة: ينسب البراهمة إلى أحد الرجال الهنود يقال له «براهم» الذي دعا إلى إله مجرد أعلى وهوالخالق لهذا الكون، لكنهم أنكروا النبوات ونفوا البعث، والبراهمة فرق عدة، منهم البددة الذين زعموا بوجود «البد» المنزه عن كل نقيصة، وفرقة الفكرة والوهم الذين يعظمون الفكر المتوسط بين المحسوس والمعقول، ويعتقدون بأثرهما في تصريف الأجسام والنفوس، وكل ذلك ينشأ من أحكام ناتجة عن خصائص الكواكب دون طبائعها، ومنهم التناسخية الذين يؤمنون بتناسخ الأحياء قاطبة المرتبط بتناسخ الأدوار والأكوار. انظر الملل والنحل للشهرستاني ص 507 - 511، والمحصل للرازي ص 308، والفصل لابن حزم ج 1 ص 69، والتمهيد للباقلاني ص 96، والإرشاد للجويني ص 302، ونهاية الإقدام للشهرستاني ص 417.\r2) انظر هذه الشبهة أيضا في الإرشاد للمؤلف ص 303، والتمهيد للباقلاني ص 98."], [215, "العقول إلى كليات المصالح لم تقف على تفاصيلها، والشرائع توضحها.\rثم لا امتناع في حمل مجيئهم على ما يوضحه العقل، فيكونون مؤكدين للمعقولات مذكرين بها، ومن تكلم بقضايا العقول لم يعد كلامه لغوا، وإن كانت العقول مرشدة إلى ما/تكلم به. وفي بعض ما فطره الله تبارك وتعالى مقنع في الدلالة على الصانع، فلم يكن ما وراء الكفاية من بدائع الصنع عبثا 1.\rومما ذكروه، أنهم قالوا: وجدنا في شرائع الرسل أمورا أباحوها وأوجبوها، وهي مستقبحة عقلا، وعدوا من ذلك ذبح البهائم غير المضرة، والتنكيس في السجود، والسعي والهرولة، ورمي الجمار من غير غرض 2.\rونحن نذكر كلمات وجيزة، تحسم هذه المواد بالكلية، فنقول: معاشر البراهمة، إنكم بزعمكم معترفون بالصانع المختار، ثم بنيتم رد النبوات على تقبيح العقل وتحسينه، وكل ما ادعيتم قبحه مأمور به، فنحن نريكم مثله من فعل الله تعالى.\r----------------------\rفي ط: لكنها لم. في ط: توضحه العقول.\rفي ط: ولم. في ط: يكن أول.\rفي ط: والتمكين. في ط: الحجار.\rفي أ: وكلما، والمثبت من ط.\rفي ط: مأمورا.\r___________________\r1) يظهر أن الجويني قد كرر ما ذكره في الإرشاد ص 303، وعلى كل حال فإن الجويني في رده على شبه البراهمة في الإرشاد والنظامية لم يأت بشيء جديد، وإنما كان عالة على ما أورده الباقلاني في التمهيد، ويمكن القول أيضا إن ردود الباقلاني على البراهمة جاءت أغنى وأدق مما ذكره الجويني. قارن التمهيد للباقلاني ص 96 - 121، والإرشاد ص 302 - 306، والمحصل للرازي ص 308، 312، والغنية للمتولي ص 148، ونهاية الإقدام للشهرستاني ص 418، وأصول الدين للبغدادي ص 155.\r2) انظر هذه الشبهة أيضا في التمهيد للباقلاني ص 102، 106، الإرشاد للجويني ص 304، 305، والغنية للمتولي ص 149."], [216, "فأما ذبح البهائم؛ فالله تبارك وتعالى يهلك البهائم بأسباب الهلاك من غير جريرة قارفوها، ويحل بهم من الآلام ما يشاء، ولا معترض عليه، فما يقبح منه فعله، لم يقبح منه الأمر به 1.\rوما ذكروه من استقباح هيئة الساجد فنقول: لوخلق الله عبدا على هيئة الساجد، ثم لم يمكنه من أطمار رثة، فيستتر بها، وتركه بادي السوأة، فلا يقبح ذلك من فعله، وليطرد المنتهى إلى هذا الموضع، أمثال ما نبهنا عليه في جميع ما ذكروه 2.\rثم إنهم بنوا أصلهم هذا على تفصيل الأفعال في حق الإله سبحانه، وقد قررنا أن الأفعال إنما تتفصل في حق من يتضرر وينتفع، تعالى الله عن ذلك وتقدس. وإذا أشبعنا كلامنا وأنهيناه إلى حد الإقناع، ثم اعترض بشيء متعلق به لم نعده، ثم نقول:\rالنبوة تعريف الله تبارك وتعالى عبدا من عباده أمره بأن يبلغ\r---------------------\rفي ط: أما.\rتبارك وتعالى: ليست في ط.\rفي ط: شاء. في ط: لا يقبح.\rفي أ: ومما، والمثبت من ط.\rفي ط: يستتر. ذلك: ليست في ط.\rالموضع: ليست في ط.\rفي ط: تفاصيل. في ط: تعالى الله وتقدس عن ذلك.\rفي ط: إن النبوة.\rتبارك وتعالى: ليست في ط.\rفي ط: أمرا.\r__________________________\r1) في الإرشاد ص 305 بعد أن استعرض الجويني الحكمة من ذلك قال: «فما كان حكمة من فعله لم يبعد كون الأمر به أيضا حكمه». وانظر أيضا رد الباقلاني على هذه الشبهة في التمهيد ص 104، والغنية للمتولي ص 149.\r2) في الإرشاد للمؤلف ص 305: «الرب تعالى قد يضطر عبده ويفقره ويعريه ويتركه كلحم على وضم والسوءة منه بادية، ولوعري واحد منا عبده مع تمكنه من ستره ومواراة سوأته لكان ملوما، والرب تعالى يفعل من ذلك ما يشاء: لا? يسئل عم?ا يفعل وهم يسئلون (23) وهوالذي يسلب العقول ويضطر المجانين إلى ما يتعاطونه مما تبقي مضرته مع القدرة على أن يكمل عقولهم». وانظر أيضا الغنية للمتولي ص 149، والتمهيد للباقلاني ص 106."], [217, "رسالته إلى عباده، وهذا ليس من المستحيلات.\rوإذا تقرر أن النبوات ليست من المستحيلات، فنذكر بعد ذلك فصلا في دلالة ثبوت النبوة ووقوعها وهي المعجزة، ونذكر شرائطها، وفصلا في وجوه دلالة/المعجزات على صدق الرسل، وفصلا في إثبات الكرامات، وفصلا في إثبات نبوة سيدنا ومولانا محمد صلى الله عليه وسلم.\r----------------\rفي ط: مستحيلات العقول.\rفي ط: فإذا. دلالة: ليست في ط.\rفي ط: ووقوعها والمعجزة وشرائطها.\rفي ط: فصل. في ط: وجه إثبات."], [218, "فصل\rفي المعجزات\r\r"]], "pg": [214, 218]}, "474.34": {"x": [[218, "سميت دلالات صدق الرسل عليهم السلام معجزات توسعا وتجوزا، فإن المعجز على الحقيقة: خلق العجز، ولكنها سميت بذلك، لأنه يظهر أنه من ليس نبيا، يعجز عن الإتيان بما يظهره الله عز وجل على النبي 1. ثم المعجزة لها شرائط 2، نحن ذاكروها إن شاء الله عز وجل:\rمنها: أن تكون فعلا لله تبارك وتعالى أوفي معنى الفعل، ولا تكون المعجزة صفة قديمة من صفات الله تبارك وتعالى، فإن صفاته الأزلية لا اختصاص لها ببعض الخلائق 3.\r------------------------\rفي ط: الأنبياء.\rعليهم السلام: ليست في ط.\rفي ط: وإنما. عز وجل: ليست في ط.\rفي ط: الله تعالى.\rتبارك وتعالى: ليست في ط.\rفي ط: الله تعالى.\r_________________________\r1) في مقالات الأشعري لابن فورك ص 177: «إن المعجزات على وجوه، أحدها: أن يخص من تظهر عليه بقدر زائدة على ما جرت العادة بفعل مثلها لمن كان على مثل هيئته وبنيته وحاله. . فإذا ظهرت هذه الأفعال على من يدعي الرسالة عند دعواها، وتحدى بها وتعذر على من يتحداه به، قيل لمن يتعذر فعل ذلك عليه إنه عاجز عنه، وإن ذلك لفعل معجز». وانظر أيضا في معنى المعجزة: أصول الدين للبغدادي ص 170، والإرشاد للمؤلف ص 307، والغنية للمتولي ص 149، والمحصل للرازي ص 301.\r2) انظر هذه الشروط أيضا في أصول الدين للبغدادي ص 171، والإرشاد للجويني ص 308 - 315، والغنية للمتولي ص 150 - 152.\r3) في الإرشاد ص 308 «فلا يجوز أن تكون المعجزة صفة قديمة، إذ لا اختصاص للصفة القديمة ببعض المتحدين دون بعض»."], [219, "والمعجزة حقها أن تكون مختصة بمن يدعي النبوة، فإذا قال مدعيها:\rمعجزتي في علم الله سبحانه أوقدرة الله، كان محالا، فإنه لا يخصص علم الله سبحانه صادقا عن كاذب.\rوإذا كانت المعجزة فعلا لله تعالى مع الشرائط التي سنشرحها، أمكن أن يقال: قصد الله [تعالى] بإظهارها تصديق من ظهرت على يديه.\rوأما قولنا: أوفي معنى الفعل، فالمراد به؛ أن مدعي النبوة لوقال:\rمعجزتي أن الرب تبارك وتعالى يمنع الخلائق في هذا اليوم عن القيام، فهذا ليس فعلا محققا، ولكنه في معنى الفعل، لأنه حكم حدده الله تبارك وتعالى لتصديق النبي 1.\rومنها: أن يكون خارقا للعادة، فإنه إذا كان معتادا يصدر من الصادق والكاذب، لم يتضمن اختصاصه بالنبي وتميزه عن غيره [به]، ووضوح ذلك يغني عن الإطناب فيه 2\rفإن قيل: كيف يتحقق خرق العادة مع العلم باختصاص آحاد الناس\r--------------------\rفي أ: ثم، والمثبت من ط.\rفي ط: معجزة في. في ط: الله تعالى.\rفي ط: قدرته. الزيادة من ط.\rفي أ: عليه. في ط: إذا.\rمعجزتي: ليست في ط. في ط: الرب تعالى.\rفي ط: الرب تعالى.\rفي أ: تصديق نبيه محمد صلى الله عليه وسلم، وما أثبته من ط.\rفي أ: يتغير، وما أثبته من ط. في أ: وتمييزه والمثبت من ط.\rالزيادة من ط. في ط: المعتاد.\r_____________________\r1) في الإرشاد ص 309: «ولوادعى نبي النبوءة وقال: آيتي أن يمتنع على أهل هذا الإقليم القيام مدة ضربها، فذلك من الآيات الظاهرة وليست هي فعلا بل هي انتفاء فعل».\r2) في الإرشاد ص 309: «إذ لوكانت عامة معتادة يستوي فيها البار والفاجر والصالح والطالح، ومدعي النبوءة المحق بها، والمفتري بدعواه، لما أفاد ما يقدر معجزا تمييزا وتنصيصا على الصادق»."], [220, "ببدائع يستأثرون بها دون عامة الخلق فإذا ادعى مدعي النبوة، وأتى بشيء [بديع]، لم نأمن من أن يكون قد استأثر بعلم خفي، وتذرع به إلى إظهار ما اختص به دون الناس، وربما كان عثر على جسم من الأجسام ذي خاصة غير معروفة ولا مألوفة، فليس للبدائع التي تعزى إلى خواص الأدوية نهاية.\rولوأبدى مبد حجر المغناطيس في قطر لم يسمعوا به، لتخيلوا جذبه للحديد خارقا للعادة، فكيف الأمان من هذا وما الذي يميز المعجزات منه 1\rقلنا: هذا تمويه على الضعفة، ولا يحتفل بأمثاله ذووالبصائر/، وسبيل الجواب عنه، أن المعجزة تنقسم قسمين 2:\rأحدهما: [ما] يكون فعلا بديعا خارقا للعادة.\rوالثاني: [ما] يكون منعا من المعتاد.\rفإن كان خارقا، فشرطه أن يترقى عن مسالك الظنون، وينتهي إلى مبلغ تنحسم فيه التقديرات التي تضمنها السؤال، وبيان ذلك بالمثال 3: إن من لم يتعد اختصاص أقوام بمزايا من العلوم-كما سبقت الإشارة إليه-فليس يجوز الزيادة من ط.\r-------------------------\rفي ط: تأمن أن.\rفي أ: مبدي، والمثبت من ط.\rفي ط: يتخيلون. في ط: الحديد.\rفي أ: تميزه، والمثبت من ط.\rفي ط: ليحفل. الزيادة من ط.\rالزيادة من ط.\r_______________________\r1) هذا القول من شبه البراهمة الذين ادعوا أن هذا الأمر قد يكون خارقا للعادة عند بعض الناس، أما العلماء الذين يطلعون على خواص الأجسام وتأثيراتها فقد يقفون على أسباب الظاهرة المدعى بها فلا تكون خارقة للعادة عندهم. انظر الإرشاد ص 311.\r2) انظر ذلك بشيء من التفصيل في مجرد مقالات الأشعري لابن فورك ص 176، 177، والإرشاد للجويني ص 307، والغنية للمتولي ص 151، ونهاية الإقدام للشهرستاني ص 417.\r3) انظر ذلك في الإرشاد أيضا ص 212."], [221, "أن تجري كل بديعة خارقة للعادة عن خواص الجواهر، ولا ينتهي الأمر في ذلك إلى تجويز كل ما يذكر له.\rومن انتهى إلى ذلك فقد خلع ربقة العقل من عنقه، وكابر البداهة، وجحد ضرورات العقول.\rولوشك شاك، في أن انقلاب عصا ثعبانا، ليس مما يتوصل إليه بخاصية جوهر، ودرك مزية في خفايا العلوم، فهومصاب في عقله.\rوكذلك من قدر ما كان يجري على عيسى صلوات الله عليه وسلامه من إحياء الموتى، وإبراء الأكمه والأبرص، إلى غيرها من آياته، من فن الحيل التي يتوصل إليها المستأثرون بدقائق العلوم، فهومختل معتوه. فما كان من المعجزات خوارق، فإنها تتميز تميزا قطعيا عن مراتب الصنائع البديعة، والأمور التي يختص بها خواص الناس. وهذا معنى خرق العادة في شرائط المعجزة 1.\rوالذي يوضح الحق في ذلك: إن من أظهر شيئا يختص به الخواص، وتحدى به الخلائق، ودعا بها إلى نفسه، فإن الدواعي تتوفر على محاولة معارضته، والتسبب إلى الإتيان بمثل ما أتى به، وسيعارض من هذا وصفه على القرب.\rوإن كان ما أتى به مدعي النبوة، مما يتوقع فيه مثل ذلك، لم تثبت نبوته مع اعتراض الشكوك. هذا في أحد القسمين، وهوما يكون خارقا\r-------------------\rفي أ: يجري. في ط: الأمر به قط.\rفي أ: البداية. في ط: فلو.\rفي ط: العصاحية. في ط: مزيد.\rفي ط: عيسى عليه السلام.\rالمستأثرون: ليست في ط.\rفي أ: ويتحدى. بها: ليست في ط.\rفي ط: منها.\rفي أ: نبوة، والمثبت من ط.\r________________________-\r1) يكرر الجويني هنا ما ذكره في الإرشاد ص 212، وهوفي ذلك لا يضيف شيئا جديدا عما ذكره الباقلاني في التمهيد ص 122 - 124."], [222, "للعادة بديعا في نفسه 1.\rوأما ما كان منعا من المعتاد، مثل أن يقول مدعي النبوة: آيتي أن يمتنع اليوم على العالمين القيام.\rفما كان كذلك، استحال أن يتوهم العاقل [ذلك] من مزية علمية خفية ودرك خاصية. وهذا مستبين لا حاجة فيه إلى فضل تقرير. فهذا مقدار غرضنا في الشرط الثاني من شرائط المعجزات 2.\rوالشرط الثالث: أن تعجز الخلائق عن معارضته، والإتيان بمثل ما أتى به، ولوعارضه معارض، لبطل ما ادعاه من اختصاص بانخراق العادة له 3.\rوالشرط الرابع: أن يدعي النبوة، ثم يظهر المعجزة مع/دعواه لها، وتحديه الخلائق بها، فتقع على حسب إيثاره في وقت اختياره مطابقة لدعواه. وهذا سر دلالتها على صدقه 4، كما سيأتي مشروحا إن شاء الله في ط: فأما ما يكون.\r----------------------------------------\rفي ط: عن. الزيادة من ط.\rوالشرط: ليست في ط. في ط: يعجز الخلق.\rفي ط: إذ لو. في ط: اختصاصه.\rوالشرط: ليست في ط.\rفي ط: من. في ط: ميز.\r____________________________\r1) انظر ذلك أيضا في الإرشاد ص 212.\r2) في الإرشاد ص 309: «آيتي أن يمتنع على أهل هذا الإقليم القيام مدة ضربها، فذلك من الآيات الظاهرة، وليست هي فعلا بل هي انتفاء فعل. . . والوجه عندي أن القعود المستمر مع محاولة القيام هوالمعجز، فرجع المعجز إلى الفعل، فإن قيل: إن القعود معتاد، والمعجز خارق للعادة، قلنا: القعود المستمر مع محاولة القيام في أقوام لا يعدون كثرة خارق للعادة، فهذا شريطة المعجزة».\r3) في الإرشاد ص 309: «ومن شرائطها أن تكون خارقة للعادة، إذ لوكانت عامة معتادة يستوي فيها البار والفاجر، والصالح والطالح، ومدعي النبوءة المحق بها والمفترى بدعواه، لما أفاده ما يقدر معجزا تمييزا وتنصيصا على الصادق».\r4) في الإرشاد ص 313: «أن يتحدى النبي بالمعجزة وتظهر وفق دعواه، فلوظهرت آية من شخص وهوساكت صامت فلا تكون الآية معجزة."], [223, "جل وعز في الفصل المشتمل على ذكر وجه دلالة المعجز.\rوالشرط الخامس: [أن] لا تظهر مكذبة له، وبيان ذلك بالمثال: إن مدعي النبوة لوقال: آيتي [أن] الله ينطق يدي هذه الآن، فنطقت وقالت: اعلموا معاشر الأشهاد، إن صاحبي مفتر كذاب، فقد أنطقني الذي أنطق كل شيء لتكذيبه فاجتنبوه. فهذه آية في تكذيبه 1.\rولوقال مدعي النبوة: آيتي أن الله تعالى يحيي هذا الميت، فأحياه الله كما ادعاه، ثم قام وله لسان ذلق، وشهد بتكذيب المدعي.\rفالذي أراه-حرس الله مولانا وتولاه-أن هذا لا يقدح في الإعجاز، فإنه لم يتحد بنطقه، وليس نطقه بعد أن أحياه الله تبارك وتعالى بدعا خارقا للعادة، وإنما إعجازه في حياته، فإذا قام حيا، ابتعد أن يؤمن أويكفر.\rوليس كذلك نطق اليد في الصورة المتقدمة، فإن المعجزة عين للنطق، وقد جرى مكذبا 2.\rسيأتي مشروحا إن شاء الله جل وعز، في ط: سنشرحه.\r--------------------------\rوالشرط: ليست في ط. الزيادة من ط.\rالزيادة من ط. الآن: ليست في ط.\rفي ط: وقد. في ط: بتكذيبه.\rفي ط: أن يحيي الله. الله: ليست في ط.\rفي ط: إذ ليس. في ط: بعد إحياء.\rتبارك وتعالى: ليست في ط.\rفي أ: ولما، والمثبت من ط.\r______________________________\r1) في الإرشاد ص 315: «ومن وجوده تعلق المعجزة بالتصديق أن لا تظهر مكذبه للنبي، مثل أن يدعي مدعي النبوة فيقول: آية صدقي أن ينطق الله يدي، فإذا أنطقها الله تعالى بتكذيبه وقالت: اعلموا أن هذا مفتر فاحذروه، فلا يكون ذلك آية».\r2) في الإرشاد ص 315: «ولوقال: آيتي أن يحيي الله هذا الميت فأحياه الله تعالى فقام وله لسان ذلق، فقال: صاحبكم هذا متخرص، وقد بعثني الله تعالى لأفضحه ثم خر صعقا. فقد قال القاضي رضي الله عنه: هذه آية لا تدل، والذي عندي في ذلك أن التكذيب إن كان خارقا للعادة فهوالذي يقدح في المعجزة، وذلك بمثابة نطق اليد بالتكذيب، فأما الميت إذا حي وكذب فتكذيبه ليس بخارق للعادة، وللنبي أن يقول: إنما الآية إحياؤه وتكذيبه إياي كتكذيب سائر الكفرة»."], [224, "وهذا تمام ما حاولناه من شرائط المعجزات، وتتضح أغراضنا فيها بالفصل الذي يليها.\r-------------------\rفي أ: فهو، والمثبت من ط."], [225, "فصل\rفي ذكر وجه دلالة المعجزة على صدق من ظهرت عليه\r\r"]], "pg": [218, 225]}, "474.35": {"x": [[225, "ليعلم الموفق لدرك هذه المعاني الشريفة، أن المعجزة لا تدل على الصدق حسب دلالة الفعل على الفاعل، فإن الفعل بعينه يدل على فاعله، واختصاصه ببعض الوجوه الجائزة، يدل على إرادة التخصيص، كما سبق لتمهيد هذه السبل في مفتتح العقيدة.\rفلا يتصور فعل غير دال على الفاعل، ولا يمتنع خارق للعادة يظهره الله تعالى بديا من غير اتصال بدعوى مدع، ثم لا يوصف بأنه يدل على تصديق. فوجه دلالة المعجزات على صدق مدعي النبوات؛ نزولها منزلة التصديق بالقول. وذلك يتضح بصورة نقدمها ونوضح الغرض منها.\rفنقول: إذا جلس ملك للناس، وتصدى لدخولهم عليه، وكان قد حز بهم أمر، وأطل عليهم مهم، فلما حضروا وأخذوا منازلهم ومراتبهم، قام قائم من خواص الملك وقال: معاشر الناس قد علمتم ما ألم بكم، وتبينتم أن الملك لم يجر اعتياده بمخاطبتكم كفاحا، وأنا رسوله إليكم في أمر يدرأ عنكم غائلة ما نزل بكم، وأنا في/دعواي هذه بمرأى من الملك ومسمع. أيها الملك: إن كنت رسولك الصادق في دعوى الرسالة فخالف عادتك، وقم واقعد، فقام الملك وقعد على حسب دعوى الرسول، نزل ذلك منزلة قوله:\r---------------------\rفي ط: الإرادة بتخصيص.\rفي ط: على ما بينا.\rلتمهيد هذه السبل: ليست في ط.\rفي ط: فاعل. في ط: العادة.\rفي أ: المعجزة، والمثبت من ط.\rفي ط: النبوة. في أ: بصوة.\rفي ط: تفرضها.\rفي أ: ومستمع، والمثبت من ط.\rفي ط: فيا أيها."], [226, "صدقت أنت رسولي. و [لو] لم يجر شيء من هذه المقدمات، فخالف الملك ما كان معتادا منه، وقام وقعد، لم يدل ذلك منه على تصديق، لأنه [لم] يقع موافقا للدعوى متصلا به 1.\rومغزى هذا الفصل يرشد إلى وجه اشتراط تعلق المعجزة بالدعوى، ويبين أنها تدل من حيث تنزل منزلة التصديق بالقول، فكذلك إذا قال النبي: معاشر الأشهاد، عرفتم أن إحياء الموتى، وقلب العصا [حية]، وفلق البحر، ليس مما ينال بحيلة أويتوصل إليه بفطنة ووسيلة، وإنما هومن فعل الإله المستأثر بالقدرة الأزلية، يا رب: إن كنت صادقا في دعوى النبوة فاقلب هذه العصا حية [وافلق البحر]، فانقلبت [وانفلق] كما أراد، كان ذلك قطعا بمثابة قول الله تبارك وتعالى: صدقت، أنت رسولي. وهذا يتصل مدركه بضرورات العقول 2.\r--------------\rالزيادة من ط. في ط: مخالف الملك عادته.\rالزيادة من ط. مغزى: ليست في ط.\rفي ط: تنزلت. في ط: وكذلك.\rفي أ: بأن. الزيادة من ط.\rفي ط: الإلهية. في ط: فيا.\rالزيادة من ط. الزيادة من ط.\rفي ط: الله تعالى.\r_________________________\r1) وهذا يتعلق بالشرط الثالث من شرائط شروط المعجزة، وهوأن تتعلق بتصديق دعوى من ظهرت على يده. وفي الإرشاد ص 213: «فإن من ادعى أنه رسول الملك وقال بمرأى منه ومسمع: إن كنت رسولك فقم واقعد ففعل الملك ذلك، كان ذلك بمثابة قوله: صدقت، ولولم يدع الرسول ذلك، بل ادعى الرسالة مطلقا، وقام الملك وقعد لما كان ذلك دالا على تصديقه، فلا بد من التحدي إذا».\r2) ومن شروط المعجزة كما ذكر الجويني في الإرشاد ص 314: «أن لا تتقدم المعجزة على الدعوى، فلوظهرت آية أولا وانقضت فقال قائل: أنا نبي والذي مضى كان معجزتي، فلا يكترث به، إذ لا تتعلق لما انقضى بدعواه».\rكذلك أجاز الجويني تأخير المعجزة عن دعوى النبوة، إذ قال ص 314: «إن تأخرت وطابقت الدعوى كانت آية، وذلك مثل أن يقول النبي: آية صدقي انخراق العادة بكذا وكذا وقت الصبح، فإذا وقع ذلك كما وعد، وكان خارقا للعادة، كان آية»."], [227, "فصل\rفي الكرامات "]], "pg": [225, 227]}, "474.36": {"x": [[227, "1\r\rقد كثر خبط الناس في إثباتها ونفيها 2، وقد ألفت في إثباتها والرد على منكريها كتابا 3، وأنا أذكر الآن لبابه في أسطر إن شاء الله جل وعز، فأقول:\r----------------\rفي ط: الله تعالى.\r_________________\r1) فرقت الأشاعرة بين الكرامة والمعجزة من ثلاثة وجوه، الأول: من جهة التسمية، فما يدل على صدق الأنبياء سموه معجزة، وما يظهر على الأولياء سموه كرامة، والثاني: إن صاحب المعجزة لا يكتمها، وإنما يظهرها ويتحدى بها المنكرين للنبوة، أما صاحب الكرامة فإنه الأولى أن يجتهد في كتمانها ولا يدعي فيها، فإن أطلع الله عليها بعض العباد، فهذا من باب التدليل على حسن منزلة صاحب الكرامة، أوعلى صدق دعواه فيما يدعيه من الحال، والوجه الثالث: إن صاحب المعجزة مأمون التبديل معصوم عن الكفر والمعصية بعد ظهور المعجزة عليه، وصاحب الكرامة لا يؤمن تبدل حاله. انظر أصول الدين للبغدادي ص 174، 175، والإرشاد للجويني ص 316، والغنية للمتولي ص 152، ونهاية الإقدام للشهرستاني ص 497، والمحصل للرازي ص 322، وغاية المرام للآمدي ص 361، والمواقف للأيجي ص 370.\r2) من الأشاعرة الذين نفوا حصول الكرامات الأستاذ أبوإسحاق الإسفراييني، وأبوعبد الله الحليمي. انظر المحصل للرازي ص 322، والمواقف للإيجي ص 370، أما المعتزلة فقد أجمعت بفرقها المختلفة على نفي الكرامات ولم يشذ إلا الخياط منهم. انظر المغني ج 15 ص 218 - 235، والمواقف ص 370، والإرشاد ص 316.\r3) لم يحدد الجويني عنوان هذا الكتاب، كذلك لم يذكر أصحاب التراجم مثل هذا المؤلف للجويني، وقد ذكره محمد الزحيلي في بحثه عن الجويني ص 112 تحت عنوان «الكرامات» معتمدا في ذلك على ما ورد في العقيدة النظامية، وهذا التحديد للعنوان لم يبن على دليل، فالجويني كما هوواضح أعلاه قد أشار إلى مضمون الكتاب وليس إلى عنوانه."], [228, "خوارق العادة ليست من فعل العباد، وإنما هي من فعل الرب تعالى وتقدس، فمن فطر السماوات والأرض، وسيطوي السماء 1، ويبدل الأرض غير الأرض 2، ويسير الجبال 3، ويفجر البحار 4، وينشر الموتى 5، قادر على أن يأتي ببديعة.\rوليس في فرض الإتيان بها قدح في النبوات، فإنا ذكرنا آنفا؛ أن المعجزة لا تدل بعينها، وإنما تدل من حيث تقع على وفق الدعوى في النبوة، فإذا لم تقع دعوى النبوة، أوقع الله ما يشاء مما يعتاد ومما لا يعتاد، فليس في تجويز الكرامات قدح في النبوات، إذا وقعت الإحاطة بوجه دلالة المعجزة على ما سبق، وما جاز في قدرة الله سبحانه، ولم ينخرم به الإعجاز. وقد نطق به القرآن، وتواترت به الآثار لا يجحده إلا مرتاب.\rفأما آي القرآن، فمنها: ما جرى على [يد] مريم عليها السلام من بدائع الآيات 6، ويستحيل أن تقدر معجزة لعيسى عليه السلام، فإنها جرت\r-------------------\rفي أ: يدل. في أ: يدل.\rفي أ: بقطع. في ط: ما.\rفي ط: جاء في قدرة الله. في ط: الأخبار فلا.\rفي ط: فأما ما أتي به.\rفي أ: دل. الزيادة من ط.\rعليه السلام: ليست في ط.\r________________\r1) قصد الجويني بذلك قوله تعالى: يوم نطوي السم?اء كطي السجل للكتب سورة الأنبياء، الآية 104.\r2) وهذا في قول الله تعالى: يوم تبدل الأرض غير الأرض والسم?او?ات سورة إبراهيم، الآية 48.\r3) كما في قول الله تعالى: يوم تمور السم?اء مورا (9) وتسير الجب?ال سيرا (10) سورة الطور، الآية 10، وقوله تعالى: ويوم نسير الجب?ال وترى الأرض ب?ارزة سورة الكهف، الآية 47، وقوله تعالى: وسيرت الجب?ال فك?انت سر?ابا (20) سورة النبأ، الآية 20، وقوله تعالى: وإذا الجب?ال سيرت (3) سورة التكوير، الآية 3.\r4) كما في قوله تعالى: وإذا البح?ار فجرت (3) سورة الانفطار، الآية 3.\r5) كما في قول الله تعالى: يخرجون من الأجد?اث كأنهم جر?اد منتشر سورة القمر، الآية 7.\r6) وضح الجويني في الإرشاد ص 320 هذه الكرامات بقوله: «فكان زكريا صلوات الله عليه يصادف عندها فاكهة الشتاء في الصيف وفاكهة الصيف في الشتاء. . . وتساقط عليها الرطب»."], [229, "قبل كونه، والمعجزات/لا تتقدم على ثبوت النبوات. ولوذهبت أنقل ما صح من الأخبار والآثار فيها لجاوزت موضوع المعتقد وحده 1\rفإن قيل: أيجوز ظهور الكرامة مع دعوى من تظهر عليه 2\rقلنا: ذهب بعض مجوزي الكرامات [إلى] أنها تظهر من غير إيثار واختيار، وزعم أنها بهذا الوجه تتميز عن المعجزات، وهذا قول من لم يحط بحقيقة الإعجاز 3. فإن المعجزة لا تدل من حيث تتعلق بالدعوى المطلقة المرسلة، وإنما تدل على النبوة من حيث تقع على وفق دعوى النبوة 4، فإن تعلق خارق عادة بدعوى أخرى، دل على صدق تلك الدعوى.\rوإذا استشهد من قام في المجلس المشهود الذي صورناه، وقال: أيها الملك، إني من المقربين عندك والمختصين في مجلسك، فإن كنت كذلك\r--------------\rفي ط: تقدم. في أ: النبوة والمثبت من ط.\rفي ط: ولونقلت. في ط: موضوع العقيدة.\rفي ط: أتجوزون ظهور الكرامات.\rفي أ: ممن والمثبت من ط.\rالزيادة من ط.\rفي ط: بدعوى الذي ادعى النبوة.\rفي ط: فإذا. في ط: والمخلصين في محبتك.\r_________________\r1) من الكرامات أيضا ما وقع لأهل الكهف، وقصة آصف الذي أحضر عرش بلقيس، وإلهام أم موسى بإلقاء موسى في النهر، وقصة عمر بن الخطاب مع سارية على الجبل، وما وقع لرسول الله صلى الله عليه وسلم في مولده وطفولته. . . وغير ذلك.\r2) انظر هذا الاعتراض والرد عليه مفصلا في الإرشاد ص 316.\r3) في الإرشاد ص 317: «وصار بعض أصحابنا إلى أن ما وقع معجزة لنبي لا يجوز وقوعه كرامة، فيمتنع عند هؤلاء أن ينفلق البحر، وتنقلب العصا ثعبانا، ويحيي الموتى كرامة لولي، إلى غير ذلك من آيات الأنبياء، وهذه الطريقة غير سديدة أيضا، والمرضي عندنا جملة خوارق العوائد في معارض الكرامات».\r4) في الإرشاد ص 319: «فإن المعجزة لا تدل لعينها، وإنما تدل لتعلقها بدعوى النبي الرسالة ونزولها منزلة التصديق بالقول»."], [230, "فقم واقعد، ففعل الملك [ذلك] دل على تصديقه.\rثم ما يجري من ذلك، لا يدل على أن مثل هذا لوجرى متعلقا بدعوى الرسالة، لم يدل على صدق مدعيها.\rنعم، لست أنكر أن سنة الله تبارك وتعالى إظهار الكرامات في الأغلب من غير إيثار واختيار، والذي ذكرناه في التجويز، لا في الإخبار عما تجري به سنة الله جلت قدرته، ولا يمتنع على القاعدة الممهدة، أن يظهر الله فتنة على [يد] من يدعي الربوبية من العتاة، كما ورد في الأقاصيص من إجراء الله النيل مع فرعون حيث ما دار، وكما ورد في الأخبار مما سيجري من الفتن وخوارق العوائد على المسيح الدجال 1.\rوليست هذه الأشياء خارقة للمعجزة، فإنا كررنا مرارا، أن المعجزة لا تدل لعينها 2، وإنما تدل من حيث توافق دعوى النبي، وليس من يدعي\r----------------\rالزيادة من ط. في ط: ثم ما هو.\rفي ط: ذلك. في ط: جرى هكذا من مدعي الولاية.\rفي ط: الله تعالى. في ط: الله تعالى.\rالزيادة من ط. في ط: العباد.\rفي ط: الله تعالى. في ط: النبوة.\r_________________________\r1) خروج الدجال أوالمسيح الدجال من العلامات العظمى لقيام الساعة، والدجال يكون قصير الجسم، أحمر الوجه، أعور العين اليسرى، بشع المنظر، مكتوب بين عينيه: كافر، فلا يخفى ذلك على كل مسلم، فيفارقه كل من في قلبه ذرة إيمان، وقد جاء في الأخبار أنه يخرج من جهة الشرق ويتجه نحوالغرب، فيدعي أولا النبوة ثم الألوهة فيتبعه أهل الفساد، ويستولي على المدن والقرى ما عدا مكة والمدينة، ومن الخوارق التي يقوم بها، إحياء بعض الذين يقتلهم، ويأمر السيل أن يسيل فيسيل، ثم الألوهة فيتبعه أهل الفساد، ويستولي على المدن والقرى ما عدا مكة والمدينة، ومن الخوارق التي يقوم بها، إحياء بعض الذين يقتلهم، ويأمر السيل أن يسيل فيسيل، ثم يأمره أن ييبس فييبس، ويأمر جبلان أن ينتطحا فينتطحا، ويمد يده الطويلة إلى البحر فيخرج من الحيتان ما يريد، ويتجه الدجال إلى بيت المقدس، فينزل عيسى بن مريم فيقتله في باب لد». وأيضا ينزل المطر ويهلك مواشي من يخالفه، وينبت الأرض، ومعه نهران يجريان الأول بالماء والثاني بالنار فالذي يراه الناس نارا فماء بارد، والذي يرونه ماء فنار تحرق. انظر فتح الباري لابن حجر ج 13 ص 96 - 113.\r2) انظر ذلك ص 228."], [231, "الإلهية طالب تصديق حتى يقال: إذا وافق ما جاء به طلب التصديق من الله كان [هذا] نازلا منزلة قوله تعالى: صدقت. ومن أحاط بما ذكرناه هان عليه درك الجواب عن كل ما يرد عليه مما سواه، وبالله التوفيق.\r----------------------\rفي ط: طلب. في ط: وافقت.\rفي ط: دلت على. الزيادة من ط.\rمما سواه وبالله التوفيق: ليست في ط."], [232, "فصل\rفي إثبات نبوة نبينا محمد صلى الله عليه وآله وسلم\r"]], "pg": [227, 232]}, "474.37": {"x": [[232, "نقول في افتتاح الكلام في ذلك: إن تعرض للطعن في نبوته ملحد معطل، فالوجه إثبات العلم بالصانع المدبر عليه أولا.\rوإن تعرض لرد نبوته برهمي، أثبتنا عليه النبوات على/الجملة كما سبق 1.\rوإن كان المعترض مليا، يقول بنبوة نبي قربت مكالمته، وكان كل ما يتمسك به، مما يحاول به مطعنا، منعكسا عليه فيمن اعترف بنبوته قاطعا.\rفإن قيل: ما معجزة رسولكم\rقلنا: في إثبات معجزاته مسلكان:\rأحدهما: التعلق بإعجاز القرآن، وقد أكثر الناس في وجه إعجاز القرآن، وتقطعوا فيه أيادي سبأ 2.\r-------------------\rفي ط: بيان. وآله: ليست في ط.\rفي أ: معجزته والمثبت من ط.\r______________________\r1) انظر ص 212.\r2) يقصد بذلك أن الذين بحثوا في إعجاز القرآن قد نحوا في ذلك مناحي عدة، فتشعبت بهم الآراء، وتباعدت بينهم المسافات، حتى أصبحوا لكثرة الاختلاف والتشعب أشبه بقوم سبأ عند ما عاقبهم الله تعالى على بطرهم للنعمة والغبطة والعيش الرغيد الذي كانوا فيه، وفي ذلك يقول الله تعالى: وجعلن?ا بينهم وبين القرى التي ب?اركن?ا فيه?ا قرى ظ?اهرة وقدرن?ا فيها السير سيروا فيه?ا لي?الي وأي?اما آمنين (18) فق?الوا ربن?ا ب?اعد بين أسف?ارن?ا وظلموا أنفسهم فجعلن?اهم أح?اديث ومزقن?اهم كل ممزق إن في ذ?لك لآي?ات لكل صب?ار شكور (19) سورة سبأ، الآيتان 18، 19، فتفرق قوم سبأ بعد خراب سد مأرب في البلاد. انظر تفسير ابن كثير ج 3 ص 533 - 535."], [233, "وصار معظم الناس: إلى أن القرآن تميز على صنوف الكلام بمزية البلاغة والجزالة، الخارجين عن المعتاد في ذلك 1.\rثم زعم زاعمون: أن إعجازه في شرف جزالته 2.\rوذهب آخرون: إلى أن إعجازه في الجزالة الفائقة، وأسلوبه الخارج عن أساليب النظم والنثر، والخطب والأراجيز.\rوهذا موقف تاه فيه الأولون والآخرون، وطعن فيه الطاعنون، وأنا بعون الله تعالى وحسن توفيقه، آتي فيه بمسلك الحق، وأبين عن واضح الوجوه اندفاع تمويهات الزائغين، وانتقاض مطاعن المبطلين 3 [إن شاء الله].\r-----------------------\rفي ط: ميز. في ط: ضروب.\rفي ط: بميزة. في أ: خارج.\rفي ط: ونبح.\rوإنا بعون الله تعالى وحسن توفيقه، ليست في ط.\rفي ط: أولي. في ط: مسلك الحق المبين.\rفي ط: على أوضح. الزيادة من ط.\r___________________________\r1) لخص الباقلاني في الإنصاف ص 54 موقف الأشاعرة من إعجاز القرآن فقال: «وفيه وجوه من الإعجاز، أحدها: ما اختص به من الجزالة والنظم والفصاحة الخارجة عن أساليب الكلام، وتحدى به فصحاء العرب بأن يأتوا بسورة من مثله فعجزوا عن الإتيان بمثله، وهم أهل الفصاحة والبلاغة، ولم يتأت لهم في ذلك في مدة ثلاث وعشرين سنة، ومن وجوه الإعجاز في القرآن اشتماله على قصص الأولين، وما كان من أخبار الماضين مع القطع بأنه صلى الله عليه وسلم كان أميا لا يكتب ولا يقرأ».\r2) ترى المعتزلة إلا النظام، وعباد بن سليمان، وهشام الفوطي، أن تأليف القرآن ونظمه معجز محال وقوعه منهم كاستحالة إحياء الموتى منهم، أما النظام فقد ذكر أن الآية في إعجاز القرآن ما فيه من الأخبار عن الغيوب، أما تأليفه ونظمه فقد جوز قدرة العباد على ذلك لولا أن أعجزهم ومنعهم من ذلك بمنع وعجز أحدثهما فيهم.\r3) بين الجويني الإعجاز في الإرشاد ص 349 بقوله: «عندنا أن القرآن معجز لاجتماع الجزالة مع الأسلوب والنظم المخالف لأساليب كلام العرب، فلا يستقل النظم بالإعجاز على التجريد ولا تستقل الجزالة أيضا»."], [234, "فليعلم المنتهي إلى ذلك، من رام أن يثبت إعجاز القرآن، بأنه في جزالته خارق للعادات، مجاوز لفصاحة اللد البلغاء، واللسن الفصحاء، فقد حاد عن مدرك الحق. فإن من تأمل كلام العرب في نظمها ونثرها، لم يتحقق عنده انتهاء جزالة القرآن، إلى حد الخروج عن العادة في الزيادة على كلام الفصحاء.\rومن تكلف إثبات ذلك فقد تكلف شططا، وظن غلطا، وتمشدق بالكلام الطويل من غير تحصيل 1. ومن أنصف وانتصف؛ ولم يتعسف، لم يلح له أن شعر امرئ القيس 2، والذبياني 3،. . .\r--------------------\rفي ط: المشتهي. في ط: للعادة.\rفي ط: مجاوز في الفصاحة أقدر البلغاء.\rفي ط: والفصحاء. في أ: كلف، والمثبت من ط.\rفي أ: وتهدف للكلام، والمثبت من ط.\r_____________________________\r1) في الإرشاد ص 349: «لوقدرنا الجزالة المحضة معجزة، لم نعدم سؤالا مستحيلا، إذ لوقال قائل: إذا قوبل القرآن بخطب العرب ونثرها وأشعارها وأراجيزها، لم ينحط كلام اللد البلغاء، واللسن الفصحاء عن جزالة القرآن انحطاطا بينا قاطعا للأوهام».\r2) امرؤ القيس (80 ق. ه‍/ 545 م): هوامرؤ القيس بن حجر بن الحارث الكندي من بني آكل المرار، شاعر جاهلي، يماني الأصل، كان أبوه ملك أسد وغطفان، أمضى شبابه في الصيد والغزل، ولما قتل أبوه، أخذ يسعى لاستعادة ملكه، لكن بني أسد هزموه بمساعدة الفرس، فاستنجد بالروم إلا أنهم خذلوه، لقب بالملك الضليل لأنه ضيع ملك أبيه، نظم معلقته في ابنة عمه عنزة، ومطلعها: قفا نبك. انظر ترجمته في طبقات الشعراء للجمحي ص 13، وشرح المعلقات السبع للزوزني ص 1، وخزانة الأدب للبغدادي ج 1 ص 299 والأغاني للأصبهاني ج 9 ص 77.\r3) الذبياني (-604 م): هوزياد بن معاوية بن ضباب بن سعد الذبياني، أبوأمامة، والنابغة لقب له، كان حكما بين الشعراء في سوق عكاظ، عاش في الجاهلية وعاصر حرب داحس والغبراء، له قصيدة البائية التي مدح بها الغساسنة، والدالية التي مدح بها النعمان من="], [235, "والجعدي 1، وزهير 2، وأعشى باهلة 3، والمعلقات السبع، وغيرها من أشعار المفلقين [من العرب]، تقصر في الجزالة عن القرآن.\rثم من بديع ما أنبه عليه-سامي رأي مولانا-أنه لوظهرت زيادة في ترقي القرآن عن مراتب الكلام، فليس فيه مقنع، فإنه قد يتفق في بعض\r---------------------\rالزيادة من ط. في ط: مرقى.\rفي ط: رتب. في ط: يبقى.\r________________________\r= المنذر، وهومن أصحاب المعلقات العشر، ومطلع معلقته: يا دار مية بالعلياء فالسند. انظر ترجمته في طبقات الشعراء للجمحي ص 17، والأغاني لأبي الفرج الأصبهاني. . .، والموشح للمرزباني ص 92، وخزانة الأدب للبغدادي ج 2 ص 116.\r1) الجعدي: قيس بن عبد الله بن عدس بن ربيعة بن جعد، المعروف بالنابغة الجعدي، أبوليلى، من الشعراء المخضرمين، مع هوى علوي، قيل إنه من أشعر الناس، لقب بالنابغة لأنه أقام مدة لا يقول الشعر ثم نبغ فيه، هجر في الجاهلية الخمر والأزلام والأوثان، سمع الرسول شعره فدعا له، خرج مع علي في حربه مع معاوية، وعمر طويلا وشهد أيام عبد الله بن الزبير، يقال إنه توفي بأصبهان. قارن به طبقات الشعراء للجمحي ص 26، الأغاني لأبي الفرج الأصبهاني ج 5 ص 1، والموشح للمرزباني ص 89، وخزانة الأدب للبغدادي ج 3 ص 150.\r2) زهير (530 - 627 م): هوزهير بن أبي سلمى (ربيعة) بن رباح المزني، من شعراء المعلقات، وكان حكيما في شعره، سميت قصائده بالحوليات لأنه كان ينظم قصيدته في شهر ويهذبها في سنة ثم يعرضها على أصحابه، شهد حرب داحس والغبراء التي دامت أربعين سنة، ثم قال معلقته مادحا من ساهم في وقفها.\rقارن عنه طبقات الشعراء للجمحي ص 15، وشرح المعلقات للزوزني ص 67، وخزانة الأدب للبغدادي ج 2 ص 290، والموشح للمرزباني ص 56.\r3) أعشى باهلة: هوعامر بن الحارث بن الحارث بن رياح الباهلي من همدان، أبوقحفان، شاعر جاهلي، اشتهر برائيته التي رثى فيها أخاه المنتشر بن وهب. انظر ترجمته في خزانة الأدب للبغدادي ج 1 ص 90، وسمط اللآلئ لأبي عبيد البكري ص 75، وطبقات فحول الشعراء لابن سلام الجمحي ص 203،210."], [236, "الأعصار، رجل قد تفرد في شعر أونثر لا يدرك شأوه، ولا يلحق منصبه في الفصاحة، وقلما يخلوعصر من مبرز لا يوازى في فنه، ولا يبارى فيما اختص به.\rولا يثبت الإعجاز بمثل ذلك، وقد قدمنا أنا نشرط في المعجزة 1، أن تجاوز في خرق العادة حدود/الظنون، وتبلغ مبلغا لا يتوقع الانتهاء إليه بمزية علم، وجودة قريحة ونفاذ طبع، ولباقة رأي، وإصابة فكر، وبعد غور.\rفإذا تقرر ذلك، فالوجه أن لا يدعى بلوغ جزالة القرآن مبلغ خرق العادة، بل نقول:\rتحدى الرسول صلى الله عليه وآله وسلم فصحاء العرب بأن يأتوا بمثل القرآن، كما أنبأ عنه قوله تبارك وتعالى: قل لئن اجتمعت الإنس والجن على أن يأتوا بمثل هذا القرآن لا يأتون بمثله 2، وتمادى على تحديه نيفا وعشرين سنة، والقرآن بلغتهم، وليس بعيدا من مبلغ اقتدارهم [في] جزالته وأسلوبه، فلم يقدروا على الإتيان بمثله.\rثم استأثر الله تبارك وتعالى برسوله صلى الله عليه وآله وسلم، وكرت الدهور، ومرت العصور، وأقطار الأرض تطفح بجميع الكفار ذوي الفطن النافذة، وتشوفهم أن يستمكنوا من مطعن في الإسلام، وفي كل قطر منهم\r----------------------------\rفي أ: قل ما. في أ: عن، والمثبت من ط.\rفي ط: يختص. في ط: نشترط.\rفي ط: ويبلغ. في ط: النبي.\rوآله: ليست في ط. في ط: يأتوا بمثله.\rمن قوله: كما أنبأ عنه. . . إلى قوله: بمثله، ليست في ط.\rالزيادة من ط. صلى الله عليه وآله وسلم: ليست في ط.\rفي ط: وشروفهم.\r_____________________\r1) انظر شروط المعجزة ص 216.\r2) سورة الإسراء، الآية 88."], [237, "طائفة مشتغلون بالنظم والنثر على لغة العرب، فقصرت قدر الخلق عن المعارضة في أربعمائة وستين سنة ونيف 1. فتبين قطعا [أن الخلق] ممنوعون عن مثل ما هومن مقدورهم، وذلك أبلغ عندنا من خرق العوائد بالأفعال البديعة في أنفسها 2.\rومن هدي لهذا المسلك فقد رشد إلى الحق المبين، وانعكس كل مطعن ذكره الطاعنون عضدا وتأييدا، فإنهم تارة: يدعون سقوط القرآن عن رتبة الجزالة، وولوجه في الركيك، وتارة: يسلمون شرف الجزالة، ويدعون أنه غير خارق للعادة، فكيف تصرفت أسئلتهم، فصرف الله الخلق عن الإتيان بمثله أوقع وأنجع. إذ الكلام كل ما كان أقرب مأخذا، وأبعد عن الغاية القصوى، كان أحرى أن يبتدر إلى معارضته، فإذا لم تجر المعارضة، لم يبق لامتناعها مع توفر الدواعي عليها محمل، إلا صرف الله الخلق.\r----------------------------------\rوستين سنة ونيف، ليست في ط.\rالزيادة من ط. في أ: ممنعون، والمثبت من ط.\rفي ط: مقدوراتهم. في ط: أرشد.\rفي أ: والوجه، والمثبت من ط. في ط: جزالته.\rفي ط: وكيف. في أ: أسولتهم، وما أثبته من ط.\rفي ط: أنجع وأوقع.\r____________________\r1) قد يكون ذلك هوتاريخ تأليف الجويني للعقيدة النظامية.\r2) إن دعوى حصر الإعجاز بصرف الله تعالى العباد عن الإتيان بمثل القرآن مع كونه مقدورا لهم لم تكن سبقا من الجويني، وإنما سبقه إلى ذلك كثيرون أشار إليهم الباقلاني في التمهيد ص 129، وأثنى على ذلك بقوله: «ومنهم أيضا من يقول: قد كانت العرب قادرة قبل التحدي على الإتيان بمثله، وإنما أعجزهم الله سبحانه عن ذلك وثبت تحدي الرسول صلى الله عليه وسلم ونقض عادتهم ليدل على صدقه، ولعمري إن ذلك لوكان كذلك لكان آية عظيمة وخرقا للعادة». وقد صرح النظام من المعتزلة بذلك إذ قال: «الآية والأعجوبة في القرآن ما فيه من الإخبار عن الغيوب، فأما التأليف والنظم فقد كان يجوز أن يقدر عليه العباد لولا أن الله منعهم بمنع وعجز أحدثهما فيهم».\rمقالات الإسلاميين ص 225، والملل والنحل للشهرستاني ص 56، 57، 103."], [238, "وهذا بمثابة لوقام النبي [صلى الله عليه وسلم] وقال: آيتي أنه يمتنع القيام الآن على الخلق مع اقتدارهم عليه من غير زمانة وعجز 1.\rفكيف يهتدي-حرس الله مولانا-إلى إعجاز القرآن من يحاول أن يثبت خروجه عن العادة في الجزالة. وشفاء الصدور في الحكم بأن مثله من مقدورات الخلق، ولكنهم مصدودون ممنوعون بصرف الله إياهم.\rوهذا الفصل، من أنفس ما يجري به خاطر، وهوخاتمة العقيدة في المآخذ العقلية، فهذا بالغ جدا، وهوعندي أبلغ من قلب العصاحية ونحوه، فإنه قد يسبق مبادر إلى أنه من اختصاص صاحبه بمزايا في العلوم، إلى أن يرده سداد الفكر، وإنما تحدى الخلائق خمسمائة سنة بكلام مماثل لكلامهم، قد بلغه رجل أمي لم يعان العلوم، ولم يدارس أهلها، فلا محمل له إلا صرف الله تبارك وتعالى ومنعه الخلق، فهذا وجه من ذكر معجزة رسول الله صلى الله عليه وآله وسلم.\rوالمسلك الثاني: أنه تواتر من طريق المعنى، أنه جرت عليه خوارق عادات 2 في قصده الدعاء إلى تصديقه: كشق القمر 3، ومكالمة الذئب\r--------------------------\rفي ط: وهذا يشابه ما لو.\rالزيادة من ط. آيتي، مكروه في أ.\rفي ط: الآن القيام. في ط: لإعجاز.\rفي ط: فإن. في ط: إلى أن يؤدي امتداد الفكر إليه.\rفي ط: فأما نحن في الخلائف. تبارك وتعالى: ليست في ط.\rفي ط: الخلق ومنعهم. في ط: النبي عليه السلام.\r___________________________\r1) يوضح الباقلاني ذلك في التمهيد ص 129 بقوله: «كما أن نبيا لوتحدى قومه بتحريك أيديهم والخروج عن أماكنهم إلى أقرب المواضع إليها، فمنعوا القدرة على ذلك، وقد اعتادوا الاقتدار عليه، ثم أقدروا عليه ثانية بعد تقصي تحديه، لكان خرق العادة بإيجاد القدرة على ذلك وإعدامها، على خلاف المتعالم المألوف آية عظيمة وحجه بينه».\r2) في مجرد مقالات الأشعري لابن فورك ص 178: «إن معجزات نبينا صلى الله عليه وسلم على قسمين أحدهما: القرآن الذي بين أظهرنا نقرأه ونكتبه. . . والثاني: ما جرى مجرى ما روي عنه من نبع الماء بين أصابعه، وإشباع الخلق الكثير من الطعام اليسير، وحنين الجذع، وكلام الذئب وتسبيح الحصا». وانظر التمهيد ص 114، والإرشاد للجويني ص 353، وأصول الدين للبغدادي ص 182.\r3) شق القمر: سأل أهل مكة رسول الله صلى الله عليه وسلم أن يريهم آية، فأراهم انشقاق القمر مرتين، ="], [239, "إياه 1، ونبع الماء من بين أصابعه 2، وتكثير الطعام القليل 3 حتى يكفي\r______________________________\r=ونزل قوله تعالى: اقتربت الس?اعة وانشق القمر (1) وإن يروا آية يعرضوا ويقولوا سحر مستمر (2) سورة القمر، الآيتان 1، 2. رواه البخاري في الصحيح ج 4 ص 186، باب سؤال المشركين أن يريهم آية، وفي التفسير سورة القمر ج 6 ص 53، ومسلم في صحيحه، كتاب صفة المنافقين، باب انشقاق القمر ج 9 ص 143، 144، وأحمد في المسند ج 1 ص 377، 413، 447، وج 3 ص 275، 278، وج 4 ص 82.\r1) حديث الذئب: بينما كان رجل من أسلم يرعى غنما له فأقبل ذئب وانتزع منها شاة، فرماه الرجل بالحجارة، ثم أقعى الذئب، وأخذ يكلم الرجل، فتعجب الرجل من تكليم الذئب له، فقال له الذئب: قد تركت أعجب من ذلك، هناك رسول الله صلى الله عليه وسلم يحدث الناس بما خلا ويحدثهم بما هوآت، وأنت هاهنا تبع غنمك، فذهب الرجل يسأل عن رسول الله صلى الله عليه وسلم، فأخبره خبر الذئب، فقال له: لقد صدقت، فلما صلى الرسول الصلاة واجتمع الناس أخبرهم الأسلمي خبر الذئب. رواه أحمد في المسند ج 2 ص 306، ج 3 ص 83، 88، 89، وأبونعيم في دلائل النبوة ج 2 ص 132، وابن سعد في الطبقات الكبرى ج 1 ص 173، والذهبي في تاريخ الإسلام (السيرة النبوية) ص 351.\r2) في صحيح البخاري ج 1 ص 61،62، كتاب الوضوء، باب رقم 47: عن أنس أن النبي صلى الله عليه وسلم دعا بإناء من ماء فأتي بقدح رحراح فيه شيء من ماء فوضع أصابعه فيه، قال أنس: فجعلت أنظر إلى الماء ينبع من بين أصابعه، قال أنس: فحزرت من توضأ ما بين السبعين إلى الثمانين. وانظر أيضا كتاب الأنبياء، باب علامات النبوة ج 4 ص 170، وقارن بألفاظ مختلفة، ابن سعد، الطبقات الكبرى لابن سعد ج 1 ص 178، ودلائل النبوة لأبي نعيم ج 2 ص 144، والسيرة النبوية من تاريخ الإسلام للذهبي ص 343.\r3) من ذلك، طرحه البركة في تمر ابنة بشير بن سعد، إذ كانت تحمل حفنة تمر في ثوبها قاصدة إطعام خالها عبد الله بن رواحة وأبيها سعد، فمرت برسول الله صلى الله عليه وسلم، فطلب منها رسول الله صلى الله عليه وسلم أن تصب التمر في كفيه، ثم أمر بثوب فبسط له، ثم دعا بالتمر عليه فتبدد فوق الثوب، ثم قال لإنسان عنده: اصرخ في أهل الخندق أنه هلم إلى الغذاء، فاجتمع أهل الخندق فجعلوا يأكلون منه، وجعل يزيد حتى صدر أهل الخندق عنه وإنه ليسقط من أطراف الثوب. الطبقات الكبرى لابن سعد ج 1 ص 177، وخاتم النبيين لمحمد أبي زهرة ج 2 ص 926."], [240, "الجمع الكثير والجم الغفير، إلى غيرها مما وردت به الأخبار 1.\rوكل قصة من تلك القصص، وإن لم تتواتر في نفسها، فقد ثبتت بمجموعها أن محمدا صلى الله عليه وسلم كان يجري عليه في معرض الدعوة [من خوارق العادة]، ما يعجز عنه غيره. والمعاني الكلية تثبت بالوقائع التي تنقل أفرادها آحادا، وهذا: كعلمنا بشجاعة علي بن أبي طالب عليه السلام، هذا ضروري مستفيض، ولكنه متلقى من أقاصيص نقلت من آحاد، وكذلك الطريق في العلم بسخاء حاتم الطائي، إلى غيره من المعاني الكلية.\rثم السر في هذا الفصل، أنه قد تحقق بالتواتر والاستفاضة، تعلقه صلى الله عليه وسلم بأجناس مختلفة من البدائع، ولوعارض شخص [في] واحد منها لوهت دعواه وانطلقت الألسن فيه، وتحزب أصحابه: إلى مرتاب فيه، وإلى ذاب عنه تقليدا، ولانتثر نظام الأمر. فإذا لم يتعرض أحد لمعارضة في شيء مما جاء به، كان ذلك أصدق آية على تميزه على الخلائق بالنبوة. والحمد لله الذي هدانا لهذا، وما كنا لنهتدي لولا أن هدانا الله.\rوفيت-حرس الله أيام مولانا-الأركان الثلاثة الموعودة، ولووقفت عند نجازها، لكان فيما قدمته أكمل/مقنع. ولكني بعد ما أتيت بالواضحة على صدق سيد الأولين والآخرين، فأرسم فصولا سمعية من قواعد الإيمان،.\r---------------------\rفي أ: ذلك، والمثبت من ط\rفي أ: فإن. الزيادة من ط.\rمن قوله: بشجاعة علي. . . في العلم، ليست في ط.\rفي ط: تعلقه عليه السلام.\rالزيادة من ط. في ط: دعوته.\rوإلى: ليست في ط. في ط: في.\r_______________________\r1) ومنها: تسبيح الحصى في يده، وحنين الجذع والجمل، وتكليم الظبية المربوطة له، وطلبها أن يحل قيودها. انظر دلائل النبوة لأبي نعيم ج 2 ص 133، وتاريخ الإسلام (السيرة النبوية) للذهبي ص 350."], [241, "فأكتفي بالمؤمن إليها، بعد تقديم الاستباق التام بوجوب اعتقاد صدقه، فنعقد بابا تحوي فصولا اعتقادها من الإيمان.1\r_________________________\r1) من قوله: والحمد لله. . . من الإيمان، ليست في ط."], [242, "باب\rفي السمعيات\r\r"]], "pg": [232, 242]}, "474.38": {"x": [[242, "من ثبت صدق لهجته إذا خبر عن كائن ممكن، حصل العلم به لا محالة، لأن المخبر عنه ممكن مقدور لله سبحانه، والمخبر صادق 1.\rثم من أسرار الدين-وهي علق مضنة 2 - أن يعلم اللبيب أن المعلومات تنقسم إلى العقليات والسمعيات. فما كان معقولا وجد العاقل له ثلجا في نفسه وانشراحا في قلبه، وما تلقاه من السمع فهوغير مرتاب فيه، ولكنه لا يجد من نفسه الثلج الذي يجده من المعقولات، فإن المخبر وإن كان مصداقا، فالمصدق فيه مقلد، ولن يبلغ العالم [الناقل] عن تقليد الصادق مبلغ من أدرك الشيء بعقله 3.\r----------------------\rفي أ: فإن، وما أثبته من ط.\rفي ط: هو. كتبت في أ: البيب.\rالزيادة من ط.\r___________________\r1) اتفق الفقهاء والمتكلمون على اعتبار كل خبر قصر عن إيجاب العلم بأنه خبر واحد، سواء رواه الواحد أوالجماعة التي تزيد عن الواحد. انظر الإحكام في أصول الأحكام لسيف الدين الآمدي ج 2 ص 33.\r2) علق مضنة: العلق، النفيس من كل شيء، والمضنة: أي يضن به، والمقصود، أن هذا السر من الدين الذي صرح به الجويني نفيس يضن بالتصريح به. انظر لسان العرب، مادة علق ج 10 ص 268.\r3) اتفق الجمهور من الفقهاء والمتكلمين على أن العلم الحاصل عن خبر التواتر ضروري، بمعنى أنه لا يحتاج إلى واسطة مفضية إليه، مع العلم أن هذه الواسطة حاضرة في الذهن، مثل قولنا: القديم لا يكون محدثا، والموجود لا يكون معدوما، ولم يشذ عن ذلك إلا أبا الحسين البصري من المعتزلة، إذ عد العلم الحاصل من التواتر نظريا. انظر الإحكام في أصول الأحكام لسيف الدين الآمدي ج 2 ص 30، 32."], [243, "وإنما ذكرت هذا حتى إذا وجد الموحد نفسه في السمعيات دون وجدانه نفسه في العقليات، لا يتهم إيمانه، ولا يشك في إيقانه.\rثم ما يقتضيه الدين القويم، والمنهج المستقيم، أن كل ما نقل عن النبي صلى الله عليه وسلم بطرق صحيحة، مرتضاة عند أهل الإثبات، وكان ممكنا غير مستحيل، فإن كان النقل تواترا، علم قطعا على حد العلم بالسمعيات.\rوإن كان النقل آحادا 1، ثبت ذلك المظنون في مأثور الأخبار، وتلقي بالقبول، ولم يعارض بالاستبعاد، فإن الاستبعاد فيما هذا سبيله من شيم المرتابين في [قواعد] الدين.\r-------------------\rفي أ: إنما. في أ: وجدت الموجد.\rفي ط: النبي عليه السلام. في أ: تواتر، وما أثبته من ط.\rفي ط: كان العلم قطعا. في أ: بالمستمعات، والمثبت من ط.\rفي أ: وإن نقل، وما أثبته من ط. في ط: الظنون.\rبالاستبعاد: ليست في ط. في ط: فالاستبعاد.\rالزيادة من ط.\r_______________________\r1) انظر الخلاف في العمل بخبر الواحد، الإحكام في أصول الأحكام للآمدي ج 2 ص 48 - 83."], [244, "فصل\rفي إعادة الخلق\r\r"]], "pg": [242, 244]}, "474.39": {"x": [[244, "هذا الفصل يستدعي تقديم إثبات جواز الإعادة عقلا، فنستبين الحجاج من احتجاج الله تعالى على منكري الإعادة إذ قال الله تبارك وتعالى: ق?ال من يحي العظ?ام وهي رميم (78) قل يحييها الذي أنشأه?ا أول مرة 1. فاحتج رب العزة بقدرته على الإنشاء الأول، على قدرته على الإعادة 2.\rفإن الإعادة نشأة ثانية، ومن قدر بالقدرة/الكاملة على شيء قدر على مثله. والنشأة الثانية في معنى النشأة الأولى قطعا، ومن لم يعترف بالنشأة فهوملحد، والوجه مكالمته في إثبات الصانع، ومن اعتقد الأولى لم يبعد الثانية 3.\r--------------------\rفي ط: إثبات تقديم. في ط: فنستثير.\rفي ط: على منكر في الإيمان.\rفي ط: قال سبحانه.\rفي ط: فاحتج سبحانه.\rفي ط: ومن قدر على شيء بالقدرة الكاملة.\rفي أ: معنا.\rقطعا: ليست في ط.\r____________________\r1) سورة يس، الآيتان 78، 79.\r2) في أسباب النزول للواحدي ص 303، قال المفسرون: إن أبي بن خلف أتى النبي صلى الله عليه وسلم بعظم حائل، فقال: يا محمد أ ترى الله يحيي هذا بعد ما قد رم، فقال: نعم، ويبعثك ويدخلك في النار، فأنزل الله تعالى هذه الآيات. وانظر القرطبي، جامع البيان ج 15 ص 58.\r3) توسع الجويني في هذه المسألة فانظرها في الإرشاد ص 371 - 374."], [245, "ثم نقرب من ذلك قولا فنقول: إذا حميت الأرض أوان الربيع، فنشأ منها النبات وضروب من الحشرات لا تعد. فما المانع من أن يجمع الله تعالى [في] الأرض على مجرى العادة، صفات تقتضي أن ينشر منها الحيوانات كلها على حكم العادة في إنبات النبات، وإخراج الثمرات 1. فإذا ثبت الجواز، فقد نطق الكتاب ومتواتر السنن بنشر الخلائق ليوم الدين، وقيامهم لرب العالمين.\r----------------\rفي أ: يقرب، والمثبت من ط.\rالزيادة من ط. في ط: وإذا.\rفي ط: نص.\r_____________________\r1) وهذا المثل الذي ساقه الجويني هوقياس مع الفارق، إذ إن النبات والديدان قبل الربيع لا تكون في حالة الموت التام، فالبذور موجودة، وبيوض الديدان أيضا موجودة، وقد طبع الله في هذا الكون سننا تعمل باضطراد، فإذا ما توافرت السنن المتعلقة بإعادة الحياة من جديد في بذور النبات وبيوض الحشرات، دبت فيها الحياة، أما حالة الموت في البشر فهي شاملة تامة، لذا يكون بعثهم للحياة من جديد أبلغ من حالة النبات والديدان."]], "pg": [244, 245]}, "474.40": {"x": [[246, "فصل في عذاب القبر 1 وسؤال منكر ونكير 2\rليس ذلك من مستحيلات العقول، فإن القادر على الخلق والإعادة، والإحياء والإماتة، إذ أراد رد الأرواح إلى قوالبها ردها.\rثم الوجه عندي في ذلك أن يقال: الفاهم من الإنسان في حياته، أجزاء\r______________________\r1) أجمع أهل السنة على ثبوت عذاب القبر، ومعتمدهم في ذلك، قول الله تعالى في آل فرعون: النار يعرضون عليه غدوا وعشيا ويوم تقوم الساعة أدخلوا آل فرعون أشد العذاب، (46) فالعرض على النار غدوا وعشيا قبل قيام الساعة، وقوله تعالى: فذرهم حتى يلاقوا يومهم الذي فيه يصعقون (45) فقبل اليوم الذي يصعق فيه العباد يخصص عذاب للذين ظلموا وهوعذاب القبر. ومن الأحاديث التي استندوا إليها في إثبات عذاب القبر أن رسول الله صلى الله عليه وسلم، مر بقبرين فقال: «إنهما ليعذبان» وقوله: «لولا أن لا تدافنوا لدعوت الله أن يسمعكم من عذاب القبر الذي أسمع منه». وقوله: «القبر روضة من رياض الجنة، أوحفرة من حفر النار». انظر الإبانة للأشعري ص 183، ومجرد مقالات الأشعري ص 170 لابن فورك، والإنصاف للباقلاني ص 45، والإرشاد للجويني ص 374، والمغني للمتولي ص 163.\r2) وإلى ذلك ذهب جميع أهل السنة، وحجتهم في ذلك قول الرسول صلى الله عليه وسلم: «العبد إذا وضع في قبره وتولى وذهب أصحابه حتى إنه ليسمع قرع نعالهم، أتاه ملكان فأقعداه فيقولان له: ما كنت تقول في هذا الرجل محمد صلى الله عليه وسلم، فيقول: أشهد أنه عبد الله ورسوله، فيقال: انظر إلى مقعدك من النار، أبدلك الله به مقعدا من الجنة». قال النبي صلى الله عليه وسلم، فيراهما جميعا، وأما الكافر أوالمنافق، فيقول: لا أدري، كنت أقول ما يقول الناس، فقال: لا دريت ولا تليت، ثم يضرب بمطرقة من حديد ضربة بين أذنيه، فيصيح صيحة يسمعها من يليه إلا الثقلين».\rرواه البخاري، الجنائز 68، 87 ج 2 ص 113، وانظر أيضا صحيح مسلم بشرح النووي 7، وسنن أبي داود، سنة 24، وسنن النسائي، جنائز ص 109، 110، ومسند أحمد ج 3 ص 126، 233."], [247, "لطيفة في قلبه أوفي دماغه، وجوارح العمل [والبطش] مستخدمة لتلك الأجزاء الفاهمة المدبرة، وليس لليد والرجل واللحوم والعضل والعظام حظ من العلم، فلعل الله تعالى-وهوالعالم بسر غيبه -يرد الروح إلى تلك الأجزاء اللطيفة ولمثلها، إلى أي صورة شاءها 1.\rوسؤال الملكين يتوجه عليها، وهي التي كانت تفهم استمرار الحياة، وهذا يدرأ تمويه الملحدة [إذ] قالوا: نحن نشاهد هذا الميت في لحده ميتا 2.\rومن وقر الإيمان في صدره، ولم يبعد عنده أن يأتي جبريل رسوله وهويراه دون من معه، لم يبعد عنده ما ذكرناه مع التقريب الذي أوضحناه 3.\rولوذهبت-أطال الله بقاء مولانا-أتكلم في الروح لطال المرام، وقد جمعت فيه كتابا سميته كتاب النفس 4، وهويشتمل على قريب من ألف ورقة.\r------------\rفي أ: قلله، والمثبت من ط.\rالزيادة من ط. في ط: المريدة.\rواللحوم: ليست في ط. في ط: والعضد.\rوهوالعالم بسر غيبه، ليست في ط.\rفي ط: على. في ط: تفهم في.\rفي ط: الملحدين. في ط: قبره.\rفي أ: لم، والمثبت من ط. فيه: ليست في ط.\r_____________________\r1) قرر الأشعري أن العذاب بمثابة آلام يحس بها الحي فيتعذب بها ويتألم، وليس بمنكر أن يعيد الله تعالى الحياة في أجزاء الحياة التي خلق فيها الموت ثم يخلق فيها الألم، لأن خلق الحياة لا يقتضي تركيب محلها، فكل جزء فيه حياة فهوحي. انظر مجرد مقالات الأشعري لابن فورك ص 170، والإنصاف للباقلاني ص 45، والإرشاد للجويني ص 374، 376، والمغني للمتولي ص 163.\r2) أنكر بعض القدرية عذاب القبر وسؤال منكر ونكير، انظر أصول الدين للبغدادي ص 245 - 246.\r3) انظر مثل ذلك أيضا في الإرشاد ص 376.\r4) هذا الكتاب هو في حكم المفقود، إذ لم يرد ذكره في فهارس المخطوطات، وانظر تعليق فوقية حسين على هذا الكتاب في لمع الأدلة ص 50."], [248, "فإذا ثبت الجواز، فقد تقرر قطعا أن رسول الله صلى الله عليه وآله وسلم، كان يستعيذ من عذاب القبر، ويأمر أصحابه بالاستعاذة منه 1. وليس هذا مما يحتاج فيه إلى تكلف نقل ورقاته، بل لم يزل المسلمون يقرنون بين عذاب القبر والنار/والاستعاذة منهما بالله تبارك وتعالى.\r---------------\rوآله: ليست في ط. فيه: ليست في ط.\rفي أ: تكليف، والمثبت من ط.\rبل لم: في ط: ولم. في أ: يقرقون.\rفي أ: منها، والمثبت من ط.\rفي ط: والاستعاذة بالله تعالى منهما.\r_______________________\r1) ومنها الحديث الذي رواه أبوداود في السنن أدب 101 ج 2 ص 324: «رب أعوذ بك من عذاب النار ومن عذاب في القبر». والحديث الذي رواه أحمد في المسند ج 5 ص 271 وفيه: أن رسول الله صلى الله عليه وسلم كان يقول عند طلوع الفجر: «اللهم إني أعوذ بك من عذاب القبر ومن فتنة القبر». والحديث الذي روته عائشة ج 6 ص 57: «أن رسول الله صلى الله عليه وسلم كان يدعوبهؤلاء الدعوات: اللهم إني أعوذ بك من فتنة المسيح، وعذاب النار، وفتنة القبر، وعذاب القبر» وج 6 ص 207."], [249, "فصل\rفي الجنة والنار والصراط والميزان\r\r"]], "pg": [246, 249]}, "474.41": {"x": [[249, "لا استحالة في تقديم خلق الجنة والنار على يوم الجزاء 1، فهما من خلق الله سبحانه كالعرش والكرسي، ولا يضيق عن تجويز تقديم خلقهما إلا صدر مرتاب 2.\rوالجنان خارجة عن أقطار السماوات والأرض، فلا احتفال بقول من يقول: كيف تنطوي عليها السماوات وقد قال بعض الحكماء: لواكتملت عقول الناس في بطون أمهاتهم وهم أجنة ثم نظروا، لذهب معظمهم إلى أنه لا بد من عالم سوى ما هم فيه.\r---------------\rفي ط: عليهما. في أ: أكمل، والمثبت من ط.\r____________________________\r1) في الإنصاف للباقلاني ص 47، والدليل على أن الجنة والنار مخلوقتان قوله تعالى: وجنة عرضها السم?او?ات والأرض أعدت للمتقين سورة آل عمران، الآية 133، والمعد لا يكون إلا موجودا مهيئا وأيضا قوله: أ فحسب الذين كفروا أن يتخذوا عب?ادي من دوني أولي?اء إن?ا أعتدن?ا جهنم للك?افرين نزلا (102) سورة الكهف، الآية 102، وأيضا قوله صلى الله عليه وسلم: «عرضت علي ليلة الإسراء الجنة والنار». وفي الإرشاد للجويني ص 377، 378 عرض أشمل لموقف الجويني في هذه المسألة. وانظر أيضا الإشارة للشيرازي ص 250.\r2) أنكرت طوائف من المعتزلة خلق الجنة والنار، وزعموا أن لا فائدة في خلقهما قبل يوم الثواب والعقاب، وحملوا ما نصت الآية عليه في قصة آدم عليه السلام على بستان من بساتين الدنيا. ومن هؤلاء، الإرشاد للجويني ص 378، وأصول الدين للبغدادي ص 237. والمعتزلة لجار الله ص 144. الهشامية أتباع هشام بن عمروالفوطي (266 ه‍)."], [250, "وعلى الجملة، من اقتصر نظره في التجويز على ما يراه ويعانيه، لا يتصور أن يدرك من المعقولات مدركا.\rفإذا ثبت الجواز، فقوله تبارك وتعالى: أعدت للمتقين 1 نص في أن الجنة كائنة مخلوقة معدة.\rوأما الصراط 2؛ فجسر ممدود على متن النار، وليس مستحيلا. فإن استنكر مرتاب وقوف الخلائق عليه على دقته، قيل له: لوأقر الله [تعالى] العالمين في الهواء من غير عماد وسند، لم يبعد، سيما والسماء والأرض مقرتان كذلك 3.\rوأما الميزان 4؛ فهوكائن معترف به، وإن جحده معاند وزعم أن\r------------------------\rفي ط: لا يفترض. في ط: العقولات.\rتبارك وتعالى: ليست في ط. في أ: كانت، والمثبت من ط.\rفي ط: في وقته. في ط: إن.\rالزيادة من ط. في ط: النيرين.\rفي أ: وساد، والمثبت من ط. في أ: جحد، وما أثبته من ط.\r______________________________\r1) سورة آل عمران، الآية 133.\r2) مما اتفقت عليه الأشاعرة إثبات الصراط، وهوجسر ممدود على متن جهنم يرده الخلق كافة، فمنهم من يمر عليه كالبرق الخاطف، ومنهم من يمر عليه كالجواد من الخيل. . . وهكذا، ويقع منه العصاة والفساق والكافرون في النار. انظر مجرد مقالات الأشعري لابن فورك ص 171، والإنصاف للباقلاني ص 46، وأصول الدين للبغدادي ص 245، والملل والنحل للشهرستاني ص 103، والاقتصاد للغزالي ص 98، وإحياء علوم الدين ج 1 ص 201، والغنية للمتولي ص 166، والإشارة للشيرازي ص 251.\r3) انظر مزيدا من الأدلة أوردها الجويني على ذلك في الإرشاد ص 380.\r4) وهوأن ينصب ميزان يوم القيامة له كفتان توزن فيهما أعمال العباد، فيتبين بثقله وخفته سعادة السعيد وشقاوة الشقي من جهة العباد.\rانظر مجرد مقالات الأشعري لابن فورك ص 171 - 172، والإنصاف للباقلاني ص 46، وأصول الدين للبغدادي ص 246، والاقتصاد للغزالي ص 98، والغنية للمتولي ص 166، 167، والتبصير للإسفراييني ص 156، ونهاية الإقدام للشهرستاني ص 469، وإحياء علوم الدين للغزالي ج 3 ص 200، ومعالم أصول الدين للرازي ص 128، والمواقف للإيجي ص 383."], [251, "الأعمال أعراض لا توزن، قيل: الموزون صحائف الأعمال، ثم الله [تعالى] يزنها ويحققها في الميزان على أقدار زنتها في علمه. وقد تواترت الأخبار في الميزان وصفته، وذكر وصف كفتيه وترجحهما بالطاعات والسيئات 1.\rومن أنكر هذه الأشياء، فما أحراه بأن ينكر النشر والحشر، وإحياء العظام وهي رميم، وبدائع الآيات وفنون المعجزات، أعانا الله من الضلالات بمنه ولطفه.\r-----------------------\rالزيادة من ط. في أ: يزونها، والمثبت من ط.\rفي ط: ويخفضها. في أ: عمله.\rوصف: ليست في ط. في ط: فما أحرى أن ينكر.\rالنشر: ليست في ط. في ط: ويدفع.\rأعاذنا الله من الضلالات بمنه ولطفه: ليست في ط.\r_______________________________\r1) ومما استشهد به الأشاعرة على أن الميزان حق، قول الله تعالى: ونضع المو?ازين القسط ليوم القي?امة فلا? تظلم نفس شيئا وإن ك?ان مثق?ال حبة من خردل أتين?ا به?ا وكفى? بن?ا ح?اسبين (47) سورة الأنبياء، الآية 47، وقوله: أول?ئك الذين كفروا بآي?ات ربهم ولق?ائه فحبطت أعم?الهم فلا? نقيم لهم يوم القي?امة وزنا (105) سورة الكهف، الآية 105، ومن الأحاديث قول الرسول صلى الله عليه وسلم، عن عائشة أنها ذكرت النار فبكت، فقال رسول الله صلى الله عليه وسلم: «ما يبكيك» قالت: ذكرت النار فبكيت، فهل تذكرون أهليكم يوم القيامة فقال رسول الله صلى الله عليه وسلم: «أما في ثلاثة مواضع فلا يذكر أحد أحدا: عند الميزان حتى يعلم أيخف ميزانه أويثقل، وعند الكتاب حين يقال هاؤم اقرؤوا كتابيه حتى يعلم أين يضع كتابه، أفي يمينه أم في شماله أم من وراء ظهره، وعند الصراط إذا وضع بين ظهري جهنم» رواه أبوداود سنه 25 ج 2 ص 25. وانظر الإنصاف للباقلاني ص 46، المجرد لابن فورك ص 172."], [252, "فصل\rفي الشفاعة\r\r"]], "pg": [249, 252]}, "474.42": {"x": [[252, "اتفق أهل الحق على إثبات الشفاعة 1. وهذا يستدعي تقديم قول في جواز غفران الذنوب فنقول 2:\rمن استقر في عقده أن الله تبارك وتعالى يفعل ما يشاء، وتقرر لديه بما قدمناه: أنه لا يجب على رب الأرباب ثواب ولا عقاب 3، لم ينكر جواز غفرانه وعفوه.\rوإن نزلنا على مقدار عقول المخالفين، في تشبيههم أحكام أفعال الله تبارك وتعالى بأفعال المخلوقين، فقد تقرر عند/العقلاء قاطبة، أن العفوفي ط: عنده.\r---------------------\rفي ط: الله تعالى. في ط: أن رب الأرباب لا يجب عليه.\rفي أ: ولا، والمثبت من ط. في أ: فعل، وما أثبته من ط.\rبأفعال المخلوقين: ليست في ط.\r______________________\r1) أجمع الأشاعرة على صحة الشفاعة من الرسول صلى الله عليه وسلم لأهل الكبائر من أمته، واستدلوا على ذلك بأدلة من القرآن والسنة. انظر في ذلك رسالة أهل الثغر للأشعري ص 97، والإبانة ص 177، والمجرد لابن فورك ص 167، والإنصاف للباقلاني ص 47، 149، والتمهيد ص 415، والاعتقاد للغزالي ص 153، وأصول البغدادي ص 244، والفرق بين الفرق ص 339، والتبصير للإسفراييني ص 156، والملل والنحل للشهرستاني ص 101، ونهاية الإقدام ص 470، والغنية للمتولي ص 172، ومعالم أصول الدين للرازي ص 133، والأربعين ص 419، والمواقف للإيجي ص 380، والإرشاد للجويني ص 393، 394.\r2) هوعينه في الإرشاد ص 393.\r3) لا توجب الأشاعرة على الله تعالى شيئا، انظر ص 273 هامش رقم 1."], [253, "والصفح، والتجاوز عن المجرمين، من مكارم الأخلاق ومعالي الأمور.\rوقد أطبقت طبقات الخلق على تفنن آرائهم، واختلاف أهوائهم، على تحسين التجاوز والعفوعند القدرة. ثم إذا عظم قدر بعض الخدم عند الملك، لم يقبح منه تشفيعه في جمع من المذنبين 1.\rفإذا تقرر الجواز في ذلك، فالأخبار الواردة في الشفاعة مدونة في الصحاح 2، بالغة مبلغ الاستفاضة.\rومولانا قد توسط بحور الأخبار، ولا أشك أنه روى في أمثاله- أمتع الله الإسلام ببقاء معاليه-أخبار الشفاعة، ووفقه لأبواب الطاعة، وجدد ذكره إلى قيام الساعة.\r-----------------------\rفي ط: في جميع. في: معروفة.\rفي ط: بالغ. في أ: تجوز.\rمن قوله: ولا أشك. . . الساعة، ليست في ط.\r-------------------------\r1) في الإرشاد ص 394: «ولا يقبح عند العقلاء أن يشفع الملك بعض المخلصين المصطفين لديه في مذنب استحق عقابا ولا ينكر ذلك إلا متعنت».\r2) ومن ذلك حديث الشفاعة المطول الذي رواه البخاري في صحيحه، توحيد 19، 24، 36، ج 9 ص 158 - 161، 179، فبعد أن يأتي المؤمنون آدم ونوح وإبراهيم وموسى آملين الشفاعة فيعتذرون لأمر ارتكبه أحدهم، فيأتون عيسى عليه السلام فيقول: «لست هناكم، ولكن ائتوا محمدا صلى الله عليه وسلم، عبدا غفر الله له ما تقدم من ذنبه وما تأخر، فيأتوني فأستأذن على ربي في داره فيؤذن لي عليه، فإذا رأيته وقعت ساجدا، فيدعني ما شاء الله أن يدعني، فيقول: ارفع محمد، وقل تسمع، واشفع تشفع، وسل تعط، قال: فأرفع رأسي فأثني على ربي بثناء وتحميد يعلمنيه، فيحد لي حدا فأخرج فأدخلهم الجنة»، ويكرر الرسول صلى الله عليه وسلم الشفاعة مرة ثانية وثالثة وفي كل مرة يخرج بعضا من المؤمنين ويدخلهم الجنة، «حتى ما يبقى في النار إلا ما حبسه القرآن، أي وجب عليه الخلود». رواه البخاري في الصحيح، كتاب التفسير، سورة 5 ج 6 ص 105، ورواه مسلم في الصحيح، كتاب الإيمان 322، ج 3 ص 35، والترمذي في السنن، قيامة 10، ج 4 ص 622."], [254, "فصل\rفي الآجال والأرزاق\r\r"]], "pg": [252, 254]}, "474.43": {"x": [[254, "لكل حدوث وعدم، وبقاء وفناء، وحياة وممات، أجل معلوم، ووقت محتوم، والخلق يموتون أويقتلون بآجالهم 1.\rوقد كثر تخبط المبتدعة في ذلك، فزعم زاعمون منهم، أن من قتل لوترك لعاش، وقاتله قاطع أجله، ولذلك يقتل من قتله 2، وهذا يدرؤه كلام قريب فنقول:\rالأجل عبارة عن وقت حدث من الأحداث، فإذا علم الله تبارك وتعالى، أن إنسانا سيقتل فلا بد من وقوع معلومه.\r----------------------------\rفي ط: وبناء. في ط: وزعم.\rفي ط: والله تعالى.\r____________________________\r1) أجمعت الأشاعرة على أن كل من مات حتف أنفه أوقتل، فإنما مات بأجله الذي جعله الله عز وجل أجلا لعمره، ووافقهم في ذلك أبوالهذيل العلاف من المعتزلة. انظر مجرد مقالات الأشعري لابن فورك ص 135، وأصول الدين للبغدادي ص 142، ومقالات الإسلاميين للأشعري ص 257، وشرح الأصول الخمسة للقاضي عبد الجبار ص 782.\r2) هوقول أغلب مدرسة المعتزلة في بغداد، وبعض معتزلة البصرة، وقد أجابت المعتزلة على السؤال الأهم في مسألة الآجال: المقتول الذي لولم يقتل، هل كان يموت أم لا إلى ثلاثة أقوال، الأول: قول أبي الهذيل العلاف، وهوإن الرجل لولم يصل مات بأجله، والثاني: يجوز لولم يقتله القاتل أن يموت ويجوز أن يعيش، والثالث: يستحيل ذلك. انظر شرح الأصول الخمسة للقاضي عبد الجبار ص 782 - 786، ومقالات الإسلاميين للأشعري ص 256، 257، وأصول الدين للبغدادي ص 143."], [255, "فإن قيل: كان يجوز أن لا يقتل ويبقى.\rقلنا: لوكان في علم الله تبارك وتعالى أنه لا يقتل لبقي، [وإن] كان في علم الله تبارك وتعالى أنه [يقتل] فإنه يقتل لا محالة.\rولوقيل: لوعلم الله تبارك وتعالى أنه لا يقتل لبقي.\rقلنا: هذا التقدير لا ينضبط، إذ كان يجوز أن يقع في معلومه أنه لا يقتل، ويموت من ساعته حتف أنفة، والذي يموت من غير قتل، كان يجوز أن يبقى دهرا، فلوفتحت أبواب التجويزات، لما استقر لشيء أجل في علم الله، فهذا القدر كاف في الآجال.\rوأما الرزق: فكل ما ينتفع به منتفع فهورزقه 1، ثم الرزق ينقسم: إلى الحلال والحرام، وإلى ما لا يتصف بالتحليل والتحريم، كرزق البهائم. والله الرازق ولا رازق غيره، ولا خالق سواه.\rثم إنه تبارك وتعالى، قسم أرزاق العباد حلالا وحراما، كما صرفهم بحكمه في الطاعات والزلات توفيقا/وخذلانا، وعطاء وحرمانا.\rومن زعم أن الظلمة والذين يتعاملون بالحرام، ليسوا في رزق الله 2،\r-----------------------\rلوكان في علم الله تبارك وتعالى أنه لا يقتل لبقي: ليست في ط.\rأضفتها اجتهادا.\rالزيادة من ط. في ط: لو.\rتبارك وتعالى: ليست في ط.\rفي أ: فإذا، والمثبت من ط.\rفي ط: التقديرات. في ط: فأما.\rفي ط: ينحصر. في ط: فلا.\rفي ط: إنه تعالى.\r_______________________________\r1) وفي مجرد مقالات الأشعري ص 137: «إن معنى الرزق فعل واقع على وجه مخصوص، وهوأن يكون مما يتغذى به الحيوان، أوينتفع به من دفع حر أوبرد وأذى وضرر واستجلاب منفعة وتمكين من ذلك».\r2) في مقالات الإسلاميين ص 257: «قالت المعتزلة: فمن غصب إنسانا مالا أوطعاما فأكله، أكل ما رزق الله غيره ولم يرزقه إياه، وزعموا بأجمعهم أن الله سبحانه لا يرزق الحرام كما لا يملك الله الحرام، وإن الله سبحانه إنما رزق الذي ملكه إياهم دون الذي غصبه». وانظر شرح الأصول الخمسة ص 784 - 786.\rمن أجل عرض لوحة التحكم ثانية، انقر على أحد رموزها."], [256, "فقد أخرج معظم الخلائق في معظم الأوقات عن كونهم مرتزقة لله تعالى، وقال تبارك وتعالى: وم?ا من دابة [في الأرض] إلا? على الله رزقها 1.\r---------------------\rفي ط: الخلق.\rفي معظم الأوقات: ليست في ط.\rفي ط: الله تعالى. الزيادة: من ط.\r________________________\r1) سورة هود، الآية 6."], [257, "فصل\rفي الإيمان ومعناه، وذكر مصير المؤمنين\rومآلهم من الجنة والنار\r\r"]], "pg": [254, 257]}, "474.44": {"x": [[257, "وهذا فصل يتعين صرف الاهتمام إليه، والاعتناء بدرك ما فيه، ومضمون الفصل وذكر حقيقته أربعة أركان:\rأحدها: في الإيمان [وذكر حقيقته].\rوالثاني: في ذكر مصير العصاة من أهل الإيمان.\rوالثالث: في زيادة الإيمان ونقصانه.\rوالرابع: في معنى قول سلف الأمة: إنا مؤمنون إن شاء الله عز وجل.\rفأما الأول: فحقيقة الإيمان عندنا: التصديق 1. وهومعناه في اللغة\r------------------------\rذكر: ليست في ط.\rوذكر حقيقية: ليست في ط.\rالزيادة من ط. في ط: أهل النار.\rفي: ليست من ط. عز وجل: ليست في ط.\r__________________________\r1) أجمعت الأشعرية على أن الإيمان هوتصديق القلب، وهواعتقاد المعتقد صدق من يؤمن به، ولا تجعل الأشاعرة إقرار اللسان مع إنكار القلب إيمانا على الحقيقة، فالمنافق ليس مؤمنا على الحقيقة، أما العمل فهوعندهم طاعة ودليل على الإيمان، وشريعة له، وشريعة الشيء غير الشيء، كما أن السيد إذا أمر عبده بفعل ففعله لا يقال إنه آمن به بل يقال أطاعه، فكانوا جميعا يفرقون بين الإيمان والطاعة. انظر المجرد لابن فورك ص 150، والإرشاد للجويني ص 396، والإنصاف للباقلاني ص 48، الإبانة للأشعري ص 22، وأصول البغدادي ص 247، واللمع للأشعري ص 154، والغنية للمتولي ص 173."], [258, "واللسان. قال الله تبارك وتعالى: وما أنت بمؤمن لنا [ولوكن?ا صادقين] 1 معناه: وما أنت بمصدق [لنا].\rوالمؤمن على التحقيق: من انطوى عقده على المعرفة بصدق من أخبر عن صانع العالم وصفاته، وأنبيائه 2.\rفإن اعترف بلسانه بما عرفه بجنانه، فهومؤمن ظاهرا وباطنا.\rوإن لم يعترف بلسانه معاندا، لم ينفعه علم قلبه، وكان في حكم الله تبارك وتعالى من الكافرين به، كفر جحود وعناد. وكذلك كان فرعون وكل معاند جحود. وكذلك عرف أحبار اليهود نبوة محمد صلى الله عليه وآله وسلم، وصادفوا نعته في التوراة، فجحدوه بغيا وحسدا، فأصبحوا من الكافرين 3.\rومن أضمر الكفر، وأظهر كلمة الإيمان، فهوالمنافق 4 الذي يتبوأ\r----------------------\rوهومعناه في اللغة واللسان: ليست في ط.\rفي ط: الله تعالى. الزيادة من ط.\rالزيادة من ط. في أ: ما والمثبت من ط.\rتبارك وتعالى: ليست في ط. وآله: ليست في ط.\rفي ط: فجحدوا. في ط: ومن أظهر كلمة الإيمان وأضمر الكفر.\r________________________________\r1) سورة يوسف، الآية 17.\r2) وكان الأشعري يميز بين الإيمان بالله تعالى والإيمان بالرسول عليه السلام، فالإيمان بالله تعالى أنه أرسل الرسول صلى الله عليه وسلم غير الإيمان به أنه واحد موجود لا يشبه خلقه. ولم ينكر الأشعري عقلا تسمية المؤمن بالله تعالى المنكر للرسول صلى الله عليه وسلم مؤمنا به، لكنه تمسك بدلالة السمع، فمنع تسمية المؤمن بالله والمنكر للرسول صلى الله عليه وسلم مؤمنا كما هوالحال بالنسبة لليهود والنصارى والمجوس. المجرد لابن فورك ص 153.\r3) كما خاطب الله سيدنا موسى السبعين رجلا قائلا: الذين يتبعون الرسول النبي الأمي الذي يجدونه مكتوبا عندهم في التور?اة والإنجيل يأمرهم بالمعروف وينه?اهم عن المنكر سورة الأعراف، الآية 157.\rوقوله تعالى: وإذ ق?ال عيسى ابن مريم ي?ا بني إسر?ائيل إني رسول الل?ه إليكم مصدقا لم?ا بين يدي من التور?اة ومبشرا برسول يأتي من بعدي اسمه أحمد فلم?ا ج?اءهم بالبين?ات ق?الوا ه?ذ?ا سحر مبين (6).\r4) وصف الأشعري المنافق بالكافر لاعتقاده، وغير مؤمن لإقراره، وبعامة كان لا يجعل إقرار اللسان مع إنكار القلب إيمانا على الحقيقة. المجرد لابن فورك ص 150."], [259, "الدرك الأسفل من النار 1.\rواسم الإيمان لا يزول بالعصيان. والدليل عليه: أن معظم آيات التكليف مصدرة بذكر المؤمنين، كما قال الله تبارك وتعالى: ي?ا أيها الذين آمنوا كتب عليكم الصي?ام 2 فكل من يخاطب بتفاصيل التكليف، مندرج تحت اسم المؤمنين 3.\rوقد خاطب الله تبارك وتعالى العصاة، وأمرهم بالتوبة فقال: ي?ا أيها الذين آمنوا توبوا إلى الل?ه 4، فخاطبهم بالإيمان وأمرهم بالتوبة.\rوأجمع المسلمون على [أن] العبادات لا تصح إلا من المؤمنين. ثم أجمعوا على أن الفاسق يصح صومه وصلاته وحجه/. ثم أثبتوا للفسقة ما يثبت للمؤمنين، فأثبتوا عليهم ما أثبتوا عليهم من المغانم والمغارم، وأنفقوا عليهم من مال المسلمين، وصلوا عليهم، ودفنوهم في مقابر\r---------------------\rفي أ: معكم، والمثبت من ط. في ط: كما قال تعالى.\rفي أ: وكل، وما أثبته من ط.\rمن قوله: فقال. . . بالتوبة، ليست في ط.\rالزيادة من ط. في ط: ثبت.\rفي ط: وأثبتوا. ما أثبتوا عليهم: ليست في ط.\rفي ط: والمغارم ما عليهم.\r______________________________________\r1) وذلك في قوله تعالى: إن المن?افقين في الدرك الأسفل من الن?ار ولن تجد لهم نصيرا سورة النساء، الآية 145.\r2) سورة البقرة، الآية 183.\r3) ساق الجويني هنا الدليل على إيمان الفاسق كما ورد في الإرشاد ص 397، والأشاعرة إجمالا ترى أن الفسق إذا لم يكن كفرا فلا ينفي الإيمان بوجه من الوجوه، وإن الفاسق مؤمن مطلقا، لأن الذي كان له مؤمن في الأول قبل وجود فسقه موجود معه في حال الفسق، فوجب أن يثبت على حكم التسمية له بأنه مؤمن كما كان قبل حدوث فسقه. انظر المجرد لابن فورك ص 154، والإنصاف للباقلاني ص 50، والغنية للمتولي ص 174، وأصول البغدادي ص 249، 250، واللمع للأشعري ص 154.\r4) سورة التحريم، الآية 8."]], "pg": [257, 259]}, "474.45": {"x": [[260, "المسلمين، وترحموا عليهم، ولم يمتنعوا من الدعاء لهم، وسؤال الله [تعالى] العفوعنهم.\rفإن قيل: هل تفرقون بين الإيمان والإسلام فرقا\rقلنا: قد يطلق الإسلام والمراد به الإيمان. وقد يطلق والمراد به الإذعان والاستسلام ظاهرا من غير إضمار حقيقة الإيمان 1. قال الله تبارك وتعالى: ق?الت الأعر?اب آمن?ا قل لم تؤمنوا ول?كن قولوا أسلمن?ا 2، فالمؤمن إذا المستسلم، وقد لا يكون المستسلم مؤمنا، وكل مؤمن على ذلك مسلم، وليس كل مسلم بمؤمن.\rالركن الثاني من الفصل: في ذكر العصاة من أهل الإيمان.\r------------------------------\rذهبت الوعيدية 3. . . في ط: فترحموا.\rالزيادة من ط. في ط: يفرق.\rفرقا: ليست في ط.\rقد يطلق الإسلام والمراد به الإيمان: ليست في ط.\rفي ط: الله تعالى. في أ: لن.\rفي أ: مستسلم، وما أثبته من ط.\rفي ط: مؤمنا.\r________________________________\r1) كان الأشعري يرى «أن الإسلام هوالاستسلام والانقياد للحكم والمتابعة في الأمر، وإن كل مؤمن مسلم، وليس كل مسلم مؤمنا إذا لم يكن استسلامه بالتصديق والإيمان». المجرد لابن فورك ص 155. ولخص الباقلاني موقف الأشاعرة في التفريق بين الإيمان والإسلام بقوله: «ويجب أن يعلم أن كل إيمان إسلام، وليس كل إسلام إيمانا، لأن معنى الإسلام الانقياد، ومعنى الإيمان التصديق، ويستحيل أن يكون مصدق غير منقاد، ولا يستحيل أن يكون منقاد، غير مصدق». الإنصاف ص 51، وقد جمع محمد بن نصر المروزي رحمه الله مقالات الإسلاميين في معنى الإسلام والإيمان والتفريق بينهما جمعا دقيقا في كتابه تعظيم قدر الصلاة، ويعد هذا الكتاب هوالأغنى في هذه المسألة. انظر تعظيم قدر الصلاة ج 1 ص 367 - 505 وج 2 ص 506 - 810.\r2) سورة الحجرات، الآية 14.\r3) وعيدية الخوارج: أدخلهم الشهرستاني في الخوارج، وهم القائلون بتكفير صاحب الكبيرة وتخليده في ="], [261, "من الخوارج 1، والزيدية 2، والقدرية 3 إلا أن من استوعب عمره في طاعة الله تبارك وتعالى، ثم قارف كبيرة واحدة، ولم يوفق للتوبة عنها، ومات عارفا بالله تبارك وتعالى، فهوخالد في النار مع المشركين الذين [لم يؤمنوولم] يأتوا حسنة قط.\rوالعجب أنهم يثبتون أحكام [أفعال] الله تبارك وتعالى على ما تجري به عوائد العقلاء، والذي ذكروه من أقبح القبائح في مقتضى العقول شاهدا.\rوإن زعموا أن الحسنات تحبط بسيئة واحدة لتناقضهما، فهلا أحبطوا\r--------------------\rتبارك وتعالى: ليست في ط.\rتبارك وتعالى: ليست في ط.\rفي ط: مخلد. الزيادة من ط.\rفي ط: حكم. الزيادة من ط.\rفي ط: لمناقضتها لها.\r____________________________\r=النار، والوعيدية نسبة إلى الوعيد الإلهي، وهوتخويف العباد بالنار، لكن الوعيدية بالغت فيه وكانوا يقولون: لوعمر أحد ألف سنة وكان صائم الدهر وقائم الليل، وارتكب كبيرة من الكبائر، ومات بدون توبة، فإنه يخلد في النار، ويحبط إيمانه وجميع طاعاته. الملل والنحل للشهرستاني ص 114، وموسوعة الفرق الإسلامية ص 520.\r1) أجمعت الخوارج إلا النجدات منهم، على أن مرتكب الكبيرة كافر يخلد في النار، وأن الله تعالى يعذبه عذابا دائما. انظر مقالات الإسلاميين للأشعري ص 86.\r2) أجمعت الزيدية على أن أصحاب الكبائر كلهم معذبون في النار، خالدون فيها ولا يخرجون منها. انظر مقالات الإسلاميين للأشعري ص 14، والفرق بين الفرق للبغدادي ص 25.\r3) القدرية: لقب من ألقاب المعتزلة لأنهم أخذوا بمقالة معبد الجهني: «لا قدر والأمر أنف» أي مستأنف، واتفق القدرية على أن مرتكب الكبيرة ليس مؤمنا وليس كافرا، إنما هوفي منزلة بين المنزلتين، ثم اتفقوا على أن المؤمن إذا خرج من الدنيا من غير توبة عن كبيرة ارتكبها استحق الخلود في النار، لكن يكون عقابه أخف من عقاب الكفار.\rانظر مقالات الإسلاميين للأشعري ص 274، والفرق بين الفرق للبغدادي ص 96، والملل والنحل للشهرستاني ص 45."], [262, "السيئة بالحسنات 1. ولوفعلوا ذلك لشهدت لهم آية من كتاب الله تبارك وتعالى، وهي قوله: إن الحسن?ات يذهبن السيئ?ات 2.\rوقد تمسكوا بآي من القرآن 3، فمن أظهرها عندهم، قوله تبارك وتعالى: ومن يقتل مؤمنا متعمدا فجز?اؤه جهنم خ?الدا فيه?ا 4.\rوعلى ظاهر هذه الآية وجوه من الكلام، ونحن نؤثر منها وجهين، أحدهما: ما روي عن ابن عباس رضي الله عنه أنه قال: معناه، ومن يقتل مؤمنا مستحلا قتله 5.\r--------------------\rفي ط: الله تعالى.\rفي أ: وهو، وما أثبته من ط.\rفي أ: عندهن، والمثبت من ط.\rفي ط: الله تعالى. في ط: متعمدا، الآية.\rفجزاؤه جهنم خالدا فيها: ليست في ط.\rفي ط: نحن. رضي الله عنه: ليست في ط.\r__________________________\r1) انظر في إحباط العمل عند المعتزلة، شرح الأصول الخمسة للقاضي عبد الجبار ص 624، والمعتزلة إجمالا موقفها ليس موحدا في هذه المسألة. انظر مثل هذا الاختلاف بين الجبائيين أبي علي وأبي هاشم في شرح الأصول الخمسة ص 628.\r2) سورة هود، الآية 114.\r3) ومن هذه الآيات: ومن يعص الل?ه ورسوله ويتعد حدوده يدخله ن?ارا خ?الدا فيه?ا سورة النساء، الآية 14، فالله تعالى أخبر أن العصاة يعذبون بالنار ويخلدون فيها، والعاصي يتناول الفاسق والكافر جميعا، فيجب حمله عليهما، ومنها قوله تعالى: ومن يعص الل?ه ورسوله فإن له ن?ار جهنم خ?الدين فيه?ا أبدا، وقوله تعالى: إن المجرمين في عذ?اب جهنم خ?الدون (74) انظر شرح الأصول الخمسة ص 657 - 663.\r4) سورة النساء، الآية 93.\r5) المشهور عن ابن عباس، أن القاتل عمدا ليس له توبة، أما جمهور السنة فإنهم قالوا: إن الرجل يقتل مؤمنا متعمدا محمول على سبيل التغليظ في الوعيد، وصححوا توبة القاتل لغيره.\rانظر تفسير الطبري ج 4 ص 137، 138، وتفسير القرطبي ج 5 ص 332، وتفسير البغوي ج 1 ص 465، وتفسير ابن كثير ج 1 ص 535، والتفسير الكبير للفخر الرازي ="], [263, "ويشهد له كذلك، أن العمد إنما يتمخض فيمن يقدم على الشيء إقداما لا يزعه عنه وازع. ومن اعتقد أن القتل من أكبر الكبائر، فقد يدعوه إليه هواه، ويزعه إيمانه عنه، فيقدم وجلا مشفقا.\rوالعامد/حقا، هوالذي لا وازع له في ذاته، والدليل عليه: أنه تبارك وتعالى ذكر في آيات القصاص أحكامه وصوره عقب الإيمان، وأثبت للقاتل اسم الأخ أخذا من أخوة الإيمان، وندب إلى العفوعنه، ولم يتعرض للوعيد 1، ولم يذكر في آياته الوعيد 2 حكم القصاص [البتة]، فهذا وجه.\rوالثاني: [إن] قوله تبارك وتعالى: خ?الدا فيه?ا ظاهر في التأبيد، فلا يبتعد حمله على الآماد الطوال، وإن كانت تنتهي. وقد يجري في مكالمة الملوك وتحياتهم: الدعاء بالخلود، إذ يقول القائل: خلد الله ملك الملوك. ولوعنوا به تأبيدا [له]، لزجروا عن سؤال المحال 3.\r--------------------------------\rفي ط: ويزعه عنه إيمانه. في ط: رجلا.\rفي ط: رأيه. في ط: أنه سبحانه.\rالزيادة من ط. فهذا وجه: ليست في ط.\rالزيادة من ط. في ط: ولا.\rفي ط: وتحاياهم.\rفي أ: بالحبوط، وما أثبته من ط.\rالزيادة من ط.\r______________________\r=ج 5 ص 246، وفتح الباري لابن حجر ج 8 ص 354، وزاد المسير لابن الجوزي ج 2 ص 194.\r1) كما في قوله تعالى: يا أيها الذين آمنوا كتب عليكم القصاص في القتلى الحر بالحر والعبد بالعبد والأنثى بالأنثى فمن عفي له من أخيه شيء فاتباع بالمعروف وأداء إليه بإحسان ذلك تخفيف من ربكم ورحمة فمن اعتدى بعد ذلك فله عذاب أليم (178) سورة البقرة، الآية 178.\r2) يعني قول الله تعالى: ومن يقتل مؤمنا متعمدا فجزاؤه جهنم خالدا فيها وغضب الله عليه ولعنه وأعد له عذابا عظيما (93) سورة النساء، الآية 93.\r3) الأصل في الخلود البقاء والاستمرار، لكن قد تستخدم مجازا فيما يطول أمده، كالدعاء للملك بالقول: خلد الله ملكه. انظر تفسير القرطبي ج 1 ص 241، وأصل المخلد، الذي يبقى مدة طويلة، ومنه قيل رجل مخلد لمن أبطأ عنه الشيب، ودابة"], [264, "والنص القاطع في وعد الله تبارك وتعالى التجاوز عن المذنبين، فهوقوله تبارك وتعالى: إن الله لا يغفر أن يشرك به ويغفر ما دون ذلك لمن يشاء 1. ولم يرد [الله] تعالى أنه يغفر لمن تاب، فإنه لوأراد ذلك لما انتظم الفرق بين الشرك وغيره 2، والمشرك مغفور له إذا تاب.\rفأما من مات [من] عصاة أهل الإيمان من غير توبة فأمره مغيب 3: إن شاء الله غفر له، أوشفع فيه شفيع. وإن شاء عرضه على\r------------------------------\rفي ط: الله تعالى. في ط: المؤمنين هو.\rفي ط: الله تعالى. الزيادة من ط.\rفي ط: لأنه. في أ: وله والمثت من ط.\rفي ط: والشرك. في ط: فإذن.\rفي أ: تاب، والمثبت من ط.\rالزيادة من ط. في ط: شفعاء.\r___________________________\r= مخلدة هي التي تبقى ثناياها حتى تخرج رباعيتها، ثم استعير للمبقي دائما، والخلود في الجنة، بقاء الأشياء على الحالة التي عليها من غير اعتراض الفساد عليها. قال الله تعالى: أولئك أصح?اب الجنة هم فيها خالدون أول?ئك أصحاب النار هم فيها خالدون ومن يقتل مؤمنا متعمدا فجزاؤه جهنم خالدا فيها. انظر المفردات في غريب القرآن للراغب الأصفهاني ص 154.\r1) سورة النساء، الآية 48.\r2) يقول الطبري في تفسير آية الوعيد السابقة ج 5 ص 139: «وأولى القول في ذلك بالصواب قول من قال: معناه ومن يقتل مؤمنا متعمدا فجزاؤه إن جزاه جهنم خالدا فيها، ولكنه يعفوأويتفضل على أهل الإيمان به وبرسوله فلا يجازيهم بالخلود فيها، ولكنه عز ذكره إما أن يعفوبفضله فلا يدخله النار، وإما أن يدخله إياها ثم يخرجه منها بفضل رحمته لما سلف من وعده عباده المؤمنين بقوله: يا عبادي الذين أسرفوا على أنفسهم لا تقنطوا من رحمة الله إن الله يغفر الذنوب جميعا فإن ظن ظان أن القاتل إن وجب أن يكون داخلا في هذه الآية فقد يجب أن يكون الشرك داخلا فيه، لأن الشرك من الذنوب، فإن الله عز ذكره قد أخبر أنه غير غافر الشرك لأحد بقوله: إن الل?ه لا يغفر أن يشرك به ويغفر ما دون ذلك لمن يشاء والقتل دون الشرك.\r3) كان الأشعري يقف في أحكام عصاة المؤمنين وفساقهم فيقول: «لا ننزل أحدا جنة ولا نارا من أهل الذنوب، بل نرد أحكامهم إلى الله تعالى، ونقول: إن شاء عذبهم، ="], [265, "النار بقدر ذنبه، ثم عاقبته الفوز الأكبر والنجاة، قال رسول الله صلى الله عليه وآله وسلم: «لا يبقى في النار من في قلبه مثقال ذرة من الإيمان» 1.\rالركن الثالث: في زيادة الإيمان ونقصانه.\r"]], "pg": [260, 265]}, "474.46": {"x": [[265, "ذهب أئمة السلف: إلى أن الإيمان معرفة بالجنان وإقرار باللسان وعمل بالأركان. فهؤلاء أدرجوا الطاعات كلها تحت اسم الإيمان، وهذا غير بعيد في التسمية، وقد سمى الله تبارك وتعالى الصلاة إيمانا في قوله [تعالى]:\r-----------------------\rفي ط: النبي صلى الله عليه وسلم.\rكلها: ليست في ط. في ط: الله تعالى.\rالزيادة من ط.\r________________________\r= وإن شاء عفا عنهم، وحجته في ذلك أولا: التعارض بين ظاهري الوعد والوعيد مع عدم ما يغلب ويرجح أحدهما على صاحبه، والثاني: أن صور الألفاظ وصيغتها مما لا يمكن القضاء بها لأجلها في عموم أوخصوص لاشتراكها واحتمالها على وجه واحد». انظر مجرد مقالات الأشعري لابن فورك ص 164، 165.\r1) في صحيح البخاري، كتاب التوحيد 39، ج 9 ص 179 من حديث الشفاعة: «فأخرج منها من كان في قلبه مثقال ذرة أوخردلة من إيمان». وفي كتاب الإيمان 15، ج 1 ص 12: «يدخل أهل الجنة الجنة، وأهل النار النار»، ثم يقول الله تعالى: «أخرجوا من كان في قلبه مثقال حبة من خردل من إيمان». وفي كتاب التوحيد 19، ج 9 ص 161: «فأخرجهم من النار وأدخلهم الجنة حتى ما يبقى في النار إلا من حبسه القرآن». وفي صحيح مسلم، إيمان 147: «لا يدخل النار أحد في قلبه مثقال حبة خردل من إيمان». وفي مسلم، إيمان 304 ج 3 ص 36: «انظروا من وجدتم في قلبه حبة من خردل من إيمان فأخرجوه». وكذلك رواه أبوداود، لباس 26 ج 2 ص 181. وفي سنن الترمذي، جهنم 10 ج 4 ص 714 حديث 2598: «يخرج من النار من كان في قلبه مثقال ذرة من الإيمان». وقال فيه: هذا حديث حسن صحيح.\rوفي سنن ابن ماجه عن عبد الله حديث 59، مقدمة 9 ج 1 ص 22، 23، وحديث رقم 4173، ج 2 ص 1397 عن عبد الله: «لا يدخل النار من كان في قلبه مثقال حبة من خردل من إيمان». وفي مسند أحمد ج 4 ص 11، 12، 17، عن أبي سعيد الخدري: «فما يترك منها عبدا في قلبه مثقال حبة إيمان إلا أخرجه منها». ومثل لفظ البخاري عن عبد الله وعبد الله بن عمر حديث ج 1 ص 399، 412، 416، وج 2 ص 315."]], "pg": [265, 265]}, "474.47": {"x": [[266, "وما كان الله ليضيع إيمانكم 1، أراد الصلاة التي صلوها إلى بيت المقدس 2. فمن أطلق اسم الإيمان على الطاعات كلها، يقول على مساق أصله:\rيزيد الإيمان بزيادة الطاعات، وينقص بنقصانها 3.\rومن قال: الإيمان هوالتصديق، فمن علم وعرف حقا، فلا يتفاوت التصديق [المعلوم] بالأعمال، زادت أونقصت. وهذا كما أن العاقل قد ينكف عن ارتياحه ومساره بعلمه بالموت، والمنهمك في لذاته واتباع شهواته/عالم بالموت علمه، ولكن غلبة هواه تستحثه على ما يتعاطاه.\rوسيأتي في الركن الرابع ما يوضح المعضل في ذلك والأرب، ويفضي من اللبيب العجب.\r\rالركن الرابع: في قول من سلف، إنا مؤمنون إن شاء الله عز وجل 4.\r----------------\rالزيادة من ط. في ط: يتخلف.\rفي أ: ولكنه، والمثبت من ط.\rفي ط: وسنبينه.\rمن قوله: ما يوضح. . . العجب، ليست في ط.\rعز وجل: ليست في ط.\r_________________________\r1) سورة البقرة، الآية 143.\r2) في أسباب النزول للواحدي ص 45، 46: أن بعض الصحابة بعد نزول هذه الآية سألوا رسول الله صلى الله عليه وسلم فقالوا: يا رسول الله توفي إخواننا وهم يصلون إلى القبلة الأولى، وقد صرفك الله تعالى إلى قبلة إبراهيم، فكيف بإخواننا فأنزل الله: وما كان الله ليضيع إيمانكم. وانظر أيضا لباب النقول للسيوطي ص 17.\r3) انظر تفصيل ذلك في كتاب الإيمان لابن تيمية ص 204 - 215.\r4) ويطلق على هذه المسألة اصطلاحا «الاستثناء في الإيمان» من أجل «الموافاة» ومعنى الموافاة اعتبار عاقبة الأمر في حال المؤمن والكافر، وما يوافي كل منهما ربه عليه يوم القيامة، وعلى ذلك تعلق وعده ووعيده ورضاه وسخطه. المجرد لابن فورك ص 161.\rوانظر آراء الفرق مسهبة في الإيمان لابن تيمية ص 370 - 395، وقد حرمت المرجئة والجهمية الاستثناء في الإيمان، بينما غلا آخرون من أتباع محمد بن يوسف بن واقد الفريابي الذي عاش مرابطا في عسقلان وقيسارية في فلسطين، حتى إن هؤلاء أصبحوا يستثنون في كل شيء، فيقولون: هذا حبل إن شاء الله، وهذا ثوبي="], [267, "وها أنا أذكر في ذلك سرا لا أستجيز إخلاء هذه العقيدة الشريفة منه، فأقول:\rجماهير الخلق من أهل السنة على عقد صحيح في الدين يتعلق بالمعتقد على ما هوبه، ولكن عقدهم ليس بمعرفة. فإن المعتقد لا يعرف ضرورة، وجماهير الخلق لا يستقلون بالأدلة.\rولوامتحن الملقبون بالإمامة فضلا عن العوام بدلالة قاعدة واحدة لبقوا فيها حيارى، فإذا كانت المعرفة لا تثبت دون الأدلة، ولا تحصل ضرورة، ولا يستقل بالأدلة كل من يعاني الكلام أيضا، فمعظم العقود ليست معارف، ولكنها عقود مستقرة صائبة مصممة.\rوما كلف الله الخلائق حقيقة معرفته ودرك اليقين في الدين، والدليل على ذلك: أن الأولين ما كلفوا تتبع الأدلة، وإنما طولبوا بعقد مصمم وشهادة والتزام أحكام، وهم إن بقوا في عاقبتهم على عقدهم ناجون فائزون. كما قال الرسول صلى الله عليه وآله وسلم: «من كان آخر كلامه لا إله إلا الله دخل الجنة» 1. فإذن أرباب المعارف في العالم الأقلون، والباقون أهل\r--------------------\rفي ط: معرفة. صائبة: ليست في ط.\rفي أ: ارتقوا، والمثبت من ط.\rفي ط: النبي صلى الله عليه وسلم.\rفي أ: فإذا. في أ: الباقون، وما أثبته من ط.\r___________________________\r= إن شاء الله. انظر الإيمان ص 372، وسير الذهبي ج 1 ص 363. أما الأشاعرة فإن رأيهم لخصه الباقلاني في الإنصاف ص 52 إذ قال: «ويجب أن يعلم أنه يجوز أن يقول العبد أنا مؤمن حقا ويعني به في الحال، ويجوز أن يقول أنا مؤمن إن شاء الله ويعني به في المستقبل، فأما في الماضي وفي الحال، فلا يجوز أن يقول إن شاء الله، لأن ذلك يكون شكا في الإيمان، ولأن الاستثناء إنما يكون في المستقبل». انظر أصول البغدادي ص 252، والتمهيد للباقلاني ص 349، 350، والمجرد لابن فورك ص 161، والإرشاد للجويني ص 400، والإحياء للغزالي ج 1 ص 144، وتعظيم قدر الصلاة للمروزي ج 2 ص 509، 528، 529.\r1) رواه أبوداود في السنن عن معاذ بن جبل جنائز 16 ج 2 ص 57، وكذلك الطبراني في المعجم الكبير ج 20 ص 112 رقم 221، وأحمد في المسند ج 5 ص 247 بلفظ: -"], [268, "عقائد 1.\rثم إذا لم يكن العقد علما، لم يكن له ضبط، ولم يدر أن العقد المأتي به في الاستقرار على الحد المطلوب أم هودونه، وهوفي ملتطم الظنون وتعارض الشبهات، فلما كان كذلك، حسن على حسب ذلك أن يقولوا: إنا مؤمنون إن شاء الله. والعارف قد تعتريه حالة يعدم فيها مذاق اليقين، فهذا وجه الاستثناء.\rولولم يجر في كتابنا هذا غير ذلك، لكان حريا أن يغتبط به، ويجل في النفوس قدره. وعلى هذه القاعدة يزيد الإيمان [وينقص] بالطاعة 2، فإن من كان معتمده عقدا تأكد معتقده بالمواظبة على الطاعة، وإن أحوب المعاصي فهي عقده، وهذا يجده معظم الخلق من أنفسهم. وقد وفقنا بما\r--------------------------\rفي ط: في. في أ: عليه، والمثبت من ط.\rالزيادة من ط. في ط: ضرى.\rفي ط: وهي.\r___________________\r= «وجبت له الجنة». وفي مسلم، إيمان 243 ج 1 ص 218 عن عثمان بلفظ: «من مات وهويعلم أنه لا إله إلا الله دخل الجنة». وفي البخاري، إيمان 1 ج 1 ص 90 عن عبد الله بن مسعود: «من مات يشرك بالله شيئا دخل النار، وقلت أنا (ابن مسعود) من مات لا يشرك بالله شيئا دخل الجنة».\r1) والجويني رحمه الله لم يأت بهذا السر ابتداعا، والشيء الجديد الذي أتى به في هذه العقيدة، هوأنه صاغ بطريقة المتكلمين ما أتى على ذكره محمد بن نصر المروزي في تعظيم قدر الصلاة على طريقة المحدثين. انظر تعظيم قدر الصلاة للمروزي ج 2 ص 506 - 528.\r2) خالف الجويني في قوله هذا قول الأشاعرة في قولهم: إن الإيمان لا يزيد ولا ينقص، وهوفي الإرشاد ص 399."], [269, "التزم بمذهب شيخه الأشعري فهويقول: «إذا حملنا الإيمان على التصديق فلا يفضل تصديق تصديقا كما لا يفضل علم علما، ومن حمله على الطاعة سرا وعلنا، وقد مال إليه القلانسي فلا يبعد على ذلك إطلاق القول بأن الإيمان يزيد بالطاعة وينقص بالمعصية، وهذا مما لا نؤثره» وهوفي الإرشاد ص 397 يقول: «والمرضي عندنا أن حقيقة الإيمان هوالتصديق بالله تعالى، فالمؤمن بالله من صدقه»."], [270, "كنا أجبنا على هذا الركن من زيادة الإيمان ونقصانه 1.\r------------------------\rمن قوله: وقد وفقنا. . . ونقصانه: ليست في ط.\r_______________________\r1) وضح الباقلاني رأي الأشاعرة في زيادة الإيمان ونقصانه في الإنصاف ص 50، إذ يقول: «لا ننكر أن نطلق أن الإيمان يزيد وينقص كما جاء في الكتاب والسنة، لكن النقصان والزيادة يرجع في الإيمان إلى أحد أمرين: إما أن يكون ذلك راجعا إلى القول والعمل دون التصديق. . . والأمر الثاني: يكون من حيث الحكم لا من حيث الصورة، فيكون ذلك أيضا في الجميع من التصديق والإقرار والعمل، ويكون المراد بذلك في الزيادة والنقصان راجعا في الجزاء والثواب والمدح والثناء دون نقص وزيادة في تصديق من حيث الصورة». وانظر الغنية للمتولي ص 174، وأصول الدين للبغدادي ص 252، ومحصل الرازي ص 349، والتمهيد للباقلاني ص 349، 350.\nفصل\rفي أحكام التوبة\r"]], "pg": [266, 270]}, "474.48": {"x": [[270, "التوبة واجبة بإجماع الأمة على كل من عصى ربه 1. واختلفت عبارات الأئمة في حقيقة التوبة.\rفقال قائلون: التوبة عبارة تحوي أركانا:\rأحدها: الندم على ما سلف من الذنوب.\rوالثاني: الانكفاف عن العصيان.\rوالثالث 2: التزام العزم على ترك معاودته.\r-----------------------\rأحكام: ليست في ط. في ط: عبارة.\rفي حقيقة التوبة: ليست في ط.\rفي ط: الذنب. في أ: إنه الانكفاف.\rفي ط: إبرام. في ط: عدم.\r_________________________\r1) يقرر الأشعري: «إن التوبة من الذنوب كلها كفرا كان أوفسقا وغيره واجب» المجرد لابن فورك ص 166. ودليل الوجوب يوضحه أبوسعد المتولي من الأشاعرة في كتابه المغني ص 176: «والدليل عليه الآيات الواردة في كتاب الله تعالى في الأمر بالتوبة، مثل قوله تعالى: وتوبوا إلى الل?ه والدليل عليه أيضا إجماع الأمة على وجوب ترك المعاصي والندم على ما حصل في الوجود».\r2) وهذه الشروط متعلقة بحق الله تعالى، أما التوبة المتعلقة بحقوق الآخرين فله ثلاث شروط، منها: الخروج عن حقه مثل رد المغصوب، وغرامة ما أتلف عليه من مال ونفس وإن لم يكن له بدل مثل القصد والضرب والأذية، والثالث الندم على ما حصل منه والعزم على تركه. انظر المغني للمتولي ص 176، أما الأشعري نفسه فكان يقول: إن حقوق الله تعالى="], [271, "وقال آخرون: التوبة هي الندم بعينه 1، ثم إنه يقتضي حلا لعقد الإصرار وعزما، فإن المصر على الشيء، لا يكون نادما على الحقيقة، وكذلك العازم على المعاودة لا يكون نادما.\rوالذي أراه في حقيقة التوبة ما أبديه الآن: فالتوبة: الرجوع، من قولهم: تاب وأتاب إذا رجع 2، ولكن ليس الرجوع إلى الطاعة من غير صفة تتعلق بالذنب توبة 3، فأقول:\rالعارف يعتريه إغفال وإهمال وذهول [وانهماك] في شهوات، وعندها يعصي. [ولوكان العارف تحت] سطوع المعرفة دائما [لما عصى قط، فإذا لها وسها عصى]، فإذا عاد سطوع المعرفة فهوعودة وتوبة.\rوهذه الحالة توجب لا محالة ندما وعزما وحلا لعقد الإصرار، وحزنا على ما تقدم، وتأسفا وتمنيا أن لو [لم] يكن فعل.\rوالتوبة رجوع العبد إلى حقيقة حضور الذهن في المعرفة، وإليه أشار رسول الله صلى الله عليه وآله وسلم، إذ قال: «لا يزني الزاني حين يزني\r----------------\rفي أ: والإصرار وعزم. في ط: تعتريه غفلات.\rوإهمال: ليست في ط. الزيادة من ط.\rفي ط: عندها. الزيادة من ط.\rالزيادة من ط. في ط: عودته وتوبته.\rالزيادة من ط. في ط: النبي.\rآله: ليست في ط.\r_________________\r=كلها تسقط بالتوبة، فأما حقوق الآدميين فلا تسقط إلا بالأداء والإبراء. المجرد لابن فورك ص 167.\r1) انظر المغني للمتولي ص 175.\r2) وهذا هوما قاله الأشعري، ففي المجرد ص 166: «إن التوبة هي الرجوع عن الشيء، منه يقال: تاب من سفره، إذا رجع، ومنه قوله عليه السلام: آيبون تائبون، للراجعين من سفرهم».\r3) وهوقول الأشعري أيضا في المجرد ص 166: «إن الرجوع عما فعل بتركه على وجه مخصوص يكون توبة، وهوأن يترك ما تقدم فعله، ويعزم على أن لا يعود إليه، ويندم على ما مضى، فيكون ترك الفعل الأول في الثاني على هذا الوجه توبة»."], [272, "وهو مؤمن» 1. أراد لوكان على حضور عرفانه لما زنى، ولكنه سها فعصى، كما ينسى الصائم صومه فيأكل 2.\r------------\rفي ط: وعصى.\r____________________\r1) رواه البخاري عن ابن عباس في كتاب الحدود 1 ج 8 ص 197، وعن أبي هريرة في كتاب الأشربة 1، 11 ج 7 ص 135، 136، ومسلم عن أبي هريرة في كتاب الإيمان 100 ج 2 ص 41، 45، والترمذي، كتاب الإيمان 11 ج 2 ص 41، 42، والدارمي في كتاب الأشربة 11 ج 2 ص 156 - 157.\r2) في شرح النووي على صحيح مسلم ج 2 ص 41، 42: «هذا الحديث مما اختلف العلماء في معناه، فالقول الصحيح الذي قاله المحققون أن معناه لا يفعل هذه المعاصي وهوكامل الإيمان. وحكي عن ابن عباس أنه ينزع منه نور الإيمان، والقول الثالث: أن نزع الإيمان إذ أتى بذلك مستحلا له مع علمه بورود الشرع بتحريمه». وانظر فتح الباري ج 12 ص 61."]], "pg": [270, 272]}, "474.49": {"x": [[273, "273\rفصل\r[في قبول التوبة]\r\rلا يحب قبول التوبة على الله عقلا 1، ولكن ورد الشرع بقبولها، قال الله تبارك وتعالى: وهوالذي يقبل التوبة عن عب?اده 2، وقال صلى الله عليه وسلم: «التائب من الذنب كمن لا ذنب له» 3.\r---------------\rفي ط: بقبوله. في ط: الله تعالى.\rفي أ: عن. في ط: الرسول عليه السلام.\r_____________________\r1) لا توجب الأشاعرة على الله تعالى شيئا، بخلاف المعتزلة التي أوجبت على الله تعالى اللطف والصلاح والأصلح وغيرها، وفي مجرد مقالات الأشعري لابن فورك ص 166: «إن قبولها غير واجب عقلا، وإنما قلنا بقبولها خبرا، وذلك من الله تعالى فضل، لأنه هوالذي يرجع بالعبد من المعصية إلى الطاعة، فينبهه على ترك المعصية ويرغبه في فعل الطاعة بإلقاء رغبة ورهبة في قلبه.\r2) سورة التوبة، الآية 104.\r3) رواه ابن ماجه في السنن، كتاب الزهد 30 ج 2 ص 1419، 1420، حديث رقم 4250، وفي المقاصد الحسنة للسخاوي ص 249 حديث رقم 313: «ابن ماجه والطبراني في الكبير، والبيهقي في الشعب من طريق أبي عبيد الله بن عبد الله بن مسعود، عن أبيه، رفعه بهذا، ورجاله ثقات، بل حسنه شيخنا يعني لشواهده، وإلا فأبوعبيدة جزم غير واحد بأنه لم يسمع من أبيه». ورواه أبونعيم في الحلية ج 4 ص 210، والسيوطي في الجامع الصغير رقم 3005، وقال البيهقي: غريب من حديث عبد الكريم ولم يصله عن معمر إلا وهيب، وقد نقل العجلوني في كشف الخفاء ج 2 ص 351 رقم 944 ما ذكره السخاوي مع إضافات وتعليقات على شواهده. وانظر تعليق الحافظ العراقي على هذا الحديث في إحياء علوم الدين ج 4 ص 149، كتاب التوبة، حاشية رقم 1."], [274, "فصل\r[العود إلى الذنب لا يبطل التوبة السابقة]\r\r"]], "pg": [273, 274]}, "474.50": {"x": [[274, "العود إلى الذنب لا يبطل التوبة السابقة، فإن التوبة في حكم عبادة منقضية، فإذا انقضت العبادة لم ينعطف البطلان عليها 1.\r______________\r1) انظر رأي الأشعري في هذه المسألة مجرد مقالات الأشعري لابن فورك ص 166 - 167."], [275, "فصل عظيم الموقع أجعله مختتم العقيدة\r[التوبة من ذنب مع الإصرار على غيره من الذنوب]\r\r"]], "pg": [274, 275]}, "474.51": {"x": [[275, "اضطرب رأي الناس في أنه هل تصح التوبة من ذنب مع الإصرار على غيره من الذنوب\rفنقل الناقلون عن أهل الحق: أن ذلك جائز 1.\rوذهب أبوهاشم الجبائي 2 إلى أن ذلك ممتنع 3/، وتمسك بما عسر على أئمة الحق الجواب عنه فقال: التوبة النصوح، إنما يجب عليها\r-------------\rفي أ: عن، وما أثبته من ط. في ط: وتمسك بها عيسى من أئمة.\rفي ط: في الجواب. في أ: يستجيب، والمثبت من ط.\r___________________________\r1) كان الأشعري يقول: «إن التوبة تصح من ذنب مع الإصرار على غيره، فيكون حكم الذنب المصر عليه ثابتا، وحكم الذي تاب منه زائلا، وكذلك كان يقول: إن التوبة تصح من الذنب الذي لا يمكن للمذنب معاودته في حال التوبة». مجرد مقالات الأشعري لابن فورك ص 166.\r2) أبوهاشم الجبائي (321 ه‍/ 933 م): هوعبد السلام بن محمد بن عبد الوهاب الجبائي، من شيوخ مدرسة الاعتزال البصرية، كان رأس فرقة البهشمية، وأهم ما ذكره في الكلام ابتداعه لنظرية الأحوال. قارن عنه: الفهرست لابن النديم ص 222، والمنية والأمل لابن المرتضى ص 53، والمنتظم لابن الجوزي ج 6 ص 261، ووفيات الأعيان لابن خلكان ج 3 ص 183.\r3) ذكر القاضي عبد الجبار مذهب أبي هاشم الجبائي في ذلك، فقال: «وأما شيخنا أبوهاشم فقد ذهب إلى أنه لا تصح التوبة عن بعض القبائح مع الإصرار على البعض» ثم ذكر القاضي الأدلة العديدة على صحة مذهب أبي هاشم. انظر شرح الأصول الخمسة للقاضي عبد الجبار ص 794 - 796، والإرشاد للجويني ص 405، والفرق بين الفرق للبغدادي ص 175، والتبصير في الدين للإسفراييني ص 81، والمغني لأبي سعيد المتولي ص 177."], [276, "استشعار تعظيم مخالفة الله تبارك وتعالى، وإكبار مبارزة الظاهر بالذنوب.\rوهذا إذا فحص حقا لم يخص ذنبا، وهذا واقع جدا. ولم يذكر الأئمة جوابا مقنعا.\rوأنا أقول: التائب من ذنبه ينقسم: إلى عارف بالله تبارك وتعالى واثق بيقينه، وإلى معتقد لا يتصف بثلج النفس.\rفإذا كان صاحب الواقعة من العارفين، فسبب معصيته ذهوله عن صفوة المعرفة، وتوبته عودة إلى حضور الذهن، ومن حضرته المعرفة، وسطعت عليه أنوارها لم يصر على ذنب من الذنوب.\rومن كان متمسكه عقدا-كما سبق وصفه 1 - إذا ضعفت شهوته في فن من المعاصي، قوي فيه عقده، ولاحق توبته، وهويصر على بقايا ذنوبه التي بقيت شهواته فيها 2. وهذا لا يدركه إلا فطن مدرك غواص. والله المستعان وعليه التكلان.\rوقد كنت وعدت أن أذكر فصولا في الإمامة، ثم بدا لي، أن أفرد للمجلس السامي كتابا 3 في الإمامة، فقد تاهت فيها الفرق، ولم يخل\r-------------\rفي ط: الله تعالى. في أ: حظر.\rفي أ: عن، وما أثبته من ط. تبارك وتعالى: ليست في ط.\rفي ط: بنفسه. في ط: لا.\rفي ط: فإذا. في أ: نص.\rفي ط: موفق. والله المستعان وعليه التكلان: ليست في ط.\rفي ط: أجرد. في أ: فيه.\r______________________\r1) انظر ص 258.\r2) وهذا الجواب أيضا من الجويني لا يرقى إلى مرتبة الأدلة التي ساقها أبوهاشم الجبائي في تأكيد ما ذهب إليه. انظر هذه الأدلة في شرح الأصول الخمسة للقاضي عبد الجبار ص 795.\r3) وقد أنجز الجويني ما وعد به، وسمى هذا الكتاب: غياث الأمم في التياث الظلم، واشتهر بالغياثي، راجع الفصل الخاص بمؤلفات الجويني ص 102."], [277, "فريق عن تعدي الحد والسرف والإفراط والتفريط، والإيجاز لا يوصل إلى بداياتها، فضلا عن مبانيها ومعانيها.\rوالداعي لأيام مولانا مرتقب سامي أمره في افتتاح كتاب نسميه بالإيالة 1 الكبرى. وهي مصدرة بالإمامة، مختتمة بالأحكام السلطانية. وقد حوم عليها مصنفون لم يفردوها. ولم أتركها عذراء في خدرها، وهي لا تخطب، فإن شرف مولانا وليها بالخطبة، بادر إلى زفافها نافضة مزوديها 2، مختالة في أعطافها 3، إن شاء الله تعالى.\rومن أحاط بما قدمته، كان من العارفين بالله تبارك وتعالى، ومن عرفه تعين عليه الانتهاض لمعرفة وظائف العبادات، وقد صح في مأثور الخبر عن سيد البشر صلى الله عليه وآله وسلم أنه قال: «بني الإسلام [على خمس]: شهادة أن لا إله إلا الله [وأن محمدا رسول الله]، وإقام الصلاة، وإيتاء الزكاة، وصوم رمضان، وحج البيت الحرام لمن استطاع إليه سبيلا» 4.\r---------------------\rفي ط: استفتاح. في أ: كتابا.\rفي أ: بالإمامة الكبرى. في ط: ولم يردوها.\rفي ط: وكم تركوا من عذراء. في أ: مدورتها، وما أثبته من ط.\rفي ط: بالله سبحانه. في أ: بمعرفة، وما أثبته من ط.\rصلى الله عليه وآله: ليست في ط. في أ: أن، والمثبت من ط.\rالزيادة من ط. ليست في أ وط، أضفتها اجتهادا.\rالحرام: ليست في ط.\r_______________________\r1) الإيالة: السياسة. انظر لسان العرب، (مادة أول) ج 11 ص 26.\r2) مزوديها: مثنى مزود، والمقصود إن كتاب الإيالة الكبرى سيكون مليئا بأبكار الأفكار، كما يمتلئ المزود بالزاد. انظر لسان العرب لابن منظور (مادة زود).\r3) أعطاف: جمع عطف، والعطف من كل شيء جانبه. لسان العرب، (مادة عطف) ج 9 ص 250.\r4) رواه البخاري في كتاب الإيمان 2 ج 1 ص 9، ومسلم في كتاب الإيمان 21، 22 ج 1 ص 177، والترمذي في كتاب الإيمان 3 ج 5 ص 5، والنسائي في كتاب الإيمان 13 ج 8 ص 107، 108."], [278, "وليس هذا الحديث مما يختص بنقله الآحاد، ويستأثر/بروايته الأفراد، بل هومعتضد الملة ومستند النحلة، نقلته الأمة قاطبة، وتلقته بالقبول، ولهج المسلمون كافة بالإطباق والاتفاق على صدوره من فلق [في] رسول الله صلى الله عليه وآله وسلم، فحتم على كل موفق للإسلام، متعبد بالتزام الأحكام، أن يحيط بهذه القواعد وظواهر معانيها، ويستبين أوامر الله تبارك وتعالى عليه.\rفمن عاضده التأييد، وساوقه التسديد، فدرك المقدار المتعين منها غير بعيد، وأنا آتي فيها بما أرى العلم به مفروضا، وهوبتحقق رجاء آمليه حقيق 1.\r[تم المعتقد النظامي بعون الله تعالى وتوفيقه]\r-------------------\r"]], "pg": [275, 278]}, "474.52": {"x": [[278, "في أ: وهو، والمثبت من ط. في أ: صدره، والمثبت من ط.\rالزيادة من ط. في ط: عليه السلام.\rتبارك وتعالى: ليست في ط.\rمن قوله: وأنا آتي. . . حقيق، ليست في ط.\r_______________________\r1) من بعد ذلك عقد الجويني فصولا في أركان الإسلام وترجيح مذهب الإمام الشافعي، وهذه الفصول أليق بالفروعيات وليس بأصول الدين، لذا آثرت عدم نشرها ضمن العقيدة النظامية، خاصة وأن الجويني قد جعل هذا الفصل مختتما للعقيدة."]], "pg": [278, 278]}}, "units": {"2": {"tit": "المقدمة للمحقق", "lvl": 1, "pg": [5, 9]}, "6": {"tit": "الفصل الأول: الحالة السياسية و الاجتماعية و الاقتصادية في عصر الجويني", "lvl": 1, "pg": [9, 22]}, "20": {"tit": "الفصل الثاني: الحالة الدينية في عصر الجويني", "lvl": 1, "pg": [22, 36]}, "34": {"tit": "الفصل الثالث: الحالة الثقافية في عصر الجويني", "lvl": 1, "pg": [36, 54]}, "52": {"tit": "الفصل الرابع حياة إمام الحرمين الجويني", "lvl": 1, "pg": [54, 81]}, "79": {"tit": "الفصل الخامس شيوخ الجويني و تلامذته", "lvl": 1, "pg": [81, 93]}, "93": {"tit": "الفصل السادس: مؤلفات الجويني", "lvl": 1, "pg": [93, 119]}, "122": {"tit": "المقدمة", "lvl": 1, "pg": [119, 124]}, "129": {"tit": "فصل أقسام العلم و النظر", "lvl": 1, "pg": [124, 129]}, "134": {"tit": "باب القول في حدث العالم", "lvl": 1, "pg": [129, 134]}, "139": {"tit": "فصل: في ترتيب تراجم العقائد بعد تمهيد حدث العالم", "lvl": 1, "pg": [134, 135]}, "140": {"tit": "باب في الإلهيات", "lvl": 1, "pg": [135, 138]}, "143": {"tit": "[القسم الأول] الكلام فيما يستحيل على الله عز و جل", "lvl": 1, "pg": [138, 144]}, "151": {"tit": "[القسم الثاني] الكلام فيما يجب لله تبارك و تعالى", "lvl": 1, "pg": [144, 145]}, "152": {"tit": "فصل [في الحياة و العلم و القدرة]", "lvl": 1, "pg": [145, 148]}, "155": {"tit": "فصل [في الإرادة]", "lvl": 1, "pg": [148, 150]}, "157": {"tit": "فصل مما يجب لله تعالى: الاتصاف بالكلام", "lvl": 1, "pg": [150, 155]}, "162": {"tit": "فصل [معتقد أهل الحق في كلام الله تعالى]", "lvl": 1, "pg": [155, 157]}, "164": {"tit": "فصل [معنى القول: بأن كلام الله تعالى مسموع]", "lvl": 1, "pg": [157, 159]}, "166": {"tit": "فصل [معنى القول: كلام الله مكتوب في المصاحف مقروء بالألسنة، محفوظ بالصدور]", "lvl": 1, "pg": [159, 162]}, "169": {"tit": "فصل [في كون الله تعالى سميعا بصيرا]", "lvl": 1, "pg": [162, 164]}, "171": {"tit": "فصل [في صفة البقاء]", "lvl": 1, "pg": [164, 165]}, "172": {"tit": "فصل [في الإضراب عن تأويل المشكلات]", "lvl": 1, "pg": [165, 169]}, "176": {"tit": "[القسم الثالث] الكلام فيما يجوز في أحكام الله سبحانه", "lvl": 1, "pg": [169, 175]}, "183": {"tit": "فصل الحادثات كلها مرادة لله تبارك و تعالى", "lvl": 1, "pg": [175, 177]}, "185": {"tit": "[فصل] [في جواز رؤية الباري عز وجل]", "lvl": 1, "pg": [177, 181]}, "190": {"tit": "فصل في الوحدانية", "lvl": 1, "pg": [181, 184]}, "193": {"tit": "باب في العبودية والصفات المرعية في ثبوت الطلبات التكليفية", "lvl": 1, "pg": [184, 214]}, "232": {"tit": "باب النبوات", "lvl": 1, "pg": [214, 218]}, "236": {"tit": "فصل في المعجزات", "lvl": 1, "pg": [218, 225]}, "243": {"tit": "فصل في ذكر وجه دلالة المعجزة على صدق من ظهرت عليه", "lvl": 1, "pg": [225, 227]}, "245": {"tit": "فصل في الكرامات", "lvl": 1, "pg": [227, 232]}, "251": {"tit": "فصل في إثبات نبوة نبينا محمد صلى الله عليه وآله وسلم", "lvl": 1, "pg": [232, 242]}, "264": {"tit": "باب في السمعيات", "lvl": 1, "pg": [242, 244]}, "266": {"tit": "فصل في إعادة الخلق", "lvl": 1, "pg": [244, 246]}, "268": {"tit": "فصل في عذاب القبر وسؤال منكر ونكير", "lvl": 1, "pg": [246, 249]}, "271": {"tit": "فصل في الجنة والنار والصراط والميزان", "lvl": 1, "pg": [249, 252]}, "275": {"tit": "فصل في الشفاعة", "lvl": 1, "pg": [252, 254]}, "277": {"tit": "فصل في الآجال والأرزاق", "lvl": 1, "pg": [254, 257]}, "280": {"tit": "فصل في الإيمان ومعناه، وذكر مصير المؤمنين ومآلهم من الجنة والنار", "lvl": 1, "pg": [257, 260]}, "284": {"tit": "الركن الثاني من الفصل: في ذكر العصاة من أهل الإيمان", "lvl": 1, "pg": [260, 265]}, "290": {"tit": "الركن الثالث: في زيادة الإيمان ونقصانه.", "lvl": 1, "pg": [265, 266]}, "292": {"tit": "الركن الرابع: في قول من سلف، إنا مؤمنون إن شاء الله عز وجل", "lvl": 1, "pg": [266, 270]}, "298": {"tit": "فصل في أحكام التوبة", "lvl": 1, "pg": [270, 273]}, "301": {"tit": "فصل [في قبول التوبة]", "lvl": 1, "pg": [273, 274]}, "302": {"tit": "فصل [العود إلى الذنب لا يبطل التوبة السابقة]", "lvl": 1, "pg": [274, 275]}, "303": {"tit": "فصل عظيم الموقع أجعله مختتم العقيدة [التوبة من ذنب مع الإصرار على غيره من الذنوب]", "lvl": 1, "pg": [275, 278]}, "306": {"tit": "تم المعتقد النظامي بعون الله تعالى وتوفيقه", "lvl": 1, "pg": [278, 278]}}};
